def load_env() -> None:
    if not ENV_PATH.exists():
        return
    for line in ENV_PATH.read_text().splitlines():
        if line and not line.startswith("#") and "=" in line:
            key, value = line.split("=", 1)
            os.environ.setdefault(key, value)


load_env()


_DB_POOL: psycopg2.pool.ThreadedConnectionPool | None = None
_DB_POOL_LOCK = threading.Lock()


def _get_db_pool() -> psycopg2.pool.ThreadedConnectionPool:
    global _DB_POOL
    if _DB_POOL is None:
        with _DB_POOL_LOCK:
            if _DB_POOL is None:
                dsn = os.environ["WATHEFNI_DATABASE_URL"]
                min_conn = int(os.environ.get("WATHEFNI_DB_POOL_MIN", "1") or "1")
                max_conn = int(os.environ.get("WATHEFNI_DB_POOL_MAX", "16") or "16")
                _DB_POOL = psycopg2.pool.ThreadedConnectionPool(
                    min_conn, max(min_conn, max_conn), dsn, cursor_factory=RealDictCursor
                )
    return _DB_POOL


class _DbConnection:
    """Context manager that reuses pooled connections and commits/rolls back like
    psycopg2's native ``with connection`` block. Connections are returned to the pool
    on exit. If the pool is unavailable or exhausted, falls back to a direct connection
    so a request never fails purely because the pool is saturated."""

    def __init__(self) -> None:
        self._conn = None
        self._from_pool = False

    def __enter__(self):
        try:
            self._conn = _get_db_pool().getconn()
            self._from_pool = True
        except Exception:
            self._conn = psycopg2.connect(os.environ["WATHEFNI_DATABASE_URL"], cursor_factory=RealDictCursor)
            self._from_pool = False
        return self._conn

    def __exit__(self, exc_type, exc, tb):
        conn = self._conn
        self._conn = None
        if conn is None:
            return False
        try:
            if exc_type is not None:
                conn.rollback()
            else:
                conn.commit()
        except Exception:
            pass
        if self._from_pool:
            try:
                _get_db_pool().putconn(conn, close=exc_type is not None)
            except Exception:
                try:
                    conn.close()
                except Exception:
                    pass
        else:
            try:
                conn.close()
            except Exception:
                pass
        return False


def db_connect() -> _DbConnection:
    return _DbConnection()


# --- Per-turn tenant scope -------------------------------------------------
# Many AI/WhatsApp helper reads (name/position/candidate resolution) historically
# searched globally across all companies. To enforce tenant isolation without
# rewriting every call site, the active company is set once per turn at the
# request entrypoints and the scoped helpers read it (and fail closed if unset).
_active_company_code: contextvars.ContextVar[str | None] = contextvars.ContextVar(
    "wathefni_active_company_code", default=None
)


def normalize_company_code(value: str | None) -> str | None:
    company = str(value or "").strip().upper()
    return company or None


def set_active_company_code(value: str | None):
    return _active_company_code.set(normalize_company_code(value))


def reset_active_company_code(token) -> None:
    try:
        _active_company_code.reset(token)
    except Exception:
        pass


def active_company_code() -> str | None:
    return _active_company_code.get()


def resolved_company_scope(explicit: str | None = None) -> str | None:
    """Return the company a tenant-scoped read must use: explicit argument first,
    else the active per-turn company. Returns None when neither is available so
    callers can fail closed instead of reading across every company."""
    return normalize_company_code(explicit) or active_company_code()


