def outbound_flow_enabled(flow: str) -> bool:
    """Per-flow rollout gate. Requires the master switch AND the flow enabled."""
    if not outbound_layer_enabled():
        return False
    raw = (os.environ.get("WATHEFNI_OUTBOUND_FLOWS") or "").strip().lower()
    if raw in _OUTBOUND_OFF_VALUES:
        return False
    if raw in _OUTBOUND_ON_VALUES:
        return True
    return flow.strip().lower() in {part.strip() for part in raw.split(",") if part.strip()}


