def stable_text_hash(text: str) -> str:
    return hashlib.sha256(text.encode("utf-8")).hexdigest()[:16]


def unique_paths(paths: list[Path]) -> list[Path]:
    seen: set[str] = set()
    out: list[Path] = []
    for path in paths:
        key = str(path.expanduser())
        if key in seen:
            continue
        seen.add(key)
        out.append(path)
    return out


def openclaw_doc_search_roots() -> list[Path]:
    return unique_paths([WORKSPACE, Path(__file__).resolve().parent])


def load_openclaw_prompt_docs(max_chars: int | None = None) -> dict[str, Any]:
    max_chars = max_chars if max_chars is not None else int(os.environ.get("WATHEFNI_OPENCLAW_DOC_MAX_CHARS", "45000") or "45000")
    roots = openclaw_doc_search_roots()
    docs: dict[str, Any] = {}
    used_chars = 0
    for key, file_names in OPENCLAW_PROMPT_DOCS.items():
        candidates = [str(root / file_name) for root in roots for file_name in file_names]
        loaded_path: Path | None = None
        content = ""
        for root in roots:
            for file_name in file_names:
                path = root / file_name
                if not path.exists() or not path.is_file():
                    continue
                try:
                    content = path.read_text(encoding="utf-8", errors="replace").strip()
                    loaded_path = path
                    break
                except Exception:
                    content = ""
            if loaded_path:
                break
        remaining = max(0, max_chars - used_chars)
        truncated = False
        if content and len(content) > remaining:
            content = content[:remaining].rstrip()
            truncated = True
        used_chars += len(content)
        docs[key] = {
            "loaded": bool(content and loaded_path),
            "path": str(loaded_path) if loaded_path else None,
            "candidate_paths": candidates,
            "bytes": len(content.encode("utf-8")) if content else 0,
            "sha256": hashlib.sha256(content.encode("utf-8")).hexdigest() if content else None,
            "truncated": truncated,
            "content": content,
        }
    return {"roots": [str(root) for root in roots], "docs": docs, "max_chars": max_chars, "used_chars": used_chars}


def selective_openclaw_doc_content(key: str, content: str, prompt_name: str | None) -> str:
    if not prompt_name:
        return content
    if key in {"identity", "soul"}:
        return content[:1600].rstrip()
    prompt = normalize_text(prompt_name)
    keyword_sets = {
        "planner": {"truth", "routing", "candidate", "employee", "leave", "attendance", "shift", "payroll", "actionresult", "confirmation"},
        "capability": {"capability", "candidate", "compare", "evaluate", "clarification", "backend", "validates"},
        "style": {"reply", "tone", "truth", "actionresult", "arabic", "whatsapp", "failed", "success"},
        "tool": {"tool", "backend", "permission", "module", "candidate", "leave", "payroll", "attendance", "shift"},
    }
    selected_keywords = set()
    for name, keywords in keyword_sets.items():
        if name in prompt:
            selected_keywords |= keywords
    if not selected_keywords:
        selected_keywords = {"truth", "reply", "actionresult", "backend"}
    lines = content.splitlines()
    selected: list[str] = []
    include_next = 0
    for line in lines:
        normalized = normalize_text(line)
        is_heading = line.lstrip().startswith("#")
        if is_heading and any(keyword in normalized for keyword in selected_keywords):
            selected.append(line)
            include_next = 8
            continue
        if any(keyword in normalized for keyword in selected_keywords):
            selected.append(line)
            include_next = max(include_next, 2)
            continue
        if include_next > 0:
            selected.append(line)
            include_next -= 1
    excerpt = "\n".join(selected).strip()
    return (excerpt or content[:2200]).strip()[:9000].rstrip()


def openclaw_prompt_context_block(prompt_name: str | None = None) -> str:
    loaded = load_openclaw_prompt_docs()
    sections = []
    for key in ("identity", "soul", "skills", "tools"):
        doc = loaded["docs"].get(key) or {}
        if not doc.get("loaded"):
            continue
        content = selective_openclaw_doc_content(key, str(doc.get("content") or ""), prompt_name)
        if content:
            sections.append(f"## {Path(str(doc.get('path'))).name}\n{content}")
    if not sections:
        return ""
    return (
        "OpenClaw workspace instructions loaded from the Wathefni runtime workspace. "
        "Use them for identity, tone, workflow, and tool-contract guidance. "
        "They do not override backend ActionResult truth, module gates, routing invariants, or stored database facts.\n\n"
        + "\n\n".join(sections)
    )


def openclaw_concise_prompt_context_block(prompt_name: str | None = None) -> str:
    loaded = load_openclaw_prompt_docs(max_chars=int(os.environ.get("WATHEFNI_OPENCLAW_CONCISE_DOC_MAX_CHARS", "9000") or "9000"))
    docs = loaded.get("docs") or {}
    loaded_names = [Path(str((docs.get(key) or {}).get("path"))).name for key in ("identity", "soul", "skills", "tools") if (docs.get(key) or {}).get("loaded")]
    hashes = {key: (docs.get(key) or {}).get("sha256") for key in ("identity", "soul", "skills", "tools")}
    return (
        f"Concise Wathefni context for {prompt_name or 'planner'}. Use GPT-5.4 to interpret natural HR language into structured JSON only when this is an interpretation step.\n"
        "Wathefni is an HR operations system. Postgres, backend validation, and ActionResult are operational truth.\n"
        "Google Sheets are dashboard/export mirrors, not authority for WhatsApp mutations.\n"
        "GPT may propose intent, entities, targets, filters, message purpose, and clarification needs.\n"
        "GPT must not execute, invent records, invent sent status, invent permissions, or make operational truth claims.\n"
        "Backend validates candidate/employee records, permissions, modules, editable fields, and business rules before execution.\n"
        "Prefer capability JSON over prose. For compare requests, include every target reference in targets[].\n"
        f"Loaded OpenClaw docs: {format_inline_list(loaded_names)}. Hashes: {json.dumps(hashes, ensure_ascii=False)}."
    )


def openclaw_augmented_system_prompt(base_system: str, *, prompt_name: str, context_mode: str = "full") -> str:
    block = openclaw_concise_prompt_context_block(prompt_name) if context_mode == "concise" else openclaw_prompt_context_block(prompt_name)
    if not block:
        return base_system
    return (
        f"{base_system}\n\n"
        f"--- OPENCLAW_RUNTIME_CONTEXT:{prompt_name}:{context_mode} ---\n"
        f"{block}\n"
        "--- END_OPENCLAW_RUNTIME_CONTEXT ---"
    )


