# Post-hire operational permissions (registry/tool-call pilot rollout). Two tiers
# per module (read vs manage) plus a dedicated payroll.export for the most
# sensitive money action. Module entitlement (company_has_module) still gates
# everything on top of these role permissions.
_POSTHIRE_PERMS_FULL = {
    "leave.read", "leave.request", "leave.decide",
    "attendance.read", "attendance.manage",
    "shifts.read", "shifts.manage",
    "onboarding.read", "onboarding.manage",
    "payroll.read", "payroll.manage", "payroll.export",
    "analytics.read",
    "compliance.read", "compliance.manage",
}
_POSTHIRE_PERMS_MANAGER = {
    "leave.read", "leave.decide",
    "attendance.read", "attendance.manage",
    "shifts.read", "shifts.manage",
    "onboarding.read",
    "payroll.read",
    "analytics.read",
}
_POSTHIRE_PERMS_VIEWER = {
    "leave.read", "attendance.read", "shifts.read", "onboarding.read", "payroll.read", "analytics.read",
    "compliance.read",
}
# Team Manager (org-hierarchy V1): a post-hire-only operational lead who handles
# their own team. Holds the decision/manage permissions needed to approve leave,
# resolve attendance issues, approve shift swaps, and approve timesheets — but
# WHICH employees they can touch is restricted to their manager_scopes (see
# manager_scope_allows_employee). No company-wide HR/settings/users/candidate
# permissions and no payroll.export. "Approve-only vs create" is further narrowed
# by the manager-facing surfaces (V1b dashboard / V1c WhatsApp), not here.
_POSTHIRE_PERMS_TEAM_MANAGER = {
    "leave.read", "leave.decide",
    "attendance.read", "attendance.manage",
    "shifts.read", "shifts.manage",
    "onboarding.read",
    "payroll.read", "payroll.manage",
    "analytics.read",
    "compliance.read",
}

