ARABIZI_SIGNAL_RE = re.compile(
    r"\b(shlon|shloon|شلون|khal|khalas|yalla|laish|shno|shinu|3adi|3nd|ee|ewa|laa|wallah|inshallah)\b",
    re.I,
)


def detect_user_language(text: str | None, metadata: dict[str, Any] | None = None) -> str:
    hinted = str((metadata or {}).get("latest_user_language") or "").lower()
    if hinted in {"ar", "arabic"}:
        return "ar"
    if hinted in {"en", "english"}:
        return "en"
    raw = text or ""
    compact = re.sub(r"\s+", "", raw)
    if compact:
        arabic_count = sum(1 for ch in compact if "\u0600" <= ch <= "\u06ff")
        if arabic_count / max(len(compact), 1) > 0.2:
            return "ar"
    if ARABIZI_SIGNAL_RE.search(raw or ""):
        return "ar"
    return "en"


def language_label(language: str) -> str:
    return "Arabic" if language == "ar" else "English"


def action_invariant_class(action_type: str | None) -> str:
    action = str(action_type or "")
    if action in READ_ONLY_ACTIONS:
        return "read_only"
    if action in MUTATION_ACTIONS:
        return "mutation"
    return "mutation" if required_module_for_action(action) or action in SHARED_COMMUNICATION_ACTIONS else "read_only"


ANALYTICAL_REFINEMENT_ACTIONS = {
    "candidate_cv_evaluation",
    "rank_candidates",
    "workforce_analytics",
    "list_shifts",
    "list_attendance",
    "list_leave_requests",
    "list_payroll_hours",
    "list_timesheets",
    "list_payroll_exports",
    "show_payroll_policy",
    "check_assessment_config",
}

ANALYTICAL_REFINEMENT_CONFIDENCE_THRESHOLD = 0.72
ANALYTICAL_REFINEMENT_FILTER_KEYS = {
    "job_role",
    "position",
    "role",
    "stage",
    "status",
    "count",
    "top_n",
    "time_period",
    "date",
    "start_date",
    "end_date",
    "branch",
    "branch_key",
    "team",
    "team_key",
}


def is_supported_analytical_action(action_type: str | None) -> bool:
    action = str(action_type or "")
    return action in ANALYTICAL_REFINEMENT_ACTIONS or (action in READ_ONLY_ACTIONS and action not in {"answer_action_failure", "answer_verification_followup", "answer_operational_followup", "answer_action_history_followup"})


def analytical_refinement_count(text: str) -> int | None:
    normalized = normalize_text(text)
    match = re.search(r"\b(?:top|first|show)\s+(\d{1,3})\b", normalized)
    if not match:
        match = re.search(r"\b(\d{1,3})\s+(?:only|results?|candidates|people|rows)\b", normalized)
    if not match:
        return None
    try:
        value = int(match.group(1))
    except Exception:
        return None
    return max(1, min(value, RANK_CANDIDATES_MAX_TOP_N))


def analytical_refinement_period(text: str) -> dict[str, str]:
    normalized = normalize_text(text)
    today = kuwait_today()
    if "today" in normalized:
        return {"date": today.isoformat()}
    if "this week" in normalized:
        start = today - timedelta(days=today.weekday())
        return {"start_date": start.isoformat(), "end_date": (start + timedelta(days=6)).isoformat()}
    if "this month" in normalized:
        start = today.replace(day=1)
        next_month = (start.replace(day=28) + timedelta(days=4)).replace(day=1)
        return {"start_date": start.isoformat(), "end_date": (next_month - timedelta(days=1)).isoformat()}
    explicit = parse_shift_date_value(text)
    return {"date": explicit.isoformat()} if explicit else {}


def analytical_refinement_status(text: str) -> str | None:
    normalized = normalize_text(text)
    if re.search(r"\b(completed|complete|finished)\b", normalized):
        return "screening_complete"
    if re.search(r"\b(pending|review pending|pending review)\b", normalized):
        return "review_pending"
    return infer_application_status_filter(text)


def possible_analytical_refinement_text(text: str) -> bool:
    normalized = normalize_text(text)
    if not normalized or len(normalized) > 140:
        return False
    cleaned = re.sub(r"\b(pls|please|kindly)\b", "", normalized).strip()
    if not cleaned or cleaned in {"ok", "okay", "yes", "no", "thanks", "thank you"}:
        return False
    return bool(
        re.search(r"\b(for|about|what about|only|top|first|same for|show only|filter|this month|this week|today|same|what about)\b", cleaned)
        or analytical_refinement_count(cleaned)
        or analytical_refinement_status(cleaned)
        or infer_position_filter_from_text(cleaned)
    )


def short_analytical_refinement_signal(text: str) -> bool:
    return possible_analytical_refinement_text(text)


def latest_successful_analytical_action_from_db(request: WhatsAppTurnRequest) -> dict[str, Any] | None:
    action_types = tuple(sorted(ANALYTICAL_REFINEMENT_ACTIONS))
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT ar.action_type, ar.status, ar.result, ar.final_reply, ar.created_at, ht.turn_id
                FROM action_results ar
                JOIN hr_turns ht ON ht.turn_id=ar.turn_id
                WHERE ar.status='completed'
                  AND ar.action_type = ANY(%s)
                  AND ht.sender_phone=%s
                  AND (%s IS NULL OR ht.account_id=%s)
                  AND (%s IS NULL OR ht.conversation_id=%s)
                ORDER BY ar.created_at DESC
                LIMIT 1
                """,
                (
                    list(action_types),
                    digits(request.sender_phone),
                    request.account_id,
                    request.account_id,
                    request.conversation_id,
                    request.conversation_id,
                ),
            )
            row = cur.fetchone()
    if not row:
        return None
    payload = row.get("result") if isinstance(row.get("result"), dict) else {}
    filters = payload.get("filters") if isinstance(payload.get("filters"), dict) else {}
    ranking_result = payload.get("ranking_result") if isinstance(payload.get("ranking_result"), dict) else {}
    ranking_filters = ranking_result.get("filters") if isinstance(ranking_result.get("filters"), dict) else {}
    action = {
        "action_type": row.get("action_type"),
        "subject_type": action_focus_type(str(row.get("action_type") or "")),
        "prompt_text": payload.get("query") or ranking_result.get("query") or "",
        "query": payload.get("query") or ranking_result.get("query") or "",
        "position": filters.get("position") or ranking_filters.get("position"),
        "status": filters.get("status") or ranking_filters.get("status"),
        "top_n": payload.get("shown_top_n") or ranking_result.get("shown_top_n"),
        "planned_by": "action_result_history",
    }
    return {
        "action_type": row.get("action_type"),
        "payload": {"action": json_safe({k: v for k, v in action.items() if v not in (None, "", [], {})}), "result": json_safe(payload)},
        "completed_at": row.get("created_at").isoformat() if hasattr(row.get("created_at"), "isoformat") else str(row.get("created_at") or ""),
        "source_turn_id": str(row.get("turn_id") or ""),
        "expires_at": operational_context_timestamp(240),
    }


def latest_successful_analytical_action(request: WhatsAppTurnRequest, context: dict[str, Any] | None) -> dict[str, Any] | None:
    current = persistent_context_pruned(context)
    latest = current.get("last_successful_action") if isinstance(current.get("last_successful_action"), dict) else None
    if latest and not focus_is_stale(latest) and is_supported_analytical_action(latest.get("action_type")):
        return latest
    return latest_successful_analytical_action_from_db(request)


def call_analytical_refinement_planner(
    *,
    text: str,
    latest_action: dict[str, Any],
    company_code: str | None,
    timeout: int = 8,
) -> dict[str, Any] | None:
    provider = planner_provider_config()
    if not provider:
        return None
    system = openclaw_augmented_system_prompt(
        (
            "You propose structured intent for Wathefni analytical follow-up refinements. "
            "Return JSON only. Do not execute tools, do not answer the user, and do not invent records or results. "
            "Only identify whether the latest HR message is refining the previous read-only analytical action. "
            "Allowed intent values: analytical_refinement, clarification_needed, unsupported, none. "
            "Allowed filters: job_role, status, stage, count, time_period, date, start_date, end_date, branch, team. "
            "Use previous_action from the provided previous action only."
        ),
        prompt_name="analytical_refinement_planner",
        context_mode="concise",
    )
    payload = {
        "latest_user_message": text,
        "previous_action": {
            "action_type": latest_action.get("action_type"),
            "payload": latest_action.get("payload"),
            "completed_at": latest_action.get("completed_at"),
        },
        "company_code": (company_code or "WATHEFNI").upper(),
        "required_shape": {
            "intent": "analytical_refinement | clarification_needed | unsupported | none",
            "previous_action": "previous action type",
            "filters": {"job_role": "optional", "status": "optional", "count": "optional", "time_period": "optional", "branch": "optional", "team": "optional"},
            "confidence": "0.0-1.0",
            "reason": "brief",
        },
    }
    if provider.get("api") == "openai-responses":
        body = {
            "model": provider["model"],
            "temperature": 0,
            "input": [
                {"role": "system", "content": system},
                {"role": "user", "content": json.dumps(payload, ensure_ascii=False)},
            ],
        }
    else:
        body = {
            "model": provider["model"],
            "temperature": 0,
            "response_format": {"type": "json_object"},
            "messages": [
                {"role": "system", "content": system},
                {"role": "user", "content": json.dumps(payload, ensure_ascii=False)},
            ],
        }
    req = urllib.request.Request(
        provider["url"],
        data=json.dumps(body).encode("utf-8"),
        headers={"Authorization": f"Bearer {provider['api_key']}", "Content-Type": "application/json"},
        method="POST",
    )
    start = time_module.monotonic()
    estimated_tokens = estimate_tokens_from_payload(body)
    prompt_hash = stable_text_hash(system)
    try:
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            parsed = json.loads(resp.read().decode("utf-8", errors="replace"))
    except Exception as exc:
        record_llm_call(
            call_name="analytical_refinement_planner",
            provider=provider,
            prompt_mode="concise",
            prompt_docs_loaded=True,
            prompt_hash=prompt_hash,
            estimated_input_tokens=estimated_tokens,
            latency_ms=int((time_module.monotonic() - start) * 1000),
            status="error",
            error=str(exc),
            metadata={"previous_action": latest_action.get("action_type")},
        )
        return None
    record_llm_call(
        call_name="analytical_refinement_planner",
        provider=provider,
        prompt_mode="concise",
        prompt_docs_loaded=True,
        prompt_hash=prompt_hash,
        estimated_input_tokens=estimated_tokens,
        latency_ms=int((time_module.monotonic() - start) * 1000),
        status="ok",
        parsed=parsed,
        metadata={"previous_action": latest_action.get("action_type")},
    )
    result = extract_json_object(extract_model_text(parsed))
    return result if isinstance(result, dict) else None


def planner_confidence(value: Any) -> float:
    try:
        return float(value)
    except Exception:
        return 0.0


def period_filter_from_value(value: Any) -> dict[str, str]:
    text = normalize_text(str(value or ""))
    if not text:
        return {}
    if text in {"today"}:
        return analytical_refinement_period("today")
    if text in {"this_week", "this week", "week"}:
        return analytical_refinement_period("this week")
    if text in {"this_month", "this month", "month"}:
        return analytical_refinement_period("this month")
    return analytical_refinement_period(text)


def normalized_planner_refinement_filters(filters: dict[str, Any], *, action_type: str, company_code: str | None) -> tuple[dict[str, Any], list[str], list[str]]:
    normalized: dict[str, Any] = {}
    unsupported: list[str] = []
    invalid: list[str] = []
    for raw_key, value in filters.items():
        key = normalize_text(str(raw_key or "")).replace(" ", "_")
        if key not in ANALYTICAL_REFINEMENT_FILTER_KEYS:
            unsupported.append(str(raw_key))
            continue
        if value in (None, "", [], {}):
            continue
        text_value = str(value).strip()
        if key in {"job_role", "position", "role"}:
            if action_type not in {"candidate_cv_evaluation", "rank_candidates"}:
                unsupported.append(str(raw_key))
                continue
            position = infer_position_filter_from_text(text_value)
            if not position:
                invalid.append(f"role/job `{text_value}`")
                continue
            normalized["position"] = position
        elif key in {"status", "stage"}:
            status = analytical_refinement_status(text_value)
            if not status:
                invalid.append(f"status `{text_value}`")
                continue
            normalized["status"] = status
        elif key in {"count", "top_n"}:
            count = analytical_refinement_count(f"top {text_value}") if not isinstance(value, int) else int(value)
            if not count:
                invalid.append(f"count `{text_value}`")
                continue
            normalized["top_n"] = count
        elif key == "time_period":
            period = period_filter_from_value(text_value)
            if not period:
                invalid.append(f"time period `{text_value}`")
                continue
            normalized.update(period)
        elif key in {"date", "start_date", "end_date"}:
            parsed = parse_shift_date_value(text_value)
            if not parsed:
                invalid.append(f"{key} `{text_value}`")
                continue
            normalized[key] = parsed.isoformat()
        elif key in {"branch", "branch_key"}:
            branch = branch_from_action({"branch_key": text_value if key == "branch_key" else "", "prompt_text": text_value, "query": text_value}, company_code)
            if not branch:
                invalid.append(f"branch `{text_value}`")
                continue
            normalized["branch_key"] = branch.get("branch_key")
            normalized["branch_name"] = branch.get("branch_name")
        elif key in {"team", "team_key"}:
            team = team_from_action({"team_key": text_value if key == "team_key" else "", "prompt_text": text_value, "query": text_value}, company_code)
            if not team:
                invalid.append(f"team `{text_value}`")
                continue
            normalized["team_key"] = team.get("team_key")
            normalized["team_name"] = team.get("team_name")
    return normalized, unsupported, invalid


def rule_based_refinement_filters(text: str, *, company_code: str | None) -> dict[str, Any]:
    refinement: dict[str, Any] = {}
    position = infer_position_filter_from_text(text, company_code=company_code)
    status = analytical_refinement_status(text)
    count = analytical_refinement_count(text)
    period = analytical_refinement_period(text)
    branch = branch_from_action({"prompt_text": text, "query": text}, company_code)
    team = team_from_action({"prompt_text": text, "query": text}, company_code)
    if position:
        refinement["position"] = position
    if status:
        refinement["status"] = status
    if count:
        refinement["top_n"] = count
    if period:
        refinement.update(period)
    if branch:
        refinement["branch_key"] = branch.get("branch_key")
        refinement["branch_name"] = branch.get("branch_name")
    if team:
        refinement["team_key"] = team.get("team_key")
        refinement["team_name"] = team.get("team_name")
    return refinement


def action_supports_refinement_filters(action_type: str, filters: dict[str, Any]) -> tuple[bool, str | None]:
    if action_type in {"candidate_cv_evaluation", "rank_candidates"}:
        unsupported = set(filters) - {"position", "status", "top_n"}
        if unsupported:
            return False, f"I can refine that candidate view by role/job, stage/status, or top count. `{sorted(unsupported)[0]}` is not supported for this view yet."
    if action_type == "check_assessment_config":
        return False, "Assessment config is a fixed configuration check. I can’t filter it like a report."
    return True, None


def build_refined_analytical_action(action: dict[str, Any], text: str, *, action_type: str, filters: dict[str, Any], source: str) -> dict[str, Any]:
    merged = dict(action)
    base_prompt = str(action.get("prompt_text") or action.get("query") or action_type.replace("_", " "))
    merged.update({k: v for k, v in filters.items() if v not in (None, "", [], {})})
    merged.update(
        {
            "action_type": action_type,
            "subject_type": action.get("subject_type") or action_focus_type(action_type),
            "prompt_text": f"{base_prompt} | refinement: {text}",
            "query": str(action.get("query") or base_prompt),
            "planned_by": "analytical_refinement",
            "resolved_from_analytical_refinement": True,
            "analytical_refinement": {"raw_text": text, "filters": json_safe(filters), "source": source},
        }
    )
    return merged


def merge_analytical_refinement(action: dict[str, Any], text: str, *, action_type: str, company_code: str | None, filters: dict[str, Any] | None = None, source: str = "rules") -> tuple[dict[str, Any] | None, dict[str, Any]]:
    refinement = filters if filters is not None else rule_based_refinement_filters(text, company_code=company_code)
    if not refinement:
        return None, {"supported": False, "reason": "no_supported_filter"}
    ok, reason = action_supports_refinement_filters(action_type, refinement)
    if not ok:
        return None, {"supported": False, "reason": "unsupported_filter_for_action", "reply": reason, "filters": json_safe(refinement)}
    return build_refined_analytical_action(action, text, action_type=action_type, filters=refinement, source=source), {"supported": True, "filters": json_safe(refinement), "source": source}


def analytical_refinement_from_planner(request: WhatsAppTurnRequest, latest: dict[str, Any], base_action: dict[str, Any], action_type: str, company_code: str | None) -> dict[str, Any] | None:
    proposal = call_analytical_refinement_planner(text=request.raw_text, latest_action=latest, company_code=company_code)
    if not proposal:
        return None
    intent = str(proposal.get("intent") or "").strip()
    confidence = planner_confidence(proposal.get("confidence"))
    previous_action = str(proposal.get("previous_action") or action_type)
    if intent in {"none", ""}:
        return None
    if intent == "clarification_needed":
        return {
            "supported": False,
            "previous_action_type": action_type,
            "reply": str(proposal.get("question") or "Which filter should I apply to the previous result?"),
            "planner_proposal": json_safe(proposal),
            "source": json_safe(latest),
        }
    if intent == "unsupported":
        return {
            "supported": False,
            "previous_action_type": action_type,
            "reply": "I can refine that by role/job, stage/status, top count, period, branch, or team. Which one should I use?",
            "planner_proposal": json_safe(proposal),
            "source": json_safe(latest),
        }
    if intent != "analytical_refinement" or previous_action != action_type or confidence < ANALYTICAL_REFINEMENT_CONFIDENCE_THRESHOLD:
        return None
    raw_filters = proposal.get("filters") if isinstance(proposal.get("filters"), dict) else {}
    filters, unsupported, invalid = normalized_planner_refinement_filters(raw_filters, action_type=action_type, company_code=company_code)
    if unsupported:
        return {
            "supported": False,
            "previous_action_type": action_type,
            "reply": "I can refine that by role/job, stage/status, top count, period, branch, or team. That filter is not supported yet.",
            "planner_proposal": json_safe(proposal),
            "source": json_safe(latest),
        }
    if invalid:
        return {
            "supported": False,
            "previous_action_type": action_type,
            "reply": f"I couldn’t match {format_inline_list(invalid)} in Wathefni’s records. Try a known role, status, branch, team, period, or top count.",
            "planner_proposal": json_safe(proposal),
            "source": json_safe(latest),
        }
    refined_action, metadata = merge_analytical_refinement(base_action, request.raw_text, action_type=action_type, company_code=company_code, filters=filters, source="planner")
    if refined_action:
        return {
            "supported": True,
            "previous_action_type": action_type,
            "action": refined_action,
            "filters": metadata.get("filters") or {},
            "planner_proposal": json_safe(proposal),
            "source": json_safe(latest),
        }
    return {
        "supported": False,
        "previous_action_type": action_type,
        "reply": metadata.get("reply") or "I can refine that by role/job, stage/status, top count, period, branch, or team. Which filter should I apply?",
        "planner_proposal": json_safe(proposal),
        "source": json_safe(latest),
    }


def analytical_refinement_context(request: WhatsAppTurnRequest, context: dict[str, Any] | None) -> dict[str, Any] | None:
    text = request.raw_text
    if not possible_analytical_refinement_text(text):
        return None
    latest = latest_successful_analytical_action(request, context)
    if not latest:
        return None
    action_type = str(latest.get("action_type") or "")
    if not is_supported_analytical_action(action_type):
        return None
    payload = latest.get("payload") if isinstance(latest.get("payload"), dict) else {}
    base_action = payload.get("action") if isinstance(payload.get("action"), dict) else {}
    if not base_action:
        base_action = {"action_type": action_type, "prompt_text": text, "query": text}
    company_code = request_company_code(request)
    planned = analytical_refinement_from_planner(request, latest, base_action, action_type, company_code)
    if planned:
        return planned
    if not short_analytical_refinement_signal(text):
        return None
    refined_action, metadata = merge_analytical_refinement(base_action, text, action_type=action_type, company_code=company_code, source="rules")
    if refined_action:
        return {
            "supported": True,
            "previous_action_type": action_type,
            "action": refined_action,
            "filters": metadata.get("filters") or {},
            "fallback": "rules",
            "source": json_safe(latest),
        }
    if short_analytical_refinement_signal(text):
        return {
            "supported": False,
            "previous_action_type": action_type,
            "reply": "I can refine that by role/job, stage/status, top count, period, or branch. Which filter should I apply?",
            "source": json_safe(latest),
        }
    return None


def operational_context_now() -> datetime:
    return datetime.now(timezone.utc)


def operational_context_timestamp(minutes: int = 0) -> str:
    return (operational_context_now() + timedelta(minutes=minutes)).isoformat()


def empty_entity_sets() -> dict[str, list[dict[str, Any]]]:
    return {
        "candidates": [],
        "employees": [],
        "jobs": [],
        "shifts": [],
        "leave_requests": [],
        "assessment_attempts": [],
        "reports": [],
    }


def default_focus_context() -> dict[str, Any]:
    focus = {"primary_entity": None, "entity_sets": empty_entity_sets()}
    for key in PERSISTENT_FOCUS_KEYS.values():
        focus[key] = None
    return focus


def turn_scratch_for_request(request: WhatsAppTurnRequest, turn_id: str) -> dict[str, Any]:
    return {
        "turn_id": turn_id,
        "user_message": request.raw_text,
        "normalized_message": normalize_text(request.raw_text),
        "detected_intent": None,
        "intent_confidence": None,
        "extracted_entities": [],
        "resolved_entities": {},
        "pronoun_resolution": None,
        "action_decision": None,
        "validation_result": None,
        "tool_result": None,
        "reply_text": None,
        "fallback_text": None,
        "error": None,
    }


def current_focus_from_context_shape(raw: dict[str, Any], focus: dict[str, Any]) -> dict[str, Any] | None:
    current = raw.get("current_focus")
    if isinstance(current, dict) and not focus_is_stale(current):
        return current
    primary = focus.get("primary_entity") if isinstance(focus, dict) else None
    if isinstance(primary, dict) and not focus_is_stale(primary):
        return primary
    for key in ("current_candidate", "current_employee", "current_leave_request", "current_shift", "current_payroll"):
        item = focus.get(key) if isinstance(focus, dict) else None
        if isinstance(item, dict) and not focus_is_stale(item):
            return item
    return None


def current_domain_from_context_shape(raw: dict[str, Any], current_focus: dict[str, Any] | None) -> str | None:
    domain = str(raw.get("current_domain") or "").strip()
    if domain:
        return domain
    entity_type = str((current_focus or {}).get("entity_type") or "")
    if entity_type == "candidate":
        return "candidates"
    if entity_type == "employee":
        return "employees"
    if entity_type == "leave_request":
        return "leave"
    if entity_type in {"shift", "shift_swap"}:
        return "shifts"
    if entity_type in {"timesheet", "payroll", "payroll_export", "payroll_policy", "payroll_preview"}:
        return "payroll"
    last_action = raw.get("last_action_result") or raw.get("last_successful_action") or raw.get("last_failed_action")
    if isinstance(last_action, dict):
        action_type = str(last_action.get("action_type") or "")
        if action_type:
            return operational_module_for_action(action_type).lower()
    return None


def persistent_context_for_request(
    context: dict[str, Any] | None,
    *,
    request: WhatsAppTurnRequest,
    turn_id: str,
) -> dict[str, Any]:
    raw = dict(context or {})
    if not raw and isinstance(context, dict):
        raw = dict(context)
    focus = raw.get("focus") if isinstance(raw.get("focus"), dict) else None
    if focus is None:
        focus = default_focus_context()
        for old_key in list(PERSISTENT_FOCUS_KEYS.values()) + ["focus_history"]:
            if old_key in raw:
                focus[old_key] = raw.get(old_key)
    entity_sets = focus.get("entity_sets") if isinstance(focus.get("entity_sets"), dict) else {}
    merged_sets = empty_entity_sets()
    for key, value in entity_sets.items():
        if key in merged_sets and isinstance(value, list):
            merged_sets[key] = value
    focus["entity_sets"] = merged_sets
    current_focus = current_focus_from_context_shape(raw, focus)
    current_domain = current_domain_from_context_shape(raw, current_focus)
    last_action_result = raw.get("last_action_result")
    if not isinstance(last_action_result, dict):
        last_action_result = raw.get("last_successful_action") if isinstance(raw.get("last_successful_action"), dict) else raw.get("last_failed_action")
    out = {
        "actor": {
            "company_id": request_company_code(request),
            "actor_id": digits(request.sender_phone),
            "actor_role": request.sender_role,
            "channel": "whatsapp",
            "conversation_id": request.conversation_id,
        },
        "focus": focus,
        "current_domain": current_domain,
        "current_focus": json_safe(current_focus) if current_focus else None,
        "last_result_set": raw.get("last_result_set"),
        "last_action_result": json_safe(last_action_result) if isinstance(last_action_result, dict) else None,
        "offered_followup": raw.get("offered_followup") or raw.get("proposed_next_action"),
        "proposed_next_action": raw.get("proposed_next_action") or raw.get("offered_followup"),
        "pending_confirmation": raw.get("pending_confirmation"),
        "pending_action": raw.get("pending_action"),
        "pending_clarification": raw.get("pending_clarification"),
        "last_failed_action": raw.get("last_failed_action"),
        "last_successful_action": raw.get("last_successful_action"),
        "failed_action_history": raw.get("failed_action_history") if isinstance(raw.get("failed_action_history"), list) else [],
        "conversation_summary": raw.get("conversation_summary") or {"short_summary": None, "updated_at": None},
    }
    return persistent_context_pruned(out)


def parse_context_timestamp(value: Any) -> datetime | None:
    if isinstance(value, datetime):
        return value if value.tzinfo else value.replace(tzinfo=timezone.utc)
    if not value:
        return None
    try:
        parsed = datetime.fromisoformat(str(value).replace("Z", "+00:00"))
        return parsed if parsed.tzinfo else parsed.replace(tzinfo=timezone.utc)
    except Exception:
        return None


def focus_is_stale(focus: dict[str, Any] | None) -> bool:
    if not isinstance(focus, dict):
        return True
    expires_at = parse_context_timestamp(focus.get("expires_at"))
    return bool(expires_at and expires_at < operational_context_now())


def failed_action_identity(item: dict[str, Any]) -> tuple[str, str, str]:
    return (str(item.get("action_type") or ""), str(item.get("target_type") or ""), str(item.get("target_id") or ""))


def business_failed_action_history(context: dict[str, Any] | None) -> list[dict[str, Any]]:
    current = context or {}
    history = current.get("failed_action_history") if isinstance(current.get("failed_action_history"), list) else []
    items = [item for item in history if isinstance(item, dict) and not focus_is_stale(item) and item.get("action_type") != "retry_last_failed_action"]
    last_failed = current.get("last_failed_action") if isinstance(current.get("last_failed_action"), dict) else None
    if last_failed and not focus_is_stale(last_failed) and last_failed.get("action_type") != "retry_last_failed_action":
        items = [last_failed, *items]
    deduped: list[dict[str, Any]] = []
    seen: set[tuple[str, str, str]] = set()
    for item in items:
        key = failed_action_identity(item)
        if key in seen:
            continue
        seen.add(key)
        deduped.append(item)
    return deduped[:5]


def persistent_context_pruned(context: dict[str, Any] | None) -> dict[str, Any]:
    current = dict(context or {})
    focus = current.get("focus") if isinstance(current.get("focus"), dict) else default_focus_context()
    for key in list(PERSISTENT_FOCUS_KEYS.values()):
        if focus_is_stale(focus.get(key)):
            focus[key] = None
    primary = focus.get("primary_entity")
    if focus_is_stale(primary):
        focus["primary_entity"] = None
    history = focus.get("focus_history") if isinstance(focus.get("focus_history"), list) else []
    focus["focus_history"] = [item for item in history if isinstance(item, dict) and not focus_is_stale(item)][:20]
    entity_sets = focus.get("entity_sets") if isinstance(focus.get("entity_sets"), dict) else {}
    merged_sets = empty_entity_sets()
    for key, value in entity_sets.items():
        if key in merged_sets and isinstance(value, list):
            merged_sets[key] = [item for item in value if isinstance(item, dict) and not focus_is_stale(item)][:20]
    focus["entity_sets"] = merged_sets
    current["focus"] = focus
    current_focus = current.get("current_focus")
    if isinstance(current_focus, dict) and focus_is_stale(current_focus):
        current["current_focus"] = None
    elif not isinstance(current_focus, dict):
        current["current_focus"] = current_focus_from_context_shape(current, focus)
    if not current.get("current_domain"):
        current["current_domain"] = current_domain_from_context_shape(current, current.get("current_focus") if isinstance(current.get("current_focus"), dict) else None)
    last_result_set = current.get("last_result_set")
    if isinstance(last_result_set, dict) and focus_is_stale(last_result_set):
        current["last_result_set"] = None
    last_action_result = current.get("last_action_result")
    if isinstance(last_action_result, dict) and focus_is_stale(last_action_result):
        current["last_action_result"] = None
    pending_action = current.get("pending_action")
    if isinstance(pending_action, dict) and focus_is_stale(pending_action):
        current["pending_action"] = None
    pending_confirmation = current.get("pending_confirmation")
    if isinstance(pending_confirmation, dict) and focus_is_stale(pending_confirmation):
        current["pending_confirmation"] = None
    pending_clarification = current.get("pending_clarification")
    if isinstance(pending_clarification, dict) and focus_is_stale(pending_clarification):
        current["pending_clarification"] = None
    offered_followup = current.get("offered_followup")
    if isinstance(offered_followup, dict) and focus_is_stale(offered_followup):
        current["offered_followup"] = None
    proposed_next_action = current.get("proposed_next_action")
    if isinstance(proposed_next_action, dict) and focus_is_stale(proposed_next_action):
        current["proposed_next_action"] = None
    last_failed_action = current.get("last_failed_action")
    if isinstance(last_failed_action, dict) and focus_is_stale(last_failed_action):
        current["last_failed_action"] = None
    last_successful_action = current.get("last_successful_action")
    if isinstance(last_successful_action, dict) and focus_is_stale(last_successful_action):
        current["last_successful_action"] = None
    history = current.get("failed_action_history") if isinstance(current.get("failed_action_history"), list) else []
    current["failed_action_history"] = [item for item in history if isinstance(item, dict) and not focus_is_stale(item)][:5]
    if isinstance(current.get("last_failed_action"), dict) and current["last_failed_action"].get("action_type") == "retry_last_failed_action":
        business_history = business_failed_action_history(current)
        current["last_failed_action"] = business_history[0] if business_history else None
        current["failed_action_history"] = business_history
    return current


def retry_clarification_action(text: str, context: dict[str, Any] | None) -> dict[str, Any] | None:
    current = persistent_context_pruned(context)
    pending = current.get("pending_action") if isinstance(current.get("pending_action"), dict) else None
    if not pending or pending.get("action_type") != "retry_last_failed_action":
        return None
    payload = pending.get("payload") if isinstance(pending.get("payload"), dict) else {}
    options = payload.get("failed_actions") if isinstance(payload.get("failed_actions"), list) else []
    options = [item for item in options if isinstance(item, dict) and not focus_is_stale(item)]
    if not options:
        return None
    normalized = normalize_text(text)
    matched: list[dict[str, Any]] = []
    for item in options:
        item_payload = item.get("payload") if isinstance(item.get("payload"), dict) else {}
        result_payload = item_payload.get("result") if isinstance(item_payload.get("result"), dict) else {}
        raw_payload = result_payload.get("payload") if isinstance(result_payload.get("payload"), dict) else result_payload
        haystack = normalize_text(json.dumps(json_safe({
            "action_type": item.get("action_type"),
            "channel": item.get("channel"),
            "target_id": item.get("target_id"),
            "target_name": item.get("target_name"),
            "payload": raw_payload,
        }), ensure_ascii=False))
        name = normalize_text(str(item.get("target_name") or ""))
        if name and name in normalized:
            matched.append(item)
            continue
        tokens = [token for token in re.findall(r"[a-z0-9]+", normalized) if token not in {"the", "one", "with", "cv", "candidate", "email", "retry", "it"}]
        if tokens and all(token in haystack for token in tokens):
            matched.append(item)
    deduped: list[dict[str, Any]] = []
    seen: set[tuple[str, str, str]] = set()
    for item in matched or options:
        key = (str(item.get("action_type") or ""), str(item.get("target_type") or ""), str(item.get("target_id") or ""))
        if key in seen:
            continue
        seen.add(key)
        deduped.append(item)
    if len(deduped) == 1:
        return {
            "action_type": "retry_last_failed_action",
            "subject_type": "action",
            "prompt_text": text,
            "selected_failed_action": json_safe(deduped[0]),
            "resolved_from_retry_clarification": True,
        }
    return None


def operational_context_pruned(context: dict[str, Any] | None) -> dict[str, Any]:
    return persistent_context_pruned(context)


def operational_focus(
    *,
    entity_type: str,
    key: str | None,
    display_name: str | None,
    company_code: str | None,
    source_action: str | None,
    confidence: str = "resolved",
    ttl_minutes: int = 90,
    extra: dict[str, Any] | None = None,
) -> dict[str, Any]:
    now = operational_context_timestamp()
    focus = {
        "entity_type": entity_type,
        "key": key,
        "display_name": display_name,
        "company_code": (company_code or "WATHEFNI").upper(),
        "source_action": source_action,
        "confidence": confidence,
        "updated_at": now,
        "expires_at": operational_context_timestamp(ttl_minutes),
    }
    if extra:
        focus.update(json_safe(extra))
    return focus


def candidate_focus_from_app(app: dict[str, Any] | None, *, source_action: str | None, confidence: str = "resolved") -> dict[str, Any] | None:
    if not app:
        return None
    contact = candidate_contact(app)
    key = str(app.get("app_key") or contact.get("app_key") or "").strip()
    if not key:
        return None
    return operational_focus(
        entity_type="candidate",
        key=key,
        display_name=contact.get("name") or app.get("candidate_name") or app.get("phone"),
        company_code=app.get("company_code"),
        source_action=source_action,
        confidence=confidence,
        extra={
            "app_key": key,
            "phone": contact.get("phone") or app.get("phone"),
            "email": contact.get("email"),
            "position_code": app.get("position_code"),
            "position_title": app.get("position_title"),
        },
    )


def employee_focus_from_employee(employee: dict[str, Any] | None, *, source_action: str | None, confidence: str = "resolved") -> dict[str, Any] | None:
    if not employee:
        return None
    key = str(employee.get("employee_key") or employee.get("phone") or "").strip()
    if not key:
        return None
    return operational_focus(
        entity_type="employee",
        key=key,
        display_name=employee.get("name") or employee.get("phone"),
        company_code=employee.get("company_code"),
        source_action=source_action,
        confidence=confidence,
        extra={
            "employee_key": employee.get("employee_key"),
            "phone": employee.get("phone"),
            "position_title": employee.get("position_title"),
            "app_key": employee.get("app_key"),
        },
    )


def leave_focus_from_leave(leave: dict[str, Any] | None, *, source_action: str | None, confidence: str = "resolved") -> dict[str, Any] | None:
    if not leave or not leave.get("leave_id"):
        return None
    return operational_focus(
        entity_type="leave_request",
        key=str(leave.get("leave_id")),
        display_name=leave.get("employee_name") or leave.get("subject_name") or "leave request",
        company_code=leave.get("company_code"),
        source_action=source_action,
        confidence=confidence,
        extra={
            "leave_id": str(leave.get("leave_id")),
            "employee_key": leave.get("employee_key"),
            "employee_phone": leave.get("employee_phone"),
            "start_date": json_safe(leave.get("start_date")),
            "end_date": json_safe(leave.get("end_date")),
            "status": leave.get("status"),
        },
    )


def shift_focus_from_payload(payload: dict[str, Any], *, source_action: str | None, confidence: str = "resolved") -> dict[str, Any] | None:
    shift = None
    for key in ("shift", "created", "cancelled", "updated_shifts", "conflicts"):
        value = payload.get(key)
        if isinstance(value, dict):
            shift = value
            break
        if isinstance(value, list) and value and isinstance(value[0], dict):
            shift = value[0]
            break
    if not shift or not (shift.get("shift_id") or shift.get("employee_key")):
        return None
    return operational_focus(
        entity_type="shift",
        key=str(shift.get("shift_id") or shift.get("employee_key")),
        display_name=shift.get("employee_name") or shift.get("name") or "shift",
        company_code=shift.get("company_code"),
        source_action=source_action,
        confidence=confidence,
        extra=json_safe({k: shift.get(k) for k in ("shift_id", "employee_key", "employee_phone", "shift_date", "start_time", "end_time", "status")}),
    )


def payroll_focus_from_payload(payload: dict[str, Any], *, source_action: str | None, confidence: str = "resolved") -> dict[str, Any] | None:
    candidates = []
    for key in ("timesheet", "payroll_export", "export"):
        if isinstance(payload.get(key), dict):
            candidates.append(payload[key])
    if isinstance(payload.get("timesheets"), list):
        candidates.extend(item for item in payload["timesheets"] if isinstance(item, dict))
    item = candidates[0] if candidates else None
    if not item or not (item.get("timesheet_id") or item.get("export_id") or item.get("employee_key")):
        return None
    key = str(item.get("timesheet_id") or item.get("export_id") or item.get("employee_key"))
    return operational_focus(
        entity_type="payroll_item",
        key=key,
        display_name=item.get("employee_name") or item.get("period_label") or "payroll item",
        company_code=item.get("company_code"),
        source_action=source_action,
        confidence=confidence,
        extra=json_safe(item),
    )


def set_operational_focus(context: dict[str, Any], focus: dict[str, Any] | None) -> dict[str, Any]:
    if not focus:
        return context
    out = persistent_context_pruned(context)
    focus_context = out.get("focus") if isinstance(out.get("focus"), dict) else default_focus_context()
    key = PERSISTENT_FOCUS_KEYS.get(str(focus.get("entity_type") or ""))
    if key:
        focus_context[key] = focus
    focus_context["primary_entity"] = focus
    entity_sets = focus_context.get("entity_sets") if isinstance(focus_context.get("entity_sets"), dict) else empty_entity_sets()
    set_key = {
        "candidate": "candidates",
        "employee": "employees",
        "job": "jobs",
        "shift": "shifts",
        "leave_request": "leave_requests",
        "assessment_attempt": "assessment_attempts",
        "report": "reports",
    }.get(str(focus.get("entity_type") or ""))
    if set_key:
        existing = entity_sets.get(set_key) if isinstance(entity_sets.get(set_key), list) else []
        entity_sets[set_key] = [focus, *[item for item in existing if isinstance(item, dict) and item.get("key") != focus.get("key")]][:20]
    focus_context["entity_sets"] = entity_sets
    history = focus_context.get("focus_history") if isinstance(focus_context.get("focus_history"), list) else []
    history = [focus, *[item for item in history if isinstance(item, dict) and item.get("key") != focus.get("key")]]
    focus_context["focus_history"] = history[:20]
    out["focus"] = focus_context
    return out


def followup_reference_in_text(text: str | None) -> bool:
    normalized = normalize_text(text)
    if not normalized:
        return False
    return bool(re.search(r"\b(him|her|them|he|she|they|it|that|this|same|that candidate|the candidate|that employee|the employee|do it|send it|approve it|reject it)\b", normalized))


def action_focus_type(action_type: str | None) -> str | None:
    action = str(action_type or "")
    if action in CANDIDATE_ACTIONS:
        return "candidate"
    if action in LEAVE_ACTIONS:
        return "leave_request"
    if action in SHIFT_ACTIONS:
        return "shift"
    if action in PAYROLL_ACTIONS:
        return "payroll_item"
    if action in EMPLOYEE_ACTIONS:
        return "employee"
    return None


def focus_for_action(context: dict[str, Any], action_type: str | None) -> dict[str, Any] | None:
    focus_type = action_focus_type(action_type)
    if not focus_type:
        return None
    focus_context = context.get("focus") if isinstance(context.get("focus"), dict) else {}
    focus = focus_context.get(PERSISTENT_FOCUS_KEYS[focus_type])
    if isinstance(focus, dict) and not focus_is_stale(focus):
        return focus
    entity_sets = focus_context.get("entity_sets") if isinstance(focus_context.get("entity_sets"), dict) else {}
    set_key = {
        "candidate": "candidates",
        "employee": "employees",
        "shift": "shifts",
        "leave_request": "leave_requests",
        "assessment_attempt": "assessment_attempts",
        "report": "reports",
    }.get(focus_type)
    compatible = [item for item in entity_sets.get(set_key, []) if isinstance(item, dict) and not focus_is_stale(item)] if set_key else []
    if len(compatible) == 1:
        return compatible[0]
    if focus_type == "employee":
        candidate = focus_context.get("current_candidate")
        if isinstance(candidate, dict) and not focus_is_stale(candidate):
            return candidate
    return None


def action_has_explicit_subject(action: dict[str, Any]) -> bool:
    subject_name = normalize_text(str(action.get("subject_name") or ""))
    has_pronoun_name = subject_name in {"him", "her", "them", "he", "she", "they", "it", "that", "this", "candidate", "employee"}
    return bool(
        action.get("app_key")
        or action.get("subject_key")
        or action.get("leave_id")
        or action.get("shift_id")
        or action.get("timesheet_id")
        or action.get("subject_phone")
        or (subject_name and not has_pronoun_name)
    )


def bind_focus_to_action(action: dict[str, Any] | None, context: dict[str, Any] | None, text: str | None) -> dict[str, Any] | None:
    if not action:
        return None
    if action_has_explicit_subject(action) or (not followup_reference_in_text(text) and not is_action_correction_to_email(text)):
        return action
    focus = focus_for_action(operational_context_pruned(context), action.get("action_type"))
    if not focus:
        return action
    bound = dict(action)
    bound["resolved_from_operational_context"] = True
    bound["operational_focus"] = json_safe(focus)
    entity_type = str(focus.get("entity_type") or "")
    if entity_type == "candidate":
        bound["subject_type"] = "candidate"
        bound["app_key"] = focus.get("app_key") or focus.get("key")
        bound["subject_key"] = focus.get("app_key") or focus.get("key")
        bound["subject_name"] = focus.get("display_name")
        bound["subject_phone"] = focus.get("phone")
        bound["selected_application"] = json_safe(focus)
    elif entity_type == "employee":
        bound["subject_type"] = "employee"
        bound["subject_key"] = focus.get("employee_key") or focus.get("key")
        bound["subject_name"] = focus.get("display_name")
        bound["subject_phone"] = focus.get("phone")
    elif entity_type == "leave_request":
        bound["subject_type"] = "leave"
        bound["leave_id"] = focus.get("leave_id") or focus.get("key")
        bound["subject_name"] = focus.get("display_name")
        bound["subject_phone"] = focus.get("employee_phone")
    elif entity_type == "shift":
        bound["subject_type"] = "shift"
        bound["shift_id"] = focus.get("shift_id") or focus.get("key")
        bound["subject_name"] = focus.get("display_name")
        bound["subject_phone"] = focus.get("employee_phone")
    elif entity_type == "payroll_item":
        bound["subject_type"] = "timesheet"
        bound["timesheet_id"] = focus.get("timesheet_id") or focus.get("key")
        bound["subject_name"] = focus.get("display_name")
    return bound


def candidate_focus_for_context(context: dict[str, Any] | None) -> dict[str, Any] | None:
    focus_context = (persistent_context_pruned(context).get("focus") if context else {}) or {}
    candidate = focus_context.get("current_candidate") if isinstance(focus_context, dict) else None
    if isinstance(candidate, dict) and not focus_is_stale(candidate):
        return candidate
    primary = focus_context.get("primary_entity") if isinstance(focus_context, dict) else None
    if isinstance(primary, dict) and primary.get("entity_type") == "candidate" and not focus_is_stale(primary):
        return primary
    return None


def action_from_candidate_focus(action_type: str, focus: dict[str, Any], text: str, *, planned_by: str) -> dict[str, Any]:
    return {
        "action_type": action_type,
        "subject_type": "candidate",
        "app_key": focus.get("app_key") or focus.get("key"),
        "subject_key": focus.get("app_key") or focus.get("key"),
        "subject_name": focus.get("display_name"),
        "subject_phone": focus.get("phone"),
        "prompt_text": text,
        "query": text,
        "planned_by": planned_by,
        "resolved_from_operational_context": True,
        "operational_focus": json_safe(focus),
        "selected_application": json_safe(focus),
        "resolved_entities": {"candidate": json_safe(focus)},
    }


def candidate_action_has_target(action: dict[str, Any] | None) -> bool:
    if not isinstance(action, dict) or action.get("action_type") not in CANDIDATE_ACTIONS | {"reject_candidate"}:
        return False
    return bool(action.get("app_key") or action.get("subject_key") or action.get("subject_phone") or action.get("selected_application"))


def capability_decision_dict(
    *,
    status: str,
    proposal: dict[str, Any],
    supported: bool = False,
    action: dict[str, Any] | None = None,
    reply: str | None = None,
    validation: dict[str, Any] | None = None,
) -> dict[str, Any]:
    decision = CapabilityDecision(
        status=status,
        capability=proposal.get("capability"),
        supported=supported,
        action=action,
        reply=reply,
        proposal=json_safe(proposal),
        validation=json_safe(validation or {}),
    )
    return pydantic_model_dict(decision)


def pending_clarification_from_context(context: dict[str, Any] | None) -> dict[str, Any] | None:
    current = persistent_context_pruned(context)
    pending = current.get("pending_clarification") if isinstance(current.get("pending_clarification"), dict) else None
    return pending if pending and not focus_is_stale(pending) else None


def clear_pending_clarification(context: dict[str, Any] | None) -> dict[str, Any]:
    current = persistent_context_pruned(context)
    current["pending_clarification"] = None
    return current


def set_pending_clarification(context: dict[str, Any] | None, clarification: dict[str, Any] | None) -> dict[str, Any]:
    current = persistent_context_pruned(context)
    current["pending_clarification"] = json_safe(clarification) if clarification else None
    return current


def pending_clarification_from_capability_decision(
    decision: dict[str, Any] | None,
    request: WhatsAppTurnRequest,
) -> dict[str, Any] | None:
    if not isinstance(decision, dict) or decision.get("status") != "needs_clarification":
        return None
    validation = decision.get("validation") if isinstance(decision.get("validation"), dict) else {}
    proposal = decision.get("proposal") if isinstance(decision.get("proposal"), dict) else {}
    if decision.get("capability") != "compare_evaluate" or validation.get("reason") != "ambiguous_compare_target":
        return None
    target = validation.get("target") if isinstance(validation.get("target"), dict) else {}
    matches = [item for item in validation.get("matches", []) if isinstance(item, dict)]
    if not target or not matches:
        return None
    return {
        "clarification_id": str(request.metadata.get("turn_id") if isinstance(request.metadata, dict) and request.metadata.get("turn_id") else ""),
        "kind": "resolve_ambiguous_compare_target",
        "original_intent": "capability_request",
        "original_capability": "compare_evaluate",
        "original_proposal": json_safe(proposal),
        "ambiguous_ref": compare_target_ref_text(target),
        "ambiguous_target": json_safe(target),
        "options": json_safe(matches),
        "resolved_candidates": json_safe(validation.get("resolved_candidates") if isinstance(validation.get("resolved_candidates"), list) else []),
        "attempt_count": 0,
        "source_turn_id": None,
        "created_at": operational_context_timestamp(),
        "updated_at": operational_context_timestamp(),
        "expires_at": operational_context_timestamp(30),
    }


def clarification_option_score(text: str, option: dict[str, Any], index: int) -> float:
    normalized = normalize_text(text)
    if not normalized:
        return 0.0
    ordinals = {
        "1": 0,
        "one": 0,
        "first": 0,
        "2": 1,
        "two": 1,
        "second": 1,
        "3": 2,
        "three": 2,
        "third": 2,
        "4": 3,
        "four": 3,
        "fourth": 3,
    }
    if ordinals.get(normalized) == index:
        return 1.0
    values = [
        option.get("position_code"),
        option.get("position_title"),
        option.get("status"),
        option.get("candidate_name"),
        option.get("app_key"),
    ]
    best = 0.0
    for value in values:
        label = normalize_text(str(value or "").replace("_", " "))
        if not label:
            continue
        if normalized == label:
            best = max(best, 1.0)
        elif re.search(rf"\b{re.escape(normalized)}\b", label):
            best = max(best, 0.86)
        elif re.search(rf"\b{re.escape(label)}\b", normalized):
            best = max(best, 0.78)
    return best


def choose_clarification_option(text: str, options: list[dict[str, Any]]) -> tuple[dict[str, Any] | None, dict[str, Any] | None]:
    scored = [(clarification_option_score(text, option, idx), option) for idx, option in enumerate(options)]
    scored = [(score, option) for score, option in scored if score >= 0.78]
    if not scored:
        return None, {"reason": "no_matching_option"}
    scored.sort(key=lambda item: item[0], reverse=True)
    if len(scored) > 1 and scored[0][0] == scored[1][0]:
        return None, {"reason": "ambiguous_clarification_option", "matches": [item[1] for item in scored if item[0] == scored[0][0]]}
    return scored[0][1], None


def resolve_pending_compare_clarification(
    request: WhatsAppTurnRequest,
    context: dict[str, Any] | None,
    pending: dict[str, Any],
) -> dict[str, Any]:
    options = [item for item in pending.get("options", []) if isinstance(item, dict)]
    selected, issue = choose_clarification_option(request.raw_text, options)
    if issue:
        attempt_count = int(pending.get("attempt_count") or 0) + 1
        pending = {**pending, "attempt_count": attempt_count, "updated_at": operational_context_timestamp()}
        if attempt_count >= 2:
            return capability_decision_dict(
                status="needs_clarification",
                proposal=pending.get("original_proposal") if isinstance(pending.get("original_proposal"), dict) else {"capability": "none"},
                reply=clarification_limit_menu_reply(),
                validation={"reason": "clarification_attempts_exceeded", "pending_clarification": json_safe(pending)},
            )
        return capability_decision_dict(
            status="needs_clarification",
            proposal=pending.get("original_proposal") if isinstance(pending.get("original_proposal"), dict) else {"capability": "compare_evaluate"},
            reply="I still need you to pick one of the listed options.",
            validation={"reason": issue.get("reason"), "pending_clarification": json_safe(pending), **({"matches": json_safe(issue.get("matches"))} if issue.get("matches") else {})},
        )
    proposal = pending.get("original_proposal") if isinstance(pending.get("original_proposal"), dict) else {}
    raw_targets = [
        target for target in normalized_compare_capability_targets(request, proposal)
        if not (isinstance(target, dict) and target.get("source") == "message_compare_targets")
    ]
    ambiguous_ref = normalize_text(str(pending.get("ambiguous_ref") or ""))
    candidates: list[dict[str, Any]] = []
    seen: set[str] = set()
    for raw_target in raw_targets:
        ref_text = compare_target_ref_text(raw_target)
        app = None
        if normalize_text(ref_text) == ambiguous_ref:
            app = selected
        elif compare_target_uses_current_focus(raw_target):
            current_focus = candidate_focus_for_context(context)
            app_key = (current_focus or {}).get("app_key") or (current_focus or {}).get("key")
            app = find_application_by_key(str(app_key), company_code=request_company_code(request)) if app_key else None
        elif ref_text:
            resolution = resolve_candidate_reference_from_text(ref_text, company_code=request_company_code(request))
            if resolution.get("status") == "resolved" and isinstance(resolution.get("application"), dict):
                app = resolution["application"]
            elif resolution.get("status") == "ambiguous":
                return capability_decision_dict(
                    status="needs_clarification",
                    proposal=proposal,
                    reply=candidate_clarification_reply([item for item in resolution.get("matches", []) if isinstance(item, dict)], action_type="compare_candidates"),
                    validation={"reason": "ambiguous_compare_target", "target": json_safe(raw_target), "matches": [candidate_lookup_match_payload(item) for item in resolution.get("matches", []) if isinstance(item, dict)], "resolved_candidates": json_safe(candidates)},
                )
        if not app:
            return capability_decision_dict(
                status="needs_clarification",
                proposal=proposal,
                reply=f"I can continue, but I could not match `{ref_text or 'that candidate'}` to a stored candidate.",
                validation={"reason": "compare_target_not_found", "target": json_safe(raw_target), "resolved_candidates": json_safe(candidates)},
            )
        payload = candidate_lookup_match_payload(app)
        key = str(payload.get("app_key") or payload.get("key") or "")
        if key and key not in seen:
            seen.add(key)
            candidates.append(payload)
    if len(candidates) < 2:
        return capability_decision_dict(
            status="needs_clarification",
            proposal=proposal,
            reply="I can compare them, but I need at least two clear candidate records.",
            validation={"reason": "not_enough_compare_targets", "resolved_candidates": json_safe(candidates)},
        )
    action = {
        "action_type": "compare_candidates",
        "subject_type": "candidate",
        "prompt_text": request.raw_text,
        "query": str(proposal.get("query") or request.raw_text),
        "planned_by": "pending_clarification",
        "capability": "compare_evaluate",
        "capability_proposal": json_safe(proposal),
        "capability_validated": True,
        "candidate_ids": [item.get("app_key") for item in candidates if item.get("app_key")],
        "candidates": json_safe(candidates[:5]),
        "resolved_entities": {"candidates": json_safe(candidates[:5])},
        "resolved_from_pending_clarification": True,
    }
    return capability_decision_dict(status="action", proposal=proposal, supported=True, action=action, validation={"compiled_action_type": "compare_candidates", "target_count": len(candidates), "resolved_clarification": json_safe(pending)})


def clarification_limit_menu_reply() -> str:
    return (
        "No worries. Let’s reset so I don’t keep guessing.\n"
        "You can ask me to:\n"
        "- show or rank candidates\n"
        "- compare candidates\n"
        "- send assessments or emails\n"
        "- handle leave, attendance, shifts, or payroll"
    )


def resolve_pending_clarification_context(
    request: WhatsAppTurnRequest,
    context: dict[str, Any] | None,
) -> dict[str, Any] | None:
    pending = pending_clarification_from_context(context)
    if not pending:
        return None
    if pending.get("kind") == "resolve_ambiguous_compare_target":
        return resolve_pending_compare_clarification(request, context, pending)
    return capability_decision_dict(
        status="needs_clarification",
        proposal=pending.get("original_proposal") if isinstance(pending.get("original_proposal"), dict) else {"capability": "none"},
        reply="I still need clarification before I continue.",
        validation={"reason": "unsupported_pending_clarification", "pending_clarification": json_safe(pending)},
    )


def capability_actor_can_mutate(request: WhatsAppTurnRequest) -> bool:
    return request.sender_role == "hr_admin" or is_hr_phone(request.sender_phone)


def capability_action_module_enabled(action_type: str, company_code: str | None) -> tuple[bool, dict[str, Any]]:
    required = required_module_for_action(action_type)
    if required and not company_has_module(company_code, required):
        return False, {
            "reason": "module_disabled",
            "required_module": required,
            "enabled_modules": sorted(configured_company_modules(company_code)),
        }
    return True, {}


def candidate_focus_from_action(action: dict[str, Any] | None, *, source_action: str | None) -> dict[str, Any] | None:
    if not isinstance(action, dict):
        return None
    selected = action.get("selected_application") if isinstance(action.get("selected_application"), dict) else {}
    if selected.get("app_key") or selected.get("key"):
        return operational_focus(
            entity_type="candidate",
            key=selected.get("app_key") or selected.get("key"),
            display_name=selected.get("candidate_name") or selected.get("name") or selected.get("display_name"),
            company_code=selected.get("company_code"),
            source_action=source_action,
            extra={
                "app_key": selected.get("app_key") or selected.get("key"),
                "phone": selected.get("phone"),
                "email": selected.get("email") or selected.get("candidate_email"),
                "position_title": selected.get("position_title"),
                "position_code": selected.get("position_code"),
            },
        )
    app_key = str(action.get("app_key") or action.get("subject_key") or "").strip()
    if app_key:
        company_code = action.get("company_code")
        return candidate_focus_from_app(find_application_by_key(app_key, company_code=company_code), source_action=source_action)
    return None


def capability_target_candidate(
    request: WhatsAppTurnRequest,
    context: dict[str, Any] | None,
    proposal: dict[str, Any],
    *,
    direct_action: dict[str, Any] | None = None,
) -> tuple[dict[str, Any] | None, dict[str, Any] | None]:
    action_focus = candidate_focus_from_action(direct_action, source_action="capability_existing_action")
    if action_focus:
        return action_focus, None
    current_focus = candidate_focus_for_context(context)
    target_ref = normalize_capability_name(proposal.get("target_ref"))
    if current_focus and (target_ref in {"", "current_candidate", "him", "her", "them", "this_candidate", "that_candidate", "the_candidate"} or followup_reference_in_text(request.raw_text)):
        return current_focus, None
    target_text = str(proposal.get("target_text") or "").strip()
    if target_ref == "explicit" or target_text:
        resolution = resolve_candidate_reference_from_text(target_text or request.raw_text, company_code=request_company_code(request))
        if resolution.get("status") == "resolved" and isinstance(resolution.get("application"), dict):
            focus = candidate_focus_from_app(resolution.get("application"), source_action="capability_resolution", confidence="current_message")
            return focus, None
        if resolution.get("status") == "ambiguous":
            return None, capability_decision_dict(
                status="needs_clarification",
                proposal=proposal,
                reply=candidate_clarification_reply([item for item in resolution.get("matches", []) if isinstance(item, dict)], action_type=None),
                validation={"reason": "ambiguous_candidate", "matches": [candidate_lookup_match_payload(item) for item in resolution.get("matches", []) if isinstance(item, dict)]},
            )
    return None, capability_decision_dict(
        status="needs_clarification",
        proposal=proposal,
        reply="I can do that, but I need to confirm which candidate you mean.",
        validation={"reason": "missing_candidate_target"},
    )


def action_from_capability_candidate(
    action_type: str,
    focus: dict[str, Any],
    request: WhatsAppTurnRequest,
    proposal: dict[str, Any],
) -> dict[str, Any]:
    action = action_from_candidate_focus(action_type, focus, request.raw_text, planned_by="capability_framework")
    action.update(
        {
            "capability": proposal.get("capability"),
            "capability_proposal": json_safe(proposal),
            "capability_validated": True,
            "planner_confidence": proposal.get("confidence"),
            "planner_reason": proposal.get("reason"),
        }
    )
    if proposal.get("purpose"):
        action["purpose"] = proposal.get("purpose")
    if proposal.get("channel"):
        action["channel"] = proposal.get("channel")
    return action


def validate_send_message_capability(
    request: WhatsAppTurnRequest,
    context: dict[str, Any] | None,
    proposal: dict[str, Any],
    *,
    direct_action: dict[str, Any] | None,
) -> dict[str, Any] | None:
    if not capability_actor_can_mutate(request):
        return capability_decision_dict(status="unsupported", proposal=proposal, reply="Only an HR admin can send candidate messages from WhatsApp.", validation={"reason": "permission_denied"})
    channel = normalize_capability_name(proposal.get("channel") or "email")
    if channel != "email":
        return capability_decision_dict(status="unsupported", proposal=proposal, reply="For candidates, this capability currently supports email from WhatsApp. WhatsApp candidate notes/messages need a dedicated backend path first.", validation={"reason": "unsupported_channel", "channel": channel})
    focus, issue = capability_target_candidate(request, context, proposal, direct_action=direct_action)
    if issue:
        return issue
    if not focus:
        return None
    purpose = normalize_capability_name(proposal.get("purpose") or capability_purpose_from_text(request.raw_text))
    if purpose not in CAPABILITY_EMAIL_PURPOSES:
        return capability_decision_dict(status="unsupported", proposal=proposal, reply=f"I can email the candidate, but `{purpose}` is not a supported email purpose yet.", validation={"reason": "unsupported_purpose", "purpose": purpose})
    action = action_from_capability_candidate("send_email", focus, request, {**proposal, "purpose": purpose, "channel": "email"})
    enabled, module_issue = capability_action_module_enabled("send_email", request_company_code(request))
    if not enabled:
        return capability_decision_dict(status="unsupported", proposal=proposal, reply=module_disabled_reply(request_company_code(request), module_issue.get("required_module")), validation=module_issue)
    return capability_decision_dict(status="action", proposal=proposal, supported=True, action=action, validation={"compiled_action_type": "send_email"})


def validate_change_stage_capability(
    request: WhatsAppTurnRequest,
    context: dict[str, Any] | None,
    proposal: dict[str, Any],
    *,
    direct_action: dict[str, Any] | None,
) -> dict[str, Any] | None:
    if not capability_actor_can_mutate(request):
        return capability_decision_dict(status="unsupported", proposal=proposal, reply="Only an HR admin can change a candidate stage from WhatsApp.", validation={"reason": "permission_denied"})
    stage = normalize_capability_name(proposal.get("new_stage") or proposal.get("stage") or "")
    action_type = CAPABILITY_STAGE_ACTIONS.get(stage)
    if not action_type:
        inferred = candidate_mutation_action_type_from_text(request.raw_text)
        action_type = inferred if inferred in {"shortlist_candidate", "hire_candidate", "reject_candidate"} else None
    if not action_type:
        return capability_decision_dict(status="needs_clarification", proposal=proposal, reply="Which stage should I set for the candidate: shortlisted, hired, or rejected?", validation={"reason": "missing_or_unsupported_stage", "new_stage": stage})
    enabled, module_issue = capability_action_module_enabled(action_type, request_company_code(request))
    if not enabled:
        return capability_decision_dict(status="unsupported", proposal=proposal, reply=module_disabled_reply(request_company_code(request), module_issue.get("required_module")), validation=module_issue)
    focus, issue = capability_target_candidate(request, context, proposal, direct_action=direct_action)
    if issue:
        return issue
    if not focus:
        return None
    action = action_from_capability_candidate(action_type, focus, request, proposal)
    return capability_decision_dict(status="action", proposal=proposal, supported=True, action=action, validation={"compiled_action_type": action_type})


def validate_update_record_capability(
    request: WhatsAppTurnRequest,
    context: dict[str, Any] | None,
    proposal: dict[str, Any],
    *,
    direct_action: dict[str, Any] | None,
) -> dict[str, Any] | None:
    if not capability_actor_can_mutate(request):
        return capability_decision_dict(status="unsupported", proposal=proposal, reply="Only an HR admin can update candidate records from WhatsApp.", validation={"reason": "permission_denied"})
    entity_type = normalize_capability_name(proposal.get("entity_type") or "candidate")
    field = normalize_capability_name(proposal.get("field"))
    if entity_type != "candidate":
        return None
    if field not in CAPABILITY_SUPPORTED_FIELDS["candidate"]:
        return capability_decision_dict(status="unsupported", proposal=proposal, reply="For candidates, I can only interpret notes updates in this v1 capability layer.", validation={"reason": "unsupported_field", "field": field})
    focus, issue = capability_target_candidate(request, context, proposal, direct_action=direct_action)
    if issue:
        return issue
    if not focus:
        return None
    if not str(proposal.get("value") or "").strip():
        return capability_decision_dict(status="needs_clarification", proposal=proposal, reply=f"What note should I add for {focus.get('display_name') or 'this candidate'}?", validation={"reason": "missing_value", "field": field})
    return capability_decision_dict(
        status="unsupported",
        proposal=proposal,
        reply="Candidate notes are not editable from WhatsApp yet. You can do that from the dashboard.",
        validation={"reason": "candidate_notes_not_whatsapp_editable_yet", "target": json_safe(focus), "field": field, "value": proposal.get("value")},
    )


def compare_target_uses_current_focus(target: dict[str, Any]) -> bool:
    ref = normalize_capability_name(target.get("ref") or target.get("target_ref") or target.get("text"))
    hint = normalize_capability_name(target.get("resolution_hint") or target.get("hint") or target.get("target_ref"))
    target_type = normalize_capability_name(target.get("type"))
    return bool(
        hint == "current_candidate"
        or target_type in {"pronoun", "current_candidate"}
        or ref in {"him", "her", "them", "he", "she", "current_candidate", "this_candidate", "that_candidate", "the_candidate"}
    )


def compare_target_ref_text(target: dict[str, Any]) -> str:
    for key in ("ref", "target_text", "text", "name", "value"):
        value = str(target.get(key) or "").strip()
        if value:
            return value
    return ""


COMPARE_TARGET_STOPWORDS = {
    "and",
    "or",
    "to",
    "with",
    "against",
    "versus",
    "vs",
    "between",
    "candidate",
    "candidates",
    "applicant",
    "applicants",
}


def compare_target_refs_from_message(text: str) -> list[str]:
    raw = re.sub(r"\s+", " ", str(text or "").replace("…", " ")).strip()
    if not raw:
        return []
    match = re.search(r"\b(?:compare|versus|vs|against|better|which)\b\s*(.+)$", raw, re.I)
    segment = match.group(1) if match else raw
    segment = re.sub(r"\b(?:pls|please|can|could|would|u|you|me|for|the|a|an)\b", " ", segment, flags=re.I)
    segment = re.sub(r"\b(?:to|with|against|versus|vs|and|between)\b|[,&/]+", ",", segment, flags=re.I)
    refs: list[str] = []
    seen: set[str] = set()
    for part in segment.split(","):
        cleaned = re.sub(r"[^A-Za-z0-9\u0600-\u06FF\s.'’_-]", " ", part)
        cleaned = re.sub(r"\s+", " ", cleaned).strip(" .")
        if not cleaned:
            continue
        pieces = [cleaned]
        words = cleaned.split()
        if 1 < len(words) <= 4:
            pieces = words
        for piece in pieces:
            normalized = normalize_text(piece)
            if not normalized or normalized in COMPARE_TARGET_STOPWORDS or len(normalized) < 2:
                continue
            if normalized not in seen:
                seen.add(normalized)
                refs.append(piece.strip())
    return refs[:8]


def normalized_compare_capability_targets(request: WhatsAppTurnRequest, proposal: dict[str, Any]) -> list[dict[str, Any]]:
    raw_targets = proposal.get("targets") if isinstance(proposal.get("targets"), list) else []
    merged: list[dict[str, Any]] = []
    seen: set[str] = set()

    def add_target(target: dict[str, Any]) -> None:
        ref = compare_target_ref_text(target)
        key = normalize_capability_name(ref or target.get("resolution_hint") or target.get("target_ref"))
        if not key or key in seen:
            return
        seen.add(key)
        merged.append(target)

    for raw_target in raw_targets:
        if not isinstance(raw_target, dict):
            continue
        if compare_target_uses_current_focus(raw_target):
            add_target(raw_target)
            continue
        ref_text = compare_target_ref_text(raw_target)
        split_refs = compare_target_refs_from_message(ref_text)
        if split_refs and len(split_refs) > 1:
            for ref in split_refs:
                add_target({"ref": ref, "type": raw_target.get("type") or "candidate_name", "source": "compare_target_split"})
        else:
            add_target(raw_target)

    for ref in compare_target_refs_from_message(request.raw_text):
        add_target({"ref": ref, "type": "candidate_name", "source": "message_compare_targets"})

    return merged


def resolve_compare_capability_targets(
    request: WhatsAppTurnRequest,
    context: dict[str, Any] | None,
    proposal: dict[str, Any],
) -> tuple[list[dict[str, Any]], dict[str, Any] | None]:
    raw_targets = normalized_compare_capability_targets(request, proposal)
    if not raw_targets:
        if proposal.get("target_ref") or proposal.get("target_text"):
            raw_targets = [{"ref": proposal.get("target_text") or proposal.get("target_ref"), "resolution_hint": proposal.get("target_ref")}]
        elif followup_reference_in_text(request.raw_text):
            raw_targets = [{"ref": "him", "resolution_hint": "current_candidate", "type": "pronoun"}]
    resolved: list[dict[str, Any]] = []
    seen: set[str] = set()
    current_focus = candidate_focus_for_context(context)
    for raw_target in raw_targets:
        if not isinstance(raw_target, dict):
            continue
        app = None
        if compare_target_uses_current_focus(raw_target):
            app_key = (current_focus or {}).get("app_key") or (current_focus or {}).get("key")
            app = find_application_by_key(str(app_key), company_code=request_company_code(request)) if app_key else None
            if not app and app_key:
                app = {
                    "app_key": app_key,
                    "phone": (current_focus or {}).get("phone"),
                    "candidate_name": (current_focus or {}).get("display_name"),
                    "candidate_email": (current_focus or {}).get("email"),
                    "position_title": (current_focus or {}).get("position_title"),
                    "position_code": (current_focus or {}).get("position_code"),
                    "company_code": (current_focus or {}).get("company_code"),
                }
        else:
            ref_text = compare_target_ref_text(raw_target)
            if not ref_text:
                continue
            resolution = resolve_candidate_reference_from_text(ref_text, company_code=request_company_code(request))
            if resolution.get("status") == "resolved" and isinstance(resolution.get("application"), dict):
                app = resolution["application"]
            elif resolution.get("status") == "ambiguous":
                return resolved, capability_decision_dict(
                    status="needs_clarification",
                    proposal=proposal,
                    reply=candidate_clarification_reply([item for item in resolution.get("matches", []) if isinstance(item, dict)], action_type="compare_candidates"),
                    validation={
                        "reason": "ambiguous_compare_target",
                        "target": json_safe(raw_target),
                        "matches": [candidate_lookup_match_payload(item) for item in resolution.get("matches", []) if isinstance(item, dict)],
                        "resolved_candidates": json_safe(resolved),
                    },
                )
        if not app:
            return resolved, capability_decision_dict(
                status="needs_clarification",
                proposal=proposal,
                reply=f"I can compare them, but I could not match `{compare_target_ref_text(raw_target) or 'that candidate'}` to a stored candidate. Which candidate did you mean?",
                validation={"reason": "compare_target_not_found", "target": json_safe(raw_target)},
            )
        payload = candidate_lookup_match_payload(app)
        key = str(payload.get("app_key") or payload.get("key") or "")
        if key and key not in seen:
            seen.add(key)
            resolved.append(payload)
    return resolved, None


def validate_compare_evaluate_capability(
    request: WhatsAppTurnRequest,
    context: dict[str, Any] | None,
    proposal: dict[str, Any],
    *,
    direct_action: dict[str, Any] | None,
) -> dict[str, Any] | None:
    filters = proposal.get("filters") if isinstance(proposal.get("filters"), dict) else {}
    operation = normalize_capability_name(proposal.get("operation") or "")
    if not operation and re.search(r"\b(compare|versus|vs|against|better|to)\b", normalize_text(request.raw_text)):
        operation = "compare"
    if operation == "compare":
        action_type = "compare_candidates"
    else:
        action_type = "candidate_cv_evaluation"
    enabled, module_issue = capability_action_module_enabled(action_type, request_company_code(request))
    if not enabled:
        return capability_decision_dict(status="unsupported", proposal=proposal, reply=module_disabled_reply(request_company_code(request), module_issue.get("required_module")), validation=module_issue)
    if action_type == "compare_candidates":
        candidates, issue = resolve_compare_capability_targets(request, context, proposal)
        if issue:
            return issue
        if len(candidates) < 2:
            return capability_decision_dict(
                status="needs_clarification",
                proposal=proposal,
                reply="I can compare them, but I need at least two clear candidate records. Which candidates should I compare?",
                validation={"reason": "not_enough_compare_targets", "resolved_candidates": json_safe(candidates)},
            )
        action = {
            "action_type": "compare_candidates",
            "subject_type": "candidate",
            "prompt_text": request.raw_text,
            "query": request.raw_text,
            "planned_by": "capability_framework",
            "capability": proposal.get("capability"),
            "capability_proposal": json_safe(proposal),
            "capability_validated": True,
            "candidate_ids": [item.get("app_key") for item in candidates if item.get("app_key")],
            "candidates": json_safe(candidates[:5]),
            "resolved_entities": {"candidates": json_safe(candidates[:5])},
        }
        return capability_decision_dict(status="action", proposal=proposal, supported=True, action=action, validation={"compiled_action_type": "compare_candidates", "target_count": len(candidates)})
    focus = None
    if followup_reference_in_text(request.raw_text) or proposal.get("target_ref") == "current_candidate":
        focus, issue = capability_target_candidate(request, context, proposal, direct_action=direct_action)
        if issue:
            return issue
    action = action_from_capability_candidate(action_type, focus, request, proposal) if focus else {
        "action_type": action_type,
        "subject_type": "candidate",
        "prompt_text": request.raw_text,
        "query": request.raw_text,
        "planned_by": "capability_framework",
        "capability": proposal.get("capability"),
        "capability_proposal": json_safe(proposal),
        "capability_validated": True,
    }
    if filters:
        normalized_filters, unsupported, invalid = normalized_planner_refinement_filters(filters, action_type=action_type, company_code=request_company_code(request))
        if unsupported or invalid:
            return capability_decision_dict(status="unsupported", proposal=proposal, reply="I can evaluate candidates using stored data, but that filter is not valid for this view.", validation={"unsupported": unsupported, "invalid": invalid})
        action.update(normalized_filters)
    return capability_decision_dict(status="action", proposal=proposal, supported=True, action=action, validation={"compiled_action_type": action_type})


def validate_filter_refine_capability(request: WhatsAppTurnRequest, context: dict[str, Any] | None, proposal: dict[str, Any]) -> dict[str, Any] | None:
    latest = latest_successful_analytical_action(request, context)
    if not latest:
        return None
    action_type = str(latest.get("action_type") or "")
    if not is_supported_analytical_action(action_type):
        return None
    payload = latest.get("payload") if isinstance(latest.get("payload"), dict) else {}
    base_action = payload.get("action") if isinstance(payload.get("action"), dict) else {}
    if not base_action:
        base_action = {"action_type": action_type, "prompt_text": request.raw_text, "query": request.raw_text}
    filters = proposal.get("filters") if isinstance(proposal.get("filters"), dict) else {}
    normalized_filters, unsupported, invalid = normalized_planner_refinement_filters(filters, action_type=action_type, company_code=request_company_code(request))
    if unsupported or invalid:
        return capability_decision_dict(status="unsupported", proposal=proposal, reply="I can refine that by role/job, stage/status, top count, period, branch, or team. That filter is not valid for the previous result.", validation={"unsupported": unsupported, "invalid": invalid})
    if not normalized_filters:
        refined_action, metadata = merge_analytical_refinement(base_action, request.raw_text, action_type=action_type, company_code=request_company_code(request), source="capability_rules")
    else:
        refined_action, metadata = merge_analytical_refinement(base_action, request.raw_text, action_type=action_type, company_code=request_company_code(request), filters=normalized_filters, source="capability_planner")
    if refined_action:
        refined_action["capability"] = "filter_refine"
        refined_action["capability_proposal"] = json_safe(proposal)
        refined_action["capability_validated"] = True
        return capability_decision_dict(status="action", proposal=proposal, supported=True, action=refined_action, validation={"compiled_action_type": action_type, "filters": metadata.get("filters")})
    return capability_decision_dict(status="needs_clarification", proposal=proposal, reply="Which filter should I apply to the previous result?", validation={"reason": "missing_supported_filter"})


def validate_capability_proposal(
    request: WhatsAppTurnRequest,
    context: dict[str, Any] | None,
    proposal: dict[str, Any],
    *,
    direct_action: dict[str, Any] | None = None,
) -> dict[str, Any] | None:
    if not proposal:
        return None
    capability = normalize_capability_name(proposal.get("capability"))
    if capability not in CAPABILITY_REGISTRY:
        return None
    if planner_confidence(proposal.get("confidence")) < CAPABILITY_CONFIDENCE_THRESHOLD:
        return None
    if capability == "send_message":
        return validate_send_message_capability(request, context, proposal, direct_action=direct_action)
    if capability == "change_stage":
        return validate_change_stage_capability(request, context, proposal, direct_action=direct_action)
    if capability == "update_record":
        return validate_update_record_capability(request, context, proposal, direct_action=direct_action)
    if capability == "compare_evaluate":
        return validate_compare_evaluate_capability(request, context, proposal, direct_action=direct_action)
    if capability == "filter_refine":
        return validate_filter_refine_capability(request, context, proposal)
    if capability == "small_talk":
        return capability_decision_dict(
            status="small_talk",
            proposal=proposal,
            supported=True,
            reply=None,
            validation={"compiled_intent": "answer_greeting", "reason": "planner_classified_small_talk"},
        )
    if capability == "explain_history":
        followup = action_history_followup_context(request, context)
        if followup:
            return capability_decision_dict(status="history", proposal=proposal, supported=True, validation={"followup": json_safe(followup)})
        return None
    if capability == "retry_repair":
        action = retry_clarification_action(request.raw_text, context) or infer_direct_action(request.raw_text, request=request)
        if action and action.get("action_type") == "retry_last_failed_action":
            return capability_decision_dict(status="action", proposal=proposal, supported=True, action=action, validation={"compiled_action_type": "retry_last_failed_action"})
    return None


def possible_capability_request_text(text: str, context: dict[str, Any] | None = None) -> bool:
    normalized = normalize_text(text)
    if not normalized or len(normalized) > 260:
        return False
    if is_pure_greeting(text) or is_sent_message_history_question(text) or is_action_failure_question(text):
        return False
    latest = (persistent_context_pruned(context).get("last_successful_action") if isinstance(context, dict) else None)
    if isinstance(latest, dict) and is_supported_analytical_action(str(latest.get("action_type") or "")) and possible_analytical_refinement_text(text):
        return True
    if len(normalized) <= 80:
        return True
    return bool(
        re.search(r"\b(add|update|set|write|save|email|message|send|shortlist|hire|reject|evaluate|compare|rank|check|show|find|who|which)\b", normalized)
        or re.search(r"\b(notes?|onboarding|compliance|requirements?|cv|cvs|candidate|candidates|assessment|attendance|leave|shift|payroll|timesheet|accomplished)\b", normalized)
    )


def capability_context(request: WhatsAppTurnRequest, context: dict[str, Any] | None, *, direct_action: dict[str, Any] | None = None, turn_id: str | None = None) -> dict[str, Any] | None:
    if not possible_capability_request_text(request.raw_text, context):
        return None
    dialog = call_dialog_interpreter(text=request.raw_text, request=request, context=context, turn_id=turn_id)
    proposal = dialog_intent_proposal(dialog)
    if not proposal:
        proposal = normalized_capability_proposal(rule_based_capability_proposal(request.raw_text))
    decision = validate_capability_proposal(request, context, proposal or {}, direct_action=direct_action)
    if not decision:
        return None
    if dialog:
        decision = {**decision, "dialog_intent": json_safe(dialog)}
    return decision


def candidate_focus_context(request: WhatsAppTurnRequest, context: dict[str, Any] | None) -> dict[str, Any] | None:
    text = request.raw_text
    company = request_company_code(request)
    current_focus = candidate_focus_for_context(context)
    mutation_action_type = candidate_mutation_action_type_from_text(text)
    if mutation_action_type and re.search(r"\b(him|her|them|he|she|this candidate|that candidate|the candidate)\b", normalize_text(text)):
        if current_focus:
            return {
                "kind": "candidate_mutation",
                "status": "resolved",
                "action": action_from_candidate_focus(mutation_action_type, current_focus, text, planned_by="candidate_focus_context"),
                "focus": json_safe(current_focus),
            }
        return {
            "kind": "candidate_mutation",
            "status": "needs_clarification",
            "action_type": mutation_action_type,
            "reply": candidate_mutation_clarification(mutation_action_type),
        }
    if current_focus and candidate_evaluation_followup_question(text):
        return {
            "kind": "candidate_evaluation",
            "status": "resolved",
            "action": action_from_candidate_focus("candidate_cv_evaluation", current_focus, text, planned_by="candidate_focus_evaluation"),
            "focus": json_safe(current_focus),
        }
    resolution = resolve_candidate_reference_from_text(text, company_code=company)
    if resolution.get("status") == "resolved" and isinstance(resolution.get("application"), dict):
        app = resolution["application"]
        focus = candidate_focus_from_app(app, source_action="candidate_focus", confidence="current_message")
        if not focus:
            return None
        if candidate_evaluation_followup_question(text):
            return {
                "kind": "candidate_evaluation",
                "status": "resolved",
                "action": action_from_candidate_focus("candidate_cv_evaluation", focus, text, planned_by="candidate_focus_evaluation"),
                "focus": json_safe(focus),
            }
        if not explicit_candidate_focus_selection(text):
            return None
        return {
            "kind": "candidate_selection",
            "status": "resolved",
            "application": candidate_lookup_match_payload(app),
            "focus": json_safe(focus),
        }
    if resolution.get("status") == "ambiguous":
        return {
            "kind": "candidate_selection",
            "status": "ambiguous",
            "matches": [candidate_lookup_match_payload(item) for item in resolution.get("matches", []) if isinstance(item, dict)],
            "reply": candidate_clarification_reply([item for item in resolution.get("matches", []) if isinstance(item, dict)], action_type=mutation_action_type),
        }
    if mutation_action_type:
        return {
            "kind": "candidate_mutation",
            "status": "needs_clarification",
            "action_type": mutation_action_type,
            "reply": candidate_mutation_clarification(mutation_action_type),
        }
    return None


def explicit_candidate_focus_selection(text: str | None) -> bool:
    normalized = normalize_text(text)
    if not normalized:
        return False
    return bool(
        re.search(
            r"\b(candidate|applicant|cv|resume|profile|application|status|tell me about|show me|details?|who is|about)\b",
            normalized,
        )
    )


def direct_action_from_operational_context(text: str, context: dict[str, Any] | None) -> dict[str, Any] | None:
    result_set_action = direct_action_from_last_result_set(text, context)
    if result_set_action:
        return result_set_action
    if not followup_reference_in_text(text) and not is_action_correction_to_email(text):
        return None
    action_type = infer_action_type_from_text(text)
    if not action_type:
        return None
    base = {
        "action_type": action_type,
        "subject_type": action_focus_type(action_type),
        "subject_name": None,
        "subject_phone": None,
        "prompt_text": text,
        "planned_by": "operational_context",
    }
    bound = bind_focus_to_action(base, context, text)
    return bound if bound and bound.get("resolved_from_operational_context") else None


def offered_followup_action(text: str, context: dict[str, Any] | None) -> dict[str, Any] | None:
    if not offered_followup_acceptance(text):
        return None
    current = persistent_context_pruned(context)
    offer = current.get("offered_followup") or current.get("proposed_next_action")
    if not isinstance(offer, dict) or focus_is_stale(offer):
        return None
    payload = offer.get("payload") if isinstance(offer.get("payload"), dict) else {}
    action = {
        **payload,
        "action_type": offer.get("action_type"),
        "subject_type": offer.get("target_type"),
        "subject_key": offer.get("target_id"),
        "prompt_text": text,
        "planned_by": "offered_followup",
        "resolved_from_offered_followup": True,
        "offered_followup": json_safe(offer),
    }
    return action if action.get("action_type") else None


def referenced_result_set_items(text: str, context: dict[str, Any] | None) -> list[dict[str, Any]]:
    normalized = normalize_text(text)
    result_set = (context or {}).get("last_result_set")
    if not isinstance(result_set, dict) or focus_is_stale(result_set):
        return []
    items = result_set.get("items") if isinstance(result_set.get("items"), list) else []
    ordinals = {
        "first": 0,
        "1st": 0,
        "second": 1,
        "2nd": 1,
        "third": 2,
        "3rd": 2,
        "one": 0,
    }
    if "first two" in normalized:
        return [item for item in items[:2] if isinstance(item, dict)]
    match = re.search(r"\btop\s+(\d+)\b", normalized)
    if match:
        return [item for item in items[: max(0, int(match.group(1)))] if isinstance(item, dict)]
    if re.search(r"\b(these two|both)\b", normalized):
        return [item for item in items[:2] if isinstance(item, dict)]
    for token, index in ordinals.items():
        if re.search(rf"\b{re.escape(token)}\b", normalized) and len(items) > index and isinstance(items[index], dict):
            return [items[index]]
    if re.search(r"\b(that one|this one|same one)\b", normalized) and len(items) == 1 and isinstance(items[0], dict):
        return [items[0]]
    return []


def direct_action_from_last_result_set(text: str, context: dict[str, Any] | None) -> dict[str, Any] | None:
    items = referenced_result_set_items(text, context)
    if not items:
        return None
    normalized = normalize_text(text)
    result_set_type = str(((context or {}).get("last_result_set") or {}).get("type") or "")
    first = items[0]
    if result_set_type == "leave_requests" and len(items) == 1 and re.search(r"\bapprove\b", normalized):
        return {
            "action_type": "approve_leave_request",
            "subject_type": "leave",
            "leave_id": first.get("leave_id") or first.get("key"),
            "subject_name": first.get("employee_name") or first.get("display_name"),
            "prompt_text": text,
            "resolved_from_last_result_set": True,
            "resolved_entities": {"leave_request": json_safe(first)},
        }
    if result_set_type in {"shift_swaps", "shifts"} and len(items) == 1 and re.search(r"\breject\b", normalized):
        return {
            "action_type": "reject_shift_swap" if result_set_type == "shift_swaps" else "cancel_shift_assignment",
            "subject_type": "shift",
            "shift_id": first.get("shift_id") or first.get("swap_id") or first.get("key"),
            "subject_name": first.get("employee_name") or first.get("display_name"),
            "prompt_text": text,
            "resolved_from_last_result_set": True,
            "resolved_entities": {"shift": json_safe(first)},
        }
    if result_set_type == "candidates" and len(items) == 1 and re.search(r"\bshortlist\b", normalized):
        return {
            "action_type": "shortlist_candidate",
            "subject_type": "candidate",
            "app_key": first.get("app_key") or first.get("key"),
            "subject_name": first.get("candidate_name") or first.get("display_name"),
            "prompt_text": text,
            "resolved_from_last_result_set": True,
            "resolved_entities": {"candidate": json_safe(first)},
        }
    if result_set_type == "candidates" and len(items) >= 2 and re.search(r"\b(compare|versus|vs|better|which)\b", normalized):
        return {
            "action_type": "compare_candidates",
            "subject_type": "candidate",
            "candidate_ids": [item.get("app_key") or item.get("key") for item in items if item.get("app_key") or item.get("key")],
            "candidates": json_safe(items[:5]),
            "prompt_text": text,
            "resolved_from_last_result_set": True,
            "resolved_entities": {"candidates": json_safe(items[:5])},
        }
    return None


def focus_from_action_binding(action: dict[str, Any] | None) -> dict[str, Any] | None:
    if not isinstance(action, dict):
        return None
    focus = action.get("operational_focus")
    return focus if isinstance(focus, dict) else None


def turn_scratch_with_action_resolution(
    scratch: dict[str, Any],
    *,
    action: dict[str, Any] | None,
    intent: str,
) -> dict[str, Any]:
    out = dict(scratch or {})
    out["detected_intent"] = intent
    if not action:
        return out
    focus = focus_from_action_binding(action)
    resolved_entities = dict(out.get("resolved_entities") or {})
    action_resolved = action.get("resolved_entities") if isinstance(action.get("resolved_entities"), dict) else {}
    for key, value in action_resolved.items():
        if isinstance(value, dict):
            resolved_entities[key] = json_safe(value)
    if focus:
        entity_type = str(focus.get("entity_type") or "")
        resolved_entities[entity_type] = json_safe(focus)
        out["pronoun_resolution"] = {
            "raw_reference": out.get("user_message"),
            "resolved_type": entity_type,
            "resolved_id": focus.get("key"),
            "confidence": focus.get("confidence") or "resolved",
            "reason": "persistent_context_focus",
        }
    out["resolved_entities"] = resolved_entities
    out["action_decision"] = {
        "action_type": action.get("action_type"),
        "target_type": action.get("subject_type") or (focus or {}).get("entity_type"),
        "target_id": action.get("app_key") or action.get("subject_key") or action.get("leave_id") or action.get("shift_id") or action.get("timesheet_id"),
        "payload": json_safe(action),
        "requires_confirmation": False,
    }
    return out


def action_with_resolved_entities(action: dict[str, Any], scratch: dict[str, Any] | None) -> dict[str, Any]:
    resolved = (scratch or {}).get("resolved_entities")
    if not isinstance(resolved, dict):
        return action
    out = dict(action)
    candidate = resolved.get("candidate")
    if isinstance(candidate, dict) and action_focus_type(out.get("action_type")) == "candidate":
        out.setdefault("app_key", candidate.get("app_key") or candidate.get("key"))
        out.setdefault("subject_key", candidate.get("app_key") or candidate.get("key"))
        out.setdefault("subject_name", candidate.get("display_name"))
        out.setdefault("subject_phone", candidate.get("phone"))
    employee = resolved.get("employee")
    if isinstance(employee, dict) and action_focus_type(out.get("action_type")) == "employee":
        out.setdefault("subject_key", employee.get("employee_key") or employee.get("key"))
        out.setdefault("subject_name", employee.get("display_name"))
        out.setdefault("subject_phone", employee.get("phone"))
    leave = resolved.get("leave_request")
    if isinstance(leave, dict) and action_focus_type(out.get("action_type")) == "leave_request":
        out.setdefault("leave_id", leave.get("leave_id") or leave.get("key"))
    return out


def result_items_for_context(action_type: str, result_payload: dict[str, Any]) -> tuple[str, list[dict[str, Any]]] | None:
    candidates = result_payload.get("matches") or result_payload.get("ranked_candidates") or result_payload.get("candidates")
    if isinstance(candidates, list) and candidates:
        return "candidates", [item for item in candidates if isinstance(item, dict)]
    for result_type, key in [
        ("leave_requests", "leave_requests"),
        ("shifts", "shifts"),
        ("shift_swaps", "shift_swaps"),
        ("timesheets", "timesheets"),
        ("payroll_exports", "exports"),
        ("assessment_attempts", "attempts"),
        ("reports", "reports"),
    ]:
        value = result_payload.get(key)
        if isinstance(value, list) and value:
            return result_type, [item for item in value if isinstance(item, dict)]
    if action_type == "rank_candidates" and isinstance(result_payload.get("results"), list):
        return "candidates", [item for item in result_payload["results"] if isinstance(item, dict)]
    return None


def operational_context_from_action_result(
    context: dict[str, Any] | None,
    *,
    action_type: str,
    status: str,
    action: dict[str, Any],
    result_payload: dict[str, Any],
) -> dict[str, Any]:
    out = persistent_context_pruned(context)
    for key in ("application", "selected_application"):
        value = result_payload.get(key)
        app = find_application_by_key(value.get("app_key")) if isinstance(value, dict) else None
        out = set_operational_focus(out, candidate_focus_from_app(app, source_action=action_type))
    candidate = result_payload.get("candidate") if isinstance(result_payload.get("candidate"), dict) else {}
    focus_context = out.get("focus") if isinstance(out.get("focus"), dict) else {}
    if candidate and candidate.get("phone") and not focus_context.get("current_candidate"):
        out = set_operational_focus(out, candidate_focus_from_app(resolve_application_for_action({"subject_phone": candidate.get("phone")}), source_action=action_type))
    app = resolve_application_for_action(action, allow_latest=False) if action_type in CANDIDATE_ACTIONS else None
    out = set_operational_focus(out, candidate_focus_from_app(app, source_action=action_type))
    employee = result_payload.get("employee") if isinstance(result_payload.get("employee"), dict) else None
    out = set_operational_focus(out, employee_focus_from_employee(employee, source_action=action_type))
    if employee and employee.get("app_key"):
        out = set_operational_focus(out, candidate_focus_from_app(find_application_by_key(employee.get("app_key")), source_action=action_type, confidence="linked_employee_app"))
    elif employee and employee.get("phone"):
        out = set_operational_focus(out, candidate_focus_from_app(resolve_application_for_action({"subject_phone": employee.get("phone")}), source_action=action_type, confidence="linked_employee_phone"))
    attempt = result_payload.get("attempt") if isinstance(result_payload.get("attempt"), dict) else None
    if attempt and attempt.get("attempt_id"):
        out = set_operational_focus(out, operational_focus(
            entity_type="assessment_attempt",
            key=str(attempt.get("attempt_id")),
            display_name=str(attempt.get("candidate_name") or attempt.get("phone") or "assessment attempt"),
            company_code=attempt.get("company_code"),
            source_action=action_type,
            extra=json_safe(attempt),
        ))
    leave = result_payload.get("leave") if isinstance(result_payload.get("leave"), dict) else None
    if not leave and isinstance(result_payload.get("leave_requests"), list) and len(result_payload.get("leave_requests") or []) == 1:
        leave = result_payload["leave_requests"][0]
    out = set_operational_focus(out, leave_focus_from_leave(leave, source_action=action_type))
    out = set_operational_focus(out, shift_focus_from_payload(result_payload, source_action=action_type))
    out = set_operational_focus(out, payroll_focus_from_payload(result_payload, source_action=action_type))
    result_items = result_items_for_context(action_type, result_payload)
    if result_items:
        result_type, items = result_items
        out["last_result_set"] = {
            "type": result_type,
            "items": json_safe(items[:20]),
            "source_action": action_type,
            "source_turn_id": action.get("turn_id"),
            "updated_at": operational_context_timestamp(),
            "expires_at": operational_context_timestamp(60),
        }
    focus_context = out.get("focus") if isinstance(out.get("focus"), dict) else {}
    current_focus = current_focus_from_context_shape(out, focus_context)
    if current_focus:
        out["current_focus"] = json_safe(current_focus)
    out["current_domain"] = current_domain_from_context_shape(out, current_focus) or operational_module_for_action(action_type).lower()
    normalized_action_result = result_payload.get("normalized_action_result") if isinstance(result_payload.get("normalized_action_result"), dict) else normalize_action_result(
        action_type=action_type,
        status=status,
        action=action,
        result_payload=result_payload,
        template_reply=str(result_payload.get("safe_user_message") or result_payload.get("final_reply") or ""),
    )
    out["last_action_result"] = {
        **json_safe(normalized_action_result),
        "status": status,
        "source_turn_id": action.get("turn_id"),
        "updated_at": operational_context_timestamp(),
        "expires_at": operational_context_timestamp(240),
    }
    if status == "completed" and result_payload.get("ok") is not False:
        success_candidate = result_payload.get("candidate") if isinstance(result_payload.get("candidate"), dict) else {}
        out["last_successful_action"] = {
            "action_type": action_type,
            "channel": result_payload.get("channel") or action_result_channel(action_type, action, result_payload),
            "target_type": result_payload.get("target_type") or action_focus_type(action_type),
            "target_id": result_payload.get("target_id") or action.get("app_key") or action.get("subject_key") or action.get("leave_id") or action.get("shift_id") or action.get("timesheet_id"),
            "target_name": result_payload.get("target_name") or success_candidate.get("name") or action.get("subject_name"),
            "payload": {"action": json_safe(action), "result": json_safe(result_payload), "normalized_action_result": json_safe(result_payload.get("normalized_action_result") or {})},
            "completed_at": operational_context_timestamp(),
            "source_turn_id": action.get("turn_id"),
            "expires_at": operational_context_timestamp(240),
        }
    should_persist_failure = status in {"failed", "partial", "needs_clarification", "needs_details", "module_disabled"} and not (
        action_type == "retry_last_failed_action" and result_payload.get("reason") == "multiple_recent_failed_actions"
    )
    if should_persist_failure:
        failure_action_type = action_type
        failure_action = dict(action)
        if action_type == "retry_last_failed_action" and isinstance(result_payload.get("last_failed_action"), dict):
            inner_failed = result_payload.get("last_failed_action") or {}
            failure_action_type = str(inner_failed.get("action_type") or result_payload.get("retried_action_type") or action_type)
            inner_payload = inner_failed.get("payload") if isinstance(inner_failed.get("payload"), dict) else {}
            inner_action = inner_payload.get("action") if isinstance(inner_payload.get("action"), dict) else {}
            if inner_action:
                failure_action = {**inner_action, "turn_id": action.get("turn_id")}
        focus = focus_from_action_binding(action)
        candidate_payload = result_payload.get("candidate") if isinstance(result_payload.get("candidate"), dict) else {}
        employee_payload = result_payload.get("employee") if isinstance(result_payload.get("employee"), dict) else {}
        target_type = result_payload.get("target_type") or action_focus_type(failure_action_type) or (focus or {}).get("entity_type")
        target_id = result_payload.get("target_id") or failure_action.get("app_key") or failure_action.get("subject_key") or failure_action.get("leave_id") or failure_action.get("shift_id") or failure_action.get("timesheet_id") or (focus or {}).get("key")
        target_name = result_payload.get("target_name") or failure_action.get("subject_name") or failure_action.get("target_name") or (focus or {}).get("display_name") or candidate_payload.get("name") or employee_payload.get("name")
        failed_action = {
            "action_type": failure_action_type,
            "channel": result_payload.get("channel") or failure_action.get("channel") or ("email" if failure_action_type == "send_email" else "whatsapp" if failure_action_type in {"notify_candidate", "send_assessment", "send_custom_employee_message", "send_onboarding_reminder"} else operational_module_for_action(failure_action_type).lower()),
            "status": status,
            "target_type": target_type,
            "target_id": target_id,
            "target_name": target_name,
            "error_code": result_payload.get("error_code") or result_payload.get("error") or result_payload.get("reason") or status,
            "error_message": result_payload.get("safe_user_message") or result_payload.get("message") or result_payload.get("final_reply"),
            "safe_user_message": result_payload.get("safe_user_message"),
            "retryable": bool(result_payload.get("retryable")),
            "payload": {"action": json_safe(failure_action), "result": json_safe(result_payload), "normalized_action_result": json_safe(result_payload.get("normalized_action_result") or {})},
            "failed_at": operational_context_timestamp(),
            "source_turn_id": action.get("turn_id"),
            "expires_at": operational_context_timestamp(120),
        }
        out["last_failed_action"] = failed_action
        history = out.get("failed_action_history") if isinstance(out.get("failed_action_history"), list) else []
        out["failed_action_history"] = [failed_action, *[item for item in history if isinstance(item, dict)]][:5]
    elif status not in {"failed", "partial", "needs_clarification", "needs_details", "module_disabled"}:
        out.pop("last_failed_action", None)
    if status in {"needs_clarification", "needs_details"}:
        pending_payload = json_safe(action)
        if isinstance(result_payload.get("failed_actions"), list):
            pending_payload["failed_actions"] = json_safe(result_payload.get("failed_actions"))
        out["pending_action"] = {
            "action_type": action_type,
            "target_type": action_focus_type(action_type),
            "target_id": action.get("app_key") or action.get("subject_key") or action.get("leave_id") or action.get("shift_id") or action.get("timesheet_id"),
            "payload": pending_payload,
            "requires_confirmation": status == "needs_clarification",
            "status": status,
            "created_at": operational_context_timestamp(),
            "updated_at": operational_context_timestamp(),
            "expires_at": operational_context_timestamp(60),
        }
    else:
        out.pop("pending_action", None)
    if action.get("resolved_from_offered_followup"):
        out["offered_followup"] = None
        out["proposed_next_action"] = None
    return out


_CV_FILENAME_SUFFIX_RE = re.compile(r"[-_\s]+(cv|resume|profile|application|final|v\d+).*$", re.IGNORECASE)
_FILENAME_SPLIT_RE = re.compile(r"[-_\s.]+")
EMAIL_RE = re.compile(r"[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,24}")
COMMON_EMAIL_TLDS = {
    "com",
    "net",
    "org",
    "edu",
    "gov",
    "info",
    "io",
    "ai",
    "co",
    "me",
    "kw",
    "sa",
    "ae",
    "qa",
    "bh",
    "om",
}


def _parse_candidate_name_from_filename(filename: str | None) -> str | None:
    """'Faisal_Almulla_CV.docx' -> 'Faisal Almulla'. Returns None if it does not look like a person."""

    if not filename:
        return None
    stem = str(filename).rsplit(".", 1)[0]
    stem = _CV_FILENAME_SUFFIX_RE.sub("", stem)
    tokens = [t for t in _FILENAME_SPLIT_RE.split(stem) if t]
    word_tokens = [t for t in tokens if t.isalpha()]
    if len(word_tokens) < 2:
        return None
    name = " ".join(part[0].upper() + part[1:].lower() for part in word_tokens[:4])
    if len(name) < 4:
        return None
    return name


def _extract_email_from_text(text: str | None) -> str | None:
    if not text:
        return None
    match = EMAIL_RE.search(str(text))
    if not match:
        return None
    return clean_extracted_email(match.group(0))


def _extract_email_from_path(path_value: str | None) -> str | None:
    if not path_value:
        return None
    try:
        path = Path(str(path_value))
        if path.exists() and path.is_file():
            return _extract_email_from_text(path.read_text(errors="ignore")[:20000])
    except Exception:
        return None
    return None


def _name_similarity(a: str | None, b: str | None) -> float:
    """Token-aware similarity in [0,1]. Used as fallback when pg_trgm is not available."""

    if not a or not b:
        return 0.0
    a_low = str(a).lower().strip()
    b_low = str(b).lower().strip()
    if not a_low or not b_low:
        return 0.0
    if a_low == b_low:
        return 1.0
    a_tokens = set(re.findall(r"[\w']+", a_low))
    b_tokens = set(re.findall(r"[\w']+", b_low))
    if a_tokens and b_tokens:
        inter = len(a_tokens & b_tokens)
        union = len(a_tokens | b_tokens)
        token_score = inter / union if union else 0.0
        if token_score > 0:
            return token_score
    a_chars = set(a_low.replace(" ", ""))
    b_chars = set(b_low.replace(" ", ""))
    if a_chars and b_chars:
        inter = len(a_chars & b_chars)
        union = len(a_chars | b_chars)
        if union:
            return 0.4 * (inter / union)
    return 0.0


def _persist_candidate_name(phone: str | None, name: str | None) -> None:
    """Write-through cache: store a parsed name into candidates.name when it's currently empty."""

    if not phone or not name:
        return
    try:
        with db_connect() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    "UPDATE candidates SET name=%s, updated_at=now() WHERE phone=%s AND (name IS NULL OR name='')",
                    (name, phone),
                )
            conn.commit()
    except Exception:
        pass


def _applications_for_phone(phone: str, *, company_code: str | None = None) -> list[dict[str, Any]]:
    sql = """
        SELECT a.*, c.name AS candidate_name, c.email AS candidate_email
        FROM applications a
        LEFT JOIN candidates c ON c.phone = a.phone
        WHERE a.phone = %s
    """
    params: list[Any] = [phone]
    if company_code:
        sql += " AND a.company_code = %s"
        params.append(company_code)
    sql += """
        ORDER BY
            CASE a.status
                WHEN 'hired' THEN 0
                WHEN 'shortlisted' THEN 1
                WHEN 'screening_complete' THEN 2
                WHEN 'review_pending' THEN 3
                WHEN 'screening' THEN 4
                ELSE 9
            END,
            a.updated_at DESC NULLS LAST,
            a.ingested_at DESC NULLS LAST
        LIMIT 10
    """
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(sql, params)
            return [dict(row) for row in cur.fetchall()]


def _fuzzy_candidate_phones_by_name(name: str, *, threshold: float, limit: int, company_code: str | None = None) -> list[dict[str, Any]]:
    """Return candidate phones whose stored name OR CV filename matches the query,
    restricted to candidates who have an application in the active company.

    Uses pg_trgm similarity when available; falls back to ILIKE + Python token similarity.
    Fails closed (returns []) when no company scope is available.
    """

    name = (name or "").strip()
    if not name:
        return []
    company = resolved_company_scope(company_code)
    if not company:
        return []
    pattern = f"%{name}%"
    results: dict[str, dict[str, Any]] = {}
    with db_connect() as conn:
        with conn.cursor() as cur:
            try:
                cur.execute(
                    """
                    SELECT c.phone, c.name, c.email, similarity(coalesce(c.name,''), %s) AS sim, 'candidates.name'::text AS source
                    FROM candidates c
                    WHERE c.name IS NOT NULL AND c.name <> '' AND similarity(c.name, %s) >= %s
                      AND EXISTS (SELECT 1 FROM applications a WHERE a.phone = c.phone AND a.company_code = %s)
                    ORDER BY sim DESC
                    LIMIT %s
                    """,
                    (name, name, threshold, company, limit * 3),
                )
                for row in cur.fetchall():
                    phone = row["phone"]
                    if phone:
                        results[phone] = {**dict(row), "phone": phone}
            except Exception:
                cur.execute(
                    """
                    SELECT c.phone, c.name, c.email
                    FROM candidates c
                    WHERE c.name ILIKE %s
                      AND EXISTS (SELECT 1 FROM applications a WHERE a.phone = c.phone AND a.company_code = %s)
                    LIMIT %s
                    """,
                    (pattern, company, limit * 3),
                )
                for row in cur.fetchall():
                    phone = row["phone"]
                    if phone:
                        results[phone] = {
                            **dict(row),
                            "phone": phone,
                            "sim": _name_similarity(name, row.get("name")),
                            "source": "candidates.name",
                        }
            cur.execute(
                """
                SELECT DISTINCT ON (cd.phone) cd.phone, cd.filename
                FROM candidate_documents cd
                WHERE cd.document_type='cv' AND cd.filename IS NOT NULL
                  AND EXISTS (SELECT 1 FROM applications a WHERE a.phone = cd.phone AND a.company_code = %s)
                """,
                (company,),
            )
            filename_rows = cur.fetchall()
    for row in filename_rows:
        phone = row.get("phone")
        if not phone or phone in results:
            continue
        parsed = _parse_candidate_name_from_filename(row.get("filename"))
        if not parsed:
            continue
        sim = _name_similarity(name, parsed)
        if sim < threshold:
            continue
        results[phone] = {
            "phone": phone,
            "name": parsed,
            "email": None,
            "sim": sim,
            "source": "candidate_documents.filename",
        }
    ranked = sorted(results.values(), key=lambda r: float(r.get("sim") or 0.0), reverse=True)
    return ranked[:limit]


def resolve_candidate(
    *,
    app_key: str | None = None,
    phone: str | None = None,
    email: str | None = None,
    name: str | None = None,
    company_code: str | None = None,
    similarity_threshold: float = 0.35,
    max_matches: int = 5,
) -> dict[str, Any]:
    """Canonical candidate resolver.

    Returns a typed result so callers can distinguish:
      - resolved: exactly one confident match
      - ambiguous: multiple plausible matches, caller should ask the user
      - not_found: caller gave identifying info but nothing in the database matches
      - no_input: caller did not supply anything to search on

    NEVER falls back silently to the latest application or the sender's own phone.
    """

    searched = {
        k: v
        for k, v in {"app_key": app_key, "phone": phone, "email": email, "name": name, "company_code": company_code}.items()
        if v
    }
    if not (app_key or phone or email or name):
        return {"status": "no_input", "matches": [], "searched": searched}
    matches: list[dict[str, Any]] = []
    if app_key:
        row = find_application_by_key(app_key, company_code=company_code)
        if row:
            return {"status": "resolved", "matches": [row], "searched": searched}
        return {"status": "not_found", "matches": [], "searched": searched}
    if email:
        rows = candidate_applications_by_email(email, company_code=company_code)
        if rows:
            if len(rows) == 1:
                return {"status": "resolved", "matches": rows, "searched": searched}
            matches.extend(rows)
    phone_digits = digits(str(phone or "")) if phone else ""
    if phone_digits:
        rows = _applications_for_phone(phone_digits, company_code=company_code)
        if rows:
            if len(rows) == 1 and not matches:
                return {"status": "resolved", "matches": rows, "searched": searched}
            matches.extend(rows)
    if name and not matches:
        candidates_found = _fuzzy_candidate_phones_by_name(name, threshold=similarity_threshold, limit=max_matches, company_code=company_code)
        for candidate in candidates_found:
            candidate_phone = candidate.get("phone")
            if not candidate_phone:
                continue
            if candidate.get("source") == "candidate_documents.filename" and candidate.get("name"):
                _persist_candidate_name(candidate_phone, candidate["name"])
            apps = _applications_for_phone(candidate_phone, company_code=company_code)
            for app in apps:
                app["candidate_name"] = app.get("candidate_name") or candidate.get("name")
                app["candidate_email"] = app.get("candidate_email") or candidate.get("email")
                app["match_similarity"] = float(candidate.get("sim") or 0.0)
                app["match_source"] = candidate.get("source")
                matches.append(app)
    if not matches:
        return {"status": "not_found", "matches": [], "searched": searched}
    seen_keys: set[str] = set()
    unique_matches: list[dict[str, Any]] = []
    for match in matches:
        key = str(match.get("app_key") or "")
        if not key or key in seen_keys:
            continue
        seen_keys.add(key)
        unique_matches.append(match)
    unique_matches.sort(key=lambda m: float(m.get("match_similarity") or 0.0), reverse=True)
    if len(unique_matches) == 1:
        return {"status": "resolved", "matches": unique_matches, "searched": searched}
    top = unique_matches[0]
    top_sim = float(top.get("match_similarity") or 0.0)
    second_sim = float(unique_matches[1].get("match_similarity") or 0.0)
    top_apps_same_phone = [m for m in unique_matches if m.get("phone") == top.get("phone")]
    other_phone_matches = [m for m in unique_matches if m.get("phone") != top.get("phone")]
    other_phone_top = float(other_phone_matches[0].get("match_similarity") or 0.0) if other_phone_matches else 0.0
    if top_sim >= 0.7 and (top_sim - other_phone_top) >= 0.15:
        return {
            "status": "resolved",
            "matches": [top_apps_same_phone[0]] if top_apps_same_phone else [top],
            "alternates": other_phone_matches[:max_matches],
            "searched": searched,
        }
    if top_sim >= 0.35 and (top_sim - other_phone_top) >= 0.10:
        return {
            "status": "resolved",
            "matches": [top_apps_same_phone[0]] if top_apps_same_phone else [top],
            "alternates": other_phone_matches[:max_matches],
            "searched": searched,
        }
    return {"status": "ambiguous", "matches": unique_matches[:max_matches], "searched": searched}


def backfill_candidate_identity_from_documents() -> dict[str, int]:
    """One-shot: copy parsed names/emails from candidate CV documents into candidates when missing."""

    updated_names = 0
    updated_emails = 0
    inserted_candidates = 0
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT DISTINCT ON (cd.phone) cd.phone, cd.filename, cd.text_path, cd.metadata, cd.raw_json
                FROM candidate_documents cd
                WHERE cd.document_type='cv' AND cd.filename IS NOT NULL
                """
            )
            rows = cur.fetchall()
            for row in rows:
                phone = row.get("phone")
                parsed = _parse_candidate_name_from_filename(row.get("filename"))
                email = None
                raw_json = row.get("raw_json") if isinstance(row.get("raw_json"), dict) else {}
                metadata = row.get("metadata") if isinstance(row.get("metadata"), dict) else {}
                for source in (raw_json, metadata):
                    email = _extract_email_from_text(source.get("email") or source.get("candidate_email")) if source else None
                    if email:
                        break
                if not email:
                    email = _extract_email_from_path(row.get("text_path"))
                if not phone or not (parsed or email):
                    continue
                cur.execute(
                    "INSERT INTO candidates (phone, name, email) VALUES (%s, %s, %s) ON CONFLICT (phone) DO NOTHING",
                    (phone, parsed, email),
                )
                inserted_candidates += cur.rowcount
                if parsed:
                    cur.execute(
                        "UPDATE candidates SET name=%s, updated_at=now() WHERE phone=%s AND (name IS NULL OR name='')",
                        (parsed, phone),
                    )
                    updated_names += cur.rowcount
                if email:
                    cur.execute(
                        "UPDATE candidates SET email=%s, updated_at=now() WHERE phone=%s AND (email IS NULL OR email='')",
                        (email, phone),
                    )
                    updated_emails += cur.rowcount
        conn.commit()
    return {"updated_names": updated_names, "updated_emails": updated_emails, "inserted_candidates": inserted_candidates}


def find_application_by_key(app_key: str | None, company_code: str | None = None) -> dict[str, Any] | None:
    key = str(app_key or "").strip()
    if not key:
        return None
    company = str(company_code or "").strip().upper()
    with db_connect() as conn:
        with conn.cursor() as cur:
            where = "a.app_key=%s"
            params: list[Any] = [key]
            if company:
                where += " AND a.company_code=%s"
                params.append(company)
            cur.execute(
                f"""
                SELECT a.*, c.name AS candidate_name, c.email AS candidate_email
                FROM applications a
                JOIN candidates c ON c.phone = a.phone
                WHERE {where}
                LIMIT 1
                """,
                params,
            )
            row = cur.fetchone()
            return dict(row) if row else None


def candidate_applications_by_email(email: str, company_code: str | None = None) -> list[dict[str, Any]]:
    target = str(email or "").strip().lower()
    if not target:
        return []
    company = str(company_code or "").strip().upper()
    with db_connect() as conn:
        with conn.cursor() as cur:
            company_clause = "AND a.company_code=%s" if company else ""
            params: list[Any] = [target]
            if company:
                params.append(company)
            cur.execute(
                f"""
                SELECT a.*, c.name AS candidate_name, c.email AS candidate_email
                FROM candidates c
                JOIN applications a ON a.phone=c.phone
                WHERE lower(c.email)=%s
                  {company_clause}
                ORDER BY c.name NULLS LAST,
                         CASE WHEN a.status IN ('hired','shortlisted','screening_complete') THEN 0 ELSE 1 END,
                         a.updated_at DESC NULLS LAST,
                         a.ingested_at DESC NULLS LAST
                LIMIT 50
                """,
                params,
            )
            return [dict(row) for row in cur.fetchall()]


def candidate_lookup_match_payload(app: dict[str, Any]) -> dict[str, Any]:
    contact = candidate_contact(app)
    return {
        "app_key": app.get("app_key"),
        "candidate_name": contact.get("name"),
        "candidate_email": contact.get("email"),
        "phone": contact.get("phone") or app.get("phone"),
        "position_title": app.get("position_title"),
        "position_code": app.get("position_code"),
        "status": app.get("status"),
    }


def candidate_email_lookup_reply(email: str, matches: list[dict[str, Any]]) -> str:
    if not matches:
        return f"I could not find a candidate using {email}."
    if len(matches) == 1:
        item = candidate_lookup_match_payload(matches[0])
        return f"Yes. I found {item.get('candidate_name') or 'one candidate'}, phone {item.get('phone')}, for {item.get('position_title') or 'the application'}."
    grouped: dict[str, dict[str, Any]] = {}
    for app in matches:
        payload = candidate_lookup_match_payload(app)
        key = f"{payload.get('candidate_email')}:{payload.get('phone')}"
        group = grouped.setdefault(key, {**payload, "positions": []})
        group["positions"].append(payload.get("position_title") or payload.get("position_code") or "application")
    lines = [f"Yes.\n\nI found {len(grouped)} candidate record{'s' if len(grouped) != 1 else ''} using {email}:"]
    for idx, group in enumerate(grouped.values(), start=1):
        lines.append(
            f"{idx}. {group.get('candidate_name') or 'Candidate'}, phone {group.get('phone')}, "
            f"active applications in {format_inline_list([str(item) for item in group.get('positions', [])])}"
        )
    lines.append("\nThat email is duplicated across records, so we should verify which one is correct before emailing or scheduling anything.")
    return "\n".join(lines)


def position_match_score(text: str, app: dict[str, Any]) -> float:
    terms = normalized_search_terms(text)
    if not terms:
        return 0.0
    haystack = normalize_text(" ".join(str(app.get(key) or "") for key in ("position_title", "position_code")))
    if not haystack:
        return 0.0
    matches = sum(1 for term in terms if term in haystack)
    return matches / max(1, len(terms))


def select_candidate_application_from_matches(matches: list[dict[str, Any]], text: str) -> dict[str, Any] | None:
    if not matches:
        return None
    scored = sorted(((position_match_score(text, app), app) for app in matches), key=lambda item: item[0], reverse=True)
    best_score, best = scored[0]
    second_score = scored[1][0] if len(scored) > 1 else 0.0
    if best_score > 0 and best_score - second_score >= 0.01:
        return best
    if len(matches) == 1:
        return matches[0]
    return None


