def attendance_date_from_action(action: dict[str, Any]) -> date:
    parsed = parse_shift_date_value(action.get("date") or action.get("attendance_date"))
    if parsed:
        return parsed
    return shift_query_window(action)[0]


def attendance_timestamp_from_action(action: dict[str, Any], attendance_date: date) -> datetime:
    raw_time = action.get("time") or action.get("check_time") or action.get("check_in_time") or action.get("check_out_time")
    parsed_time = parse_shift_time_value(raw_time)
    if parsed_time:
        return datetime.combine(attendance_date, parsed_time, tzinfo=KUWAIT_TZ)
    return datetime.now(KUWAIT_TZ)


def attendance_shift_datetime(shift_date: Any, shift_time: Any) -> datetime | None:
    parsed_date = parse_shift_date_value(shift_date)
    parsed_time = parse_shift_time_value(shift_time) if isinstance(shift_time, str) else shift_time
    if not parsed_date or not parsed_time:
        return None
    return datetime.combine(parsed_date, parsed_time, tzinfo=KUWAIT_TZ)


def attendance_minutes_late(check_in_at: Any, shift: dict[str, Any] | None) -> int:
    if not check_in_at or not shift:
        return 0
    start_dt = attendance_shift_datetime(shift.get("shift_date"), shift.get("start_time"))
    if not start_dt:
        return 0
    check_dt = check_in_at if isinstance(check_in_at, datetime) else datetime.fromisoformat(str(check_in_at).replace("Z", "+00:00"))
    if check_dt.tzinfo is None:
        check_dt = check_dt.replace(tzinfo=KUWAIT_TZ)
    return max(0, int((check_dt.astimezone(KUWAIT_TZ) - start_dt).total_seconds() // 60))


def attendance_minutes_early_leave(check_out_at: Any, shift: dict[str, Any] | None) -> int:
    if not check_out_at or not shift:
        return 0
    end_dt = attendance_shift_datetime(shift.get("shift_date"), shift.get("end_time"))
    if not end_dt:
        return 0
    check_dt = check_out_at if isinstance(check_out_at, datetime) else datetime.fromisoformat(str(check_out_at).replace("Z", "+00:00"))
    if check_dt.tzinfo is None:
        check_dt = check_dt.replace(tzinfo=KUWAIT_TZ)
    return max(0, int((end_dt - check_dt.astimezone(KUWAIT_TZ)).total_seconds() // 60))


