def leave_date_window(action: dict[str, Any]) -> tuple[date, date]:
    start_date, end_date = shift_query_window(action)
    if end_date < start_date:
        return start_date, start_date
    return start_date, end_date


def infer_leave_type(text: str | None, explicit: str | None = None) -> str:
    raw = normalize_text(explicit or "")
    if raw:
        return raw.replace(" ", "_")
    normalized = normalize_text(text)
    if re.search(r"\b(sick|ill|medical)\b", normalized):
        return "sick"
    if re.search(r"\b(vacation|holiday|annual)\b", normalized):
        return "vacation"
    return "time_off"


