def list_payroll_hours(action: dict[str, Any], *, company_code: str | None, sync_sheet: bool = True) -> dict[str, Any]:
    company = (company_code or "WATHEFNI").upper()
    start_date, end_date = payroll_period_from_action(action)
    scope = org_scope_for_action(action, company)
    employee = resolve_attendance_employee(action, company_code=company, required=False)
    if employee and action.get("viewer_phone") and not manager_scope_allows_employee(employee, company_code=company, viewer_phone=action.get("viewer_phone")):
        return {"ok": False, "error": "employee_outside_manager_scope", "action": action, "start_date": start_date.isoformat(), "end_date": end_date.isoformat(), "scope": json_safe(scope)}
    if (action.get("subject_name") or action.get("subject_phone")) and not employee:
        return {"ok": False, "error": "employee_not_found", "action": action, "start_date": start_date.isoformat(), "end_date": end_date.isoformat()}
    params: list[Any] = [company, start_date, end_date]
    employee_clause = ""
    if employee:
        employee_clause = "AND {alias}.employee_key=%s"
        params.append(employee.get("employee_key"))
    leave_params: list[Any] = [company, end_date, start_date]
    if employee:
        leave_params.append(employee.get("employee_key"))
    scope_clause_shifts, scope_params_shifts = employee_scope_sql("s", scope)
    scope_clause_attendance, scope_params_attendance = employee_scope_sql("ar", scope)
    scope_clause_leave, scope_params_leave = employee_scope_sql("lr", scope)
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                f"""
                SELECT s.*
                FROM shift_assignments s
                WHERE s.company_code=%s
                  AND s.shift_date BETWEEN %s AND %s
                  AND status='scheduled'
                  {employee_clause.format(alias='s') if employee_clause else ''}
                  {scope_clause_shifts}
                ORDER BY s.employee_name NULLS LAST, s.shift_date, s.start_time
                LIMIT 2000
                """,
                [*params, *scope_params_shifts],
            )
            shifts = [dict(row) for row in cur.fetchall()]
            cur.execute(
                f"""
                SELECT ar.*
                FROM attendance_records ar
                WHERE ar.company_code=%s
                  AND ar.attendance_date BETWEEN %s AND %s
                  {employee_clause.format(alias='ar') if employee_clause else ''}
                  {scope_clause_attendance}
                ORDER BY ar.employee_name NULLS LAST, ar.attendance_date
                LIMIT 2000
                """,
                [*params, *scope_params_attendance],
            )
            attendance_rows = [dict(row) for row in cur.fetchall()]
            cur.execute(
                f"""
                SELECT lr.*
                FROM leave_requests lr
                WHERE lr.company_code=%s
                  AND lr.status='approved'
                  AND lr.start_date <= %s
                  AND lr.end_date >= %s
                  {employee_clause.format(alias='lr') if employee_clause else ''}
                  {scope_clause_leave}
                ORDER BY lr.employee_name NULLS LAST, lr.start_date
                LIMIT 1000
                """,
                [*leave_params, *scope_params_leave],
            )
            leaves = [dict(row) for row in cur.fetchall()]
    summaries: dict[str, dict[str, Any]] = {}

    def ensure_summary(key: str, *, name: str | None = None, phone: str | None = None) -> dict[str, Any]:
        summary = summaries.setdefault(
            key,
            {
                "employee_key": key,
                "employee_name": name or "",
                "employee_phone": digits(phone),
                "period": format_shift_date_range(start_date, end_date),
                "scheduled_minutes": 0,
                "worked_minutes": 0,
                "approved_leave_minutes": 0,
                "absent_minutes": 0,
                "late_minutes": 0,
                "early_leave_minutes": 0,
                "overtime_minutes": 0,
                "shift_count": 0,
                "attendance_count": 0,
                "approved_leave_days": 0,
            },
        )
        if name and not summary.get("employee_name"):
            summary["employee_name"] = name
        if phone and not summary.get("employee_phone"):
            summary["employee_phone"] = digits(phone)
        return summary

    approved_leave_by_employee: dict[str, list[dict[str, Any]]] = {}
    for leave in leaves:
        key = str(leave.get("employee_key") or "")
        if not key:
            continue
        approved_leave_by_employee.setdefault(key, []).append(leave)
        ensure_summary(key, name=leave.get("employee_name"), phone=leave.get("employee_phone"))

    for shift in shifts:
        key = str(shift.get("employee_key") or "")
        if not key:
            continue
        summary = ensure_summary(key, name=shift.get("employee_name"), phone=shift.get("employee_phone"))
        scheduled = minutes_between_times(shift.get("start_time"), shift.get("end_time"))
        summary["scheduled_minutes"] += scheduled
        if str(shift.get("status") or "scheduled") == "scheduled":
            summary["shift_count"] += 1
        shift_date = parse_shift_date_value(shift.get("shift_date"))
        if shift_date:
            on_leave = any(parse_shift_date_value(leave.get("start_date")) <= shift_date <= parse_shift_date_value(leave.get("end_date")) for leave in approved_leave_by_employee.get(key, []) if parse_shift_date_value(leave.get("start_date")) and parse_shift_date_value(leave.get("end_date")))
            if on_leave:
                summary["approved_leave_minutes"] += scheduled

    for row in attendance_rows:
        key = str(row.get("employee_key") or "")
        if not key:
            continue
        summary = ensure_summary(key, name=row.get("employee_name"), phone=row.get("employee_phone"))
        status = str(row.get("status") or "")
        summary["attendance_count"] += 1
        summary["late_minutes"] += int(row.get("late_minutes") or 0)
        summary["early_leave_minutes"] += int(row.get("early_leave_minutes") or 0)
        worked = minutes_between_datetimes(row.get("check_in_at"), row.get("check_out_at"))
        summary["worked_minutes"] += worked
        scheduled = minutes_between_times(row.get("scheduled_start"), row.get("scheduled_end"))
        if status == "absent":
            summary["absent_minutes"] += scheduled
        elif status == "approved_leave" and scheduled:
            if not approved_leave_by_employee.get(key):
                summary["approved_leave_minutes"] += scheduled

    for summary in summaries.values():
        summary["overtime_minutes"] = max(0, int(summary.get("worked_minutes") or 0) - int(summary.get("scheduled_minutes") or 0))
        if int(summary.get("absent_minutes") or 0):
            summary["payroll_status"] = "Needs review"
        elif int(summary.get("late_minutes") or 0) or int(summary.get("early_leave_minutes") or 0):
            summary["payroll_status"] = "Review exceptions"
        else:
            summary["payroll_status"] = "Ready"

    out = sorted(summaries.values(), key=lambda item: (str(item.get("employee_name") or "").lower(), str(item.get("employee_key") or "")))
    result = {
        "ok": True,
        "company_code": company,
        "start_date": start_date.isoformat(),
        "end_date": end_date.isoformat(),
        "employee": json_safe(employee) if employee else None,
        "summaries": json_safe(out),
        "count": len(out),
        "source_counts": {"shifts": len(shifts), "attendance": len(attendance_rows), "approved_leave": len(leaves)},
        "scope": json_safe(scope),
    }
    scoped_view = bool(scope.get("restricted") or scope.get("requested_branch"))
    result["sheet_sync"] = sync_payroll_hours_sheet(company, result) if sync_sheet and not scoped_view else {"ok": True, "skipped": True, "reason": "scoped_or_employee_self_service_read"}
    return result


def analytics_insight(metric: str, subject: str, value: Any, detail: str) -> dict[str, Any]:
    return {
        "metric": metric,
        "subject": subject,
        "value": value,
        "detail": detail,
    }


def analytics_sheet_row(result: dict[str, Any], insight: dict[str, Any]) -> list[str]:
    scope = result.get("scope") if isinstance(result.get("scope"), dict) else {}
    scope_text = "Scoped manager view" if scope.get("restricted") else "Company"
    if scope.get("requested_branch"):
        branch = scope.get("requested_branch") if isinstance(scope.get("requested_branch"), dict) else {}
        scope_text = str(branch.get("branch_name") or branch.get("branch_key") or scope_text)
    return [
        format_shift_date_range(result.get("start_date"), result.get("end_date")),
        scope_text,
        shift_sheet_cell(insight.get("metric")),
        shift_sheet_cell(insight.get("subject")),
        shift_sheet_cell(insight.get("value")),
        shift_sheet_cell(insight.get("detail")),
        now_iso(),
    ]


