def normalize_posthire_result(result: dict[str, Any], *, action_type: str, reply: str | None = None) -> dict[str, Any]:
    """Shape a legacy post-hire executor result into the registry result contract.

    Post-hire executors (leave, attendance, shifts, payroll, ...) return
    {"ok": bool, ...} dicts with domain payloads. The registry/tool-call layer
    expects action_type/success/status/message and a safe_user_message that the
    orchestrator can surface to the user verbatim. This keeps every original key
    (leave, leave_requests, shift_conflicts, employee_notification, sheet_sync,
    error, ...) so downstream renderers and audit retain full detail.

    `reply` is normally produced by the matching format_*_reply helper and becomes
    the user-facing safe message. needs_confirmation results map to a
    needs_confirmation status rather than a hard failure.
    """

    data = dict(result) if isinstance(result, dict) else {}
    ok = bool(data.get("ok"))
    if ok:
        status = "completed"
    elif data.get("needs_confirmation"):
        status = "needs_confirmation"
    else:
        status = "failed"
    safe = str(reply or data.get("safe_user_message") or data.get("message") or "").strip()
    if not safe:
        safe = "Done." if ok else "I could not complete that action."
    data["action_type"] = action_type
    data["success"] = ok
    data["status"] = status
    data["message"] = safe
    data["safe_user_message"] = safe
    return json_safe(data)


def format_payroll_hours_reply(result: dict[str, Any], *, employee_view: bool = False) -> str:
    if not result.get("ok"):
        if result.get("error") == "employee_outside_manager_scope":
            return "That employee is outside your manager scope."
        if result.get("error") == "employee_not_found":
            return "I could not find your employee record for payroll hours." if employee_view else "I need the exact employee name or phone before calculating payroll hours for one person."
        return "I could not calculate payroll hours safely."
    rows = result.get("summaries") if isinstance(result.get("summaries"), list) else []
    period = format_shift_date_range(result.get("start_date"), result.get("end_date"))
    if not rows:
        return f"I do not see payroll hours for you in {period}." if employee_view else f"No payroll hours found for {period}."
    lines = [f"Your payroll hours ({period}):" if employee_view else f"Payroll hours ({period}):"]
    for row in rows[:12]:
        name = "" if employee_view else f"{row.get('employee_name') or row.get('employee_phone') or 'Employee'}: "
        pieces = [
            f"worked {decimal_hours(row.get('worked_minutes'))}h",
            f"scheduled {decimal_hours(row.get('scheduled_minutes'))}h",
        ]
        if int(row.get("approved_leave_minutes") or 0):
            pieces.append(f"approved leave {decimal_hours(row.get('approved_leave_minutes'))}h")
        if int(row.get("absent_minutes") or 0):
            pieces.append(f"absent {decimal_hours(row.get('absent_minutes'))}h")
        if int(row.get("overtime_minutes") or 0):
            pieces.append(f"overtime {decimal_hours(row.get('overtime_minutes'))}h")
        if int(row.get("late_minutes") or 0):
            pieces.append(f"{row.get('late_minutes')} min late")
        lines.append(f"- {name}{', '.join(pieces)} ({row.get('payroll_status') or 'Ready'})")
    if len(rows) > 12 and not employee_view:
        lines.append(f"And {len(rows) - 12} more employees.")
    sheet_sync = result.get("sheet_sync") if isinstance(result.get("sheet_sync"), dict) else {}
    if sheet_sync.get("ok") and not employee_view:
        lines.append("Payroll Hours sheet updated.")
    return "\n".join(lines)


def format_workforce_analytics_reply(result: dict[str, Any]) -> str:
    if not result.get("ok"):
        if result.get("error") == "employee_outside_manager_scope":
            return "That analytics view is outside your manager scope."
        return "I could not generate workforce analytics safely."
    insights = result.get("insights") if isinstance(result.get("insights"), list) else []
    period = format_shift_date_range(result.get("start_date"), result.get("end_date"))
    metric = analytics_metric_from_text(result.get("metric") or "")
    counts = result.get("counts") if isinstance(result.get("counts"), dict) else {}
    pending_review = int(counts.get("pending_leave") or 0) + int(counts.get("pending_availability") or 0) + int(counts.get("pending_swaps") or 0)
    lines = [f"Workforce analytics ({period}):"]
    lines.append(
        f"- Scheduled shifts: {counts.get('scheduled_shifts', 0)} | Absences: {counts.get('absent_records', 0)} | Late records: {counts.get('late_records', 0)} | Pending review: {pending_review}"
    )
    priority_metrics = {
        "late": {"Top lateness", "Late records"},
        "absence": {"Top absence", "Absences", "Branch absences"},
        "overtime": {"Overtime risk"},
        "branch": {"Branch absences"},
        "coverage": {"Scheduled shifts", "Pending review"},
        "attendance_quality": {"Best attendance"},
        "review": {"Pending review", "Top lateness", "Top absence", "Overtime risk"},
    }.get(metric, set())
    selected = [item for item in insights if not priority_metrics or item.get("metric") in priority_metrics]
    if not selected:
        selected = insights
    for item in selected[:8]:
        lines.append(f"- {item.get('metric')}: {item.get('subject')} - {item.get('value')} ({item.get('detail')})")
    if len(selected) > 8:
        lines.append(f"And {len(selected) - 8} more insight rows.")
    sheet_sync = result.get("sheet_sync") if isinstance(result.get("sheet_sync"), dict) else {}
    if sheet_sync.get("ok") and not sheet_sync.get("skipped"):
        lines.append("Analytics sheet updated.")
    return "\n".join(lines)


def timesheet_hours_parts(row: dict[str, Any]) -> str:
    pieces = [
        f"worked {decimal_hours(row.get('worked_minutes'))}h",
        f"scheduled {decimal_hours(row.get('scheduled_minutes'))}h",
    ]
    if int(row.get("approved_leave_minutes") or 0):
        pieces.append(f"approved leave {decimal_hours(row.get('approved_leave_minutes'))}h")
    if int(row.get("absent_minutes") or 0):
        pieces.append(f"absent {decimal_hours(row.get('absent_minutes'))}h")
    if int(row.get("overtime_minutes") or 0):
        pieces.append(f"overtime {decimal_hours(row.get('overtime_minutes'))}h")
    if int(row.get("late_minutes") or 0):
        pieces.append(f"{row.get('late_minutes')} min late")
    return ", ".join(pieces)


def format_create_timesheet_review_reply(result: dict[str, Any]) -> str:
    if not result.get("ok"):
        if result.get("error") == "employee_outside_manager_scope":
            return "That employee is outside your manager scope."
        if result.get("error") == "employee_not_found":
            return "I need the exact employee name or phone before preparing that timesheet."
        return "I could not prepare timesheets safely."
    rows = result.get("timesheets") if isinstance(result.get("timesheets"), list) else []
    period = format_shift_date_range(result.get("start_date"), result.get("end_date"))
    if not rows:
        skipped = result.get("skipped_approved") if isinstance(result.get("skipped_approved"), list) else []
        if skipped:
            return f"Those timesheets for {period} are already approved, so I did not overwrite them."
        return f"No payroll hours found to prepare timesheets for {period}."
    lines = [f"Prepared {len(rows)} draft timesheet{'s' if len(rows) != 1 else ''} for {period}:"]
    for row in rows[:10]:
        lines.append(f"- {row.get('employee_name') or row.get('employee_phone')}: {timesheet_hours_parts(row)} ({row.get('payroll_status') or 'Ready'})")
    if len(rows) > 10:
        lines.append(f"And {len(rows) - 10} more timesheets.")
    skipped = result.get("skipped_approved") if isinstance(result.get("skipped_approved"), list) else []
    if skipped:
        lines.append(f"Skipped {len(skipped)} already-approved timesheet{'s' if len(skipped) != 1 else ''}.")
    sheet_sync = result.get("sheet_sync") if isinstance(result.get("sheet_sync"), dict) else {}
    if sheet_sync.get("ok"):
        lines.append("Timesheet Approvals sheet updated.")
    lines.append("Review these, then approve or reject the timesheets for that period.")
    return "\n".join(lines)


def format_timesheet_decision_reply(result: dict[str, Any], decision: str) -> str:
    if not result.get("ok"):
        if result.get("error") == "missing_period":
            return "Which timesheet period should I change? Send a period like this week, this month, or a date range."
        if result.get("error") == "timesheet_not_found":
            return "I could not find draft timesheets for that period. Prepare the timesheets first, then approve or reject them."
        return "I could not update timesheets safely."
    rows = result.get("timesheets") if isinstance(result.get("timesheets"), list) else []
    if not rows:
        return "I did not find draft timesheets to update."
    label = "Approved" if decision == "approved" else "Rejected"
    period = format_shift_date_range(rows[0].get("period_start"), rows[0].get("period_end"))
    lines = [f"{label} {len(rows)} timesheet{'s' if len(rows) != 1 else ''} for {period}:"]
    for row in rows[:10]:
        lines.append(f"- {row.get('employee_name') or row.get('employee_phone')}: {timesheet_hours_parts(row)}")
    if len(rows) > 10:
        lines.append(f"And {len(rows) - 10} more timesheets.")
    sheet_sync = result.get("sheet_sync") if isinstance(result.get("sheet_sync"), dict) else {}
    if sheet_sync.get("ok"):
        lines.append("Timesheet Approvals sheet updated.")
    return "\n".join(lines)


