def format_set_payroll_policy_reply(result: dict[str, Any]) -> str:
    if not result.get("ok"):
        if result.get("error") == "no_policy_updates":
            return "Which payroll policy should I update? For example: set overtime policy to review only, make leave unpaid, or enable absence deductions."
        return "I could not update payroll policy safely."
    updates = result.get("updates") if isinstance(result.get("updates"), dict) else {}
    lines = ["Payroll policy updated:"]
    for key, value in updates.items():
        label = display_status(key)
        if isinstance(value, bool):
            lines.append(f"- {label}: {format_policy_bool(value)}")
        elif key.endswith("_kwd") and value is not None:
            lines.append(f"- {label}: {float(value):.3f} KWD")
        elif key.endswith("_minutes"):
            lines.append(f"- {label}: {decimal_hours(value)}h")
        else:
            lines.append(f"- {label}: {display_status(value)}")
    lines.append("Payment processing is still disabled; this only affects previews.")
    return "\n".join(lines)


