def notify_employee_shift_created(
    *,
    result: dict[str, Any],
    account_id: str | None,
    created_by_phone: str | None,
) -> dict[str, Any]:
    if result.get("bulk"):
        notifications: list[dict[str, Any]] = []
        for item in result.get("results") if isinstance(result.get("results"), list) else []:
            if isinstance(item, dict) and item.get("ok"):
                notification = notify_employee_shift_created(result=item, account_id=account_id, created_by_phone=created_by_phone)
                item["employee_notification"] = notification
                notifications.append(notification)
        return {"ok": any(item.get("ok") for item in notifications), "notifications": notifications}
    employee = result.get("employee") if isinstance(result.get("employee"), dict) else {}
    created = result.get("created") if isinstance(result.get("created"), list) else []
    if not employee or not created:
        return {"ok": False, "error": "missing_employee_or_shift"}
    message = shift_creation_employee_message(created)
    # Phase E: route shift assignment through the delivery layer when enabled
    # (template -> email -> needs-follow-up). Default off keeps direct WhatsApp.
    if outbound_flow_enabled("shift"):
        first = created[0] if created else {}
        send_result = deliver_employee_notification(
            employee,
            flow="shift",
            template_key="shift_assigned",
            text=message,
            email_subject="Your shift schedule",
            account_id=account_id,
            company_code=str(first.get("company_code") or employee.get("company_code") or "WATHEFNI"),
            variables={
                "shift_date": format_shift_date(first.get("shift_date")),
                "shift_time": format_shift_time(first.get("start_time")),
                "location": first.get("location") or "",
            },
        )
    else:
        send_result = send_custom_employee_message(employee, account_id, message)
    with db_connect() as conn:
        with conn.cursor() as cur:
            for shift in created:
                record_shift_event(
                    cur,
                    shift=shift,
                    company_code=str(shift.get("company_code") or employee.get("company_code") or "WATHEFNI"),
                    event_type="employee_notified" if send_result.get("ok") else "employee_notification_failed",
                    payload={"message": message, "send": send_result, "shift_id": shift.get("shift_id")},
                    created_by_phone=created_by_phone,
                )
        conn.commit()
    return {"ok": bool(send_result.get("ok")), "message": message, "send": send_result}


def notify_employee_shift_cancelled(
    *,
    result: dict[str, Any],
    account_id: str | None,
    created_by_phone: str | None,
) -> dict[str, Any]:
    if result.get("bulk"):
        notifications: list[dict[str, Any]] = []
        for item in result.get("results") if isinstance(result.get("results"), list) else []:
            if isinstance(item, dict) and item.get("ok"):
                notification = notify_employee_shift_cancelled(result=item, account_id=account_id, created_by_phone=created_by_phone)
                item["employee_notification"] = notification
                notifications.append(notification)
        return {"ok": any(item.get("ok") for item in notifications), "notifications": notifications}
    employee = result.get("employee") if isinstance(result.get("employee"), dict) else {}
    cancelled = result.get("cancelled") if isinstance(result.get("cancelled"), list) else []
    if not employee or not cancelled:
        return {"ok": False, "error": "missing_employee_or_shift"}
    message = shift_cancellation_employee_message(cancelled)
    if outbound_flow_enabled("shift"):
        first = cancelled[0] if cancelled else {}
        send_result = deliver_employee_notification(
            employee,
            flow="shift",
            template_key="shift_cancelled",
            text=message,
            email_subject="A shift was cancelled",
            account_id=account_id,
            company_code=str(first.get("company_code") or employee.get("company_code") or "WATHEFNI"),
            variables={"shift_date": format_shift_date(first.get("shift_date"))},
        )
    else:
        send_result = send_custom_employee_message(employee, account_id, message)
    with db_connect() as conn:
        with conn.cursor() as cur:
            for shift in cancelled:
                record_shift_event(
                    cur,
                    shift=shift,
                    company_code=str(shift.get("company_code") or employee.get("company_code") or "WATHEFNI"),
                    event_type="employee_cancellation_notified" if send_result.get("ok") else "employee_cancellation_notification_failed",
                    payload={"message": message, "send": send_result, "shift_id": shift.get("shift_id")},
                    created_by_phone=created_by_phone,
                )
        conn.commit()
    return {"ok": bool(send_result.get("ok")), "message": message, "send": send_result}


def format_list_shifts_reply(result: dict[str, Any], *, employee_view: bool = False) -> str:
    if not result.get("ok") and result.get("error") == "employee_outside_manager_scope":
        return "That employee is outside your manager scope."
    shifts = result.get("shifts") if isinstance(result.get("shifts"), list) else []
    if not shifts:
        if employee_view:
            return "You do not have any scheduled shifts for that period."
        return "No scheduled shifts found for that period."
    title = "Your shifts:" if employee_view else f"Scheduled shifts ({format_shift_date_range(result.get('start_date'), result.get('end_date'))}):"
    lines = [title]
    for shift in shifts[:20]:
        name = "" if employee_view else f"{shift.get('employee_name') or shift.get('employee_phone')} — "
        extra = []
        if shift.get("location"):
            extra.append(str(shift.get("location")))
        if shift.get("role"):
            extra.append(str(shift.get("role")))
        suffix = f" ({', '.join(extra)})" if extra else ""
        lines.append(f"- {format_shift_date(shift.get('shift_date'))}: {name}{format_shift_time(shift.get('start_time'))}-{format_shift_time(shift.get('end_time'))}{suffix}")
    if len(shifts) > 20:
        lines.append(f"And {len(shifts) - 20} more shifts.")
    return "\n".join(lines)


def format_cancel_shift_reply(result: dict[str, Any]) -> str:
    if result.get("bulk"):
        results = result.get("results") if isinstance(result.get("results"), list) else []
        lines = [f"Bulk shift cancellation complete: {result.get('completed_count', 0)}/{result.get('requested_count', len(results))} employees had shifts cancelled."]
        for item in results[:8]:
            if not isinstance(item, dict):
                continue
            employee = item.get("employee") if isinstance(item.get("employee"), dict) else {}
            name = employee.get("name") or employee.get("phone") or "Employee"
            cancelled_count = len(item.get("cancelled") if isinstance(item.get("cancelled"), list) else [])
            if item.get("ok"):
                note = f"{name}: {cancelled_count} shift{'s' if cancelled_count != 1 else ''}"
                notification = item.get("employee_notification") if isinstance(item.get("employee_notification"), dict) else {}
                if notification:
                    note += f", {notification_status_text(notification)}"
                lines.append(f"- {note}")
            else:
                lines.append(f"- {name}: no scheduled shifts found")
        unresolved = result.get("unresolved") if isinstance(result.get("unresolved"), list) else []
        if unresolved:
            lines.append(f"{len(unresolved)} employee reference{'s' if len(unresolved) != 1 else ''} could not be resolved.")
        if len(results) > 8:
            lines.append(f"And {len(results) - 8} more results.")
        return "\n".join(lines)
    if not result.get("ok"):
        if result.get("error") == "employee_outside_manager_scope":
            return "That employee is outside your manager scope."
        if result.get("error") == "employee_not_found":
            return "I could not find that employee to cancel shifts."
        return "I could not find scheduled shifts to cancel for that employee and period."
    employee = result.get("employee") or {}
    count = len(result.get("cancelled") or [])
    reply = f"Cancelled {count} shift{'s' if count != 1 else ''} for {employee.get('name') or employee.get('phone')}."
    notification = result.get("employee_notification") if isinstance(result.get("employee_notification"), dict) else {}
    if notification:
        if notification.get("ok"):
            reply += f" {employee.get('name') or 'The employee'} was notified."
        else:
            reply += f" {employee.get('name') or 'The employee'} was cancelled, but {notification_status_text(notification)}."
    return reply


def format_request_availability_reply(result: dict[str, Any], *, employee_view: bool = False) -> str:
    if not result.get("ok"):
        error = result.get("error")
        if error == "employee_outside_manager_scope":
            return "That employee is outside your manager scope."
        if error == "employee_not_found":
            return "I need the employee name or phone before recording availability."
        if error == "employee_company_mismatch":
            return "That employee does not belong to this company."
        return "I could not record availability safely."
    availability = result.get("availability") if isinstance(result.get("availability"), dict) else {}
    employee = result.get("employee") if isinstance(result.get("employee"), dict) else {}
    name = "your" if employee_view else f"{employee.get('name') or availability.get('employee_name') or 'Employee'}'s"
    date_text = format_shift_date_range(availability.get("start_date"), availability.get("end_date"))
    status = str(availability.get("status") or "requested")
    kind = display_status(availability.get("availability_type")).lower() or "availability"
    if employee_view:
        suffix = " HR has been notified." if status == "requested" else ""
        return f"I recorded your {kind} availability for {date_text}.{suffix}"
    return f"Recorded {name} {kind} availability for {date_text} ({display_status(status)})."


def format_list_availability_reply(result: dict[str, Any], *, employee_view: bool = False) -> str:
    if not result.get("ok") and result.get("error") == "employee_outside_manager_scope":
        return "That employee is outside your manager scope."
    rows = result.get("availability") if isinstance(result.get("availability"), list) else []
    period = format_shift_date_range(result.get("start_date"), result.get("end_date"))
    if not rows:
        return f"I do not see availability records for you in {period}." if employee_view else f"No availability records found for {period}."
    lines = ["Your availability:" if employee_view else f"Availability ({period}):"]
    for row in rows[:20]:
        name = "" if employee_view else f"{row.get('employee_name') or row.get('employee_phone')} - "
        lines.append(
            f"- {format_shift_date_range(row.get('start_date'), row.get('end_date'))}: {name}{display_status(row.get('availability_type'))}, {display_status(row.get('status'))}, {availability_time_window(row)}"
        )
    if len(rows) > 20:
        lines.append(f"And {len(rows) - 20} more records.")
    return "\n".join(lines)


def format_request_shift_swap_reply(result: dict[str, Any], *, employee_view: bool = False) -> str:
    if not result.get("ok"):
        error = result.get("error")
        if error == "employee_outside_manager_scope":
            return "That employee is outside your manager scope."
        if error == "employee_not_found":
            return "I need the employee name or phone before creating a shift swap request."
        if error == "no_scheduled_shift":
            return "I could not find a scheduled shift for that employee in the requested period."
        if error == "ambiguous_shift":
            return "I found more than one scheduled shift. Please specify the exact shift date or time."
        if error == "target_company_mismatch":
            return "The swap target does not belong to this company."
        return "I could not create the shift swap request safely."
    swap = result.get("swap") if isinstance(result.get("swap"), dict) else {}
    date_text = format_shift_date(swap.get("shift_date"))
    target = swap.get("target_employee_name")
    if employee_view:
        target_text = f" with {target}" if target else ""
        return f"Your shift swap request for {date_text}{target_text} has been sent to HR for approval."
    requester = swap.get("requester_employee_name") or "Employee"
    target_text = f" with {target}" if target else ""
    return f"Shift swap request created for {requester} on {date_text}{target_text}."


def format_shift_swap_decision_reply(result: dict[str, Any], decision: str) -> str:
    if not result.get("ok"):
        error = result.get("error")
        if error == "employee_outside_manager_scope":
            return "That shift swap is outside your manager scope."
        if error == "shift_swap_not_found":
            return "I could not find one pending shift swap request to update."
        if error == "ambiguous_shift_swap":
            return "I found more than one pending shift swap. Please specify the employee, date, or swap ID."
        if error == "target_shift_conflict":
            return "I cannot approve that swap because the target employee has a shift conflict."
        if error == "missing_target_employee":
            return "I cannot approve that swap until the target employee is clear."
        if error == "requester_shift_not_active":
            return "I cannot approve that swap because the original shift is no longer active."
        return "I could not update the shift swap safely."
    swap = result.get("swap") if isinstance(result.get("swap"), dict) else {}
    label = "Approved" if decision == "approved" else "Rejected"
    return f"{label} shift swap for {swap.get('requester_employee_name') or 'the employee'} on {format_shift_date(swap.get('shift_date'))}."


def format_list_shift_swaps_reply(result: dict[str, Any]) -> str:
    if not result.get("ok"):
        return "I could not list shift swaps safely."
    rows = result.get("swaps") if isinstance(result.get("swaps"), list) else []
    period = format_shift_date_range(result.get("start_date"), result.get("end_date"))
    if not rows:
        return f"No shift swap requests found for {period}."
    lines = [f"Shift swaps ({period}):"]
    for row in rows[:20]:
        target = f" with {row.get('target_employee_name')}" if row.get("target_employee_name") else ""
        lines.append(f"- {format_shift_date(row.get('shift_date'))}: {row.get('requester_employee_name') or row.get('requester_employee_phone')}{target} - {display_status(row.get('status'))}")
    if len(rows) > 20:
        lines.append(f"And {len(rows) - 20} more requests.")
    return "\n".join(lines)


def latest_shift_conflict_context(text: str | None = None) -> dict[str, Any] | None:
    employee = employee_mentioned_in_text(text or "")
    filters = [
        str(value).lower()
        for value in [
            (employee or {}).get("employee_key"),
            (employee or {}).get("phone"),
            (employee or {}).get("name"),
        ]
        if value
    ]
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT ar.action_type, ar.status, ar.result, ar.final_reply, ar.created_at, ht.raw_text
                FROM action_results ar
                LEFT JOIN hr_turns ht ON ht.turn_id=ar.turn_id
                WHERE ar.action_type='create_shift_assignment'
                  AND ar.created_at > now() - interval '45 minutes'
                  AND ar.result ? 'conflicts'
                ORDER BY ar.created_at DESC
                LIMIT 10
                """
            )
            rows = [dict(row) for row in cur.fetchall()]
    for row in rows:
        payload = row.get("result") if isinstance(row.get("result"), dict) else {}
        conflicts = payload.get("conflicts") if isinstance(payload.get("conflicts"), list) else []
        if not conflicts:
            continue
        haystack = json.dumps(json_safe(row), ensure_ascii=False).lower()
        if filters and not any(item in haystack for item in filters):
            continue
        return row
    return None


def explicit_shift_replacement_action(text: str) -> dict[str, Any] | None:
    normalized = normalize_text(text)
    if not normalized or len(normalized) > 240:
        return None
    has_cancel = re.search(r"\b(cancel|remove|delete)\b", normalized)
    has_schedule = re.search(r"\b(schedule|reschedule|replace|change)\b", normalized)
    has_shift = re.search(r"\b(shift|work|roster)\b", normalized)
    if not (has_cancel and has_schedule and has_shift):
        return None
    start_time, end_time, time_error = extract_shift_time_range({"prompt_text": text})
    employee = employee_mentioned_in_text(text)
    if not employee:
        return None
    start_date, end_date = shift_query_window({"prompt_text": text})
    action: dict[str, Any] = {
        "action_type": "replace_conflicting_shift_assignment",
        "subject_type": "shift",
        "subject_name": employee.get("name"),
        "subject_phone": employee.get("phone"),
        "prompt_text": text,
        "date": start_date.isoformat() if start_date == end_date else "",
        "start_date": start_date.isoformat(),
        "end_date": end_date.isoformat(),
        "employee": json_safe(employee),
        "replace_mode": "explicit_cancel_and_schedule",
        "allow_create_without_cancel": True,
    }
    if time_error:
        action["error"] = time_error
    else:
        action["start_time"] = format_shift_time(start_time)
        action["end_time"] = format_shift_time(end_time)
    return action


def infer_shift_conflict_replacement_action(text: str) -> dict[str, Any] | None:
    normalized = normalize_text(text)
    if not normalized or len(normalized) > 180:
        return None
    if not re.search(r"\b(cancel|replace|change|reschedule|schedule|yes|this|that)\b", normalized):
        return None
    context = latest_shift_conflict_context(text)
    if not context:
        return None
    payload = context.get("result") if isinstance(context.get("result"), dict) else {}
    employee = payload.get("employee") if isinstance(payload.get("employee"), dict) else {}
    conflicts = payload.get("conflicts") if isinstance(payload.get("conflicts"), list) else []
    if not employee or not conflicts:
        return None
    previous_text = str(context.get("raw_text") or "")
    start_time, end_time, time_error = extract_shift_time_range({"prompt_text": text})
    if time_error:
        start_time, end_time, time_error = extract_shift_time_range({"prompt_text": previous_text})
    if time_error:
        return {
            "action_type": "replace_conflicting_shift_assignment",
            "subject_type": "shift",
            "subject_name": employee.get("name"),
            "subject_phone": employee.get("phone"),
            "prompt_text": text,
            "previous_prompt_text": previous_text,
            "error": time_error,
            "context": json_safe(context),
        }
    first_conflict = conflicts[0]
    shift_date = str(first_conflict.get("shift_date") or (payload.get("requested_dates") or [""])[0] or "")
    return {
        "action_type": "replace_conflicting_shift_assignment",
        "subject_type": "shift",
        "subject_name": employee.get("name"),
        "subject_phone": employee.get("phone"),
        "prompt_text": text,
        "previous_prompt_text": previous_text,
        "date": shift_date,
        "start_time": format_shift_time(start_time),
        "end_time": format_shift_time(end_time),
        "employee": json_safe(employee),
        "conflict_shift_ids": [str(item.get("shift_id")) for item in conflicts if item.get("shift_id")],
        "conflicts": json_safe(conflicts),
        "context_created_at": json_safe(context.get("created_at")),
    }


def infer_shift_replacement_action(text: str) -> dict[str, Any] | None:
    return explicit_shift_replacement_action(text) or infer_shift_conflict_replacement_action(text)


def active_shift_ids_for_replacement(employee: dict[str, Any], action: dict[str, Any], *, company_code: str | None) -> list[str]:
    company = (company_code or employee.get("company_code") or "WATHEFNI").upper()
    start_date, end_date = shift_query_window(action)
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT shift_id
                FROM shift_assignments
                WHERE company_code=%s
                  AND employee_key=%s
                  AND shift_date BETWEEN %s AND %s
                  AND status='scheduled'
                ORDER BY shift_date, start_time
                LIMIT 25
                """,
                (company, employee.get("employee_key"), start_date, end_date),
            )
            return [str(row["shift_id"]) for row in cur.fetchall() if row.get("shift_id")]


def replace_conflicting_shift_assignment(
    action: dict[str, Any],
    *,
    company_code: str | None,
    created_by_phone: str | None,
    account_id: str | None,
) -> dict[str, Any]:
    if action.get("error"):
        return {"ok": False, "error": action.get("error"), "action": json_safe(action)}
    employee = action.get("employee") if isinstance(action.get("employee"), dict) else None
    if not employee:
        employee = resolve_shift_employee(action, required=True)
    if not employee:
        return {"ok": False, "error": "employee_not_found", "action": json_safe(action)}
    company = (company_code or employee.get("company_code") or "WATHEFNI").upper()
    conflict_ids = [item for item in action.get("conflict_shift_ids", []) if item]
    if not conflict_ids:
        conflict_ids = active_shift_ids_for_replacement(employee, action, company_code=company)
    if not conflict_ids and not action.get("allow_create_without_cancel"):
        return {"ok": False, "error": "missing_conflict_shift", "employee": json_safe(employee), "action": json_safe(action)}
    cancelled: list[dict[str, Any]] = []
    if conflict_ids:
        with db_connect() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """
                    UPDATE shift_assignments
                    SET status='cancelled', updated_at=now()
                    WHERE company_code=%s
                      AND employee_key=%s
                      AND shift_id = ANY(%s::uuid[])
                      AND status='scheduled'
                    RETURNING *
                    """,
                    (company, employee.get("employee_key"), conflict_ids),
                )
                cancelled = [dict(row) for row in cur.fetchall()]
                for shift in cancelled:
                    record_shift_event(cur, shift=shift, company_code=company, event_type="cancelled_for_replacement", payload={"action": action, "shift": shift}, created_by_phone=created_by_phone)
            conn.commit()
    cancel_sheet_sync = sync_shift_sheet_rows(company, cancelled) if cancelled else {"ok": True, "skipped": True, "reason": "no_cancelled_shifts"}
    create_result = create_shift_assignment_for_employee(action, employee=employee, company_code=company, created_by_phone=created_by_phone)
    if create_result.get("ok"):
        create_result["employee_notification"] = notify_employee_shift_created(result=create_result, account_id=account_id, created_by_phone=created_by_phone)
    cancel_notification = {"ok": False, "skipped": True}
    if cancelled:
        cancel_notification = notify_employee_shift_cancelled(
            result={"ok": True, "employee": json_safe(employee), "cancelled": json_safe(cancelled)},
            account_id=account_id,
            created_by_phone=created_by_phone,
        )
    return {
        "ok": bool(create_result.get("ok")) and (bool(cancelled) or bool(action.get("allow_create_without_cancel"))),
        "employee": json_safe(employee),
        "cancelled": json_safe(cancelled),
        "created": json_safe(create_result.get("created") if isinstance(create_result.get("created"), list) else []),
        "create_result": json_safe(create_result),
        "cancel_sheet_sync": json_safe(cancel_sheet_sync),
        "cancel_notification": json_safe(cancel_notification),
        "action": json_safe(action),
    }


def format_replace_shift_reply(result: dict[str, Any]) -> str:
    employee = result.get("employee") if isinstance(result.get("employee"), dict) else {}
    name = employee.get("name") or employee.get("phone") or "the employee"
    if not result.get("ok"):
        if result.get("error") == "missing_shift_time":
            return f"I can replace {name}'s conflicting shift, but I need the new time."
        if result.get("error") == "invalid_shift_time_range":
            return "That replacement time range is invalid. Please use a same-day start and end time."
        return f"I could not replace the conflicting shift for {name}."
    created = result.get("created") if isinstance(result.get("created"), list) else []
    if created:
        shift = created[0]
        cancelled = result.get("cancelled") if isinstance(result.get("cancelled"), list) else []
        if not cancelled:
            return f"Scheduled the replacement for {name} on {format_shift_date(shift.get('shift_date'))} from {format_shift_time(shift.get('start_time'))} to {format_shift_time(shift.get('end_time'))}."
        return f"Cancelled {name}'s conflicting shift and scheduled the replacement for {format_shift_date(shift.get('shift_date'))} from {format_shift_time(shift.get('start_time'))} to {format_shift_time(shift.get('end_time'))}."
    return f"Cancelled {name}'s conflicting shift, but I could not create the replacement."


def is_employee_shift_question(text: str) -> bool:
    normalized = normalize_text(text)
    return bool(
        re.search(r"\b(shift|shifts|schedule|roster|working|work|availability|available|unavailable)\b", normalized)
        and re.search(r"\b(today|tomorrow|week|when|what|am i|my|status)\b", normalized)
    )


def is_employee_shift_objection(text: str) -> bool:
    normalized = normalize_text(text)
    if not normalized:
        return False
    shift_objection = bool(
        re.search(r"\b(shift|work|schedule|roster|time|today|tomorrow)\b", normalized)
        and re.search(r"\b(cant|can't|cannot|wont|won't|unable|not able|not available|unavailable|available|wrong|mistake|change|swap|late|sick|off|cancel)\b", normalized)
    )
    availability_request = bool(
        re.search(r"\b(available|availability|unavailable|not available|cannot work|can't work|cant work|can work|free|prefer|preferred)\b", normalized)
        and re.search(r"\b(today|tomorrow|week|monday|tuesday|wednesday|thursday|friday|saturday|sunday|next|this)\b", normalized)
    )
    swap_request = bool(re.search(r"\b(swap|switch|trade)\b", normalized))
    return shift_objection or availability_request or swap_request


def handle_employee_shift_objection_turn(request: WhatsAppTurnRequest) -> dict[str, Any] | None:
    employee = find_employee_by_phone(request.sender_phone)
    if not employee or not is_employee_shift_objection(request.raw_text):
        return None
    if not company_has_module(employee.get("company_code"), "shifts"):
        return {"error": "module_disabled", "company_code": employee.get("company_code"), "required_module": "shifts", "employee_key": employee.get("employee_key")}
    availability_action = infer_availability_action(request.raw_text, request=request)
    if availability_action and availability_action.get("action_type") in {"request_availability", "request_shift_swap"}:
        availability_action["subject_phone"] = employee.get("phone")
        if availability_action.get("action_type") == "request_shift_swap":
            result = request_shift_swap(
                availability_action,
                company_code=employee.get("company_code"),
                created_by_phone=employee.get("phone"),
                account_id=request.account_id,
            )
            return {
                "reply": format_request_shift_swap_reply(result, employee_view=True),
                "employee_key": employee.get("employee_key"),
                "result": result,
                "intent": "request_shift_swap",
                "turn_focus": "employee_shift_swap",
            }
        result = request_availability(
            availability_action,
            company_code=employee.get("company_code"),
            created_by_phone=employee.get("phone"),
            account_id=request.account_id,
        )
        return {
            "reply": format_request_availability_reply(result, employee_view=True),
            "employee_key": employee.get("employee_key"),
            "result": result,
            "intent": "request_availability",
            "turn_focus": "employee_availability",
        }
    action = {
        "prompt_text": request.raw_text,
        "subject_phone": employee.get("phone"),
    }
    result = list_shifts(action, company_code=employee.get("company_code"))
    shifts = result.get("shifts") if isinstance(result.get("shifts"), list) else []
    name = employee.get("name") or employee.get("phone") or "Employee"
    if shifts:
        shift_text = "; ".join(
            f"{format_shift_date(shift.get('shift_date'))} {format_shift_time(shift.get('start_time'))}-{format_shift_time(shift.get('end_time'))}"
            for shift in shifts[:3]
        )
        reply = f"I understand, {name}. I found your scheduled shift: {shift_text}. I have notified HR, but I cannot change or cancel it until HR updates the schedule."
    else:
        reply = f"I understand, {name}. I do not see a scheduled shift for that period, but I have notified HR about your message."
    hr_message = f"{name} replied about a shift: \"{request.raw_text}\""
    if shifts:
        hr_message += f" Scheduled shift: {shift_text}."
    hr_notification = notify_hr_admins(
        company_code=employee.get("company_code"),
        account_id=request.account_id,
        message=hr_message,
        subject_type="employee_shift",
        subject_key=employee.get("employee_key"),
    )
    with db_connect() as conn:
        with conn.cursor() as cur:
            if shifts:
                for shift in shifts[:5]:
                    record_shift_event(
                        cur,
                        shift=shift,
                        company_code=str(shift.get("company_code") or employee.get("company_code") or "WATHEFNI"),
                        event_type="employee_shift_objection",
                        payload={"raw_text": request.raw_text, "employee": json_safe(employee), "hr_notification": hr_notification},
                        created_by_phone=employee.get("phone"),
                    )
            else:
                record_shift_event(
                    cur,
                    shift=None,
                    company_code=str(employee.get("company_code") or "WATHEFNI"),
                    event_type="employee_shift_objection",
                    payload={"raw_text": request.raw_text, "employee_key": employee.get("employee_key"), "employee": json_safe(employee), "hr_notification": hr_notification},
                    created_by_phone=employee.get("phone"),
                )
        conn.commit()
    return {"reply": reply, "employee_key": employee.get("employee_key"), "result": result, "hr_notification": hr_notification}


def handle_employee_shift_turn(request: WhatsAppTurnRequest) -> dict[str, Any] | None:
    employee = find_employee_by_phone(request.sender_phone)
    if not employee or not is_employee_shift_question(request.raw_text):
        return None
    if not company_has_module(employee.get("company_code"), "shifts"):
        return {"error": "module_disabled", "company_code": employee.get("company_code"), "required_module": "shifts", "employee_key": employee.get("employee_key")}
    availability_action = infer_availability_action(request.raw_text, request=request)
    if availability_action and availability_action.get("action_type") == "list_availability":
        availability_action["subject_phone"] = employee.get("phone")
        result = list_availability(availability_action, company_code=employee.get("company_code"))
        return {"reply": format_list_availability_reply(result, employee_view=True), "employee_key": employee.get("employee_key"), "result": result}
    action = {
        "prompt_text": request.raw_text,
        "subject_phone": employee.get("phone"),
    }
    result = list_shifts(action, company_code=employee.get("company_code"))
    return {"reply": format_list_shifts_reply(result, employee_view=True), "employee_key": employee.get("employee_key"), "result": result}


def is_employee_attendance_command(text: str) -> bool:
    normalized = normalize_text(text)
    return bool(
        re.search(r"\b(check(?:ed)? in|clock(?:ed)? in|i'?m here|i am here|arrived|present|check(?:ed)? out|clock(?:ed)? out|leaving|left|attendance)\b", normalized)
    )


def handle_employee_attendance_turn(request: WhatsAppTurnRequest) -> dict[str, Any] | None:
    employee = find_employee_by_phone(request.sender_phone)
    if not employee or not is_employee_attendance_command(request.raw_text):
        return None
    if not company_has_module(employee.get("company_code"), "attendance"):
        return {"error": "module_disabled", "company_code": employee.get("company_code"), "required_module": "attendance", "employee_key": employee.get("employee_key")}
    action = infer_attendance_action(request.raw_text, request=request)
    if not action:
        return None
    action["subject_phone"] = employee.get("phone")
    company = employee.get("company_code")
    if action.get("action_type") == "check_in_employee":
        result = check_in_employee(action, company_code=company, created_by_phone=employee.get("phone"))
        reply = format_attendance_mutation_reply(result, "check_in_employee")
        if result.get("ok") and int(((result.get("attendance") or {}).get("late_minutes") or 0)) > 0:
            result["hr_notification"] = notify_attendance_exception(result, account_id=request.account_id, event_type="late_check_in")
        return {"reply": reply, "employee_key": employee.get("employee_key"), "result": result, "intent": "check_in_employee", "turn_focus": "employee_attendance"}
    if action.get("action_type") == "check_out_employee":
        result = check_out_employee(action, company_code=company, created_by_phone=employee.get("phone"))
        return {"reply": format_attendance_mutation_reply(result, "check_out_employee"), "employee_key": employee.get("employee_key"), "result": result, "intent": "check_out_employee", "turn_focus": "employee_attendance"}
    result = list_attendance(action, company_code=company)
    return {"reply": format_list_attendance_reply(result, employee_view=True), "employee_key": employee.get("employee_key"), "result": result, "intent": "list_attendance", "turn_focus": "employee_attendance"}


def is_employee_leave_command(text: str) -> bool:
    normalized = normalize_text(text)
    return bool(re.search(r"\b(leave|time off|day off|sick|vacation|holiday|off today|off tomorrow|my leave)\b", normalized))


def handle_employee_leave_turn(request: WhatsAppTurnRequest) -> dict[str, Any] | None:
    employee = find_employee_by_phone(request.sender_phone)
    if not employee or not is_employee_leave_command(request.raw_text):
        return None
    if not company_has_module(employee.get("company_code"), "leave"):
        return {"error": "module_disabled", "company_code": employee.get("company_code"), "required_module": "leave", "employee_key": employee.get("employee_key")}
    action = infer_leave_action(request.raw_text, request=request)
    if not action:
        return None
    action["subject_phone"] = employee.get("phone")
    company = employee.get("company_code")
    action_type = action.get("action_type")
    if action_type == "request_leave":
        result = request_leave(action, company_code=company, created_by_phone=employee.get("phone"))
        return {"reply": format_leave_mutation_reply(result, "request_leave", employee_view=True), "employee_key": employee.get("employee_key"), "result": result, "intent": "request_leave", "turn_focus": "employee_leave"}
    if action_type == "cancel_leave_request":
        result = cancel_leave_request(action, company_code=company, created_by_phone=employee.get("phone"), account_id=request.account_id)
        return {"reply": format_leave_mutation_reply(result, "cancel_leave_request", employee_view=True), "employee_key": employee.get("employee_key"), "result": result, "intent": "cancel_leave_request", "turn_focus": "employee_leave"}
    result = list_leave_requests(action, company_code=company)
    return {"reply": format_list_leave_requests_reply(result, employee_view=True), "employee_key": employee.get("employee_key"), "result": result, "intent": "list_leave_requests", "turn_focus": "employee_leave"}


def is_employee_payroll_command(text: str) -> bool:
    normalized = normalize_text(text)
    if not normalized:
        return False
    if re.search(r"\b(export payroll|payroll export|policy|rate|salary|bank file|transfer|pay me|payment)\b", normalized):
        return True
    return bool(
        re.search(r"\b(my\s+)?(payroll|hours|worked|scheduled hours|overtime|late minutes|early leave|timesheets?|time sheets?|pay period)\b", normalized)
        or re.search(r"\bhow many hours\b", normalized)
    )


def handle_employee_payroll_turn(request: WhatsAppTurnRequest) -> dict[str, Any] | None:
    employee = find_employee_by_phone(request.sender_phone)
    if not employee or not is_employee_payroll_command(request.raw_text):
        return None
    if not company_has_module(employee.get("company_code"), "payroll"):
        return {"error": "module_disabled", "company_code": employee.get("company_code"), "required_module": "payroll", "employee_key": employee.get("employee_key")}
    normalized = normalize_text(request.raw_text)
    if re.search(r"\b(export payroll|payroll export|policy|rate|salary|bank file|transfer|pay me|payment)\b", normalized):
        return {
            "reply": "I can show your own payroll hours and timesheet status. Salary amounts, payroll exports, bank files, and payments are handled by HR.",
            "employee_key": employee.get("employee_key"),
            "intent": "employee_payroll_boundary",
            "turn_focus": "employee_payroll",
            "result": {"ok": False, "error": "employee_payroll_boundary", "employee_key": employee.get("employee_key")},
        }
    company = employee.get("company_code")
    if re.search(r"\b(timesheets?|time sheets?|approved payroll|draft payroll|payroll approval)\b", normalized):
        action = infer_timesheet_action(request.raw_text, request=request) or {
            "action_type": "list_timesheets",
            "subject_type": "timesheet",
            "subject_phone": employee.get("phone"),
            "prompt_text": request.raw_text,
            "query": request.raw_text,
        }
        action["action_type"] = "list_timesheets"
        action["subject_phone"] = employee.get("phone")
        result = list_timesheets(action, company_code=company)
        return {"reply": format_list_timesheets_reply(result, employee_view=True), "employee_key": employee.get("employee_key"), "result": result, "intent": "list_timesheets", "turn_focus": "employee_payroll"}
    action = infer_payroll_action(request.raw_text, request=request) or {
        "action_type": "list_payroll_hours",
        "subject_type": "payroll",
        "subject_phone": employee.get("phone"),
        "prompt_text": request.raw_text,
        "query": request.raw_text,
    }
    action["subject_phone"] = employee.get("phone")
    result = list_payroll_hours(action, company_code=company, sync_sheet=False)
    return {"reply": format_payroll_hours_reply(result, employee_view=True), "employee_key": employee.get("employee_key"), "result": result, "intent": "list_payroll_hours", "turn_focus": "employee_payroll"}


def run_shift_reminder_scan(*, account_id: str | None, dry_run: bool = True, limit: int = 50, hours_ahead: int = 2) -> dict[str, Any]:
    now_local = datetime.now(KUWAIT_TZ).replace(tzinfo=None)
    until_local = now_local + timedelta(hours=max(1, min(hours_ahead, 24)))
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT s.*, e.phone, e.name
                FROM shift_assignments s
                LEFT JOIN employees e ON e.employee_key=s.employee_key
                WHERE s.status='scheduled'
                  AND s.reminder_sent_at IS NULL
                  AND (s.shift_date + s.start_time) BETWEEN %s AND %s
                ORDER BY s.shift_date, s.start_time
                LIMIT %s
                """,
                (now_local, until_local, max(1, min(limit, 200))),
            )
            rows = [dict(row) for row in cur.fetchall()]
    results: list[dict[str, Any]] = []
    skipped: list[dict[str, Any]] = []
    for shift in rows:
        if not company_has_module(shift.get("company_code"), "shifts"):
            skipped.append({"shift_id": str(shift.get("shift_id")), "company_code": shift.get("company_code"), "reason": "shifts_module_disabled"})
            continue
        message = f"Reminder: your shift is on {format_shift_date(shift.get('shift_date'))} from {format_shift_time(shift.get('start_time'))} to {format_shift_time(shift.get('end_time'))}."
        entry = {"shift_id": str(shift.get("shift_id")), "employee_key": shift.get("employee_key"), "phone": shift.get("phone") or shift.get("employee_phone"), "message": message, "dry_run": dry_run}
        if not dry_run:
            employee = {"phone": shift.get("phone") or shift.get("employee_phone"), "name": shift.get("name") or shift.get("employee_name"), "employee_key": shift.get("employee_key"), "company_code": shift.get("company_code")}
            if outbound_flow_enabled("shift"):
                send_result = deliver_employee_notification(
                    employee,
                    flow="shift",
                    template_key="shift_reminder",
                    text=message,
                    email_subject="Shift reminder",
                    account_id=account_id,
                    company_code=str(shift.get("company_code") or "WATHEFNI"),
                    variables={
                        "shift_date": format_shift_date(shift.get("shift_date")),
                        "shift_time": format_shift_time(shift.get("start_time")),
                    },
                )
            else:
                send_result = send_custom_employee_message(employee, account_id, message)
            entry["send"] = send_result
            if send_result.get("ok"):
                with db_connect() as conn:
                    with conn.cursor() as cur:
                        cur.execute("UPDATE shift_assignments SET reminder_sent_at=now(), updated_at=now() WHERE shift_id=%s", (shift.get("shift_id"),))
                        record_shift_event(cur, shift=shift, company_code=str(shift.get("company_code") or ""), event_type="reminder_sent", payload=entry, created_by_phone=None)
                    conn.commit()
        results.append(entry)
    return {"ok": True, "dry_run": dry_run, "count": len(results), "skipped_count": len(skipped), "results": results, "skipped": skipped}


def run_attendance_absence_scan(*, account_id: str | None, dry_run: bool = True, limit: int = 50, grace_minutes: int = 30) -> dict[str, Any]:
    now_local = datetime.now(KUWAIT_TZ).replace(tzinfo=None)
    cutoff = now_local - timedelta(minutes=max(1, min(grace_minutes, 240)))
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT s.*, e.phone, e.name, lr.leave_id AS approved_leave_id
                FROM shift_assignments s
                LEFT JOIN employees e ON e.employee_key=s.employee_key
                LEFT JOIN attendance_records ar
                  ON ar.shift_id=s.shift_id
                 AND ar.employee_key=s.employee_key
                 AND ar.company_code=s.company_code
                LEFT JOIN leave_requests lr
                  ON lr.company_code=s.company_code
                 AND lr.employee_key=s.employee_key
                 AND lr.status='approved'
                 AND lr.start_date <= s.shift_date
                 AND lr.end_date >= s.shift_date
                WHERE s.status='scheduled'
                  AND (s.shift_date + s.start_time) < %s
                  AND ar.attendance_id IS NULL
                ORDER BY s.shift_date, s.start_time
                LIMIT %s
                """,
                (cutoff, max(1, min(limit, 200))),
            )
            rows = [dict(row) for row in cur.fetchall()]
    results: list[dict[str, Any]] = []
    skipped: list[dict[str, Any]] = []
    for shift in rows:
        company = str(shift.get("company_code") or "WATHEFNI")
        if not company_has_module(company, "attendance"):
            skipped.append({"shift_id": str(shift.get("shift_id")), "company_code": company, "reason": "attendance_module_disabled"})
            continue
        employee = {"employee_key": shift.get("employee_key"), "phone": shift.get("phone") or shift.get("employee_phone"), "name": shift.get("name") or shift.get("employee_name"), "company_code": company}
        action = {"action_type": "mark_attendance_absent", "subject_phone": employee.get("phone"), "date": shift_sheet_cell(shift.get("shift_date")), "shift_id": str(shift.get("shift_id")), "allow_without_shift": False, "notes": "Auto no-show scan"}
        entry = {"shift_id": str(shift.get("shift_id")), "employee": employee, "dry_run": dry_run}
        if shift.get("approved_leave_id"):
            entry["approved_leave_id"] = str(shift.get("approved_leave_id"))
            if not dry_run:
                with db_connect() as conn:
                    with conn.cursor() as cur:
                        attendance = upsert_attendance_record(
                            cur,
                            company=company,
                            employee=employee,
                            shift=shift,
                            attendance_date=parse_shift_date_value(shift.get("shift_date")) or kuwait_today(),
                            status="approved_leave",
                            notes="Approved leave",
                            source_text="Auto no-show scan",
                            created_by_phone=None,
                            action={"action_type": "attendance_approved_leave_scan", "leave_id": str(shift.get("approved_leave_id"))},
                        )
                        record_attendance_event(cur, attendance=attendance, company_code=company, event_type="approved_leave", payload={"attendance": attendance, "shift": shift, "leave_id": str(shift.get("approved_leave_id"))}, created_by_phone=None)
                    conn.commit()
                sheet_sync = sync_attendance_sheet_rows(company, [attendance])
                record_attendance_sheet_sync(attendance, sheet_sync, created_by_phone=None)
                entry["result"] = {"ok": True, "attendance": json_safe(attendance), "sheet_sync": json_safe(sheet_sync)}
            results.append(entry)
            continue
        if not dry_run:
            result = mark_attendance_absent(action, company_code=company, created_by_phone=None)
            if result.get("ok"):
                result["hr_notification"] = notify_attendance_exception(result, account_id=account_id, event_type="marked_absent")
            entry["result"] = result
        results.append(entry)
    return {"ok": True, "dry_run": dry_run, "count": len(results), "skipped_count": len(skipped), "results": results, "skipped": skipped}




def find_next_required_onboarding_item(employee_key: str) -> dict[str, Any] | None:
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT item_id, label, item_type, document_type, status
                FROM onboarding_items
                WHERE employee_key=%s AND required IS TRUE AND status IN ('pending','missing','requested')
                ORDER BY created_at ASC
                LIMIT 1
                """,
                (employee_key,),
            )
            row = cur.fetchone()
            return dict(row) if row else None


def recompute_employee_onboarding_counts(cur: Any, employee_key: str) -> None:
    cur.execute(
        """
        SELECT
          COUNT(*) FILTER (WHERE required IS TRUE AND status NOT IN ('received','complete','completed','verified')) AS pending,
          COUNT(*) FILTER (WHERE required IS TRUE AND status IN ('received','complete','completed','verified')) AS complete
        FROM onboarding_items
        WHERE employee_key=%s
        """,
        (employee_key,),
    )
    row = cur.fetchone() or {}
    pending = int(row.get("pending") or 0)
    complete = int(row.get("complete") or 0)
    status = "completed" if pending == 0 and complete > 0 else "in_progress"
    cur.execute(
        """
        UPDATE employees
        SET documents_pending=%s, documents_complete=%s, onboarding_status=%s, updated_at=now()
        WHERE employee_key=%s
        """,
        (pending, complete, status, employee_key),
    )


def sync_employee_posthire(phone: str, company_code: str | None) -> dict[str, Any]:
    company = (company_code or "WATHEFNI").upper()
    out: dict[str, Any] = {
        "employee": sync_employee_sheet_from_db(phone, company),
        "compliance": sync_compliance_sheet_from_db(phone, company),
    }
    fallback_helpers = {
        "employee": "sync_employee_sheet.py",
        "compliance": "sync_compliance_sheet.py",
    }
    for key, helper in fallback_helpers.items():
        if not out.get(key, {}).get("ok"):
            out[f"{key}_fallback"] = run_workspace_tool([
                str(WORKSPACE / "tools" / "google" / helper),
                "--company",
                company,
                "--phone",
                digits(phone),
            ], timeout=60)
    return out


def safe_storage_name(value: str | None, default: str = "document") -> str:
    name = re.sub(r"[^A-Za-z0-9._-]+", "-", value or "").strip("-._")
    return name[:120] or default


def sha256_file(path: Path) -> str | None:
    try:
        digest = hashlib.sha256()
        with path.open("rb") as handle:
            for chunk in iter(lambda: handle.read(1024 * 1024), b""):
                digest.update(chunk)
        return digest.hexdigest()
    except Exception:
        return None


def storage_env_value(env_values: dict[str, str], company_code: str, key: str) -> str | None:
    company_key = f"{company_code.upper()}_{key}"
    return env_values.get(company_key) or env_values.get(f"WATHEFNI_{key}") or env_values.get(key)


def document_storage_config(company_code: str | None) -> dict[str, Any]:
    company = (company_code or "WATHEFNI").upper()
    env_values = planner_env()
    config_path = WORKSPACE / "data" / "companies" / company / "document-storage.json"
    file_config = read_json(config_path, {}) if config_path.exists() else {}
    drive_folder_id = (
        storage_env_value(env_values, company, "DOCUMENT_DRIVE_FOLDER_ID")
        or storage_env_value(env_values, company, "DRIVE_FOLDER_ID")
        or file_config.get("drive_folder_id")
        or file_config.get("parent_folder_id")
    )
    configured_provider = (
        storage_env_value(env_values, company, "DOCUMENT_STORAGE_PROVIDER")
        or file_config.get("provider")
        or "local"
    )
    fallback_provider = (
        storage_env_value(env_values, company, "DOCUMENT_STORAGE_FALLBACK_PROVIDER")
        or file_config.get("fallback_provider")
        or "local"
    )
    return {
        "company_code": company,
        "provider": str(configured_provider or "local").strip().lower(),
        "fallback_provider": str(fallback_provider or "local").strip().lower(),
        "drive_folder_id": str(drive_folder_id).strip() if drive_folder_id else None,
        "local_root": str(file_config.get("local_root") or (WORKSPACE / "data" / "companies" / company / "employees")),
    }


def run_gog_wathefni(args: list[str], timeout: int = 90) -> dict[str, Any]:
    env_vars = os.environ.copy()
    env_vars.update(openclaw_env())
    proc = subprocess.run(["gog-wathefni", *args, "--json", "--no-input"], text=True, capture_output=True, timeout=timeout, env=env_vars)
    output = (proc.stdout or "").strip()
    parsed: Any = None
    if output:
        try:
            parsed = json.loads(output)
        except Exception:
            parsed = output
    return {
        "ok": proc.returncode == 0,
        "returncode": proc.returncode,
        "stdout": output[-2000:],
        "stderr": (proc.stderr or "")[-2000:],
        "json": parsed,
    }


def parse_drive_upload_result(result: dict[str, Any]) -> dict[str, Any]:
    payload = result.get("json")
    if not isinstance(payload, dict):
        return {}
    file_obj = payload.get("file") if isinstance(payload.get("file"), dict) else payload
    return {
        "external_file_id": file_obj.get("id") or file_obj.get("fileId"),
        "storage_url": file_obj.get("webViewLink") or file_obj.get("webContentLink") or file_obj.get("url"),
        "raw": payload,
    }


def store_document_local(
    *,
    employee: dict[str, Any],
    item_id: str,
    source_path: Path,
    mime_type: str,
    checksum: str | None,
    config: dict[str, Any],
) -> dict[str, Any]:
    phone = digits(employee.get("phone")) or "unknown-phone"
    company = str(config.get("company_code") or employee.get("company_code") or "WATHEFNI").upper()
    ext = source_path.suffix or mimetypes.guess_extension(mime_type) or ".bin"
    file_name = f"{safe_storage_name(item_id)}-{(checksum or uuid.uuid4().hex)[:12]}{ext}"
    destination_dir = Path(str(config.get("local_root") or "")) / phone / "documents" / safe_storage_name(item_id)
    destination_dir.mkdir(parents=True, exist_ok=True)
    destination_path = destination_dir / file_name
    if source_path.resolve() != destination_path.resolve():
        shutil.copy2(source_path, destination_path)
    try:
        object_key = str(destination_path.relative_to(WORKSPACE))
    except Exception:
        object_key = str(destination_path)
    return {
        "ok": True,
        "provider": "local",
        "storage_status": "stored",
        "storage_object_key": object_key,
        "storage_url": f"local://{object_key}",
        "external_file_id": None,
        "drive_file_id": None,
        "drive_url": None,
        "content_sha256": checksum,
        "mime_type": mime_type,
        "stored_at": now_iso(),
        "metadata": {"company_code": company, "local_path": str(destination_path)},
    }


def store_document_google_drive(
    *,
    employee: dict[str, Any],
    item_id: str,
    source_path: Path,
    mime_type: str,
    checksum: str | None,
    config: dict[str, Any],
) -> dict[str, Any]:
    folder_id = config.get("drive_folder_id")
    if not folder_id:
        return {"ok": False, "provider": "google_drive", "storage_status": "failed", "storage_error": "missing_drive_folder_id"}
    phone = digits(employee.get("phone")) or "unknown-phone"
    company = str(config.get("company_code") or employee.get("company_code") or "WATHEFNI").upper()
    ext = source_path.suffix or mimetypes.guess_extension(mime_type) or ".bin"
    upload_name = f"{company}-{phone}-{safe_storage_name(item_id)}-{(checksum or uuid.uuid4().hex)[:12]}{ext}"
    result = run_gog_wathefni(
        [
            "drive",
            "upload",
            str(source_path),
            "--name",
            upload_name,
            "--parent",
            str(folder_id),
            "--mime-type",
            mime_type,
        ],
        timeout=120,
    )
    if not result.get("ok"):
        return {
            "ok": False,
            "provider": "google_drive",
            "storage_status": "failed",
            "storage_error": result.get("stderr") or result.get("stdout") or "drive_upload_failed",
            "raw": result,
        }
    parsed = parse_drive_upload_result(result)
    external_file_id = parsed.get("external_file_id")
    storage_url = parsed.get("storage_url")
    return {
        "ok": bool(external_file_id or storage_url),
        "provider": "google_drive",
        "storage_status": "stored",
        "storage_object_key": external_file_id,
        "storage_url": storage_url,
        "external_file_id": external_file_id,
        "drive_file_id": external_file_id,
        "drive_url": storage_url,
        "content_sha256": checksum,
        "mime_type": mime_type,
        "stored_at": now_iso(),
        "metadata": {"drive": parsed.get("raw"), "upload_name": upload_name},
    }


def store_onboarding_document(
    *,
    employee: dict[str, Any],
    item_id: str,
    media: dict[str, Any] | None,
) -> dict[str, Any]:
    if not has_current_media_upload(media):
        return {"ok": True, "provider": "metadata_only", "storage_status": "not_required", "metadata": {}}
    source = Path(str((media or {}).get("path") or ""))
    if not source.exists() or not source.is_file():
        return {"ok": False, "provider": "local", "storage_status": "failed", "storage_error": "missing_local_media_file"}
    mime_type = str((media or {}).get("type") or (media or {}).get("mime_type") or "").strip()
    if "/" not in mime_type:
        mime_type = mimetypes.guess_type(source.name)[0] or "application/octet-stream"
    checksum = sha256_file(source)
    config = document_storage_config(employee.get("company_code"))
    provider = str(config.get("provider") or "local")
    if provider == "google_drive":
        primary = store_document_google_drive(employee=employee, item_id=item_id, source_path=source, mime_type=mime_type, checksum=checksum, config=config)
        if primary.get("ok"):
            return primary
        if config.get("fallback_provider") == "local":
            fallback = store_document_local(employee=employee, item_id=item_id, source_path=source, mime_type=mime_type, checksum=checksum, config=config)
            fallback["storage_status"] = "stored_with_fallback"
            fallback["primary_provider"] = "google_drive"
            fallback["storage_error"] = primary.get("storage_error")
            return fallback
        return primary
    return store_document_local(employee=employee, item_id=item_id, source_path=source, mime_type=mime_type, checksum=checksum, config=config)


def source_file_details(path_value: str | None, mime_value: str | None = None) -> tuple[Path | None, str | None, str | None, int | None]:
    if not path_value:
        return None, None, None, None
    source = Path(str(path_value))
    if not source.exists() or not source.is_file():
        return source, None, None, None
    mime_type = str(mime_value or "").strip()
    if "/" not in mime_type:
        mime_type = mimetypes.guess_type(source.name)[0] or "application/octet-stream"
    checksum = sha256_file(source)
    try:
        size_bytes = source.stat().st_size
    except Exception:
        size_bytes = None
    return source, mime_type, checksum, size_bytes


def storage_object_key_for_path(path: Path) -> str:
    try:
        return str(path.relative_to(WORKSPACE))
    except Exception:
        return str(path)


