def upsert_file_registry(
    cur: Any,
    *,
    company_code: str,
    owner_phone: str | None,
    subject_type: str,
    subject_key: str,
    file_kind: str,
    document_type: str | None,
    original_filename: str | None,
    source_path: str | None,
    local_path: str | None,
    storage_result: dict[str, Any],
    metadata: dict[str, Any] | None = None,
) -> None:
    checksum = storage_result.get("content_sha256")
    cur.execute(
        """
        SELECT file_id
        FROM file_registry
        WHERE subject_type=%s
          AND subject_key=%s
          AND file_kind=%s
          AND COALESCE(document_type,'')=COALESCE(%s,'')
          AND COALESCE(content_sha256,'')=COALESCE(%s,'')
        ORDER BY updated_at DESC
        LIMIT 1
        """,
        (subject_type, subject_key, file_kind, document_type, checksum),
    )
    existing = cur.fetchone()
    row_metadata = metadata or {}
    provider = storage_result.get("provider") or "local"
    status = storage_result.get("storage_status") or ("stored" if storage_result.get("ok") else "failed")
    if existing:
        cur.execute(
            """
            UPDATE file_registry
            SET company_code=%s, owner_phone=%s, original_filename=%s, source_path=%s,
                local_path=%s, storage_provider=%s, storage_object_key=%s,
                external_file_id=%s, storage_url=%s, content_sha256=%s, mime_type=%s,
                size_bytes=%s, storage_status=%s, storage_error=%s, metadata=%s,
                raw_json=%s, stored_at=CASE WHEN %s IS NOT NULL THEN now() ELSE stored_at END,
                updated_at=now()
            WHERE file_id=%s
            """,
            (
                company_code,
                owner_phone,
                original_filename,
                source_path,
                local_path,
                provider,
                storage_result.get("storage_object_key"),
                storage_result.get("external_file_id"),
                storage_result.get("storage_url"),
                checksum,
                storage_result.get("mime_type"),
                storage_result.get("size_bytes"),
                status,
                storage_result.get("storage_error"),
                Json(row_metadata),
                Json({"storage": storage_result, "metadata": row_metadata}),
                provider,
                existing["file_id"],
            ),
        )
    else:
        cur.execute(
            """
            INSERT INTO file_registry (
                company_code, owner_phone, subject_type, subject_key, file_kind,
                document_type, original_filename, source_path, local_path,
                storage_provider, storage_object_key, external_file_id, storage_url,
                content_sha256, mime_type, size_bytes, storage_status, storage_error,
                metadata, raw_json, stored_at
            )
            VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,CASE WHEN %s IS NOT NULL THEN now() ELSE NULL END)
            """,
            (
                company_code,
                owner_phone,
                subject_type,
                subject_key,
                file_kind,
                document_type,
                original_filename,
                source_path,
                local_path,
                provider,
                storage_result.get("storage_object_key"),
                storage_result.get("external_file_id"),
                storage_result.get("storage_url"),
                checksum,
                storage_result.get("mime_type"),
                storage_result.get("size_bytes"),
                status,
                storage_result.get("storage_error"),
                Json(row_metadata),
                Json({"storage": storage_result, "metadata": row_metadata}),
                provider,
            ),
        )


def onboarding_item_row(cur: Any, employee_key: str, item_id: str) -> dict[str, Any]:
    cur.execute(
        """
        SELECT item_id, label, item_type, document_type
        FROM onboarding_items
        WHERE employee_key=%s AND item_id=%s
        LIMIT 1
        """,
        (employee_key, item_id),
    )
    row = cur.fetchone()
    return dict(row) if row else {"item_id": item_id, "document_type": item_id, "label": item_id}


def record_employee_document_receipt(
    cur: Any,
    *,
    employee: dict[str, Any],
    item_id: str,
    value: str,
    media: dict[str, Any] | None,
    storage_result: dict[str, Any],
    extraction: dict[str, Any] | None = None,
) -> None:
    employee_key = employee["employee_key"]
    item = onboarding_item_row(cur, employee_key, item_id)
    document_type = str(item.get("document_type") or item.get("item_id") or item_id)
    filename = Path(str((media or {}).get("path") or "")).name if has_current_media_upload(media) else None
    metadata = {
        "item_id": item_id,
        "label": item.get("label"),
        "value": value,
        "storage": storage_result,
        "received_at": now_iso(),
    }
    extraction = extraction if isinstance(extraction, dict) else extract_compliance_document_metadata(document_type=document_type, text=value, media=media)
    if extraction:
        metadata["extraction"] = json_safe(extraction)
    expiry_date = extraction.get("expiry_date_parsed") if isinstance(extraction, dict) else None
    issued_date = extraction.get("issued_date_parsed") if isinstance(extraction, dict) else None
    document_number = str(extraction.get("document_number") or "").strip() if isinstance(extraction, dict) else ""
    extraction_status = str(extraction.get("extraction_status") or "").strip() if isinstance(extraction, dict) else None
    extraction_error = str(extraction.get("extraction_error") or "").strip() if isinstance(extraction, dict) and extraction.get("extraction_error") else None
    extraction_confidence = extraction.get("confidence") if isinstance(extraction, dict) else None
    drive_file_id = storage_result.get("drive_file_id") or (storage_result.get("external_file_id") if storage_result.get("provider") == "google_drive" else None)
    drive_url = storage_result.get("drive_url") or (storage_result.get("storage_url") if storage_result.get("provider") == "google_drive" else None)
    fields = (
        employee_key,
        digits(employee.get("phone")),
        (employee.get("company_code") or "WATHEFNI"),
        item_id,
        document_type,
        filename,
        (media or {}).get("path"),
        drive_file_id,
        drive_url,
        "received",
        Json(metadata),
        Json(metadata),
        now_utc().date(),
        storage_result.get("provider"),
        storage_result.get("storage_object_key"),
        storage_result.get("external_file_id"),
        storage_result.get("storage_url"),
        storage_result.get("content_sha256"),
        storage_result.get("mime_type"),
        storage_result.get("storage_status"),
        storage_result.get("storage_error"),
        document_number or None,
        issued_date,
        expiry_date,
        extraction_status,
        extraction_error,
        extraction_confidence,
    )
    cur.execute(
        """
        SELECT document_id
        FROM employee_documents
        WHERE employee_key=%s AND document_type=%s
        ORDER BY updated_at DESC
        LIMIT 1
        """,
        (employee_key, document_type),
    )
    existing = cur.fetchone()
    if existing:
        cur.execute(
            """
            UPDATE employee_documents
            SET phone=%s, company_code=%s, item_id=%s, filename=%s, local_path=%s,
                drive_file_id=%s, drive_url=%s, status=%s, metadata=%s, raw_json=%s,
                received_at=%s, storage_provider=%s, storage_object_key=%s,
                external_file_id=%s, storage_url=%s, content_sha256=%s, mime_type=%s,
                storage_status=%s, storage_error=%s, document_number=%s,
                issued_at=COALESCE(%s, issued_at), expiry_date=COALESCE(%s, expiry_date),
                extraction_status=%s, extraction_error=%s, extraction_confidence=%s,
                extracted_at=CASE WHEN %s IS NOT NULL THEN now() ELSE extracted_at END,
                stored_at=CASE WHEN %s IS NOT NULL THEN now() ELSE stored_at END,
                updated_at=now()
            WHERE document_id=%s
            """,
            (
                fields[1], fields[2], fields[3], fields[5], fields[6],
                fields[7], fields[8], fields[9], fields[10], fields[11],
                fields[12], fields[13], fields[14], fields[15], fields[16],
                fields[17], fields[18], fields[19], fields[20], fields[21],
                fields[22], fields[23], fields[24], fields[25], fields[26],
                fields[24], fields[13],
                existing["document_id"],
            ),
        )
    else:
        cur.execute(
            """
            INSERT INTO employee_documents (
                employee_key, phone, company_code, item_id, document_type, filename,
                local_path, drive_file_id, drive_url, status, metadata, raw_json, received_at,
                storage_provider, storage_object_key, external_file_id, storage_url,
                content_sha256, mime_type, storage_status, storage_error, document_number,
                issued_at, expiry_date, extraction_status, extraction_error, extraction_confidence,
                extracted_at, stored_at
            )
            VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,CASE WHEN %s IS NOT NULL THEN now() ELSE NULL END,CASE WHEN %s IS NOT NULL THEN now() ELSE NULL END)
            """,
            (*fields, fields[24], fields[13]),
        )
    if document_type in {"civil_id", "passport", "medical", "education_cert"}:
        cur.execute(
            """
            SELECT employee_key, document_type
            FROM compliance_documents
            WHERE employee_key=%s AND document_type=%s
            ORDER BY updated_at DESC
            LIMIT 1
            """,
            (employee_key, document_type),
        )
        compliance = cur.fetchone()
        compliance_metadata = {**metadata, "employee_document_type": document_type}
        if compliance:
            cur.execute(
                """
                UPDATE compliance_documents
                SET status='received',
                    notes=%s,
                    raw_json=%s,
                    document_number=COALESCE(%s, document_number),
                    issued_date=COALESCE(%s, issued_date),
                    expiry_date=COALESCE(%s, expiry_date),
                    days_until_expiry=CASE WHEN %s::date IS NULL THEN days_until_expiry ELSE (%s::date - CURRENT_DATE) END,
                    extraction_status=%s,
                    extraction_error=%s,
                    extraction_confidence=%s,
                    extracted_at=CASE WHEN %s IS NOT NULL THEN now() ELSE extracted_at END,
                    updated_at=now()
                WHERE employee_key=%s AND document_type=%s
                """,
                (
                    value,
                    Json(compliance_metadata),
                    document_number or None,
                    issued_date,
                    expiry_date,
                    expiry_date,
                    expiry_date,
                    extraction_status,
                    extraction_error,
                    extraction_confidence,
                    extraction_status,
                    employee_key,
                    document_type,
                ),
            )
        else:
            cur.execute(
                """
                INSERT INTO compliance_documents (
                    employee_key, document_type, label, status, notes, raw_json,
                    document_number, issued_date, expiry_date, days_until_expiry,
                    extraction_status, extraction_error, extraction_confidence, extracted_at,
                    company_code
                )
                VALUES (%s,%s,%s,'received',%s,%s,%s,%s,%s,CASE WHEN %s::date IS NULL THEN NULL ELSE (%s::date - CURRENT_DATE) END,%s,%s,%s,CASE WHEN %s IS NOT NULL THEN now() ELSE NULL END,%s)
                """,
                (
                    employee_key,
                    document_type,
                    item.get("label"),
                    value,
                    Json(compliance_metadata),
                    document_number or None,
                    issued_date,
                    expiry_date,
                    expiry_date,
                    expiry_date,
                    extraction_status,
                    extraction_error,
                    extraction_confidence,
                    extraction_status,
                    employee.get("company_code") or "WATHEFNI",
                ),
            )
    storage_metadata = storage_result.get("metadata") if isinstance(storage_result.get("metadata"), dict) else {}
    upsert_file_registry(
        cur,
        company_code=employee.get("company_code") or "WATHEFNI",
        owner_phone=digits(employee.get("phone")),
        subject_type="employee",
        subject_key=employee_key,
        file_kind="onboarding_document",
        document_type=document_type,
        original_filename=filename,
        source_path=(media or {}).get("path"),
        local_path=storage_metadata.get("local_path") or (media or {}).get("path"),
        storage_result=storage_result,
        metadata={
            "item_id": item_id,
            "label": item.get("label"),
            "employee_key": employee_key,
            "value": value,
        },
    )

def find_candidate_application_for_file(phone: str | None) -> dict[str, Any] | None:
    target = digits(phone)
    if not target:
        return None
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT *
                FROM applications
                WHERE phone=%s
                ORDER BY
                  CASE
                    WHEN status IN ('awaiting_cv','cv_received','screening','screening_complete') OR current_step IN ('cv_request','cv_upload','screening','screening_complete') THEN 0
                    WHEN status IN ('review_pending','shortlisted') THEN 1
                    ELSE 2
                  END,
                  updated_at DESC NULLS LAST,
                  ingested_at DESC NULLS LAST
                LIMIT 1
                """,
                (target,),
            )
            row = cur.fetchone()
            return dict(row) if row else None


def register_candidate_cv_file(
    cur: Any,
    *,
    application: dict[str, Any],
    media: dict[str, Any],
    file_kind: str = "candidate_cv",
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    source, mime_type, checksum, size_bytes = source_file_details(media.get("path"), media.get("type") or media.get("mime_type"))
    if not source or not source.exists() or not mime_type:
        return {"ok": False, "storage_status": "failed", "storage_error": "missing_candidate_cv_media_file"}
    company_code = str(application.get("company_code") or "WATHEFNI").upper()
    phone = digits(application.get("phone"))
    app_key = str(application.get("app_key") or f"{phone}-{company_code}-{application.get('position_code') or 'APPLICATION'}")
    storage_result = store_subject_file(
        company_code=company_code,
        owner_phone=phone,
        subject_type="application",
        subject_key=app_key,
        file_kind=file_kind,
        source_path=source,
        mime_type=mime_type,
        checksum=checksum,
    )
    storage_result["size_bytes"] = storage_result.get("size_bytes") or size_bytes
    original_filename = Path(str(media.get("path") or "")).name
    storage_metadata = storage_result.get("metadata") if isinstance(storage_result.get("metadata"), dict) else {}
    registry_metadata = {
        "phone": phone,
        "app_key": app_key,
        "company_code": company_code,
        "position_code": application.get("position_code"),
        "source": "candidate_whatsapp_media",
        "latest": True,
        "versioned_at": now_iso(),
        **(metadata or {}),
    }
    try:
        cur.execute(
            """
            UPDATE candidate_documents
            SET metadata=COALESCE(metadata,'{}'::jsonb) || %s::jsonb,
                updated_at=now()
            WHERE app_key=%s AND document_type='cv'
            """,
            (
                Json({"latest": False, "superseded_at": now_iso(), "superseded_by_filename": original_filename}),
                app_key,
            ),
        )
    except Exception:
        pass
    upsert_file_registry(
        cur,
        company_code=company_code,
        owner_phone=phone,
        subject_type="application",
        subject_key=app_key,
        file_kind=file_kind,
        document_type="cv",
        original_filename=original_filename,
        source_path=str(source),
        local_path=storage_metadata.get("local_path") or str(source),
        storage_result=storage_result,
        metadata=registry_metadata,
    )
    raw_json = dict(application.get("raw_json") or {})
    cv_json = dict(raw_json.get("cv") or {})
    cv_storage = {
        "provider": storage_result.get("provider"),
        "object_key": storage_result.get("storage_object_key"),
        "external_file_id": storage_result.get("external_file_id"),
        "url": storage_result.get("storage_url"),
        "sha256": storage_result.get("content_sha256"),
        "mime_type": storage_result.get("mime_type"),
        "size_bytes": storage_result.get("size_bytes"),
        "status": storage_result.get("storage_status"),
        "stored_at": storage_result.get("stored_at") or now_iso(),
    }
    previous_versions = cv_json.get("previous_versions") if isinstance(cv_json.get("previous_versions"), list) else []
    if cv_json.get("filename") or cv_json.get("storage"):
        previous_versions = [
            *previous_versions,
            {
                "filename": cv_json.get("filename"),
                "storage": cv_json.get("storage"),
                "received_at": cv_json.get("received_at") or cv_json.get("storage", {}).get("stored_at") if isinstance(cv_json.get("storage"), dict) else None,
                "superseded_at": now_iso(),
            },
        ][-10:]
    cv_json["storage"] = cv_storage
    cv_json["previous_versions"] = previous_versions
    cv_json["latest"] = True
    cv_json["versioned_at"] = registry_metadata["versioned_at"]
    cv_json.setdefault("path", str(source))
    cv_json.setdefault("filename", original_filename)
    cv_json.setdefault("source", "whatsapp_document")
    raw_json["cv"] = cv_json
    sync_json = dict(raw_json.get("sync") or {})
    sync_json["file_registry"] = {"status": "ok" if storage_result.get("ok") else "failed", "updated_at": now_iso()}
    raw_json["sync"] = sync_json
    received_ok = bool(storage_result.get("ok"))
    if received_ok:
        raw_json["cv_received"] = True
        raw_json["status"] = "screening"
        raw_json["current_step"] = "screening"
        cv_json["processing"] = {
            "file_received": True,
            "file_stored": bool(storage_result.get("ok")),
            "text_extracted": False,
            "profile_parsed": False,
            "semantic_indexed": False,
            "screening_prefill_ready": False,
            "screening_questions_sent": False,
            "status": "pending_async_processing",
            "updated_at": now_iso(),
        }
        raw_json["cv"] = cv_json
    cur.execute(
        """
        UPDATE applications
        SET raw_json=%s,
            cv_received=CASE WHEN %s THEN true ELSE cv_received END,
            cv_received_at=CASE WHEN %s THEN COALESCE(cv_received_at, CURRENT_DATE) ELSE cv_received_at END,
            status=CASE WHEN %s AND status IN ('awaiting_cv','cv_received') THEN 'screening' ELSE status END,
            current_step=CASE WHEN %s AND current_step IN ('cv_request','cv_upload') THEN 'screening' ELSE current_step END,
            screening_status=CASE WHEN %s AND (screening_status IS NULL OR screening_status IN ('not_started','awaiting_cv')) THEN 'pending' ELSE screening_status END,
            drive_sync_status=CASE WHEN %s='google_drive' AND %s THEN 'ok' ELSE drive_sync_status END,
            updated_at=COALESCE(updated_at, CURRENT_DATE)
        WHERE app_key=%s
        """,
        (
            Json(raw_json),
            received_ok,
            received_ok,
            received_ok,
            received_ok,
            received_ok,
            storage_result.get("provider"),
            received_ok,
            app_key,
        ),
    )
    try:
        cur.execute(
            """
            SELECT document_id
            FROM candidate_documents
            WHERE app_key=%s AND document_type='cv' AND filename=%s
            ORDER BY created_at DESC
            LIMIT 1
            """,
            (app_key, original_filename),
        )
        existing_doc = cur.fetchone()
        doc_payload = {
            **cv_json,
            "received_at": now_iso(),
            "storage": cv_storage,
        }
        if existing_doc:
            cur.execute(
                """
                UPDATE candidate_documents
                SET local_path=%s,
                    source=%s,
                    extraction_status=COALESCE(extraction_status, %s),
                    drive_file_id=%s,
                    drive_url=%s,
                    metadata=%s,
                    raw_json=%s,
                    updated_at=now()
                WHERE document_id=%s
                """,
                (
                    storage_metadata.get("local_path") or str(source),
                    cv_json.get("source") or "whatsapp_document",
                    "pending_extraction",
                    storage_result.get("external_file_id"),
                    storage_result.get("storage_url"),
                    Json(registry_metadata),
                    Json(doc_payload),
                    existing_doc.get("document_id"),
                ),
            )
        else:
            cur.execute(
                """
                INSERT INTO candidate_documents
                (app_key, phone, document_type, filename, local_path, source, extraction_status,
                 extraction_method, extraction_chars, drive_file_id, drive_url, metadata, raw_json, received_at)
                VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,CURRENT_DATE)
                """,
                (
                    app_key,
                    phone,
                    "cv",
                    original_filename,
                    storage_metadata.get("local_path") or str(source),
                    cv_json.get("source") or "whatsapp_document",
                    "pending_extraction" if received_ok else "failed",
                    None,
                    None,
                    storage_result.get("external_file_id"),
                    storage_result.get("storage_url"),
                    Json(registry_metadata),
                    Json(doc_payload),
                ),
            )
    except Exception:
        # Older deployments may not have candidate_documents; canonical application
        # truth above is still the authority used by HR chat.
        pass
    return {"ok": bool(storage_result.get("ok")), "app_key": app_key, "storage": storage_result}


# --- Bulk CV import: shared import core -------------------------------------
# Imported candidates use a company-scoped surrogate identity so that imports are
# never deduplicated across companies and never reuse a real candidate row from a
# different tenant. The real phone/email/name are preserved inside raw_json/profile.
def import_surrogate_phone(company_code: str, *, email: str | None = None, checksum: str | None = None) -> str:
    company = str(company_code or "").strip().upper()
    seed = (str(email or "").strip().lower()) or (str(checksum or "").strip().lower()) or uuid.uuid4().hex
    token = hashlib.sha1(f"{company}:{seed}".encode("utf-8")).hexdigest()[:16]
    return f"imp-{company.lower()}-{token}"


def import_app_key(surrogate_phone: str, company_code: str, position_code: str | None) -> str:
    company = str(company_code or "").strip().upper()
    pos = str(position_code or "").strip().upper() or "IMPORT"
    return f"{surrogate_phone}-{company}-{pos}"


def register_imported_cv(
    cur: Any,
    *,
    company_code: str,
    batch_id: str,
    source_path: Path,
    original_filename: str,
    mime_type: str | None = None,
    checksum: str | None = None,
    size_bytes: int | None = None,
    candidate_name: str | None = None,
    candidate_email: str | None = None,
    candidate_phone: str | None = None,
    position_code: str | None = None,
    position_title: str | None = None,
    source: str = "bulk_upload",
    role_suggestion: dict[str, Any] | None = None,
    source_ref: str | None = None,
    auto_admit: bool = False,
    admit_reason: str | None = None,
) -> dict[str, Any]:
    company = str(company_code or "").strip().upper()
    resolved_source, resolved_mime, resolved_checksum, resolved_size = source_file_details(str(source_path), mime_type)
    if not resolved_source or not resolved_source.exists() or not resolved_mime:
        return {"ok": False, "status": "failed", "error": "unreadable_or_unsupported_file"}
    checksum = checksum or resolved_checksum
    size_bytes = size_bytes or resolved_size
    email = (str(candidate_email).strip().lower() if candidate_email else None) or None
    surrogate_phone = import_surrogate_phone(company, email=email, checksum=checksum)
    position_code = (str(position_code).strip() if position_code else "") or ""
    app_key = import_app_key(surrogate_phone, company, position_code)
    # Tiered intake: an explicit role signal (position_code) + company auto-admit
    # setting places the candidate directly into Candidates (review_pending). Anything
    # else is held in the Intake queue (import_review with a role guess, else needs_role).
    auto_admitted = bool(auto_admit and position_code)
    if auto_admitted:
        held_status = "review_pending"
        current_step = "review"
    else:
        held_status = "import_review" if position_code else "needs_role"
        current_step = "import_review"

    cur.execute(
        """
        INSERT INTO candidates (phone, name, email, current_status, active_company_code, active_position_code, profile, raw_json, data_source)
        VALUES (%s,%s,%s,%s,%s,%s,%s,%s,'production')
        ON CONFLICT (phone) DO UPDATE
          SET name=COALESCE(NULLIF(candidates.name,''), EXCLUDED.name),
              email=COALESCE(NULLIF(candidates.email,''), EXCLUDED.email),
              active_company_code=COALESCE(candidates.active_company_code, EXCLUDED.active_company_code),
              updated_at=now()
        """,
        (
            surrogate_phone,
            candidate_name or None,
            email,
            held_status,
            company,
            position_code or None,
            Json(json_safe({
                "identity_source": "bulk_import",
                "import_batch_id": batch_id,
                "contact": {"phone": candidate_phone or None, "email": email, "name": candidate_name or None},
            })),
            Json(json_safe({"identity_source": "bulk_import", "import_batch_id": batch_id})),
        ),
    )

    storage_result = store_subject_file(
        company_code=company,
        owner_phone=surrogate_phone,
        subject_type="application",
        subject_key=app_key,
        file_kind="candidate_cv",
        source_path=resolved_source,
        mime_type=resolved_mime,
        checksum=checksum,
    )
    storage_result["size_bytes"] = storage_result.get("size_bytes") or size_bytes
    if not storage_result.get("ok"):
        return {"ok": False, "status": "failed", "error": storage_result.get("storage_error") or "storage_failed", "app_key": app_key}
    storage_metadata = storage_result.get("metadata") if isinstance(storage_result.get("metadata"), dict) else {}

    registry_metadata = {
        "company_code": company,
        "app_key": app_key,
        "source": "bulk_import",
        "import_batch_id": batch_id,
        "original_filename": original_filename,
        "candidate_email": email,
        "candidate_name": candidate_name or None,
        "latest": True,
        "versioned_at": now_iso(),
    }
    upsert_file_registry(
        cur,
        company_code=company,
        owner_phone=surrogate_phone,
        subject_type="application",
        subject_key=app_key,
        file_kind="candidate_cv",
        document_type="cv",
        original_filename=original_filename,
        source_path=str(resolved_source),
        local_path=storage_metadata.get("local_path") or str(resolved_source),
        storage_result=storage_result,
        metadata=registry_metadata,
    )
    cur.execute(
        """
        SELECT file_id::text AS file_id
        FROM file_registry
        WHERE subject_type='application' AND subject_key=%s AND file_kind='candidate_cv'
        ORDER BY updated_at DESC LIMIT 1
        """,
        (app_key,),
    )
    file_row = cur.fetchone()
    file_id = (file_row or {}).get("file_id")

    cv_storage = {
        "provider": storage_result.get("provider"),
        "object_key": storage_result.get("storage_object_key"),
        "external_file_id": storage_result.get("external_file_id"),
        "url": storage_result.get("storage_url"),
        "sha256": storage_result.get("content_sha256"),
        "mime_type": storage_result.get("mime_type"),
        "size_bytes": storage_result.get("size_bytes"),
        "status": storage_result.get("storage_status"),
        "stored_at": storage_result.get("stored_at") or now_iso(),
    }
    cv_json = {
        "filename": original_filename,
        "path": storage_metadata.get("local_path") or str(resolved_source),
        "source": "bulk_import",
        "latest": True,
        "versioned_at": registry_metadata["versioned_at"],
        "storage": cv_storage,
        "processing": {
            "file_received": True,
            "file_stored": True,
            "text_extracted": False,
            "profile_parsed": False,
            "semantic_indexed": False,
            "status": "pending_async_processing",
            "updated_at": now_iso(),
        },
    }
    app_raw = {
        "cv": cv_json,
        "cv_received": True,
        "data_source": "production",
        "candidate_name": candidate_name or None,
        "import": {
            "held": not auto_admitted,
            "auto_admitted": auto_admitted,
            "admit_reason": admit_reason if auto_admitted else None,
            "batch_id": batch_id,
            "source": source or "bulk_upload",
            "source_ref": source_ref or original_filename,
            "original_filename": original_filename,
            "needs_role": held_status == "needs_role",
            "role_suggestion": role_suggestion or None,
            "imported_at": now_iso(),
        },
    }
    cur.execute(
        """
        INSERT INTO applications
            (app_key, phone, company_code, position_code, position_title, status, current_step,
             cv_received, cv_received_at, screening_status, raw_json, data_source, data_source_detail,
             import_batch_id, source_ref, ingested_at, created_at, updated_at)
        VALUES (%s,%s,%s,%s,%s,%s,%s,true,CURRENT_DATE,'not_started',%s,'production',%s,%s,%s,now(),CURRENT_DATE,CURRENT_DATE)
        ON CONFLICT (app_key) DO UPDATE
          SET raw_json=COALESCE(applications.raw_json,'{}'::jsonb) || EXCLUDED.raw_json,
              position_title=COALESCE(applications.position_title, EXCLUDED.position_title),
              cv_received=true,
              cv_received_at=COALESCE(applications.cv_received_at, CURRENT_DATE),
              import_batch_id=COALESCE(applications.import_batch_id, EXCLUDED.import_batch_id),
              source_ref=COALESCE(applications.source_ref, EXCLUDED.source_ref),
              updated_at=CURRENT_DATE
        """,
        (
            app_key,
            surrogate_phone,
            company,
            position_code,
            position_title or None,
            held_status,
            current_step,
            Json(json_safe(app_raw)),
            f"bulk_import:{batch_id}",
            batch_id,
            source_ref or original_filename,
        ),
    )

    document_id = None
    try:
        doc_payload = {**cv_json, "received_at": now_iso(), "storage": cv_storage}
        cur.execute(
            """
            INSERT INTO candidate_documents
                (app_key, phone, document_type, filename, local_path, source, extraction_status,
                 drive_file_id, drive_url, metadata, raw_json, received_at)
            VALUES (%s,%s,'cv',%s,%s,'bulk_import','pending_extraction',%s,%s,%s,%s,CURRENT_DATE)
            RETURNING document_id::text
            """,
            (
                app_key,
                surrogate_phone,
                original_filename,
                storage_metadata.get("local_path") or str(resolved_source),
                storage_result.get("external_file_id"),
                storage_result.get("storage_url"),
                Json(registry_metadata),
                Json(doc_payload),
            ),
        )
        doc_row = cur.fetchone()
        document_id = (doc_row or {}).get("document_id")
    except Exception:
        pass

    return {
        "ok": True,
        "status": held_status,
        "auto_admitted": auto_admitted,
        "admit_reason": admit_reason if auto_admitted else None,
        "app_key": app_key,
        "surrogate_phone": surrogate_phone,
        "file_id": file_id,
        "document_id": document_id,
        "checksum": checksum,
        "size_bytes": size_bytes,
        "mime_type": resolved_mime,
        "position_code": position_code or None,
    }


def handle_candidate_file_turn(request: WhatsAppTurnRequest) -> dict[str, Any] | None:
    media = request.media or {}
    if not has_current_media_upload(media):
        return None
    media_type = str(media.get("type") or media.get("mime_type") or "").lower()
    allowed_media = {
        "application/pdf",
        "application/msword",
        "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
        "text/plain",
    }
    if not (media_type.startswith("image/") or media_type in allowed_media):
        return None
    application = find_candidate_application_for_file(request.sender_phone)
    if not application:
        return None
    if not company_has_module(application.get("company_code"), "pre_hiring"):
        return {
            "ok": False,
            "error": "module_disabled",
            "company_code": application.get("company_code"),
            "required_module": "pre_hiring",
        }
    with db_connect() as conn:
        with conn.cursor() as cur:
            result = register_candidate_cv_file(
                cur,
                application=application,
                media=media,
                metadata={"conversation_id": request.conversation_id, "raw_text": request.raw_text},
            )
        conn.commit()
    if result.get("ok"):
        result["reply"] = "Got it — I received your CV and I’m processing it now. I’ll continue with the next step once it’s ready."
    else:
        result["reply"] = "I received your file, but I could not save it safely. Please resend your CV as a clear PDF, Word document, or image."
    return result


def extract_pdf_text_best_effort(path: Path) -> tuple[str, str, str | None]:
    """Best-effort PDF text extraction without making receipt depend on parsing.

    Prefer `pdftotext` when installed. If unavailable, use a lightweight literal
    string fallback so text-based simple PDFs can still progress. Scanned PDFs
    will correctly fail and the worker can send fallback screening questions.
    """

    pdftotext = shutil.which("pdftotext")
    if pdftotext:
        try:
            proc = subprocess.run(
                [pdftotext, "-layout", str(path), "-"],
                capture_output=True,
                text=True,
                timeout=30,
            )
            if proc.returncode == 0 and cv_text_quality_ok(proc.stdout):
                return proc.stdout.strip(), "pdftotext", None
        except Exception as exc:
            return "", "pdftotext", str(exc)
    try:
        raw = path.read_bytes()
        strings = []
        for match in re.finditer(rb"\(([^()]{3,500})\)", raw):
            text = match.group(1).decode("latin-1", errors="ignore")
            text = text.replace("\\n", "\n").replace("\\r", "\n").replace("\\t", " ")
            if re.search(r"[A-Za-z\u0600-\u06FF]", text):
                strings.append(text)
        extracted = "\n".join(strings).strip()
        if extracted and cv_text_quality_ok(extracted):
            return extracted, "pdf-literal-fallback", None
        return "", "pdf-literal-fallback", "no_text_extracted"
    except Exception as exc:
        return "", "pdf-literal-fallback", str(exc)


def extract_candidate_cv_text_from_path(path_value: str | None, mime_type: str | None = None) -> tuple[str, str, str | None]:
    path = Path(str(path_value or ""))
    if not path.exists() or not path.is_file():
        return "", "missing-file", "file_not_found"
    guessed = str(mime_type or mimetypes.guess_type(path.name)[0] or "").lower()
    suffix = path.suffix.lower()
    if guessed.startswith("text/") or suffix in {".txt", ".md", ".csv"}:
        try:
            return path.read_text(errors="ignore").strip(), "text", None
        except Exception as exc:
            return "", "text", str(exc)
    if guessed in {"application/vnd.openxmlformats-officedocument.wordprocessingml.document"} or suffix == ".docx":
        text = docx_text_preview(path)
        return text, "docx-stdlib", None if text else "no_text_extracted"
    if guessed == "application/pdf" or suffix == ".pdf":
        return extract_pdf_text_best_effort(path)
    if guessed.startswith("image/") or suffix in {".jpg", ".jpeg", ".png", ".webp"}:
        return extract_image_cv_text_with_vision(path, guessed or mimetypes.guess_type(path.name)[0] or "image/jpeg")
    return "", "unsupported", f"unsupported_mime:{guessed or suffix}"


def extract_image_cv_text_with_vision(path: Path, mime_type: str) -> tuple[str, str, str | None]:
    provider = planner_provider_config()
    if not provider:
        return "", "gpt-vision", "missing_model_provider"
    try:
        if not path.exists() or not path.is_file() or path.stat().st_size > 8 * 1024 * 1024:
            return "", "gpt-vision", "image_file_unavailable_or_too_large"
        encoded = base64.b64encode(path.read_bytes()).decode("ascii")
        data_uri = f"{mime_type or 'image/jpeg'};base64,{encoded}"
        if not data_uri.startswith("data:"):
            data_uri = f"data:{data_uri}"
    except Exception as exc:
        return "", "gpt-vision", str(exc)
    system = (
        "You extract text from an image CV/resume for an HR application. "
        "Return JSON only. Preserve useful CV text in reading order. Do not invent."
    )
    prompt = json.dumps(
        {
            "task": "Extract all visible CV/resume text from this image.",
            "json_schema": {
                "text": "full extracted CV text, preserving line breaks where helpful",
                "confidence": "number 0..1",
                "reason": "short note about legibility",
            },
        },
        ensure_ascii=False,
    )
    try:
        if provider.get("api") == "openai-responses":
            body = {
                "model": provider["model"],
                "temperature": 0,
                "input": [
                    {"role": "system", "content": system},
                    {
                        "role": "user",
                        "content": [
                            {"type": "input_text", "text": prompt},
                            {"type": "input_image", "image_url": data_uri},
                        ],
                    },
                ],
            }
        else:
            body = {
                "model": provider["model"],
                "temperature": 0,
                "messages": [
                    {"role": "system", "content": system},
                    {
                        "role": "user",
                        "content": [
                            {"type": "text", "text": prompt},
                            {"type": "image_url", "image_url": {"url": data_uri}},
                        ],
                    },
                ],
            }
        req = urllib.request.Request(
            provider["url"],
            data=json.dumps(body).encode("utf-8"),
            headers={"Authorization": f"Bearer {provider['api_key']}", "Content-Type": "application/json"},
            method="POST",
        )
        with urllib.request.urlopen(req, timeout=45) as resp:
            parsed = json.loads(resp.read().decode("utf-8", errors="replace"))
        result = extract_json_object(extract_model_text(parsed))
        if not isinstance(result, dict):
            return "", "gpt-vision", "vision_json_not_found"
        try:
            confidence = float(result.get("confidence") or 0)
        except Exception:
            confidence = 0.0
        text = str(result.get("text") or "").strip()
        if confidence < 0.45:
            return "", "gpt-vision", f"low_confidence:{confidence}"
        if not cv_text_quality_ok(text):
            return "", "gpt-vision", "low_quality_text"
        return text, "gpt-5.4-vision", None
    except Exception as exc:
        return "", "gpt-vision", str(exc)


def cv_text_quality_ok(text: str | None) -> bool:
    raw = str(text or "").strip()
    if len(raw) < 80:
        return False
    words = re.findall(r"[A-Za-z\u0600-\u06FF][A-Za-z\u0600-\u06FF0-9+#.'-]{1,}", raw)
    if len(words) < 12:
        return False
    alpha_chars = sum(1 for ch in raw if ch.isalpha())
    printable_chars = sum(1 for ch in raw if ch.isprintable() and not ch.isspace())
    if printable_chars and alpha_chars / max(printable_chars, 1) < 0.35:
        return False
    # Common PDF metadata-only extraction signals. If these dominate, parsing
    # did not actually recover CV content.
    metadata_markers = sum(raw.lower().count(marker) for marker in ("reportlab", "anonymous", "unspecified", "obj", "endobj", "xref"))
    if metadata_markers >= 3 and len(words) < 40:
        return False
    return True


def parse_candidate_profile_from_cv_text(text: str, *, fallback_name: str | None = None, fallback_phone: str | None = None) -> dict[str, Any]:
    lines = [line.strip() for line in str(text or "").splitlines() if line.strip()]
    email = _extract_email_from_text(text)
    phone_match = re.search(r"(?:\+?965)?\s?([569]\d{7})\b", text or "")
    phone = digits(phone_match.group(0)) if phone_match else digits(fallback_phone)
    name = fallback_name
    if lines:
        first = lines[0]
        if 2 <= len(first.split()) <= 5 and not _extract_email_from_text(first) and not re.search(r"\d", first):
            name = first
    skills: list[str] = []
    skill_capture = False
    for line in lines:
        lower = line.lower()
        if any(marker in lower for marker in ("key skills", "skills", "technical skills")):
            skill_capture = True
            continue
        if skill_capture and any(marker in lower for marker in ("experience", "education", "languages", "professional summary")):
            break
        if skill_capture:
            item = re.sub(r"^[•\\-\\*\\d\\.\\s]+", "", line).strip()
            if item and len(item) <= 80:
                skills.append(item)
    return {
        "name": name,
        "email": email,
        "phone": phone or None,
        "skills": skills[:20],
        "summary": " ".join(lines[:4])[:800] if lines else None,
        "parsed_at": now_iso(),
        "parser": "regex_cv_profile_v1",
    }


def extract_structured_candidate_profile_from_cv_text(text: str, *, application: dict[str, Any]) -> dict[str, Any] | None:
    provider = planner_provider_config()
    if not provider or not text.strip():
        return None
    system = (
        "You extract structured candidate profile facts from one CV. "
        "Return JSON only. Do not invent. Use null/empty arrays when not visible. "
        "Keep evidence short and quote/paraphrase only visible CV facts."
    )
    payload = {
        "role": application.get("position_title") or application.get("position_code"),
        "cv_text": text[:12000],
        "json_schema": {
            "name": "string|null",
            "email": "string|null",
            "phone": "string|null",
            "summary": "short string|null",
            "skills": ["string"],
            "tools": ["string"],
            "experience_years": "number|null",
            "education": "string|null",
            "languages": ["string"],
            "role_relevant_experience": "short string|null",
            "confidence": "number 0..1",
            "evidence": ["short string"],
        },
    }
    if provider.get("api") == "openai-responses":
        body = {
            "model": provider["model"],
            "temperature": 0,
            "input": [
                {"role": "system", "content": system},
                {"role": "user", "content": json.dumps(payload, ensure_ascii=False)},
            ],
        }
    else:
        body = {
            "model": provider["model"],
            "temperature": 0,
            "messages": [
                {"role": "system", "content": system},
                {"role": "user", "content": json.dumps(payload, ensure_ascii=False)},
            ],
        }
    req = urllib.request.Request(
        provider["url"],
        data=json.dumps(body).encode("utf-8"),
        headers={"Authorization": f"Bearer {provider['api_key']}", "Content-Type": "application/json"},
        method="POST",
    )
    try:
        with urllib.request.urlopen(req, timeout=20) as resp:
            parsed = json.loads(resp.read().decode("utf-8", errors="replace"))
    except Exception:
        return None
    result = extract_json_object(extract_model_text(parsed))
    if not isinstance(result, dict):
        return None
    try:
        confidence = float(result.get("confidence") or 0)
    except Exception:
        confidence = 0.0
    result["confidence"] = confidence
    result["parser"] = "llm_cv_profile_v1"
    result["parsed_at"] = now_iso()
    return result


def merge_candidate_profiles(regex_profile: dict[str, Any], llm_profile: dict[str, Any] | None) -> dict[str, Any]:
    if not isinstance(llm_profile, dict) or float(llm_profile.get("confidence") or 0) < 0.55:
        return regex_profile
    merged = dict(regex_profile)
    for key in ("name", "email", "phone", "summary", "education", "experience_years", "role_relevant_experience"):
        if llm_profile.get(key) not in (None, "", [], {}):
            merged[key] = llm_profile.get(key)
    for key in ("skills", "tools", "languages", "evidence"):
        if isinstance(llm_profile.get(key), list) and llm_profile[key]:
            merged[key] = llm_profile[key]
    merged["llm_profile"] = llm_profile
    merged["parser"] = "llm_cv_profile_v1+regex_fallback"
    merged["parsed_at"] = now_iso()
    return merged


def screening_questions_for_application(application: dict[str, Any]) -> list[dict[str, Any]]:
    company_code = str(application.get("company_code") or "WATHEFNI")
    position_code = str(application.get("position_code") or "")
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT metadata, raw_json FROM positions WHERE company_code=%s AND position_code=%s LIMIT 1",
                (company_code, position_code),
            )
            row = cur.fetchone()
    if row:
        metadata = row.get("metadata") if isinstance(row.get("metadata"), dict) else {}
        raw_json = row.get("raw_json") if isinstance(row.get("raw_json"), dict) else {}
        for source in (metadata, raw_json):
            questions = source.get("screening_questions") if isinstance(source, dict) else None
            if isinstance(questions, list) and questions:
                return [q for q in questions if isinstance(q, dict)]
    role = str(application.get("position_title") or application.get("position_code") or "this role")
    return [
        {"key": "visa_status", "question": "What is your current visa or residency status in Kuwait?", "required": True},
        {"key": "salary_expectation", "question": "What is your expected monthly salary in KD?", "required": True},
        {"key": "availability", "question": "When can you start?", "required": True},
        {"key": "relevant_experience", "question": f"Briefly describe your relevant experience for {role}.", "required": True},
        {"key": "tools", "question": "Which tools, software, or systems are you strongest with?", "required": False},
    ]


def prefill_screening_answers_from_profile(profile: dict[str, Any], questions: list[dict[str, Any]]) -> tuple[dict[str, Any], dict[str, str], dict[str, Any]]:
    answers: dict[str, Any] = {}
    sources: dict[str, str] = {}
    evidence: dict[str, Any] = {}
    haystack = " ".join(str(v) for v in profile.values() if isinstance(v, (str, int, float))).lower()
    for question in questions:
        key = str(question.get("key") or "")
        if question.get("allow_cv_prefill") is not True:
            continue
        qtext = str(question.get("question") or "").lower()
        value = None
        if key in {"experience_years", "finance_experience_years"} and profile.get("experience_years") not in (None, ""):
            value = str(profile.get("experience_years"))
        elif key in {"tools", "finance_tools", "stack", "channels"}:
            tools = profile.get("tools") if isinstance(profile.get("tools"), list) else profile.get("skills")
            if isinstance(tools, list) and tools:
                value = ", ".join(str(item) for item in tools[:8])
        elif key in {"relevant_experience", "campaign_examples"} or "experience" in qtext:
            value = profile.get("role_relevant_experience") or profile.get("summary")
        elif key == "visa_status":
            # Only prefill very explicit citizenship/residency evidence.
            if "kuwaiti" in haystack or "كويتي" in haystack:
                value = "Kuwaiti"
        if value:
            answers[key] = value
            sources[key] = "cv_prefill"
            evidence[key] = {"value": value, "profile_parser": profile.get("parser"), "confidence": profile.get("confidence")}
    return answers, sources, evidence


def update_cv_processing_flags(raw_json: dict[str, Any], **updates: Any) -> dict[str, Any]:
    raw = dict(raw_json or {})
    cv = dict(raw.get("cv") or {})
    processing = dict(cv.get("processing") or {})
    processing.update({key: value for key, value in updates.items() if value is not None})
    processing["updated_at"] = now_iso()
    cv["processing"] = processing
    raw["cv"] = cv
    return raw


def upsert_application_semantic_document(
    cur: Any,
    *,
    application: dict[str, Any],
    content: str,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    app_key = str(application.get("app_key") or "")
    if not app_key or not content.strip():
        return {"ok": False, "error": "missing_app_key_or_content"}
    company_code = str(application.get("company_code") or "WATHEFNI").upper()
    position_code = str(application.get("position_code") or "")
    phone = digits(application.get("phone"))
    title = str(application.get("position_title") or position_code or "Application CV")
    content_hash = hashlib.sha256(content.encode("utf-8")).hexdigest()
    cfg = embedding_provider_config()
    embedding = None
    provider = None
    model = None
    dimensions = None
    if cfg:
        # Voyage document embeddings use input_type=document. Keep separate from
        # query embeddings so ranking remains semantically meaningful.
        body = {"input": [content[:12000]], "model": cfg["model"], "input_type": "document"}
        req = urllib.request.Request(
            cfg["url"],
            data=json.dumps(body).encode("utf-8"),
            headers={"Authorization": f"Bearer {cfg['api_key']}", "Content-Type": "application/json"},
            method="POST",
        )
        try:
            with urllib.request.urlopen(req, timeout=18) as resp:
                parsed = json.loads(resp.read().decode("utf-8", errors="replace"))
            data = parsed.get("data") if isinstance(parsed, dict) else None
            raw_embedding = data[0].get("embedding") if isinstance(data, list) and data and isinstance(data[0], dict) else None
            if isinstance(raw_embedding, list):
                embedding = [float(value) for value in raw_embedding]
                provider = cfg["provider"]
                model = cfg["model"]
                dimensions = len(embedding)
        except Exception:
            embedding = None
    semantic_id = f"application:{app_key}:cv"
    if embedding:
        cur.execute(
            """
            INSERT INTO semantic_documents
            (semantic_id, entity_type, entity_key, company_code, phone, app_key, position_code, title, content, content_hash, provider, model, dimensions, embedding, metadata, created_at, updated_at)
            VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s::vector,%s,now(),now())
            ON CONFLICT (semantic_id) DO UPDATE SET
              content=EXCLUDED.content,
              content_hash=EXCLUDED.content_hash,
              provider=EXCLUDED.provider,
              model=EXCLUDED.model,
              dimensions=EXCLUDED.dimensions,
              embedding=EXCLUDED.embedding,
              metadata=EXCLUDED.metadata,
              updated_at=now()
            """,
            (
                semantic_id,
                "application",
                app_key,
                company_code,
                phone,
                app_key,
                position_code,
                title,
                content,
                content_hash,
                provider,
                model,
                dimensions,
                pgvector_literal(embedding),
                Json(json_safe(metadata or {})),
            ),
        )
    else:
        cur.execute(
            """
            INSERT INTO semantic_documents
            (semantic_id, entity_type, entity_key, company_code, phone, app_key, position_code, title, content, content_hash, provider, model, dimensions, metadata, created_at, updated_at)
            VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,now(),now())
            ON CONFLICT (semantic_id) DO UPDATE SET
              content=EXCLUDED.content,
              content_hash=EXCLUDED.content_hash,
              provider=EXCLUDED.provider,
              model=EXCLUDED.model,
              dimensions=EXCLUDED.dimensions,
              metadata=EXCLUDED.metadata,
              updated_at=now()
            """,
            (
                semantic_id,
                "application",
                app_key,
                company_code,
                phone,
                app_key,
                position_code,
                title,
                content,
                content_hash,
                provider,
                model,
                dimensions,
                Json(json_safe({**(metadata or {}), "embedding_status": "missing"})),
            ),
        )
    return {"ok": True, "semantic_id": semantic_id, "embedded": bool(embedding), "content_hash": content_hash}


def process_candidate_cv_document(document_id: str, *, dry_run: bool = False, send_screening: bool = True) -> dict[str, Any]:
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT cd.*, a.*, c.name AS candidate_name, c.email AS candidate_email, c.profile AS candidate_profile, c.raw_json AS candidate_raw_json
                FROM candidate_documents cd
                JOIN applications a ON a.app_key=cd.app_key
                LEFT JOIN candidates c ON c.phone=a.phone
                WHERE cd.document_id=%s
                """,
                (document_id,),
            )
            row = cur.fetchone()
            if not row:
                return {"ok": False, "error": "document_not_found", "document_id": document_id}
            item = dict(row)
            app = {key: item.get(key) for key in (
                "app_key", "phone", "company_code", "position_code", "apply_code", "position_title", "company_name",
                "status", "current_step", "cv_received", "cv_received_at", "screening_status", "raw_json",
            )}
            raw_json = app.get("raw_json") if isinstance(app.get("raw_json"), dict) else {}
            # Imported candidates (held in the Intake queue OR auto-admitted into
            # Candidates) get their CV extracted and indexed, but are NEVER auto-messaged.
            # HR drives all outreach manually. Held imports also never auto-advance status.
            held_import = str(app.get("status") or "").strip().lower() in HELD_IMPORT_STATUSES
            imported_app = isinstance(raw_json.get("import"), dict)
            if held_import or imported_app:
                send_screening = False
            local_path = item.get("local_path") or ((raw_json.get("cv") or {}).get("path") if isinstance(raw_json.get("cv"), dict) else None)
            text, method, error = extract_candidate_cv_text_from_path(local_path, (raw_json.get("cv") or {}).get("storage", {}).get("mime_type") if isinstance(raw_json.get("cv"), dict) else None)
            if dry_run:
                return {"ok": bool(text), "document_id": document_id, "method": method, "chars": len(text), "error": error}
            text_path = None
            if text:
                text_dir = WORKSPACE / "data" / "candidates" / digits(app.get("phone")) / "cv-text"
                text_dir.mkdir(parents=True, exist_ok=True)
                text_path = text_dir / f"{safe_storage_name(str(app.get('app_key')))}.txt"
                text_path.write_text(text, encoding="utf-8")
                regex_profile = parse_candidate_profile_from_cv_text(text, fallback_name=item.get("candidate_name"), fallback_phone=app.get("phone"))
                llm_profile = extract_structured_candidate_profile_from_cv_text(text, application=app)
                profile = merge_candidate_profiles(regex_profile, llm_profile)
                screening_questions = screening_questions_for_application(app)
                prefill_answers, prefill_sources, prefill_evidence = prefill_screening_answers_from_profile(profile, screening_questions)
                semantic = upsert_application_semantic_document(
                    cur,
                    application=app,
                    content=text,
                    metadata={"source": "cv_worker", "document_id": document_id, "extraction_method": method},
                )
                candidate_profile = item.get("candidate_profile") if isinstance(item.get("candidate_profile"), dict) else {}
                existing_apps = candidate_profile.get("applications") if isinstance(candidate_profile.get("applications"), list) else []
                updated_apps: list[dict[str, Any]] = []
                found_app = False
                for existing_app in existing_apps:
                    if not isinstance(existing_app, dict):
                        continue
                    if str(existing_app.get("app_key") or "") == str(app.get("app_key") or ""):
                        found_app = True
                        updated_apps.append({
                            **existing_app,
                            "status": "screening",
                            "current_step": "screening",
                            "cv_received": True,
                            "screening_status": "pending",
                            "updated_at": now_iso(),
                        })
                    else:
                        updated_apps.append(existing_app)
                if not found_app:
                    updated_apps.append({
                        "app_key": app.get("app_key"),
                        "company_code": app.get("company_code"),
                        "position_code": app.get("position_code"),
                        "apply_code": app.get("apply_code"),
                        "status": "screening",
                        "current_step": "screening",
                        "cv_received": True,
                        "screening_status": "pending",
                        "updated_at": now_iso(),
                    })
                merged_profile = {
                    **candidate_profile,
                    **{k: v for k, v in profile.items() if v not in (None, "", [], {})},
                    "applications": updated_apps,
                    "current_status": "screening",
                    "active_company_code": app.get("company_code"),
                    "active_position_code": app.get("position_code"),
                    "active_application": {
                        "app_key": app.get("app_key"),
                        "apply_code": app.get("apply_code"),
                        "company_code": app.get("company_code"),
                        "position_code": app.get("position_code"),
                        "updated_at": now_iso(),
                    },
                }
                cur.execute(
                    """
                    UPDATE candidates
                    SET name=COALESCE(NULLIF(%s,''), name),
                        email=COALESCE(NULLIF(%s,''), email),
                        profile=%s,
                        raw_json=COALESCE(raw_json,'{}'::jsonb) || %s::jsonb,
                        updated_at=now()
                    WHERE phone=%s
                    """,
                    (
                        profile.get("name"),
                        profile.get("email"),
                        Json(json_safe(merged_profile)),
                        Json(json_safe({"profile_parse": profile})),
                        digits(app.get("phone")),
                    ),
                )
                current_screening = raw_json.get("screening") if isinstance(raw_json.get("screening"), dict) else {}
                current_answers = current_screening.get("answers") if isinstance(current_screening.get("answers"), dict) else {}
                current_sources = current_screening.get("answer_sources") if isinstance(current_screening.get("answer_sources"), dict) else {}
                current_evidence = current_screening.get("answer_evidence") if isinstance(current_screening.get("answer_evidence"), dict) else {}
                merged_answers = {**prefill_answers, **current_answers}
                merged_sources = {**prefill_sources, **current_sources}
                merged_evidence = {**prefill_evidence, **current_evidence}
                required_keys = [str(q.get("key") or "") for q in screening_questions if q.get("required") is True and q.get("key")]
                pending_keys = [key for key in required_keys if not str(merged_answers.get(key) or "").strip()]
                screening_status = "complete" if not pending_keys and required_keys else "pending"
                next_raw = {
                    **raw_json,
                    "screening": {
                        **current_screening,
                        "status": screening_status,
                        "answers": merged_answers,
                        "answer_sources": merged_sources,
                        "answer_evidence": merged_evidence,
                        "questions": screening_questions,
                        "pending_keys": pending_keys,
                        "completed_at": now_iso() if screening_status == "complete" else current_screening.get("completed_at"),
                    },
                }
                next_raw = update_cv_processing_flags(
                    raw_json,
                    file_received=True,
                    file_stored=True,
                    text_extracted=True,
                    profile_parsed=True,
                    semantic_indexed=bool(semantic.get("ok")),
                    screening_prefill_ready=True,
                    screening_prefill_count=len(prefill_answers),
                    status="processed",
                    extraction_method=method,
                    extraction_chars=len(text),
                )
                next_raw["screening"] = {
                    **current_screening,
                    "status": screening_status,
                    "answers": merged_answers,
                    "answer_sources": merged_sources,
                    "answer_evidence": merged_evidence,
                    "questions": screening_questions,
                    "pending_keys": pending_keys,
                    "completed_at": now_iso() if screening_status == "complete" else current_screening.get("completed_at"),
                }
                cur.execute(
                    """
                    UPDATE applications
                    SET raw_json=%s,
                        cv_received=true,
                        cv_received_at=COALESCE(cv_received_at, CURRENT_DATE),
                        status=CASE WHEN status IN ('needs_role','import_review') THEN status WHEN %s='complete' THEN 'screening_complete' WHEN status IN ('awaiting_cv','cv_received') THEN 'screening' ELSE status END,
                        current_step=CASE WHEN status IN ('needs_role','import_review') THEN current_step ELSE 'screening' END,
                        screening_status=%s,
                        screening_completed_at=CASE WHEN %s='complete' THEN COALESCE(screening_completed_at, CURRENT_DATE) ELSE screening_completed_at END,
                        updated_at=COALESCE(updated_at, CURRENT_DATE)
                    WHERE app_key=%s
                    """,
                    (Json(json_safe(next_raw)), screening_status, screening_status, screening_status, app.get("app_key")),
                )
                cur.execute(
                    """
                    UPDATE candidate_documents
                    SET text_path=%s,
                        extraction_status=%s,
                        extraction_method=%s,
                        extraction_chars=%s,
                        metadata=COALESCE(metadata,'{}'::jsonb) || %s::jsonb,
                        updated_at=now()
                    WHERE document_id=%s
                    """,
                    (str(text_path), "ok", method, len(text), Json(json_safe({"semantic": semantic, "profile": profile})), document_id),
                )
                conn.commit()
                screening_result = None
                if send_screening:
                    # Import lazily to avoid circular boot coupling; action_registry is
                    # already validated at startup.
                    ctx = _action_registry.ExecutionContext(
                        request=WhatsAppTurnRequest(
                            account_id=None,
                            conversation_id=None,
                            sender_phone="system",
                            sender_role="system",
                            raw_text="send screening questions",
                            metadata={"source": "cv_processing_worker", "document_id": document_id},
                        ),
                        action={"action_type": "send_screening_questions", "app_key": app.get("app_key")},
                        state={},
                        graph_state={},
                        intent={},
                        legacy=sys.modules[__name__],
                    )
                    screening_result = _action_registry.execute("send_screening_questions", ctx)
                    with db_connect() as flag_conn:
                        with flag_conn.cursor() as flag_cur:
                            flag_cur.execute("SELECT raw_json FROM applications WHERE app_key=%s", (app.get("app_key"),))
                            flag_row = flag_cur.fetchone()
                            latest_raw = flag_row.get("raw_json") if flag_row and isinstance(flag_row.get("raw_json"), dict) else next_raw
                            latest_raw = update_cv_processing_flags(
                                latest_raw,
                                screening_questions_sent=bool((screening_result or {}).get("success")),
                                screening_questions_sent_at=now_iso() if bool((screening_result or {}).get("success")) else None,
                            )
                            flag_cur.execute("UPDATE applications SET raw_json=%s WHERE app_key=%s", (Json(json_safe(latest_raw)), app.get("app_key")))
                        flag_conn.commit()
                return {
                    "ok": True,
                    "document_id": document_id,
                    "app_key": app.get("app_key"),
                    "chars": len(text),
                    "method": method,
                    "semantic": semantic,
                    "screening": json_safe(screening_result),
                }
            next_raw = update_cv_processing_flags(
                raw_json,
                file_received=True,
                file_stored=True,
                text_extracted=False,
                profile_parsed=False,
                semantic_indexed=False,
                screening_prefill_ready=False,
                status="failed",
                failed_reason=error or "no_text_extracted",
                extraction_method=method,
            )
            cur.execute("UPDATE applications SET raw_json=%s, updated_at=COALESCE(updated_at, CURRENT_DATE) WHERE app_key=%s", (Json(json_safe(next_raw)), app.get("app_key")))
            cur.execute(
                """
                UPDATE candidate_documents
                SET extraction_status=%s,
                    extraction_method=%s,
                    metadata=COALESCE(metadata,'{}'::jsonb) || %s::jsonb,
                    updated_at=now()
                WHERE document_id=%s
                """,
                ("failed", method, Json(json_safe({"extraction_error": error or "no_text_extracted"})), document_id),
            )
            conn.commit()
            screening_result = None
            if send_screening:
                ctx = _action_registry.ExecutionContext(
                    request=WhatsAppTurnRequest(
                        account_id=None,
                        conversation_id=None,
                        sender_phone="system",
                        sender_role="system",
                        raw_text="send fallback screening questions",
                        metadata={"source": "cv_processing_worker", "document_id": document_id, "parse_failed": True},
                    ),
                    action={"action_type": "send_screening_questions", "app_key": app.get("app_key")},
                    state={},
                    graph_state={},
                    intent={},
                    legacy=sys.modules[__name__],
                )
                screening_result = _action_registry.execute("send_screening_questions", ctx)
                with db_connect() as flag_conn:
                    with flag_conn.cursor() as flag_cur:
                        flag_cur.execute("SELECT raw_json FROM applications WHERE app_key=%s", (app.get("app_key"),))
                        flag_row = flag_cur.fetchone()
                        latest_raw = flag_row.get("raw_json") if flag_row and isinstance(flag_row.get("raw_json"), dict) else next_raw
                        latest_raw = update_cv_processing_flags(
                            latest_raw,
                            screening_questions_sent=bool((screening_result or {}).get("success")),
                            screening_questions_sent_at=now_iso() if bool((screening_result or {}).get("success")) else None,
                        )
                        flag_cur.execute("UPDATE applications SET raw_json=%s WHERE app_key=%s", (Json(json_safe(latest_raw)), app.get("app_key")))
                    flag_conn.commit()
            return {"ok": False, "document_id": document_id, "app_key": app.get("app_key"), "method": method, "error": error, "screening": json_safe(screening_result)}


def run_candidate_cv_processing_worker(*, dry_run: bool = True, limit: int = 10, force: bool = False, send_screening: bool = True) -> dict[str, Any]:
    ensure_schema()
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT document_id::text
                FROM candidate_documents
                WHERE document_type='cv'
                  AND (%s OR extraction_status IS NULL OR extraction_status IN ('pending_extraction','stored'))
                ORDER BY updated_at ASC NULLS FIRST, created_at ASC
                LIMIT %s
                """,
                (force, limit),
            )
            document_ids = [row["document_id"] for row in cur.fetchall()]
    results = [process_candidate_cv_document(document_id, dry_run=dry_run, send_screening=send_screening) for document_id in document_ids]
    return {"dry_run": dry_run, "limit": limit, "force": force, "processed": len(results), "results": json_safe(results)}


def is_candidate_cv_truth_question(text: str) -> bool:
    normalized = normalize_text(text)
    if not normalized:
        return False
    return bool(
        re.search(r"\b(cv|resume|file|document|application)\b", normalized)
        and re.search(r"\b(already|sent|uploaded|submitted|received|receive|got|have you|did you|why|again|status)\b", normalized)
    )


def candidate_cv_truth(application: dict[str, Any]) -> dict[str, Any]:
    raw_json = application.get("raw_json") if isinstance(application.get("raw_json"), dict) else {}
    cv_json = raw_json.get("cv") if isinstance(raw_json.get("cv"), dict) else {}
    app_key = str(application.get("app_key") or "")
    file_count = 0
    latest_file: dict[str, Any] | None = None
    if app_key:
        with db_connect() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """
                    SELECT storage_status, storage_url, original_filename, created_at, updated_at
                    FROM file_registry
                    WHERE subject_type='application'
                      AND subject_key=%s
                      AND document_type='cv'
                    ORDER BY updated_at DESC, created_at DESC
                    LIMIT 1
                    """,
                    (app_key,),
                )
                row = cur.fetchone()
                latest_file = dict(row) if row else None
                cur.execute(
                    """
                    SELECT COUNT(*) AS count
                    FROM file_registry
                    WHERE subject_type='application'
                      AND subject_key=%s
                      AND document_type='cv'
                      AND storage_status IN ('stored','ok','uploaded')
                    """,
                    (app_key,),
                )
                file_count = int((cur.fetchone() or {}).get("count") or 0)
    storage = cv_json.get("storage") if isinstance(cv_json.get("storage"), dict) else {}
    cv_received = bool(application.get("cv_received") is True or cv_json or file_count > 0)
    storage_ok = bool(file_count > 0 or storage.get("status") in {"stored", "ok", "uploaded"} or storage.get("provider"))
    return {
        "cv_received": cv_received,
        "storage_ok": storage_ok,
        "status": application.get("status"),
        "current_step": application.get("current_step"),
        "app_key": app_key,
        "position_code": application.get("position_code"),
        "latest_file": json_safe(latest_file or {}),
        "cv": json_safe(cv_json),
    }


def handle_candidate_truth_turn(request: WhatsAppTurnRequest) -> dict[str, Any] | None:
    if has_current_media_upload(request.media or {}):
        return None
    if not is_candidate_cv_truth_question(request.raw_text):
        return None
    application = find_candidate_application_for_file(request.sender_phone)
    if not application:
        return None
    if not company_has_module(application.get("company_code"), "pre_hiring"):
        return {"reply": candidate_safe_module_unavailable_reply(), "application": json_safe(application), "module_disabled": "pre_hiring"}
    truth = candidate_cv_truth(application)
    if truth.get("cv_received") and truth.get("storage_ok"):
        reply = "Yes, I have your CV saved. Wathefni HR will review it and follow up with the next step."
    elif truth.get("cv_received"):
        reply = "I can see CV information on your application, but I do not see a safely stored file yet. Please resend your CV as a PDF, Word document, or clear image."
    else:
        reply = "I do not see a CV saved for your application yet. Please send your CV here as a PDF, Word document, or clear image."
    return {"reply": reply, "application": json_safe(application), "truth": truth}


CANDIDATE_FORBIDDEN_POLICY_PATTERNS: list[tuple[str, str]] = [
    ("hiring_promise", r"\b(you('| a)?re hired|you are hired|you will get the job|guaranteed|we will hire you|job is yours)\b"),
    ("decision_claim", r"\b(you('| a)?re shortlisted|you are shortlisted|you have been shortlisted|you('| a)?re rejected|you are rejected)\b"),
    ("ranking_or_score", r"\b(score|ranking|ranked|percentile|top candidate|best candidate|strong candidate|weak candidate|strong fit|weak fit)\b"),
    ("comparison", r"\b(other candidates|other applicants|better than|worse than|compared to|among applicants)\b"),
    ("internal_notes", r"\b(internal notes?|recruiter notes?|hr notes?|hr likes|internal score|embedding|semantic score)\b"),
    ("salary_offer", r"\b(we can offer|salary approved|offer you\s+\d|your offer is|we will pay)\b"),
]


def apply_candidate_reply_policy(reply: str | None, *, request: WhatsAppTurnRequest, result: dict[str, Any] | None) -> dict[str, Any]:
    text = str(reply or "").strip()
    if not text:
        return {"reply": text, "policy_applied": False, "violations": []}
    normalized = normalize_text(text)
    violations: list[str] = []
    for label, pattern in CANDIDATE_FORBIDDEN_POLICY_PATTERNS:
        if re.search(pattern, normalized, re.I):
            violations.append(label)
    if not violations:
        return {"reply": text, "policy_applied": False, "violations": []}
    if "salary_offer" in violations:
        safe = "I can’t negotiate or confirm salary decisions here. I can help with your application status, missing information, or next steps."
    elif "ranking_or_score" in violations or "comparison" in violations or "internal_notes" in violations:
        safe = "I can’t share hiring review details here. I can help with your application status, missing information, or next steps."
    else:
        safe = "Thanks — your application is in progress. Wathefni HR will review your information and follow up with the next step."
    return {"reply": safe, "policy_applied": True, "violations": violations, "original_reply": text}


def candidate_active_application(phone: str | None) -> dict[str, Any] | None:
    return find_candidate_application_for_file(phone)


def candidate_missing_or_next_reply(application: dict[str, Any]) -> str:
    raw_json = application.get("raw_json") if isinstance(application.get("raw_json"), dict) else {}
    screening = raw_json.get("screening") if isinstance(raw_json.get("screening"), dict) else {}
    processing = (raw_json.get("cv") or {}).get("processing") if isinstance(raw_json.get("cv"), dict) else {}
    title = application.get("position_title") or application.get("position_code") or "this role"
    if not application.get("cv_received"):
        return f"Your application for {title} is started. Next step: please send your CV here as a PDF, Word document, image, or clear text."
    if isinstance(processing, dict) and processing.get("status") in {"pending_async_processing", "processing"}:
        return "I received your CV and I’m still processing it. I’ll continue with the next step once it’s ready."
    pending_keys = screening.get("pending_keys") if isinstance(screening.get("pending_keys"), list) else []
    questions = screening.get("questions") if isinstance(screening.get("questions"), list) else []
    if pending_keys:
        next_question = format_next_screening_question([q for q in questions if isinstance(q, dict)], [str(item) for item in pending_keys])
        return f"Your CV is received. Next step: please answer this quick application question:\n\n{next_question}"
    if str(application.get("screening_status") or screening.get("status") or "").lower() in {"complete", "completed"}:
        return "Your application is complete for review. Wathefni HR will review it and follow up with the next step."
    return "Your application is in progress. I can help with your CV, quick application questions, or application status."


def public_candidate_roles(company_code: str | None = "WATHEFNI", *, limit: int = 5) -> list[dict[str, Any]]:
    company = str(company_code or "WATHEFNI").upper()
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT position_code, title, salary_min, salary_max, currency, apply_code
                FROM positions
                WHERE company_code=%s
                  AND COALESCE(status, 'open') IN ('open','active')
                ORDER BY updated_at DESC NULLS LAST, created_at DESC
                LIMIT %s
                """,
                (company, limit),
            )
            roles: list[dict[str, Any]] = []
            for row in cur.fetchall():
                item = dict(row)
                for key in ("salary_min", "salary_max"):
                    if item.get(key) is not None:
                        try:
                            item[key] = float(item[key])
                        except Exception:
                            item[key] = str(item[key])
                roles.append(json_safe(item))
            return roles


def public_candidate_welcome_reply(company_code: str | None = "WATHEFNI") -> str:
    roles = public_candidate_roles(company_code, limit=5)
    lines = [
        "Hi, welcome to Wathefni.",
        "",
        "I can help you apply or continue an application.",
        "",
        "If you have an APPLY code, send it here.",
    ]
    if roles:
        lines.append("If not, tell me which role you’re interested in. Current open roles include:")
        for idx, role in enumerate(roles, 1):
            title = role.get("title") or role.get("position_code")
            lines.append(f"{idx}. {title}")
    else:
        lines.append("If you don’t have a code, please ask the company for the job QR or APPLY code.")
    return "\n".join(lines)


def role_interest_from_text(text: str | None) -> str | None:
    normalized = normalize_text(text)
    if not re.search(r"\b(apply|application|interested|job|role|position)\b", normalized):
        return None
    cleaned = re.sub(r"\b(i|want|wanna|wana|would like|to|apply|application|for|job|role|position|at|wathefni|here is my cv|cv|resume|please|pls)\b", " ", normalized)
    cleaned = re.sub(r"\s+", " ", cleaned).strip()
    return cleaned or None


def public_role_matches(query: str | None, *, company_code: str | None = "WATHEFNI") -> list[dict[str, Any]]:
    if not query:
        return []
    roles = public_candidate_roles(company_code, limit=50)
    terms = [term for term in normalize_text(query).split() if len(term) >= 2]
    scored = []
    for role in roles:
        haystack = normalize_text(f"{role.get('title') or ''} {role.get('position_code') or ''}".replace("_", " "))
        score = sum(1 for term in terms if term in haystack)
        if score:
            scored.append((score, role))
    scored.sort(key=lambda item: item[0], reverse=True)
    return [role for _, role in scored[:5]]


def parse_apply_code_text(text: str | None) -> dict[str, str] | None:
    match = re.search(r"\b(APPLY-([A-Z0-9_]+)-([A-Z0-9_]+))\b", str(text or "").upper())
    if not match:
        return None
    return {"apply_code": match.group(1), "company_code": match.group(2), "position_code": match.group(3)}


def public_role_by_apply_code(apply_code: str | None) -> dict[str, Any] | None:
    parsed = parse_apply_code_text(apply_code)
    if not parsed:
        return None
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT company_code, position_code, title, salary_min, salary_max, currency, apply_code
                FROM positions
                WHERE company_code=%s
                  AND position_code=%s
                  AND COALESCE(status, 'open') IN ('open','active')
                LIMIT 1
                """,
                (parsed["company_code"], parsed["position_code"]),
            )
            row = cur.fetchone()
    if not row:
        return None
    item = dict(row)
    for key in ("salary_min", "salary_max"):
        if item.get(key) is not None:
            try:
                item[key] = float(item[key])
            except Exception:
                item[key] = str(item[key])
    return json_safe(item)


PUBLIC_CANDIDATE_SCOPE = "public_candidate_options"


def active_public_candidate_session(request: WhatsAppTurnRequest) -> dict[str, Any] | None:
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT *
                FROM public_candidate_sessions
                WHERE phone=%s
                  AND COALESCE(account_id,'default')=COALESCE(%s,'default')
                  AND (%s IS NULL OR conversation_id=%s)
                  AND status='active'
                  AND expires_at > now()
                ORDER BY updated_at DESC
                LIMIT 1
                """,
                (digits(request.sender_phone), request.account_id, request.conversation_id, request.conversation_id),
            )
            row = cur.fetchone()
            return json_safe(dict(row)) if row else None


def upsert_public_candidate_session(
    request: WhatsAppTurnRequest,
    *,
    roles: list[dict[str, Any]] | None = None,
    selected_position_code: str | None = None,
    pending_media: dict[str, Any] | None = None,
    metadata: dict[str, Any] | None = None,
    status: str = "active",
) -> dict[str, Any]:
    company_code = request_company_code(request) or "WATHEFNI"
    existing = active_public_candidate_session(request)
    merged_metadata = {}
    if existing and isinstance(existing.get("metadata"), dict):
        merged_metadata.update(existing["metadata"])
    if metadata:
        merged_metadata.update(metadata)
    data_source, data_source_detail = data_source_from_request(request)
    if data_source_detail:
        merged_metadata.setdefault("data_source_detail", data_source_detail)
    shown = roles if roles is not None else ((existing or {}).get("shown_role_options") if isinstance((existing or {}).get("shown_role_options"), list) else [])
    media = pending_media if pending_media is not None else ((existing or {}).get("pending_media") if isinstance((existing or {}).get("pending_media"), dict) else {})
    with db_connect() as conn:
        with conn.cursor() as cur:
            if existing:
                cur.execute(
                    """
                    UPDATE public_candidate_sessions
                    SET status=%s,
                        selected_position_code=COALESCE(%s, selected_position_code),
                        shown_role_options=%s,
                        pending_media=%s,
                        metadata=%s,
                        data_source=%s,
                        updated_at=now(),
                        expires_at=now() + interval '2 hours'
                    WHERE session_id=%s
                    RETURNING *
                    """,
                    (status, selected_position_code, Json(json_safe(shown or [])), Json(json_safe(media or {})), Json(json_safe(merged_metadata)), data_source, existing["session_id"]),
                )
            else:
                cur.execute(
                    """
                    INSERT INTO public_candidate_sessions
                    (account_id, conversation_id, phone, company_code, status, selected_position_code, shown_role_options, pending_media, metadata, data_source, expires_at)
                    VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,now() + interval '2 hours')
                    RETURNING *
                    """,
                    (
                        request.account_id,
                        request.conversation_id,
                        digits(request.sender_phone),
                        company_code,
                        status,
                        selected_position_code,
                        Json(json_safe(shown or [])),
                        Json(json_safe(media or {})),
                        Json(json_safe(merged_metadata)),
                        data_source,
                    ),
                )
            row = dict(cur.fetchone())
        conn.commit()
    return json_safe(row)


def complete_public_candidate_session(request: WhatsAppTurnRequest) -> None:
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                UPDATE public_candidate_sessions
                SET status='completed', updated_at=now()
                WHERE phone=%s
                  AND COALESCE(account_id,'default')=COALESCE(%s,'default')
                  AND (%s IS NULL OR conversation_id=%s)
                  AND status='active'
                """,
                (digits(request.sender_phone), request.account_id, request.conversation_id, request.conversation_id),
            )
        conn.commit()


def start_public_candidate_application(request: WhatsAppTurnRequest, role: dict[str, Any]) -> dict[str, Any] | None:
    phone = digits(request.sender_phone)
    company = str(role.get("company_code") or request_company_code(request) or "WATHEFNI").upper()
    position = str(role.get("position_code") or "").strip()
    if not phone or not position:
        return None
    result = run_workspace_tool(
        [
            str(WORKSPACE / "tools" / "db" / "update_state.py"),
            "start-application",
            "--phone",
            phone,
            "--company",
            company,
            "--position",
            position,
        ],
        timeout=75,
    )
    app_key = f"{phone}-{company}-{position}"
    data_source, data_source_detail = data_source_from_request(request)
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                UPDATE applications
                SET data_source=%s,
                    data_source_detail=%s,
                    raw_json=COALESCE(raw_json,'{}'::jsonb) || %s::jsonb
                WHERE app_key=%s
                """,
                (
                    data_source,
                    data_source_detail,
                    Json(json_safe({"data_source": data_source, "data_source_detail": data_source_detail, "source_conversation_id": request.conversation_id})),
                    app_key,
                ),
            )
            cur.execute(
                """
                SELECT a.*, c.name AS candidate_name, c.email AS candidate_email
                FROM applications a
                LEFT JOIN candidates c ON c.phone=a.phone
                WHERE a.app_key=%s
                LIMIT 1
                """,
                (app_key,),
            )
            row = cur.fetchone()
    if not row:
        return None
    app_row = json_safe(dict(row))
    app_row["start_result"] = json_safe(result)
    return app_row


def attach_public_pending_cv_to_application(request: WhatsAppTurnRequest, application: dict[str, Any], session: dict[str, Any] | None) -> dict[str, Any] | None:
    pending_media = (session or {}).get("pending_media") if isinstance((session or {}).get("pending_media"), dict) else {}
    media = pending_media.get("media") if isinstance(pending_media.get("media"), dict) else {}
    if not media or not has_current_media_upload(media):
        return None
    with db_connect() as conn:
        with conn.cursor() as cur:
            result = register_candidate_cv_file(
                cur,
                application=application,
                media=media,
                metadata={
                    "conversation_id": request.conversation_id,
                    "raw_text": pending_media.get("raw_text") or request.raw_text,
                    "source": "public_candidate_pending_cv",
                    "public_session_id": (session or {}).get("session_id"),
                },
            )
        conn.commit()
    return result


def load_public_candidate_options(request: WhatsAppTurnRequest) -> list[dict[str, Any]]:
    session = active_public_candidate_session(request)
    if session and isinstance(session.get("shown_role_options"), list) and session["shown_role_options"]:
        return [role for role in session["shown_role_options"] if isinstance(role, dict)]
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT payload
                FROM memory_snapshots
                WHERE scope=%s
                  AND payload->>'phone'=%s
                  AND COALESCE(payload->>'account_id', 'default')=COALESCE(%s, 'default')
                  AND (%s IS NULL OR payload->>'conversation_id'=%s)
                  AND COALESCE(payload->>'expires_at','') > %s
                ORDER BY created_at DESC
                LIMIT 1
                """,
                (
                    PUBLIC_CANDIDATE_SCOPE,
                    digits(request.sender_phone),
                    request.account_id,
                    request.conversation_id,
                    request.conversation_id,
                    now_iso(),
                ),
            )
            row = cur.fetchone()
    payload = row.get("payload") if row and isinstance(row.get("payload"), dict) else {}
    roles = payload.get("roles") if isinstance(payload.get("roles"), list) else []
    return [role for role in roles if isinstance(role, dict)]


def parse_public_role_selection_deterministic(text: str | None, roles: list[dict[str, Any]]) -> int | None:
    normalized = normalize_text(text)
    ordinal_map = {
        "second": 2,
        "2": 2,
        "two": 2,
        "third": 3,
        "3": 3,
        "three": 3,
        "fourth": 4,
        "4": 4,
        "fifth": 5,
        "5": 5,
        "first": 1,
        "1": 1,
        "one": 1,
    }
    for key, idx in ordinal_map.items():
        if re.search(rf"\b{re.escape(key)}\b", normalized) and 1 <= idx <= len(roles):
            return idx
    for idx, role in enumerate(roles, 1):
        title = normalize_text(str(role.get("title") or role.get("position_code") or "").replace("_", " "))
        code = normalize_text(str(role.get("position_code") or "").replace("_", " "))
        if title and title in normalized:
            return idx
        if code and code in normalized:
            return idx
    return None


def parse_public_role_selection_with_gpt(text: str, roles: list[dict[str, Any]]) -> int | None:
    provider = planner_provider_config()
    if not provider or not text.strip() or not roles:
        return None
    payload = {
        "candidate_message": text,
        "options": [
            {
                "index": idx,
                "title": role.get("title"),
                "position_code": role.get("position_code"),
                "apply_code": role.get("apply_code"),
            }
            for idx, role in enumerate(roles, 1)
        ],
        "json_schema": {
            "selected_index": "integer|null",
            "confidence": "number 0..1",
            "reason": "short string",
        },
    }
    system = "Map the candidate's reply to one of the listed public job options. Return JSON only. Do not invent an option."
    if provider.get("api") == "openai-responses":
        body = {"model": provider["model"], "temperature": 0, "input": [{"role": "system", "content": system}, {"role": "user", "content": json.dumps(payload, ensure_ascii=False)}]}
    else:
        body = {"model": provider["model"], "temperature": 0, "messages": [{"role": "system", "content": system}, {"role": "user", "content": json.dumps(payload, ensure_ascii=False)}]}
    try:
        req = urllib.request.Request(
            provider["url"],
            data=json.dumps(body).encode("utf-8"),
            headers={"Authorization": f"Bearer {provider['api_key']}", "Content-Type": "application/json"},
            method="POST",
        )
        with urllib.request.urlopen(req, timeout=12) as resp:
            parsed = json.loads(resp.read().decode("utf-8", errors="replace"))
        result = extract_json_object(extract_model_text(parsed))
        if not isinstance(result, dict):
            return None
        idx = int(result.get("selected_index") or 0)
        confidence = float(result.get("confidence") or 0)
        if confidence >= 0.55 and 1 <= idx <= len(roles):
            return idx
    except Exception:
        return None
    return None


def handle_public_candidate_role_selection_turn(request: WhatsAppTurnRequest) -> dict[str, Any] | None:
    if has_current_media_upload(request.media or {}):
        return None
    if candidate_active_application(request.sender_phone):
        return None
    roles = load_public_candidate_options(request)
    if not roles:
        return None
    session = active_public_candidate_session(request)
    normalized = normalize_text(request.raw_text)
    if session and session.get("selected_position_code") and normalized in {"yes", "y", "confirm", "go ahead", "start", "start it", "apply"}:
        role = next((item for item in roles if str(item.get("position_code") or "") == str(session.get("selected_position_code") or "")), None)
        if role:
            application = start_public_candidate_application(request, role)
            if application:
                cv_result = attach_public_pending_cv_to_application(request, application, session)
                complete_public_candidate_session(request)
                if cv_result and cv_result.get("ok"):
                    return {
                        "reply": f"Done, your {role.get('title') or role.get('position_code')} application is started. I received your CV and I’m processing it now.",
                        "role": role,
                        "application": application,
                        "cv_result": json_safe(cv_result),
                        "intent": "public_candidate_application_started_with_cv",
                        "turn_focus": "public_candidate",
                    }
                return {
                    "reply": f"Done, your {role.get('title') or role.get('position_code')} application is started. Please send your CV here as a PDF, Word document, image, or clear text.",
                    "role": role,
                    "application": application,
                    "intent": "public_candidate_application_started",
                    "turn_focus": "public_candidate",
                }
    selected = parse_public_role_selection_deterministic(request.raw_text, roles)
    if selected is None:
        selected = parse_public_role_selection_with_gpt(request.raw_text or "", roles)
    if selected is None or not (1 <= selected <= len(roles)):
        return None
    role = roles[selected - 1]
    session = upsert_public_candidate_session(request, selected_position_code=str(role.get("position_code") or ""), metadata={"selected_role": role})
    if normalized in {"yes", "y", "confirm", "go ahead", "start", "start it", "apply"} or "start" in normalized:
        application = start_public_candidate_application(request, role)
        if application:
            cv_result = attach_public_pending_cv_to_application(request, application, session)
            complete_public_candidate_session(request)
            if cv_result and cv_result.get("ok"):
                return {
                    "reply": f"Done, your {role.get('title') or role.get('position_code')} application is started. I received your CV and I’m processing it now.",
                    "role": role,
                    "application": application,
                    "cv_result": json_safe(cv_result),
                    "intent": "public_candidate_application_started_with_cv",
                    "turn_focus": "public_candidate",
                }
            return {
                "reply": f"Done, your {role.get('title') or role.get('position_code')} application is started. Please send your CV here as a PDF, Word document, image, or clear text.",
                "role": role,
                "application": application,
                "intent": "public_candidate_application_started",
                "turn_focus": "public_candidate",
            }
    has_pending_cv = isinstance((session or {}).get("pending_media"), dict) and bool((session or {}).get("pending_media", {}).get("media"))
    suffix = "\n\nReply “start” and I’ll start it and attach the CV you already sent." if has_pending_cv else "\n\nOr reply “start” and I’ll start it for you."
    return {
        "reply": f"Great — {role.get('title') or role.get('position_code')}.\n\nSend this APPLY code to start:\n\n{role.get('apply_code')}{suffix}",
        "role": role,
        "session": session,
        "intent": "public_candidate_role_selected",
        "turn_focus": "public_candidate",
    }


def handle_public_candidate_apply_code_turn(request: WhatsAppTurnRequest) -> dict[str, Any] | None:
    if candidate_active_application(request.sender_phone):
        return None
    parsed = parse_apply_code_text(request.raw_text)
    if not parsed:
        return None
    role = public_role_by_apply_code(parsed["apply_code"])
    if not role:
        return {
            "reply": "I couldn’t find an open role for that APPLY code. Please check the code or ask the company for the latest job QR.",
            "intent": "public_candidate_apply_code_not_found",
            "turn_focus": "public_candidate",
        }
    session = upsert_public_candidate_session(
        request,
        roles=[role],
        selected_position_code=str(role.get("position_code") or ""),
        metadata={"source": "apply_code", "apply_code": parsed["apply_code"]},
    )
    application = start_public_candidate_application(request, role)
    if not application:
        return {
            "reply": "I found the role, but I couldn’t start the application safely. Please try again in a moment.",
            "role": role,
            "session": session,
            "intent": "public_candidate_apply_code_start_failed",
            "turn_focus": "public_candidate",
        }
    cv_result = attach_public_pending_cv_to_application(request, application, session)
    complete_public_candidate_session(request)
    if cv_result and cv_result.get("ok"):
        reply = f"Your application for {role.get('title') or role.get('position_code')} is started. I received your CV and I’m processing it now."
    else:
        reply = f"Your application for {role.get('title') or role.get('position_code')} is started. Please send your CV here as a PDF, Word document, image, or clear text."
    return {
        "reply": reply,
        "role": role,
        "application": application,
        "cv_result": json_safe(cv_result) if cv_result else None,
        "intent": "public_candidate_apply_code_started",
        "turn_focus": "public_candidate",
    }


def handle_public_candidate_apply_interest_turn(request: WhatsAppTurnRequest) -> dict[str, Any] | None:
    if candidate_active_application(request.sender_phone):
        return None
    pending_media = None
    if has_current_media_upload(request.media or {}):
        pending_media = {
            "media": request.media or {},
            "raw_text": request.raw_text,
            "received_at": now_iso(),
        }
    query = role_interest_from_text(request.raw_text)
    if not query and not pending_media:
        return None
    if not query and pending_media:
        roles = public_candidate_roles(request_company_code(request), limit=5)
        upsert_public_candidate_session(request, roles=roles, pending_media=pending_media, metadata={"source": "pending_cv_without_role"})
        return {
            "reply": "Thanks, I received your CV. Which role do you want to apply for?",
            "roles": roles,
            "intent": "public_candidate_pending_cv_needs_role",
            "turn_focus": "public_candidate",
        }
    matches = public_role_matches(query)
    if not matches:
        if pending_media:
            upsert_public_candidate_session(request, pending_media=pending_media, metadata={"source": "pending_cv_no_role_match", "query": query})
        return {
            "reply": "Thanks, I received your CV. I couldn’t confidently match the role. Please tell me which role you want to apply for, or send an APPLY code.",
            "intent": "public_candidate_apply_help",
            "turn_focus": "public_candidate",
        }
    if len(matches) == 1:
        role = matches[0]
        upsert_public_candidate_session(
            request,
            roles=matches,
            selected_position_code=str(role.get("position_code") or ""),
            pending_media=pending_media,
            metadata={"source": "single_role_match", "query": query},
        )
        suffix = "\n\nReply “start” and I’ll start it and attach the CV you already sent." if pending_media else "\n\nOr scan the job QR if you have it."
        return {
            "reply": f"I found {role.get('title') or role.get('position_code')}. To apply, send this APPLY code:\n\n{role.get('apply_code')}{suffix}",
            "role": role,
            "intent": "public_candidate_role_match",
            "turn_focus": "public_candidate",
        }
    lines = ["I found a few matching roles. Which one do you want to apply for?"]
    for idx, role in enumerate(matches, 1):
        lines.append(f"{idx}. {role.get('title') or role.get('position_code')} — {role.get('apply_code')}")
    if pending_media:
        lines.append("\nI received your CV too. Once you choose the role, I’ll attach it to that application.")
    upsert_public_candidate_session(request, roles=matches, pending_media=pending_media, metadata={"source": "role_options", "query": query})
    return {
        "reply": "\n".join(lines),
        "roles": matches,
        "intent": "public_candidate_role_options",
        "turn_focus": "public_candidate",
    }


def handle_candidate_cv_update_request_turn(request: WhatsAppTurnRequest) -> dict[str, Any] | None:
    if has_current_media_upload(request.media or {}):
        return None
    normalized = normalize_text(request.raw_text)
    if not re.search(r"\b(update|change|replace|resend|send another|forgot|add something|new cv|latest cv)\b", normalized):
        return None
    if not re.search(r"\b(cv|resume|file|document)\b", normalized):
        return None
    application = candidate_active_application(request.sender_phone)
    if not application:
        return None
    return {
        "reply": "No problem — please send the updated CV here as a PDF, Word document, image, or clear text. I’ll save the new version to your application and process it again.",
        "application": json_safe(application),
        "intent": "candidate_cv_update_request",
        "turn_focus": "candidate_cv_update",
    }


def handle_candidate_process_faq_turn(request: WhatsAppTurnRequest) -> dict[str, Any] | None:
    if has_current_media_upload(request.media or {}):
        return None
    normalized = normalize_text(request.raw_text)
    application = candidate_active_application(request.sender_phone)
    if not application:
        return None
    if re.search(r"\b(how long|when.*hear|what happens|next step|what now|is that it|anything else|done|finished)\b", normalized):
        return {
            "reply": candidate_missing_or_next_reply(application),
            "application": json_safe(application),
            "intent": "candidate_process_question",
            "turn_focus": "candidate_process",
        }
    return None


def handle_candidate_application_status_turn(request: WhatsAppTurnRequest) -> dict[str, Any] | None:
    if has_current_media_upload(request.media or {}):
        return None
    normalized = normalize_text(request.raw_text)
    if not re.search(r"\b(status|application|where.*application|did you receive|received|missing|cv|resume)\b", normalized):
        return None
    application = candidate_active_application(request.sender_phone)
    if not application:
        return None
    return {
        "reply": candidate_missing_or_next_reply(application),
        "application": json_safe(application),
        "intent": "candidate_application_status",
        "turn_focus": "candidate_status",
    }


def handle_candidate_casual_turn(request: WhatsAppTurnRequest) -> dict[str, Any] | None:
    if has_current_media_upload(request.media or {}):
        return None
    normalized = normalize_text(request.raw_text)
    if normalized in {"hi", "hello", "hey", "salam", "thanks", "thank you", "ok", "okay"}:
        application = candidate_active_application(request.sender_phone)
        if not application:
            return {
                "reply": public_candidate_welcome_reply(request_company_code(request)),
                "application": {},
                "intent": "public_candidate_welcome",
                "turn_focus": "public_candidate",
            }
        next_line = candidate_missing_or_next_reply(application)
        return {
            "reply": f"Hi — {next_line}" if normalized not in {"thanks", "thank you", "ok", "okay"} else f"You're welcome. {next_line}",
            "application": json_safe(application) if application else {},
            "intent": "candidate_casual",
            "turn_focus": "candidate_casual",
        }
    return None


def handle_candidate_safe_fallback_turn(request: WhatsAppTurnRequest) -> dict[str, Any] | None:
    if has_current_media_upload(request.media or {}):
        return None
    if not str(request.raw_text or "").strip():
        return None
    application = candidate_active_application(request.sender_phone)
    if not application:
        return {
            "reply": public_candidate_welcome_reply(request_company_code(request)),
            "application": {},
            "intent": "public_candidate_fallback",
            "turn_focus": "public_candidate",
        }
    return {
        "reply": "I can help with your application status, CV upload/update, quick application questions, and next steps. What would you like to check?",
        "application": json_safe(application),
        "intent": "candidate_safe_fallback",
        "turn_focus": "candidate_fallback",
    }


def active_candidate_screening_application(phone: str | None) -> dict[str, Any] | None:
    target = digits(phone)
    if not target:
        return None
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT a.*, c.name AS candidate_name, c.email AS candidate_email
                FROM applications a
                LEFT JOIN candidates c ON c.phone=a.phone
                WHERE a.phone=%s
                  AND (a.current_step='screening' OR a.screening_status='pending' OR a.raw_json->'screening'->>'status'='pending')
                ORDER BY a.updated_at DESC NULLS LAST, a.ingested_at DESC NULLS LAST
                LIMIT 1
                """,
                (target,),
            )
            row = cur.fetchone()
            return dict(row) if row else None


def screening_questions_from_raw(application: dict[str, Any]) -> list[dict[str, Any]]:
    raw_json = application.get("raw_json") if isinstance(application.get("raw_json"), dict) else {}
    screening = raw_json.get("screening") if isinstance(raw_json.get("screening"), dict) else {}
    questions = screening.get("questions") if isinstance(screening.get("questions"), list) else None
    if questions:
        return [q for q in questions if isinstance(q, dict)]
    return screening_questions_for_application(application)


def parse_screening_reply_answers(text: str, questions: list[dict[str, Any]], pending_keys: list[str]) -> dict[str, str]:
    raw = str(text or "").strip()
    if not raw:
        return {}
    by_index: dict[int, str] = {}
    matches = list(re.finditer(r"(?:^|\n)\s*(\d{1,2})[\).\:-]\s*(.+?)(?=(?:\n\s*\d{1,2}[\).\:-]\s*)|\Z)", raw, re.S))
    for match in matches:
        try:
            idx = int(match.group(1))
        except Exception:
            continue
        value = re.sub(r"\s+", " ", match.group(2)).strip()
        if value:
            by_index[idx] = value
    answers: dict[str, str] = {}
    if by_index:
        for idx, value in by_index.items():
            if 1 <= idx <= len(questions):
                key = str(questions[idx - 1].get("key") or f"q{idx}")
                answers[key] = value
        return answers
    # If the candidate replies naturally, bind to the next missing question.
    if pending_keys:
        answers[pending_keys[0]] = raw
    return answers


def parse_screening_reply_with_gpt(
    text: str,
    *,
    questions: list[dict[str, Any]],
    pending_keys: list[str],
    existing_answers: dict[str, Any],
) -> dict[str, Any] | None:
    provider = planner_provider_config()
    if not provider or not text.strip() or not questions:
        return None
    allowed_keys = [str(q.get("key") or f"q{idx}") for idx, q in enumerate(questions, 1)]
    payload = {
        "candidate_reply": text,
        "questions": [
            {
                "key": str(q.get("key") or f"q{idx}"),
                "question": q.get("question") or q.get("text") or q.get("key"),
                "required": bool(q.get("required")),
            }
            for idx, q in enumerate(questions, 1)
        ],
        "pending_keys": pending_keys,
        "existing_answers": existing_answers,
        "rules": [
            "Return JSON only.",
            "Only use keys from questions.",
            "Extract multiple answers if present, even if out of order.",
            "If the candidate corrects an earlier answer, put it in corrections.",
            "If the candidate asks a question instead of answering, set candidate_question.",
            "Do not infer HR decisions or scores.",
        ],
        "json_schema": {
            "answers": {"question_key": "answer string"},
            "corrections": {"question_key": "corrected answer string"},
            "candidate_question": "string|null",
            "unsupported_request": "string|null",
            "confidence": "number 0..1",
            "reason": "short string",
        },
    }
    system = "You parse candidate screening replies into structured answers for an HR application. Do not invent. Return JSON only."
    if provider.get("api") == "openai-responses":
        body = {
            "model": provider["model"],
            "temperature": 0,
            "input": [
                {"role": "system", "content": system},
                {"role": "user", "content": json.dumps(payload, ensure_ascii=False)},
            ],
        }
    else:
        body = {
            "model": provider["model"],
            "temperature": 0,
            "messages": [
                {"role": "system", "content": system},
                {"role": "user", "content": json.dumps(payload, ensure_ascii=False)},
            ],
        }
    req = urllib.request.Request(
        provider["url"],
        data=json.dumps(body).encode("utf-8"),
        headers={"Authorization": f"Bearer {provider['api_key']}", "Content-Type": "application/json"},
        method="POST",
    )
    try:
        with urllib.request.urlopen(req, timeout=16) as resp:
            parsed = json.loads(resp.read().decode("utf-8", errors="replace"))
    except Exception:
        return None
    result = extract_json_object(extract_model_text(parsed))
    if not isinstance(result, dict):
        return None
    try:
        confidence = float(result.get("confidence") or 0)
    except Exception:
        confidence = 0.0
    answers = result.get("answers") if isinstance(result.get("answers"), dict) else {}
    corrections = result.get("corrections") if isinstance(result.get("corrections"), dict) else {}
    clean_answers = {str(k): str(v).strip() for k, v in answers.items() if str(k) in allowed_keys and str(v).strip()}
    clean_corrections = {str(k): str(v).strip() for k, v in corrections.items() if str(k) in allowed_keys and str(v).strip()}
    if confidence < 0.55 and not clean_answers and not clean_corrections and not result.get("candidate_question"):
        return None
    return {
        "answers": clean_answers,
        "corrections": clean_corrections,
        "candidate_question": str(result.get("candidate_question") or "").strip() or None,
        "unsupported_request": str(result.get("unsupported_request") or "").strip() or None,
        "confidence": confidence,
        "reason": result.get("reason"),
        "parser": "gpt_screening_reply_v1",
    }


def format_next_screening_question(questions: list[dict[str, Any]], pending_keys: list[str]) -> str:
    if not pending_keys:
        return ""
    key = pending_keys[0]
    for question in questions:
        if str(question.get("key") or "") == key:
            return str(question.get("question") or question.get("text") or key)
    return key


def handle_candidate_screening_turn(request: WhatsAppTurnRequest) -> dict[str, Any] | None:
    if has_current_media_upload(request.media or {}):
        return None
    application = active_candidate_screening_application(request.sender_phone)
    if not application:
        return None
    if not company_has_module(application.get("company_code"), "pre_hiring"):
        return {"reply": candidate_safe_module_unavailable_reply(), "application": json_safe(application), "module_disabled": "pre_hiring"}
    raw_json = application.get("raw_json") if isinstance(application.get("raw_json"), dict) else {}
    screening = raw_json.get("screening") if isinstance(raw_json.get("screening"), dict) else {}
    if str(screening.get("status") or application.get("screening_status") or "").lower() in {"complete", "completed"}:
        return None
    questions = screening_questions_from_raw(application)
    existing_answers = screening.get("answers") if isinstance(screening.get("answers"), dict) else {}
    required_keys = [str(q.get("key") or f"q{idx}") for idx, q in enumerate(questions, 1) if q.get("required") is True]
    missing_before = [key for key in required_keys if not str(existing_answers.get(key) or "").strip()]
    if not missing_before:
        return None
    normalized = normalize_text(request.raw_text)
    if normalized in {"hi", "hello", "hey", "salam", "thanks", "thank you", "ok", "okay"}:
        next_question = format_next_screening_question(questions, missing_before)
        return {
            "reply": f"Thanks. Please answer this quick application question:\n\n{next_question}",
            "application": json_safe(application),
            "questions": json_safe(questions),
            "pending_keys": missing_before,
            "intent": "await_screening_answer",
            "turn_focus": "candidate_screening",
        }
    parsed_structured = parse_screening_reply_with_gpt(
        request.raw_text,
        questions=questions,
        pending_keys=missing_before,
        existing_answers=existing_answers,
    )
    parsed_answers: dict[str, str] = {}
    parsed_corrections: dict[str, str] = {}
    parser_name = "deterministic_screening_reply_v1"
    parser_confidence = None
    if parsed_structured:
        parsed_answers = dict(parsed_structured.get("answers") or {})
        parsed_corrections = dict(parsed_structured.get("corrections") or {})
        parser_name = str(parsed_structured.get("parser") or "gpt_screening_reply_v1")
        parser_confidence = parsed_structured.get("confidence")
        if parsed_structured.get("candidate_question") and not parsed_answers and not parsed_corrections:
            next_question = format_next_screening_question(questions, missing_before)
            return {
                "reply": f"I can help with the application process, but I can’t share hiring decisions here.\n\nPlease also answer this quick application question:\n{next_question}",
                "application": json_safe(application),
                "candidate_question": parsed_structured.get("candidate_question"),
                "pending_keys": missing_before,
                "intent": "candidate_screening_question",
                "turn_focus": "candidate_screening",
            }
    if not parsed_answers and not parsed_corrections:
        parsed_answers = parse_screening_reply_answers(request.raw_text, questions, missing_before)
    if not parsed_answers and not parsed_corrections:
        next_question = format_next_screening_question(questions, missing_before)
        return {
            "reply": f"Please answer this quick application question:\n\n{next_question}",
            "application": json_safe(application),
            "questions": json_safe(questions),
            "pending_keys": missing_before,
            "intent": "await_screening_answer",
            "turn_focus": "candidate_screening",
        }
    answers = {**existing_answers, **parsed_answers, **parsed_corrections}
    answer_sources = screening.get("answer_sources") if isinstance(screening.get("answer_sources"), dict) else {}
    answer_evidence = screening.get("answer_evidence") if isinstance(screening.get("answer_evidence"), dict) else {}
    for key, value in {**parsed_answers, **parsed_corrections}.items():
        answer_sources[key] = "candidate_reply"
        answer_evidence[key] = {
            "reply_text": request.raw_text,
            "captured_at": now_iso(),
            "value": value,
            "parser": parser_name,
            "confidence": parser_confidence,
            "correction": key in parsed_corrections,
        }
    missing_after = [key for key in required_keys if not str(answers.get(key) or "").strip()]
    status = "complete" if not missing_after else "pending"
    screening_next = {
        **screening,
        "status": status,
        "answers": answers,
        "answer_sources": answer_sources,
        "answer_evidence": answer_evidence,
        "questions": questions,
        "pending_keys": missing_after,
        "last_answered_at": now_iso(),
        "completed_at": now_iso() if status == "complete" else screening.get("completed_at"),
    }
    raw_next = {**raw_json, "screening": screening_next}
    if status == "complete":
        raw_next["status"] = "screening_complete"
        raw_next["current_step"] = "screening_complete"
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                UPDATE applications
                SET raw_json=%s,
                    screening_status=%s,
                    screening_completed_at=CASE WHEN %s='complete' THEN COALESCE(screening_completed_at, CURRENT_DATE) ELSE screening_completed_at END,
                    status=CASE WHEN %s='complete' THEN 'screening_complete' ELSE status END,
                    current_step=CASE WHEN %s='complete' THEN 'screening_complete' ELSE current_step END,
                    updated_at=COALESCE(updated_at, CURRENT_DATE)
                WHERE app_key=%s
                """,
                (Json(json_safe(raw_next)), status, status, status, status, application.get("app_key")),
            )
        conn.commit()
    if status == "complete":
        reply = "Thanks — I’ve saved your screening answers. Your application is now complete for review."
    else:
        next_question = format_next_screening_question(questions, missing_after)
        reply = f"Thanks, I saved that.\n\nNext question:\n{next_question}"
    return {
        "reply": reply,
        "application": json_safe({**application, "raw_json": raw_next, "screening_status": status, "status": "screening_complete" if status == "complete" else application.get("status")}),
        "captured_answers": json_safe(parsed_answers),
        "captured_corrections": json_safe(parsed_corrections),
        "parser": parser_name,
        "parser_confidence": parser_confidence,
        "pending_keys": missing_after,
        "screening_status": status,
        "intent": "handle_candidate_screening_answer",
        "turn_focus": "candidate_screening",
    }


def non_hr_truth_response(
    *,
    handler_key: str,
    intent: str,
    turn_focus: str,
    result: dict[str, Any],
) -> dict[str, Any]:
    return {
        "authoritative": True,
        "reply": result.get("reply"),
        "handler_key": handler_key,
        "intent": intent,
        "turn_focus": turn_focus,
        "final_reply_source": f"{handler_key}_handler",
        "result": json_safe(result),
        "truth_response": {
            "handler_key": handler_key,
            "intent": intent,
            "turn_focus": turn_focus,
            "has_backend_truth": True,
        },
    }


def handle_non_hr_conversational_turn(request: WhatsAppTurnRequest) -> dict[str, Any] | None:
    ordered_handlers = [
        ("employee_shift_objection", "handle_employee_shift_objection", "employee_shift", handle_employee_shift_objection_turn),
        ("employee_leave", "handle_employee_leave", "employee_leave", handle_employee_leave_turn),
        ("employee_attendance", "handle_employee_attendance", "employee_attendance", handle_employee_attendance_turn),
        ("employee_payroll", "handle_employee_payroll", "employee_payroll", handle_employee_payroll_turn),
        ("employee_shift", "answer_employee_shift_status", "employee_shift", handle_employee_shift_turn),
        ("candidate_assessment", "handle_candidate_assessment", "candidate_assessment", handle_candidate_assessment_turn),
        ("public_candidate_apply_code", "public_candidate_apply_code_started", "public_candidate", handle_public_candidate_apply_code_turn),
        ("public_candidate_selection", "public_candidate_role_selected", "public_candidate", handle_public_candidate_role_selection_turn),
        ("public_candidate_apply", "public_candidate_apply_help", "public_candidate", handle_public_candidate_apply_interest_turn),
        ("candidate_cv_update", "candidate_cv_update_request", "candidate_cv_update", handle_candidate_cv_update_request_turn),
        ("candidate_screening", "handle_candidate_screening_answer", "candidate_screening", handle_candidate_screening_turn),
        ("candidate_status", "candidate_application_status", "candidate_status", handle_candidate_application_status_turn),
        ("candidate_process", "candidate_process_question", "candidate_process", handle_candidate_process_faq_turn),
        ("candidate_truth", "answer_candidate_cv_status", "candidate_cv_status", handle_candidate_truth_turn),
        ("employee_onboarding", "handle_employee_onboarding_reply", "employee_onboarding", handle_employee_onboarding_turn),
        ("candidate_file", "handle_candidate_file", "candidate_file", handle_candidate_file_turn),
        ("candidate_casual", "candidate_casual", "candidate_casual", handle_candidate_casual_turn),
        ("candidate_fallback", "candidate_safe_fallback", "candidate_fallback", handle_candidate_safe_fallback_turn),
    ]
    for handler_key, intent, turn_focus, handler in ordered_handlers:
        result = handler(request)
        if not result:
            continue
        if result.get("reply"):
            if handler_key.startswith("candidate_"):
                guarded = apply_candidate_reply_policy(str(result.get("reply") or ""), request=request, result=result)
                result = {**result, "reply": guarded.get("reply"), "candidate_policy": guarded}
            return non_hr_truth_response(
                handler_key=handler_key,
                intent=str(result.get("intent") or intent),
                turn_focus=str(result.get("turn_focus") or turn_focus),
                result=result,
            )
        if result.get("error") == "module_disabled":
            module = str(result.get("required_module") or handler_key)
            result["reply"] = module_disabled_reply(result.get("company_code"), module)
            return non_hr_truth_response(handler_key=handler_key, intent=intent, turn_focus="module_disabled", result=result)
    return None


def plan_employee_onboarding_reply(
    *,
    employee: dict[str, Any],
    text: str,
    media: dict[str, Any] | None,
    next_item: dict[str, Any] | None,
) -> dict[str, Any] | None:
    system = (
        "You classify employee onboarding replies for Wathefni. "
        "Call classify_employee_onboarding_reply when the reply contains a name, bank/IBAN details, a document/photo indication, or any onboarding item. "
        "Use current_pending_item for ambiguous document/photo media. "
        "For Civil ID, passport, personal photo, medical, or education certificates, text-only messages are not receipts; require current-message media. "
        "Repeated instructions such as 'please send Civil ID, passport, personal photo' are not employee submissions. Do not invent values."
    )
    user_payload = {
        "employee": {
            "employee_key": employee.get("employee_key"),
            "name": employee.get("name"),
            "phone": employee.get("phone"),
            "onboarding_status": employee.get("onboarding_status"),
        },
        "reply_text": text,
        "media": media or {},
        "current_pending_item": next_item or {},
        "valid_items": ["bank_details", "civil_id", "passport", "personal_photo", "medical", "education_cert"],
    }
    call = call_single_tool_agent(system=system, user_payload=user_payload, tools=EMPLOYEE_REPLY_TOOL_DEFINITIONS)
    if not call or call.get("tool") != "classify_employee_onboarding_reply":
        return None
    args = call.get("args") if isinstance(call.get("args"), dict) else {}
    try:
        confidence = float(args.get("confidence", 0))
    except Exception:
        confidence = 0.0
    if confidence < 0.55:
        return None
    reply_type = str(args.get("reply_type") or "unknown")
    item_id = str(args.get("item_id") or "unknown")
    value = str(args.get("value") or text or "").strip()
    if reply_type == "name" and value:
        return {"reply_type": "name", "value": value, "reason": args.get("reason"), "confidence": confidence}
    if reply_type == "onboarding_item" and item_id in {"bank_details", "civil_id", "passport", "personal_photo", "medical", "education_cert"}:
        return {"reply_type": "onboarding_item", "item_id": item_id, "value": value, "reason": args.get("reason"), "confidence": confidence}
    return None


MEDIA_REQUIRED_ONBOARDING_ITEMS = {"civil_id", "passport", "personal_photo", "medical", "education_cert"}
IDENTITY_REQUIRED_ONBOARDING_ITEMS = {"civil_id", "passport"}


def has_current_media_upload(media: dict[str, Any] | None) -> bool:
    if not isinstance(media, dict):
        return False
    media_path = str(media.get("path") or media.get("url") or "").strip()
    media_type = str(media.get("type") or media.get("mime_type") or "").strip().lower()
    return bool(media_path and media_type)


def is_onboarding_instruction_echo(text: str | None) -> bool:
    normalized = normalize_text(text)
    if not normalized:
        return False
    instruction_markers = [
        "confirm your full name",
        "should appear in our records",
        "also please send",
        "please send civil id",
        "please send passport",
        "civil id front and back",
        "passport photo page",
        "personal photo",
    ]
    hits = sum(1 for marker in instruction_markers if marker in normalized)
    return hits >= 2 and ("please send" in normalized or "confirm your full name" in normalized)


def text_has_iban(text: str | None) -> bool:
    compact = re.sub(r"[^a-z0-9]+", "", normalize_text(text))
    return bool(re.search(r"kw\d{2}[a-z0-9]{10,}", compact))


KUWAIT_BANKS = {
    "NBOK": {"canonical": "National Bank of Kuwait", "aliases": ["nbk", "national bank of kuwait", "بنك الكويت الوطني"]},
    "GULB": {"canonical": "Gulf Bank", "aliases": ["gulf bank", "بنك الخليج"]},
    "CBKU": {"canonical": "Commercial Bank of Kuwait", "aliases": ["cbk", "commercial bank of kuwait", "البنك التجاري الكويتي"]},
    "ABKK": {"canonical": "Al Ahli Bank of Kuwait", "aliases": ["abk", "al ahli bank of kuwait", "ahli bank of kuwait", "البنك الاهلي الكويتي", "البنك الأهلي الكويتي"]},
    "BRGN": {"canonical": "Burgan Bank", "aliases": ["burgan", "burgan bank", "بنك برقان"]},
    "AUBK": {"canonical": "Ahli United Bank", "aliases": ["aub", "ahli united bank", "al ahli united bank", "البنك الاهلي المتحد", "البنك الأهلي المتحد"]},
    "KFHU": {"canonical": "Kuwait Finance House", "aliases": ["kfh", "kuwait finance house", "بيت التمويل الكويتي"]},
    "BBYN": {"canonical": "Boubyan Bank", "aliases": ["boubyan", "boubyan bank", "بنك بوبيان"]},
    "KIBK": {"canonical": "Kuwait International Bank", "aliases": ["kib", "kuwait international bank", "بنك الكويت الدولي"]},
    "WARB": {"canonical": "Warba Bank", "aliases": ["warba", "warba bank", "بنك وربة"]},
    "IBKU": {"canonical": "Industrial Bank of Kuwait", "aliases": ["ibk", "industrial bank of kuwait", "بنك الكويت الصناعي"]},
}


def extract_kuwait_iban(text: str | None) -> str | None:
    compact = re.sub(r"[^A-Za-z0-9]+", "", text or "").upper()
    match = re.search(r"KW\d{2}[A-Z]{4}[A-Z0-9]{22}", compact)
    return match.group(0) if match else None


def iban_mod97_valid(iban: str) -> bool:
    rearranged = iban[4:] + iban[:4]
    converted = ""
    for ch in rearranged:
        if ch.isdigit():
            converted += ch
        elif "A" <= ch <= "Z":
            converted += str(ord(ch) - 55)
        else:
            return False
    remainder = 0
    for ch in converted:
        remainder = (remainder * 10 + int(ch)) % 97
    return remainder == 1


def mentioned_kuwait_bank_codes(text: str | None) -> set[str]:
    normalized = normalize_text(text)
    compact = re.sub(r"[^a-z0-9]+", "", normalized)
    codes: set[str] = set()
    for code, info in KUWAIT_BANKS.items():
        if code.lower() in compact:
            codes.add(code)
            continue
        for alias in info["aliases"]:
            alias_norm = normalize_text(alias)
            if alias_norm and alias_norm in normalized:
                codes.add(code)
                break
    return codes


def validate_kuwait_bank_details(text: str | None) -> dict[str, Any]:
    iban = extract_kuwait_iban(text)
    if not iban:
        return {"ok": False, "error": "missing_or_invalid_kuwait_iban_format"}
    bank_code = iban[4:8]
    bank = KUWAIT_BANKS.get(bank_code)
    if not bank:
        return {"ok": False, "error": "unknown_kuwait_bank_code", "iban": iban, "bank_code": bank_code}
    if not iban_mod97_valid(iban):
        return {"ok": False, "error": "invalid_iban_checksum", "iban": iban, "bank_code": bank_code, "bank_name": bank["canonical"]}
    mentioned_codes = mentioned_kuwait_bank_codes(text)
    if not mentioned_codes:
        return {"ok": False, "error": "missing_bank_name", "iban": iban, "bank_code": bank_code, "bank_name": bank["canonical"]}
    if bank_code not in mentioned_codes:
        mentioned_names = [KUWAIT_BANKS[code]["canonical"] for code in sorted(mentioned_codes)]
        return {
            "ok": False,
            "error": "bank_name_mismatch",
            "iban": iban,
            "bank_code": bank_code,
            "bank_name": bank["canonical"],
            "mentioned_banks": mentioned_names,
        }
    return {"ok": True, "iban": iban, "bank_code": bank_code, "bank_name": bank["canonical"]}


def text_has_bank_detail_answer(text: str | None) -> bool:
    normalized = normalize_text(text)
    if text_has_iban(normalized):
        return True
    if is_onboarding_instruction_echo(normalized):
        return False
    return bool(
        re.search(r"\b(bank|iban|account|salary|kfh|nbk|gulf bank|بنك|ايبان|آيبان)\b", normalized)
        and re.search(r"\d", normalized)
    )


def normalized_name_tokens(value: str | None) -> set[str]:
    normalized = normalize_text(value)
    tokens = re.findall(r"[\w\u0600-\u06FF]+", normalized)
    return {token for token in tokens if len(token) >= 3 and not token.isdigit()}


def document_name_match(expected_name: str | None, document_name: str | None) -> dict[str, Any]:
    expected_tokens = normalized_name_tokens(expected_name)
    document_tokens = normalized_name_tokens(document_name)
    expected_compact = " ".join(sorted(expected_tokens))
    document_compact = " ".join(sorted(document_tokens))
    if not expected_tokens or not document_tokens:
        return {
            "status": "unverified",
            "match": False,
            "token_score": 0,
            "sequence_score": 0,
            "reason": "missing_employee_or_document_name",
        }
    overlap = expected_tokens & document_tokens
    token_score = len(overlap) / max(1, len(expected_tokens))
    sequence_score = SequenceMatcher(None, expected_compact, document_compact).ratio()
    matched = token_score >= 0.5 or sequence_score >= 0.72
    if matched:
        status = "matched"
    elif not overlap:
        status = "mismatch"
    else:
        status = "unverified"
    return {
        "status": status,
        "match": matched,
        "expected_name": expected_name,
        "document_name": document_name,
        "overlap_tokens": sorted(overlap),
        "token_score": round(token_score, 3),
        "sequence_score": round(sequence_score, 3),
    }


def media_data_uri(media: dict[str, Any] | None) -> str | None:
    if not isinstance(media, dict):
        return None
    media_path = str(media.get("path") or media.get("local_path") or media.get("source_path") or media.get("url") or "").strip()
    if not media_path or media_path.startswith(("http://", "https://", "data:")):
        return media_path if media_path.startswith("data:") else None
    path = Path(media_path)
    try:
        if not path.exists() or not path.is_file() or path.stat().st_size > 8 * 1024 * 1024:
            return None
        mime_type = str(media.get("type") or media.get("mime_type") or "").strip().lower()
        if "/" not in mime_type:
            mime_type = mimetypes.guess_type(path.name)[0] or "image/jpeg"
        encoded = base64.b64encode(path.read_bytes()).decode("ascii")
        return f"data:{mime_type};base64,{encoded}"
    except Exception:
        return None


def extract_model_text(parsed: dict[str, Any]) -> str:
    output_text = parsed.get("output_text")
    if isinstance(output_text, str) and output_text.strip():
        return output_text
    chunks: list[str] = []
    for item in parsed.get("output") or []:
        for content in item.get("content") or []:
            if isinstance(content, dict):
                text = content.get("text") or content.get("output_text")
                if isinstance(text, str):
                    chunks.append(text)
    if chunks:
        return "\n".join(chunks)
    message = ((parsed.get("choices") or [{}])[0].get("message") or {})
    content = message.get("content")
    return content if isinstance(content, str) else ""


def verify_onboarding_media_item(item_id: str, text: str, media: dict[str, Any] | None) -> dict[str, Any] | None:
    provider = planner_provider_config()
    data_uri = media_data_uri(media)
    if not provider or not data_uri:
        return None
    system = (
        "You verify employee onboarding uploads for Wathefni. "
        "Look at the image/file and decide if it is the expected document item. "
        "Do not trust captions, quoted messages, or screenshots of chat instructions. "
        "If the image is a WhatsApp screenshot, a checklist, or instructions asking for documents, mark it as instruction_screenshot and not a match. "
        "Return JSON only."
    )
    prompt = json.dumps(
        {
            "expected_item": item_id,
            "reply_text": text,
            "allowed_detected_items": [
                "civil_id",
                "passport",
                "personal_photo",
                "medical",
                "education_cert",
                "instruction_screenshot",
                "unknown",
            ],
            "json_schema": {
                "matches_expected_item": "boolean",
                "detected_item": "string",
                "confidence": "number from 0 to 1",
                "reason": "short string",
            },
        },
        ensure_ascii=False,
    )
    if provider.get("api") == "openai-responses":
        body = {
            "model": provider["model"],
            "temperature": 0,
            "input": [
                {"role": "system", "content": system},
                {
                    "role": "user",
                    "content": [
                        {"type": "input_text", "text": prompt},
                        {"type": "input_image", "image_url": data_uri},
                    ],
                },
            ],
        }
    else:
        body = {
            "model": provider["model"],
            "temperature": 0,
            "messages": [
                {"role": "system", "content": system},
                {
                    "role": "user",
                    "content": [
                        {"type": "text", "text": prompt},
                        {"type": "image_url", "image_url": {"url": data_uri}},
                    ],
                },
            ],
        }
    req = urllib.request.Request(
        provider["url"],
        data=json.dumps(body).encode("utf-8"),
        headers={"Authorization": f"Bearer {provider['api_key']}", "Content-Type": "application/json"},
        method="POST",
    )
    try:
        with urllib.request.urlopen(req, timeout=18) as resp:
            parsed = json.loads(resp.read().decode("utf-8", errors="replace"))
    except Exception:
        return None
    result = extract_json_object(extract_model_text(parsed))
