def assessment_link_secret() -> bytes:
    secret = (
        os.environ.get("WATHEFNI_ASSESSMENT_LINK_SECRET")
        or os.environ.get("WATHEFNI_DASHBOARD_TOKEN")
        or os.environ.get("AI_OCTOPUS_DASHBOARD_TOKEN")
        or os.environ.get("DASHBOARD_TOKEN")
        or os.environ.get("WATHEFNI_DATABASE_URL")
        or "wathefni-assessment-dev-secret"
    )
    return str(secret).encode("utf-8")


def video_interview_link_secret() -> bytes:
    secret = (
        os.environ.get("WATHEFNI_VIDEO_INTERVIEW_LINK_SECRET")
        or os.environ.get("WATHEFNI_ASSESSMENT_LINK_SECRET")
        or os.environ.get("WATHEFNI_DASHBOARD_TOKEN")
        or os.environ.get("AI_OCTOPUS_DASHBOARD_TOKEN")
        or os.environ.get("DASHBOARD_TOKEN")
        or os.environ.get("WATHEFNI_DATABASE_URL")
        or "wathefni-video-interview-dev-secret"
    )
    return str(secret).encode("utf-8")


def b64url_encode(value: bytes) -> str:
    return base64.urlsafe_b64encode(value).decode("ascii").rstrip("=")


def b64url_decode(value: str) -> bytes:
    padded = value + ("=" * (-len(value) % 4))
    return base64.urlsafe_b64decode(padded.encode("ascii"))


def sign_assessment_token(attempt_id: str, expires_at: int) -> str:
    payload = f"{attempt_id}:{expires_at}"
    signature = hmac.new(assessment_link_secret(), payload.encode("utf-8"), hashlib.sha256).digest()
    return b64url_encode(f"{payload}:".encode("utf-8") + signature)


def verify_assessment_token(attempt_id: str, token: str | None) -> bool:
    if not token:
        return False
    try:
        decoded = b64url_decode(str(token))
        prefix, signature = decoded[:-32], decoded[-32:]
        payload = prefix.decode("utf-8").rstrip(":")
        token_attempt_id, expires_text = payload.rsplit(":", 1)
        expires_at = int(expires_text)
    except Exception:
        return False
    if str(token_attempt_id) != str(attempt_id) or expires_at < int(time_module.time()):
        return False
    expected = hmac.new(assessment_link_secret(), payload.encode("utf-8"), hashlib.sha256).digest()
    return hmac.compare_digest(signature, expected)


def assessment_public_link(attempt_id: str, *, ttl_days: int = 14) -> str:
    expires_at = int(time_module.time() + max(1, ttl_days) * 24 * 60 * 60)
    token = sign_assessment_token(str(attempt_id), expires_at)
    return f"{assessment_public_base_url()}/assessment/{attempt_id}?token={urllib.parse.quote(token)}"


def sign_video_interview_token(interview_id: str, expires_at: int) -> str:
    payload = f"{interview_id}:{expires_at}"
    signature = hmac.new(video_interview_link_secret(), payload.encode("utf-8"), hashlib.sha256).digest()
    return b64url_encode(f"{payload}:".encode("utf-8") + signature)


def verify_video_interview_token(interview_id: str, token: str | None) -> bool:
    if not token:
        return False
    try:
        decoded = b64url_decode(str(token))
        prefix, signature = decoded[:-32], decoded[-32:]
        payload = prefix.decode("utf-8").rstrip(":")
        token_interview_id, expires_text = payload.rsplit(":", 1)
        expires_at = int(expires_text)
    except Exception:
        return False
    if str(token_interview_id) != str(interview_id) or expires_at < int(time_module.time()):
        return False
    expected = hmac.new(video_interview_link_secret(), payload.encode("utf-8"), hashlib.sha256).digest()
    return hmac.compare_digest(signature, expected)


def video_interview_public_link(interview_id: str, *, ttl_days: int = 14) -> tuple[str, datetime]:
    ttl_seconds = max(1, ttl_days) * 24 * 60 * 60
    expires_at_epoch = int(time_module.time() + ttl_seconds)
    expires_at = datetime.fromtimestamp(expires_at_epoch, tz=timezone.utc)
    token = sign_video_interview_token(str(interview_id), expires_at_epoch)
    return f"{video_interview_public_base_url()}/video-interview/{interview_id}?token={urllib.parse.quote(token)}", expires_at


