def required_module_for_action(action_type: str | None) -> str | None:
    return ACTION_REQUIRED_MODULES.get(str(action_type or ""))


def operational_module_for_action(action_type: str | None) -> str:
    action = str(action_type or "")
    if action == "retry_last_failed_action":
        return "RETRY"
    if action in SHARED_COMMUNICATION_ACTIONS:
        return "COMMUNICATIONS"
    module = required_module_for_action(action)
    if module:
        return module.upper()
    if action.startswith("answer_"):
        return "STATUS"
    if "reminder" in action or "message" in action or "notify" in action:
        return "COMMUNICATION"
    return "OPERATIONS"


def operational_wording_enabled() -> bool:
    return os.environ.get("WATHEFNI_OPERATIONAL_WORDING_ENABLED", "true").strip().lower() not in {"0", "false", "off", "no"}


def walk_operational_values(value: Any, key_path: str = "") -> list[tuple[str, Any]]:
    out: list[tuple[str, Any]] = []
    if isinstance(value, dict):
        for key, item in value.items():
            path = f"{key_path}.{key}" if key_path else str(key)
            out.extend(walk_operational_values(item, path))
    elif isinstance(value, list):
        for idx, item in enumerate(value[:20]):
            out.extend(walk_operational_values(item, f"{key_path}[{idx}]"))
    else:
        out.append((key_path, value))
    return out


def unique_limited(values: list[str], limit: int = 6) -> list[str]:
    seen: set[str] = set()
    out: list[str] = []
    for value in values:
        cleaned = re.sub(r"\s+", " ", str(value or "")).strip()
        key = normalize_text(cleaned)
        if not cleaned or key in seen:
            continue
        seen.add(key)
        out.append(cleaned)
        if len(out) >= limit:
            break
    return out


def operational_fact_bundle(action_type: str, status: str, result_payload: dict[str, Any], template_reply: str) -> dict[str, Any]:
    names: list[str] = []
    dates: list[str] = []
    statuses: list[str] = []
    emails: list[str] = []
    module = operational_module_for_action(action_type)
    for path, value in walk_operational_values(result_payload):
        lower_path = path.lower()
        leaf = re.sub(r"\[\d+\]", "", lower_path).split(".")[-1]
        if any(part in lower_path for part in ("metadata", "raw_json", "source_text", "operational_wording")):
            continue
        if value is None:
            continue
        if isinstance(value, str):
            if leaf in {"name", "employee_name", "candidate_name"} and len(value) <= 120:
                names.append(value)
            if module == "PRE_HIRING" and "email" in lower_path and "@" in value:
                emails.append(value)
            if leaf == "status" and len(value) <= 80 and not lower_path.startswith("employee."):
                statuses.append(value)
            if leaf in {"attendance_date", "shift_date"} and parse_iso_date(value):
                dates.append(value)
            elif lower_path in {"start_date", "end_date", "leave.start_date", "leave.end_date", "attendance.start_date", "attendance.end_date"} and parse_iso_date(value):
                dates.append(value)
        elif isinstance(value, date) and not isinstance(value, datetime):
            if leaf in {"attendance_date", "shift_date", "start_date", "end_date"}:
                dates.append(value.isoformat())
    template_dates = re.findall(r"\b\d{4}-\d{2}-\d{2}\b", template_reply or "")
    dates.extend(template_dates)
    if status:
        statuses.append(status)
    if action_type == "mark_attendance_absent" and isinstance(result_payload, dict) and result_payload.get("error") == "approved_leave_exists":
        statuses.extend(["approved leave", "absent"])
    return {
        "module": module,
        "action_type": action_type,
        "status": status,
        "names": unique_limited(names, limit=5),
        "dates": unique_limited(dates, limit=4),
        "statuses": unique_limited(statuses, limit=5),
        "emails": unique_limited(emails, limit=4),
        "backend_reply": template_reply,
        "grounded_payload": compact_grounded_payload(result_payload),
    }


def compact_grounded_payload(value: Any, *, depth: int = 0) -> Any:
    if depth > 4:
        return None
    if value is None or isinstance(value, (bool, int, float)):
        return value
    if isinstance(value, str):
        text = value.strip()
        return text[:1200] + "..." if len(text) > 1200 else text
    if isinstance(value, list):
        return [compact_grounded_payload(item, depth=depth + 1) for item in value[:8]]
    if isinstance(value, dict):
        out: dict[str, Any] = {}
        for key, item in value.items():
            key_text = str(key)
            lowered = key_text.lower()
            if lowered in {"raw_json", "metadata", "provider_payload", "operational_wording"}:
                continue
            if any(marker in lowered for marker in {"api_key", "token", "secret", "password"}):
                continue
            out[key_text] = compact_grounded_payload(item, depth=depth + 1)
            if len(out) >= 40:
                break
        return out
    return str(value)[:500]


def normalized_for_verify(value: str | None) -> str:
    return re.sub(r"\s+", " ", re.sub(r"[^a-z0-9@\u0600-\u06ff]+", " ", normalize_text(value))).strip()


def date_fact_variants(value: str) -> list[str]:
    parsed = parse_iso_date(value)
    if parsed:
        return unique_limited([
            value,
            format_shift_date(parsed),
            f"{parsed.day} {parsed.strftime('%B %Y')}",
            f"{parsed.day} {parsed.strftime('%b %Y')}",
        ], limit=6)
    return [value]


def reply_contains_any(reply: str, variants: list[str]) -> bool:
    normalized_reply = normalized_for_verify(reply)
    for variant in variants:
        normalized_variant = normalized_for_verify(variant)
        if normalized_variant and normalized_variant in normalized_reply:
            return True
    return False


def verify_operational_wording(reply: str, facts: dict[str, Any]) -> tuple[bool, str]:
    text = str(reply or "").strip()
    if not text or len(text) > 2800:
        return False, "empty_or_too_long"
    action_type = str(facts.get("action_type") or "")
    for name in facts.get("names") if isinstance(facts.get("names"), list) else []:
        if not reply_contains_any(text, [str(name)]):
            return False, f"missing_name:{name}"
    for date_value in facts.get("dates") if isinstance(facts.get("dates"), list) else []:
        if not reply_contains_any(text, date_fact_variants(str(date_value))):
            return False, f"missing_date:{date_value}"
    if action_type == "mark_attendance_absent" and "approved_leave" in normalized_for_verify(json.dumps(facts, ensure_ascii=False)).replace(" ", "_"):
        if not reply_contains_any(text, ["approved leave", "approved sick leave"]):
            return False, "missing_approved_leave"
        if not reply_contains_any(text, ["absent", "mark them absent", "mark him absent"]):
            return False, "missing_absent_action"
    allowed_emails = {normalize_text(item) for item in (facts.get("emails") if isinstance(facts.get("emails"), list) else [])}
    for email in re.findall(r"[\w.+-]+@[\w.-]+\.[a-zA-Z]{2,}", text):
        if normalize_text(email) not in allowed_emails:
            return False, "unexpected_email"
    if action_type not in {"answer_candidate_email_lookup", "prepare_candidate_email", "schedule_candidate_meeting", "send_email", "notify_candidate", "send_assessment", "schedule_interview", "rank_candidates"}:
        stale_markers = ["full stack", "candidate with that email", "azizalmulla16@gmail.com"]
        lowered = normalize_text(text)
        if any(marker in lowered for marker in stale_markers):
            return False, "stale_candidate_context"
    return True, "ok"


def extract_text_from_llm_response(parsed: dict[str, Any], provider: dict[str, str]) -> str:
    if provider.get("api") == "openai-responses":
        output_text = parsed.get("output_text")
        if isinstance(output_text, str) and output_text.strip():
            return output_text.strip()
        parts: list[str] = []
        for item in parsed.get("output") or []:
            for content in item.get("content") or []:
                if isinstance(content, dict) and content.get("type") in {"output_text", "text"}:
                    text = content.get("text")
                    if isinstance(text, str):
                        parts.append(text)
        return "\n".join(parts).strip()
    return str((((parsed.get("choices") or [{}])[0].get("message") or {}).get("content") or "")).strip()


def recent_assistant_replies(turn_id: str | None, limit: int = 3) -> list[str]:
    if not turn_id:
        return []
    try:
        with db_connect() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """
                    SELECT ar.final_reply
                    FROM action_results ar
                    JOIN hr_turns current_turn ON current_turn.turn_id=%s
                    JOIN hr_turns turn ON turn.turn_id=ar.turn_id
                    WHERE ar.final_reply IS NOT NULL
                      AND btrim(ar.final_reply) <> ''
                      AND turn.sender_phone=current_turn.sender_phone
                      AND (current_turn.account_id IS NULL OR turn.account_id=current_turn.account_id)
                      AND (current_turn.conversation_id IS NULL OR turn.conversation_id=current_turn.conversation_id)
                      AND ar.turn_id <> %s
                    ORDER BY ar.created_at DESC
                    LIMIT %s
                    """,
                    (turn_id, turn_id, max(1, min(limit, 5))),
                )
                return [str(row["final_reply"]) for row in cur.fetchall() if row.get("final_reply")]
    except Exception:
        return []


def call_operational_wording_llm(*, user_text: str, facts: dict[str, Any], turn_id: str | None = None, timeout: int = 8) -> str | None:
    provider = planner_provider_config()
    if not provider:
        return None
    system = openclaw_augmented_system_prompt(OPERATIONAL_WORDING_BASE_SYSTEM, prompt_name="style_layer", context_mode="concise")
    requested_language = detect_user_language(user_text)
    payload = {
        "current_user_message": user_text,
        "requested_language": language_label(requested_language),
        "recent_assistant_replies": recent_assistant_replies(turn_id),
        "structured_facts": facts,
        "backend_reply": facts.get("backend_reply"),
        "grounded_payload": facts.get("grounded_payload"),
        "style": "warm operator, professional but not stiff, Kuwaiti-friendly when natural, concise but not robotic",
    }
    if provider.get("api") == "openai-responses":
        body = {
            "model": provider["model"],
            "temperature": 0.2,
            "input": [
                {"role": "system", "content": system},
                {"role": "user", "content": json.dumps(payload, ensure_ascii=False)},
            ],
        }
    else:
        body = {
            "model": provider["model"],
            "temperature": 0.2,
            "messages": [
                {"role": "system", "content": system},
                {"role": "user", "content": json.dumps(payload, ensure_ascii=False)},
            ],
        }
    req = urllib.request.Request(
        provider["url"],
        data=json.dumps(body).encode("utf-8"),
        headers={"Authorization": f"Bearer {provider['api_key']}", "Content-Type": "application/json"},
        method="POST",
    )
    start = time_module.monotonic()
    estimated_tokens = estimate_tokens_from_payload(body)
    prompt_hash = stable_text_hash(system)
    try:
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            parsed = json.loads(resp.read().decode("utf-8", errors="replace"))
    except Exception as exc:
        record_llm_call(
            turn_id=turn_id,
            call_name="style_layer",
            provider=provider,
            prompt_mode="concise",
            prompt_docs_loaded=True,
            prompt_hash=prompt_hash,
            estimated_input_tokens=estimated_tokens,
            latency_ms=int((time_module.monotonic() - start) * 1000),
            status="error",
            error=str(exc),
            metadata={"action_type": facts.get("action_type"), "status": facts.get("status")},
        )
        return None
    record_llm_call(
        turn_id=turn_id,
        call_name="style_layer",
        provider=provider,
        prompt_mode="concise",
        prompt_docs_loaded=True,
        prompt_hash=prompt_hash,
        estimated_input_tokens=estimated_tokens,
        latency_ms=int((time_module.monotonic() - start) * 1000),
        status="ok",
        parsed=parsed,
        metadata={"action_type": facts.get("action_type"), "status": facts.get("status")},
    )
    return extract_text_from_llm_response(parsed, provider) or None


def compose_operational_reply(
    *,
    action_type: str,
    status: str,
    result_payload: dict[str, Any],
    template_reply: str,
    user_text: str | None,
    turn_id: str | None = None,
) -> tuple[str, dict[str, Any]]:
    facts = operational_fact_bundle(action_type, status, result_payload, template_reply)
    if not operational_wording_enabled():
        return template_reply, {"enabled": False, "used": False, "facts": facts}
    candidate = call_operational_wording_llm(user_text=user_text or "", facts=facts, turn_id=turn_id)
    if not candidate:
        return template_reply, {"enabled": True, "used": False, "reason": "llm_unavailable", "facts": facts}
    ok, reason = verify_operational_wording(candidate, facts)
    if not ok:
        return template_reply, {"enabled": True, "used": False, "reason": reason, "candidate_reply": candidate, "facts": facts}
    return candidate, {"enabled": True, "used": True, "reason": "verified", "facts": facts}


def wathefni_style_context(action_type: str | None) -> str:
    action = str(action_type or "")
    if action in {"candidate_cv_evaluation", "rank_candidates"}:
        return "candidate_cv_evaluation"
    if action == "compare_candidates":
        return "candidate_comparison"
    if action == "workforce_analytics":
        return "workforce_analytics"
    if action == "check_assessment_config":
        return "assessment_config"
    return "general"


def friendly_success_correction_reply(action_type: str, target: str | None) -> str:
    name = target or "the target"
    action = str(action_type or "")
    if action == "send_email":
        return f"Actually, the email was sent successfully to {name}."
    if action in {"notify_candidate", "send_assessment", "send_custom_employee_message", "send_onboarding_reminder"}:
        return f"Actually, the message was sent successfully to {name}."
    if action in {"approve_leave_request", "reject_leave_request", "approve_shift_swap", "reject_shift_swap"}:
        return f"Actually, that decision was completed successfully for {name}."
    if action == "export_payroll":
        return "Actually, the payroll export completed successfully."
    return f"Actually, the {action.replace('_', ' ') or 'action'} completed successfully for {name}."


def greeting_reply_for_text(text: str | None) -> str:
    return ""


def safe_fallback_reply(kind: str) -> str:
    if kind == "operational":
        return "I don’t want to guess on that. I need to check the action history before I make any claim about sending, failing, or completing an action."
    if kind == "domain":
        return "I should answer that from Wathefni’s stored records, not old chat context. Ask me to show, rank, or compare the relevant records and I’ll use the backend data."
    if kind == "neutral_help":
        return "Please send a specific HR request so Wathefni can route it through the right grounded workflow."
    return "Please send a specific HR request."


def style_backend_reply(
    state: GraphState,
    *,
    action_type: str,
    status: str,
    template_reply: str,
    result_payload: dict[str, Any] | None = None,
) -> tuple[str, dict[str, Any]]:
    return render_grounded_reply(
        action_type=action_type,
        status=status,
        result_payload=result_payload or {"reply": template_reply},
        template_reply=template_reply,
        user_text=state["request"].raw_text,
        turn_id=state.get("turn_id"),
    )


EXACT_TEMPLATE_ACTIONS = {
    "answer_action_history_followup",
    "answer_sent_message_history",
}


def should_use_grounded_template_only(action_type: str | None, status: str | None) -> bool:
    action = str(action_type or "")
    if action in EXACT_TEMPLATE_ACTIONS:
        return True
    return False


def render_grounded_reply(
    *,
    action_type: str,
    status: str,
    result_payload: dict[str, Any],
    template_reply: str,
    user_text: str | None,
    turn_id: str | None = None,
) -> tuple[str, dict[str, Any]]:
    if should_use_grounded_template_only(action_type, status):
        return template_reply, {
            "mode": "grounded_template",
            "used": False,
            "reason": "exact_template_required",
            "action_type": action_type,
            "status": status,
        }
    reply, wording = compose_operational_reply(
        action_type=action_type,
        status=status,
        result_payload=result_payload,
        template_reply=template_reply,
        user_text=user_text,
        turn_id=turn_id,
    )
    return reply, {"mode": "operational_wording", **json_safe(wording)}


def check_assessment_config(company_code: str | None) -> dict[str, Any]:
    company = (company_code or "WATHEFNI").upper()
    payload = dashboard_assessment_config_payload(company)
    battery = payload.get("battery") if isinstance(payload.get("battery"), dict) else {}
    item_bank = payload.get("item_bank") if isinstance(payload.get("item_bank"), dict) else {}
    role_profiles = payload.get("role_profiles") if isinstance(payload.get("role_profiles"), dict) else {}
    validation = payload.get("validation") if isinstance(payload.get("validation"), dict) else {}
    return {
        "ok": True,
        "company_code": company,
        "battery": battery,
        "item_bank": item_bank,
        "role_profiles": role_profiles,
        "validation": validation,
        "config": payload,
    }


def format_check_assessment_config_reply(result: dict[str, Any]) -> str:
    battery = result.get("battery") if isinstance(result.get("battery"), dict) else {}
    item_bank = result.get("item_bank") if isinstance(result.get("item_bank"), dict) else {}
    role_profiles = result.get("role_profiles") if isinstance(result.get("role_profiles"), dict) else {}
    validation = result.get("validation") if isinstance(result.get("validation"), dict) else item_bank.get("validation") if isinstance(item_bank.get("validation"), dict) else {}
    role_labels = []
    for key, profile in list(role_profiles.items())[:6]:
        if isinstance(profile, dict):
            role_labels.append(str(profile.get("label") or key))
    return (
        "Yes. The live assessment config is present.\n"
        f"- Battery: {battery.get('name') or battery.get('battery_key') or 'Wathefni assessment battery'}\n"
        f"- Item bank: {item_bank.get('item_count') or item_bank.get('total_items') or 0} items\n"
        f"- Role profiles: {len(role_profiles)} configured"
        + (f" ({', '.join(role_labels)})" if role_labels else "")
        + f"\n- Validation: {'ok' if validation.get('ok', True) else 'needs review'}"
    )


def action_result_channel(action_type: str | None, action: dict[str, Any] | None, payload: dict[str, Any] | None) -> str:
    action_type = str(action_type or "")
    action = action or {}
    payload = payload or {}
    if action.get("channel"):
        return str(action.get("channel"))
    if action_type == "send_email" or payload.get("gmail"):
        return "email"
    if action_type in {"notify_candidate", "send_assessment", "send_custom_employee_message", "send_onboarding_reminder", "retry_last_employee_message"} or payload.get("send"):
        return "whatsapp"
    if action_type in PAYROLL_ACTIONS or action_type in {"set_payroll_policy", "preview_payroll", "list_payroll_hours", "create_timesheet_review"}:
        return "payroll"
    if action_type in LEAVE_ACTIONS or action_type in {"request_leave", "list_leave_requests"}:
        return "leave"
    if action_type in SHIFT_ACTIONS or action_type in {"create_shift_assignment", "cancel_shift_assignment", "list_shifts"}:
        return "shifts"
    if action_type in CANDIDATE_ACTIONS:
        return "pre_hiring"
    if action_type in EMPLOYEE_ACTIONS:
        return "employee"
    return operational_module_for_action(action_type).lower()


def action_result_target(action_type: str | None, action: dict[str, Any] | None, payload: dict[str, Any] | None) -> tuple[str | None, str | None, str | None]:
    action_type = str(action_type or "")
    action = action or {}
    payload = payload or {}
    candidate = payload.get("candidate") if isinstance(payload.get("candidate"), dict) else {}
    application = payload.get("application") if isinstance(payload.get("application"), dict) else {}
    selected = payload.get("selected_application") if isinstance(payload.get("selected_application"), dict) else {}
    employee = payload.get("employee") if isinstance(payload.get("employee"), dict) else {}
    leave = payload.get("leave") if isinstance(payload.get("leave"), dict) else {}
    shift = payload.get("shift") if isinstance(payload.get("shift"), dict) else {}
    timesheet = payload.get("timesheet") if isinstance(payload.get("timesheet"), dict) else {}

    target_type = action_focus_type(action_type)
    target_id = (
        action.get("app_key")
        or application.get("app_key")
        or selected.get("app_key")
        or action.get("subject_key")
        or employee.get("employee_key")
        or action.get("leave_id")
        or leave.get("leave_id")
        or action.get("shift_id")
        or shift.get("shift_id")
        or action.get("timesheet_id")
        or timesheet.get("timesheet_id")
    )
    target_name = (
        action.get("target_name")
        or candidate.get("name")
        or application.get("candidate_name")
        or selected.get("candidate_name")
        or employee.get("name")
        or leave.get("employee_name")
        or shift.get("employee_name")
        or timesheet.get("employee_name")
        or action.get("subject_name")
    )
    if not target_type:
        if candidate or application or selected or action.get("app_key"):
            target_type = "candidate"
        elif employee or action.get("subject_key"):
            target_type = "employee"
        elif leave or action.get("leave_id"):
            target_type = "leave_request"
        elif shift or action.get("shift_id"):
            target_type = "shift"
        elif timesheet or action.get("timesheet_id"):
            target_type = "timesheet"
    if not target_id and candidate:
        target_id = candidate.get("phone") or candidate.get("email")
    return (str(target_type) if target_type else None, str(target_id) if target_id else None, str(target_name) if target_name else None)


def action_result_error_code(status: str | None, payload: dict[str, Any] | None) -> str | None:
    payload = payload or {}
    for key in ("error_code", "error", "reason"):
        if payload.get(key):
            return str(payload.get(key))
    send = payload.get("send") if isinstance(payload.get("send"), dict) else {}
    if send.get("error"):
        return str(send.get("error"))
    gmail = payload.get("gmail") if isinstance(payload.get("gmail"), dict) else {}
    gmail_text = f"{gmail.get('stderr') or ''}\n{gmail.get('stdout') or ''}".lower()
    if "neither $xdg_config_home nor $home are defined" in gmail_text:
        return "gmail_config_home_missing"
    if "reauth" in gmail_text or "re-auth" in gmail_text or "authorization" in gmail_text or "token" in gmail_text:
        return "gmail_auth_required"
    if gmail and not gmail.get("ok", False):
        return "gmail_send_failed"
    if status and status not in {"completed", "ok"}:
        return str(status)
    return None


def action_result_debug_detail(error_code: str | None, payload: dict[str, Any] | None) -> str | None:
    payload = payload or {}
    gmail = payload.get("gmail") if isinstance(payload.get("gmail"), dict) else {}
    if gmail:
        detail = str(gmail.get("stderr") or gmail.get("stdout") or "").strip()
        if detail:
            return detail[:1000]
    send = payload.get("send") if isinstance(payload.get("send"), dict) else {}
    if send:
        detail = str(send.get("message") or send.get("detail") or send.get("error") or "").strip()
        if detail:
            return detail[:1000]
    for key in ("debug_detail", "message", "error_message", "reason", "error"):
        if payload.get(key):
            return str(payload.get(key))[:1000]
    return error_code


def action_result_retryable(error_code: str | None, action_type: str | None) -> bool:
    if error_code in {"missing_candidate_email", "candidate_not_found", "employee_not_found", "ambiguous_candidate", "module_disabled", "needs_backend_tool"}:
        return False
    if error_code in {"gmail_auth_required", "gmail_config_home_missing", "gmail_send_failed", "conversation_closed", "conversation_inactive", "no_usable_conversation_id"}:
        return True
    return str(action_type or "") in {"send_email", "notify_candidate", "send_assessment", "send_custom_employee_message", "send_onboarding_reminder"}


def action_result_safe_message(
    *,
    action_type: str,
    status: str,
    target_name: str | None,
    error_code: str | None,
    template_reply: str,
) -> str:
    name = target_name or "the target"
    if status == "completed" and not error_code:
        return template_reply or f"{action_type.replace('_', ' ').title()} completed."
    if error_code == "gmail_config_home_missing":
        return f"The email did not send because the Gmail sender cannot find its Google config in the server environment. {name} was resolved correctly; the blocker is backend email configuration."
    if error_code == "gmail_auth_required" or error_code == "invalid_grant":
        return f"I couldn't send the message to {name}. Email needs reconnecting."
    if error_code == "gmail_send_failed":
        return f"The email did not send because the Gmail sender returned an error. {name} was resolved correctly."
    if error_code == "missing_candidate_email":
        return f"I found {name}, but the candidate has no email address."
    if error_code in {"missing_candidate_contact", "missing_candidate_phone", "missing_candidate_conversation_id"}:
        return f"I found {name}, but the candidate has no phone number."
    if error_code in {"conversation_closed", "conversation_inactive"}:
        return f"I couldn't send the WhatsApp message to {name}. WhatsApp conversation is not active."
    if error_code == "no_usable_conversation_id":
        return f"I couldn't send the WhatsApp message to {name}. WhatsApp conversation is not active."
    if error_code == "candidate_not_found":
        return "I could not find the candidate for that action."
    if error_code == "employee_not_found":
        return "I could not find the employee for that action."
    if error_code == "module_disabled":
        return template_reply or "That module is not enabled for this company."
    if status in {"needs_clarification", "needs_details"}:
        return template_reply
    if error_code:
        return template_reply or "The action did not complete. Please check the candidate details and try again."
    return template_reply or "The action did not complete. Please try again."


def normalize_action_result(
    *,
    action_type: str,
    status: str,
    action: dict[str, Any] | None,
    result_payload: dict[str, Any] | None,
    template_reply: str,
) -> dict[str, Any]:
    raw_payload = json_safe(result_payload or {})
    target_type, target_id, target_name = action_result_target(action_type, action, raw_payload)
    error_code = action_result_error_code(status, raw_payload)
    raw_ok = raw_payload.get("ok") if isinstance(raw_payload, dict) else None
    return {
        "ok": bool(status == "completed" and raw_ok is not False and not error_code),
        "action_type": action_type,
        "channel": action_result_channel(action_type, action, raw_payload),
        "target_type": target_type,
        "target_id": target_id,
        "target_name": target_name,
        "error_code": error_code,
        "safe_user_message": action_result_safe_message(
            action_type=action_type,
            status=status,
            target_name=target_name,
            error_code=error_code,
            template_reply=template_reply,
        ),
        "debug_detail": action_result_debug_detail(error_code, raw_payload),
        "retryable": action_result_retryable(error_code, action_type) if status != "completed" else False,
        "payload": raw_payload,
    }


def normalized_result_payload(
    *,
    action_type: str,
    status: str,
    action: dict[str, Any] | None,
    result_payload: dict[str, Any] | None,
    template_reply: str,
) -> dict[str, Any]:
    raw_payload = json_safe(result_payload or {})
    normalized = normalize_action_result(
        action_type=action_type,
        status=status,
        action=action,
        result_payload=raw_payload,
        template_reply=template_reply,
    )
    return {**raw_payload, **normalized, "normalized_action_result": normalized}


def normalized_action_result_from_row(row: dict[str, Any]) -> dict[str, Any]:
    payload = row.get("result") if isinstance(row.get("result"), dict) else {}
    normalized = payload.get("normalized_action_result") if isinstance(payload.get("normalized_action_result"), dict) else None
    if normalized:
        return normalized
    action = payload.get("action") if isinstance(payload.get("action"), dict) else {}
    return normalize_action_result(
        action_type=str(row.get("action_type") or payload.get("action_type") or "action"),
        status=str(row.get("status") or "failed"),
        action=action,
        result_payload=payload,
        template_reply=str(row.get("final_reply") or ""),
    )


def normalized_action_result_from_failed_context(failed: dict[str, Any]) -> dict[str, Any]:
    payload = failed.get("payload") if isinstance(failed.get("payload"), dict) else {}
    result_payload = payload.get("result") if isinstance(payload.get("result"), dict) else {}
    normalized = payload.get("normalized_action_result") if isinstance(payload.get("normalized_action_result"), dict) else None
    if not normalized and isinstance(result_payload.get("normalized_action_result"), dict):
        normalized = result_payload.get("normalized_action_result")
    if normalized:
        return normalized
    action = payload.get("action") if isinstance(payload.get("action"), dict) else {}
    synthesized = {
        "ok": False,
        "action_type": str(failed.get("action_type") or action.get("action_type") or "action"),
        "channel": failed.get("channel") or action_result_channel(failed.get("action_type"), action, result_payload),
        "target_type": failed.get("target_type"),
        "target_id": failed.get("target_id"),
        "target_name": failed.get("target_name"),
        "error_code": failed.get("error_code"),
        "safe_user_message": failed.get("safe_user_message") or failed.get("error_message") or "",
        "debug_detail": failed.get("error_message") or action_result_debug_detail(failed.get("error_code"), result_payload),
        "retryable": bool(failed.get("retryable")),
        "payload": json_safe(result_payload),
    }
    if not synthesized["safe_user_message"]:
        synthesized["safe_user_message"] = action_result_safe_message(
            action_type=synthesized["action_type"],
            status=str(failed.get("status") or "failed"),
            target_name=synthesized.get("target_name"),
            error_code=synthesized.get("error_code"),
            template_reply="",
        )
    return synthesized


def action_failure_explanation_from_normalized(result: dict[str, Any]) -> str:
    action_type = str(result.get("action_type") or "action").replace("_", " ")
    target = str(result.get("target_name") or "that target")
    safe = str(result.get("safe_user_message") or "").strip()
    error_code = str(result.get("error_code") or "").strip()
    if result.get("ok"):
        return f"It did not fail. The latest {action_type} for {target} completed."
    if safe:
        suffix = f" Error code: {error_code}." if error_code else ""
        return f"It failed because: {safe}{suffix}"
    if error_code:
        return f"It failed because the backend returned `{error_code}` for the latest {action_type}."
    return f"The latest {action_type} failed, but the backend did not return a specific error code."


def enforce_operational_reply_invariants(reply: str, result_payload: dict[str, Any]) -> str:
    normalized = result_payload.get("normalized_action_result") if isinstance(result_payload.get("normalized_action_result"), dict) else result_payload
    action_type_raw = str(normalized.get("action_type") or "")
    if action_invariant_class(action_type_raw) == "read_only":
        return reply
    ok = bool(normalized.get("ok"))
    error_code = normalized.get("error_code")
    safe = str(normalized.get("safe_user_message") or "").strip()
    lowered = normalize_text(reply)
    success_claim = bool(re.search(r"\b(done|completed|sent|emailed|delivered|notified|approved|rejected|hired|shortlisted|exported)\b", lowered))
    failure_claim = bool(
        re.search(
            r"\b(failed|failed to send|couldn'?t send|could not send|couldn'?t email|could not email|did not send|didn'?t send|"
            r"did not email|didn'?t email|wasn'?t delivered|was not delivered|not delivered|not sent|no message went out|"
            r"did not complete|didn'?t complete|not completed)\b",
            lowered,
        )
    )
    if success_claim and not ok:
        return safe or f"The action did not complete. Backend error: {error_code or 'unknown'}."
    if failure_claim and ok:
        target = normalized.get("target_name") or "the target"
        return friendly_success_correction_reply(action_type_raw, str(target))
    if failure_claim and not ok and not (error_code or safe):
        return "The action did not complete, but the backend did not return a specific error code."
    return reply


def direct_action_result_state(
    state: GraphState,
    *,
    action_type: str,
    status: str,
    reply: str,
    result_payload: dict[str, Any],
) -> GraphState:
    action = state.get("direct_action") or {"action_type": action_type}
    action_for_context = {**dict(action), "turn_id": state.get("turn_id")}
    result_payload = normalized_result_payload(
        action_type=action_type,
        status=status,
        action=action_for_context,
        result_payload=result_payload,
        template_reply=reply,
    )
    reply, wording = render_grounded_reply(
        action_type=action_type,
        status=status,
        result_payload=result_payload,
        template_reply=str(result_payload.get("safe_user_message") or reply),
        user_text=state["request"].raw_text,
        turn_id=state.get("turn_id"),
    )
    reply = enforce_operational_reply_invariants(reply, result_payload)
    result_payload = {**result_payload, "operational_wording": json_safe(wording)}
    actor = actor_context_from_payload(result_payload)
    if not actor.get("company_code"):
        request_company = request_company_code(state["request"])
        actor = actor_context_for_hr_user(
            {"phone": digits(state["request"].sender_phone), "role": state["request"].sender_role or "hr_admin", "company_code": request_company},
            company_code=request_company or "",
            hr_phone=state["request"].sender_phone,
        )
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                UPDATE hr_turns
                SET intent=%s, turn_focus=%s, final_reply_source=%s
                WHERE turn_id=%s
                """,
                (action_type, "action_execution", "direct_action_result", state["turn_id"]),
            )
            cur.execute(
                """
                INSERT INTO action_results
                (turn_id, action_id, action_type, status, result, final_reply,
                 company_code, actor_user_id, actor_email, actor_phone, actor_role)
                VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)
                """,
                (
                    state["turn_id"],
                    None,
                    action_type,
                    status,
                    Json(json_safe(result_payload)),
                    reply,
                    actor.get("company_code"),
                    actor.get("actor_user_id"),
                    actor.get("actor_email"),
                    actor.get("actor_phone"),
                    actor.get("actor_role"),
                ),
            )
        conn.commit()
    persistent_context = operational_context_from_action_result(
        state.get("persistent_context"),
        action_type=action_type,
        status=status,
        action=action_for_context,
        result_payload=result_payload,
    )
    turn_scratch = {
        **(state.get("turn_scratch") or {}),
        "tool_result": {"ok": status == "completed", "result": json_safe(result_payload), "error": None if status == "completed" else status},
        "reply_text": reply,
    }
    return {**state, "persistent_context": persistent_context, "turn_scratch": turn_scratch, "authoritative": True, "reply_text": reply, "final_reply_source": "direct_action_result"}


def approve_pending_action(state: GraphState) -> GraphState:
    action = state.get("pending_action")
    if not action:
        return {**state, "authoritative": False, "final_reply_source": "llm_fallback"}
    company_code = request_company_code(state["request"])
    action = action_with_resolved_entities(
        {**expand_pending_action(dict(action)), "company_code": company_code},
        state.get("turn_scratch"),
    )
    action_type = action["action_type"]
    result_payload: dict[str, Any] = {}
    actor = actor_context_for_hr_user(
        {"phone": digits(state["request"].sender_phone), "role": state["request"].sender_role or "hr_admin", "company_code": company_code},
        company_code=company_code or "",
        hr_phone=state["request"].sender_phone,
    )
    required_module = required_module_for_action(action_type)
    if required_module and not company_has_module(company_code, required_module):
        reply = module_disabled_reply(company_code, required_module)
        action_for_context = {**dict(action), "turn_id": state.get("turn_id")}
        result_payload = normalized_result_payload(
            action_type=action_type,
            status="module_disabled",
            action=action_for_context,
            result_payload={
                "reason": "module_disabled",
                "company_code": company_code,
                "required_module": required_module,
                "enabled_modules": sorted(configured_company_modules(company_code)),
                "action": json_safe(action),
            },
            template_reply=reply,
        )
        with db_connect() as conn:
            with conn.cursor() as cur:
                cur.execute("UPDATE pending_actions SET status='rejected', resolved_at=now() WHERE action_id=%s", (action["action_id"],))
                cur.execute(
                    """
                    INSERT INTO action_results
                    (turn_id, action_id, action_type, status, result, final_reply,
                     company_code, actor_user_id, actor_email, actor_phone, actor_role)
                    VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)
                    """,
                    (
                        state["turn_id"],
                        action["action_id"],
                        action_type,
                        "module_disabled",
                        Json(json_safe(result_payload)),
                        reply,
                        actor.get("company_code"),
                        actor.get("actor_user_id"),
                        actor.get("actor_email"),
                        actor.get("actor_phone"),
                        actor.get("actor_role"),
                    ),
                )
            conn.commit()
        persistent_context = operational_context_from_action_result(
            state.get("persistent_context"),
            action_type=action_type,
            status="module_disabled",
            action=action_for_context,
            result_payload=result_payload,
        )
        turn_scratch = {**(state.get("turn_scratch") or {}), "tool_result": {"ok": False, "error": "module_disabled"}, "reply_text": reply}
        return {**state, "persistent_context": persistent_context, "turn_scratch": turn_scratch, "authoritative": True, "reply_text": reply, "final_reply_source": "pending_action_module_disabled"}

    if action_type == "start_onboarding":
        employee = resolve_employee_for_direct_action(action, allow_latest=False)
        if not employee:
            reply = "I could not find the employee to start onboarding."
            status = "failed"
        else:
            start_onboarding(employee)
            refreshed_employee = find_employee_by_phone(employee.get("phone"), company_code=employee.get("company_code")) or employee
            employee_notification = notify_employee_onboarding_started(refreshed_employee, state["request"].account_id)
            sheet_sync = sync_employee_posthire(refreshed_employee.get("phone") or "", refreshed_employee.get("company_code"))
            if employee_notification.get("ok"):
                reply = f"Onboarding started for {refreshed_employee.get('name') or 'the employee'} and they were notified."
            else:
                reply = f"Onboarding started for {refreshed_employee.get('name') or 'the employee'}, but I could not notify them immediately."
            status = "completed"
            result_payload = {"employee": json_safe(refreshed_employee), "employee_notification": employee_notification, "sheet_sync": sheet_sync}
    elif action_type == "hire_candidate":
        app = resolve_application_for_action(action, allow_latest=False)
        if not app:
            reply = "I could not find the candidate to hire."
            status = "failed"
        else:
            update_result = update_application_status(app, "hired")
            posthire_result = transition_hire(app)
            ok = bool(update_result.get("ok") and posthire_result.get("ok"))
            status = "completed" if ok else "failed"
            name = app.get("candidate_name") or action.get("subject_name") or "the candidate"
            reply = f"{name} is hired and employee setup is done." if ok else f"I could not complete hiring for {name}."
            result_payload = {"application": json_safe(app), "update": update_result, "posthire": posthire_result}
    elif action_type == "shortlist_candidate":
        app = resolve_application_for_action(action, allow_latest=False)
        if not app:
            reply = "I could not find the candidate to shortlist."
            status = "failed"
        else:
            update_result = update_application_status(app, "shortlisted")
            update_ok = workspace_tool_operation_ok(update_result)
            sheet_ok = workspace_tool_sheet_sync_ok(update_result)
            status = "completed" if update_ok and sheet_ok else "partial" if update_ok else "failed"
            name = app.get("candidate_name") or action.get("subject_name") or "the candidate"
            if update_ok and sheet_ok:
                reply = f"{name} is shortlisted and the sheet is synced."
            elif update_ok:
                reply = f"{name} is shortlisted in the backend, but Google Sheets sync failed."
            else:
                reply = f"I could not shortlist {name}."
            result_payload = {"application": json_safe(app), "update": update_result}
    elif action_type == "reject_candidate":
        app = resolve_application_for_action(action, allow_latest=False)
        if not app:
            reply = "I could not find the candidate to reject."
            status = "failed"
        else:
            update_result = update_application_status(app, "rejected")
            update_ok = workspace_tool_operation_ok(update_result)
            sheet_ok = workspace_tool_sheet_sync_ok(update_result)
            status = "completed" if update_ok and sheet_ok else "partial" if update_ok else "failed"
            name = app.get("candidate_name") or action.get("subject_name") or "the candidate"
            if update_ok and sheet_ok:
                reply = f"{name} is rejected and the sheet is synced."
            elif update_ok:
                reply = f"{name} is rejected in the backend, but Google Sheets sync failed."
            else:
                reply = f"I could not reject {name}."
            result_payload = {"application": json_safe(app), "update": update_result}
    elif action_type == "approve_timesheet":
        result = approve_timesheet(action, company_code=company_code, created_by_phone=state["request"].sender_phone)
        status = "completed" if result.get("ok") else "needs_clarification" if result.get("needs_clarification") else "failed"
        reply = format_timesheet_decision_reply(result, "approved")
        result_payload = result
    elif action_type == "reject_timesheet":
        result = reject_timesheet(action, company_code=company_code, created_by_phone=state["request"].sender_phone)
        status = "completed" if result.get("ok") else "needs_clarification" if result.get("needs_clarification") else "failed"
        reply = format_timesheet_decision_reply(result, "rejected")
        result_payload = result
    elif action_type == "set_payroll_policy":
        result = set_payroll_policy(action, company_code=company_code, created_by_phone=state["request"].sender_phone)
        status = "completed" if result.get("ok") else "needs_clarification" if result.get("needs_clarification") else "failed"
        reply = format_set_payroll_policy_reply(result)
        result_payload = result
    elif action_type == "export_payroll":
        result = export_payroll(action, company_code=company_code, created_by_phone=state["request"].sender_phone)
        status = "completed" if result.get("ok") else "needs_clarification" if result.get("needs_clarification") else "failed"
        reply = format_export_payroll_reply(result)
        result_payload = result
    elif action_type == "notify_candidate":
        app = resolve_application_for_action(action, allow_latest=False)
        if not app:
            reply = "I could not find the candidate to notify."
            status = "failed"
        else:
            result = notify_candidate(app, state["request"].account_id)
            status = "completed" if result.get("ok") else "failed"
            name = app.get("candidate_name") or action.get("subject_name") or "the candidate"
            send_error = (result.get("send") or {}).get("error") if isinstance(result.get("send"), dict) else None
            if result.get("ok"):
                reply = f"{name} was notified."
            elif send_error == "conversation_closed":
                reply = f"I found {name}, but WhatsApp conversation is not active. The candidate needs to message again before I can send a WhatsApp reply."
            else:
                reply = f"I could not notify {name}."
            result_payload = result
    elif action_type == "send_assessment":
        app = resolve_application_for_action(action, allow_latest=False)
        if not app:
            reply = "I could not find the candidate to send the assessment."
            status = "failed"
        else:
            result = send_assessment(app, state["request"].account_id)
            status = "completed" if result.get("ok") else "failed"
            name = app.get("candidate_name") or action.get("subject_name") or "the candidate"
            send_error = (result.get("send") or {}).get("error") if isinstance(result.get("send"), dict) else None
            if result.get("ok"):
                reply = f"Assessment message sent to {name}."
            elif send_error == "conversation_closed":
                reply = f"I found {name}, but WhatsApp conversation is not active. The candidate needs to message again before I can send a WhatsApp reply."
            else:
                reply = f"I could not send the assessment to {name}."
            result_payload = result
    elif action_type == "send_email":
        app = resolve_application_for_action(action, allow_latest=False)
        if not app:
            reply = "I could not find the candidate to email."
            status = "failed"
        else:
            result = send_email(app, action)
            status = "completed" if result.get("ok") else "failed"
            name = app.get("candidate_name") or action.get("subject_name") or "the candidate"
            reply = f"Email sent to {name}." if result.get("ok") else f"I could not send the email to {name}."
            result_payload = result
    elif action_type == "schedule_interview":
        app = resolve_application_for_action(action, allow_latest=False)
        if not app:
            reply = "I could not find the candidate to schedule."
            status = "failed"
        else:
            result = schedule_interview(app, action)
            status = "completed" if result.get("ok") else "failed"
            name = app.get("candidate_name") or action.get("subject_name") or "the candidate"
            if result.get("ok"):
                reply = f"Interview scheduled for {name}."
            elif result.get("error") == "missing_interview_time":
                reply = f"I need an exact interview time before scheduling {name}."
            else:
                reply = f"I could not schedule the interview for {name}."
            result_payload = result
    else:
        status = "needs_backend_tool"
        reply = f"{action_type} needs a dedicated backend sender before I can execute it safely."
        result_payload = {"action_type": action_type, "reason": "missing_backend_sender"}

    action_for_context = {**dict(action), "turn_id": state.get("turn_id")}
    result_payload = normalized_result_payload(
        action_type=action_type,
        status=status,
        action=action_for_context,
        result_payload=result_payload,
        template_reply=reply,
    )
    reply, wording = render_grounded_reply(
        action_type=action_type,
        status=status,
        result_payload=result_payload,
        template_reply=str(result_payload.get("safe_user_message") or reply),
        user_text=state["request"].raw_text,
        turn_id=state.get("turn_id"),
    )
    reply = enforce_operational_reply_invariants(reply, result_payload)
    result_payload = {**result_payload, "operational_wording": json_safe(wording)}

    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute("UPDATE pending_actions SET status=%s, resolved_at=now() WHERE action_id=%s", ("approved" if status == "completed" else status, action["action_id"]))
            cur.execute(
                """
                INSERT INTO action_results
                (turn_id, action_id, action_type, status, result, final_reply,
                 company_code, actor_user_id, actor_email, actor_phone, actor_role)
                VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)
                """,
                (
                    state["turn_id"],
                    action["action_id"],
                    action_type,
                    status,
                    Json(json_safe(result_payload)),
                    reply,
                    actor.get("company_code"),
                    actor.get("actor_user_id"),
                    actor.get("actor_email"),
                    actor.get("actor_phone"),
                    actor.get("actor_role"),
                ),
            )
            record_pending_operation_from_result(
                cur,
                state=state,
                action_type=action_type,
                status=status,
                action=dict(action),
                result_payload=result_payload,
                reply=reply,
            )
        conn.commit()
    persistent_context = operational_context_from_action_result(
        state.get("persistent_context"),
        action_type=action_type,
        status=status,
        action=action_for_context,
        result_payload=result_payload,
    )
    turn_scratch = {
        **(state.get("turn_scratch") or {}),
        "tool_result": {"ok": status == "completed", "result": json_safe(result_payload), "error": None if status == "completed" else status},
        "reply_text": reply,
    }
    return {**state, "persistent_context": persistent_context, "turn_scratch": turn_scratch, "authoritative": True, "reply_text": reply, "final_reply_source": "pending_action_result"}


def execute_direct_action(state: GraphState) -> GraphState:
    action = state.get("direct_action")
    if not action:
        return {**state, "authoritative": False, "final_reply_source": "llm_fallback"}

    company_code = request_company_code(state["request"])
    action = action_with_resolved_entities({**action, "viewer_phone": state["request"].sender_phone, "company_code": company_code}, state.get("turn_scratch"))
    action_type = action["action_type"]
    result_payload: dict[str, Any] = {}
    actor = actor_context_for_hr_user(
        {"phone": digits(state["request"].sender_phone), "role": state["request"].sender_role or "hr_admin", "company_code": company_code},
        company_code=company_code or "",
        hr_phone=state["request"].sender_phone,
    )
    if action.get("capability_proposal") and not action.get("capability_validated"):
        decision = validate_capability_proposal(state["request"], state.get("persistent_context"), action.get("capability_proposal"), direct_action=action)
        if not decision or decision.get("status") != "action" or not isinstance(decision.get("action"), dict):
            reply = str((decision or {}).get("reply") or "I could not validate that capability safely, so I did not execute it.")
            return direct_action_result_state(
                state,
                action_type=action_type,
                status="needs_clarification",
                reply=reply,
                result_payload={"reason": "capability_validation_failed", "action": action, "capability_decision": json_safe(decision)},
            )
        action = action_with_resolved_entities({**decision["action"], "viewer_phone": state["request"].sender_phone}, state.get("turn_scratch"))
        action_type = action["action_type"]
    required_module = required_module_for_action(action_type)
    if required_module and not company_has_module(company_code, required_module):
        return direct_action_result_state(
            state,
            action_type=action_type,
            status="module_disabled",
            reply=module_disabled_reply(company_code, required_module),
            result_payload={
                "reason": "module_disabled",
                "company_code": company_code,
                "required_module": required_module,
                "enabled_modules": sorted(configured_company_modules(company_code)),
                "action": action,
            },
        )

    if action_type in {"shortlist_candidate", "hire_candidate", "reject_candidate", "send_assessment", "send_email"}:
        if action.get("error") == "ambiguous_candidate":
            return direct_action_result_state(
                state,
                action_type=action_type,
                status="needs_clarification",
                reply=candidate_clarification_reply([item for item in action.get("matches", []) if isinstance(item, dict)], action_type=action_type),
                result_payload={"reason": "ambiguous_candidate", "matches": action.get("matches") or [], "action": action},
            )
        if not candidate_action_has_target(action):
            return direct_action_result_state(
                state,
                action_type=action_type,
                status="needs_clarification",
                reply=candidate_mutation_clarification(action_type),
                result_payload={"reason": "missing_candidate_target", "action": action},
            )

    if action_type in {"set_payroll_policy", "export_payroll", "list_payroll_exports"}:
        viewer_scope = manager_scope_context(action.get("viewer_phone"), company_code)
        if viewer_scope.get("restricted"):
            return direct_action_result_state(
                state,
                action_type=action_type,
                status="failed",
                reply="That is a company-wide payroll action. Please ask an HR admin with full company access.",
                result_payload={
                    "reason": "company_wide_action_requires_hr_admin",
                    "company_code": company_code,
                    "action": action,
                    "scope": json_safe(viewer_scope),
                },
            )

    if action_requires_confirmation(action_type):
        return create_pending_confirmation_state(state, action)

    if action_type == "retry_last_failed_action":
        status, reply, result_payload = retry_action_from_failed_context(state)
    elif action_type == "retry_last_employee_message":
        result = retry_last_employee_message(state["request"].account_id)
        status = "completed" if result.get("ok") else "failed"
        if result.get("bulk_retry"):
            lines = [f"Tried again for {result.get('attempted_count', 0)} employee notification{'s' if result.get('attempted_count', 0) != 1 else ''}:"]
            for item in result.get("results") if isinstance(result.get("results"), list) else []:
                employee = item.get("employee") if isinstance(item.get("employee"), dict) else {}
                retry = item.get("retry") if isinstance(item.get("retry"), dict) else {}
                name = employee.get("name") or employee.get("phone") or "Employee"
                if retry.get("ok"):
                    lines.append(f"- {name}: sent")
                else:
                    lines.append(f"- {name}: {notification_status_text(retry)}")
            reply = "\n".join(lines)
        else:
            employee = result.get("employee") if isinstance(result.get("employee"), dict) else {}
            name = employee.get("name") or "the employee"
            send_error = (result.get("send") or {}).get("error") if isinstance(result.get("send"), dict) else result.get("error")
            if result.get("ok"):
                if result.get("retried_action_type") == "send_onboarding_reminder" and employee.get("employee_key"):
                    result["reminder_update"] = mark_onboarding_reminder_sent(str(employee.get("employee_key")))
                reply = f"Sent again to {name}."
            elif send_error in ("conversation_closed", "conversation_inactive", "no_usable_conversation_id"):
                reply = "I found the last message, but WhatsApp conversation is not active."
            else:
                reply = f"I could not resend the last message to {name}."
        result_payload = result
    elif action_type == "check_assessment_config":
        result = check_assessment_config(company_code)
        status = "completed" if result.get("ok") else "failed"
        reply = format_check_assessment_config_reply(result) if result.get("ok") else "I could not check the assessment configuration right now."
        result_payload = result
    elif action_type == "answer_candidate_email_lookup":
        email = str(action.get("email") or "").strip().lower()
        matches = candidate_applications_by_email(email)
        status = "completed"
        reply = candidate_email_lookup_reply(email, matches)
        result_payload = {
            "email": email,
            "matches": [candidate_lookup_match_payload(app) for app in matches],
            "match_count": len(matches),
        }
    elif action_type == "prepare_candidate_email":
        if action.get("error") == "ambiguous_candidate":
            status = "needs_clarification"
            reply = "I found more than one matching candidate. Please specify the role or phone before I email anyone."
            result_payload = {"reason": "ambiguous_candidate", "matches": action.get("matches") or [], "action": action}
        else:
            app = find_application_by_key(action.get("app_key"), company_code=company_code)
            if not app:
                status = "failed"
                reply = "I could not find the selected candidate to email."
                result_payload = {"reason": "candidate_not_found", "action": action}
            else:
                contact = candidate_contact(app)
                status = "needs_details"
                reply = f"What should I send in the email to {contact.get('name') or 'the candidate'} for {contact.get('position_title') or 'that application'}?"
                result_payload = {"selected_application": candidate_lookup_match_payload(app), "needs": "email_body", "action": action}
    elif action_type == "schedule_candidate_meeting":
        app = find_application_by_key(action.get("app_key"), company_code=company_code)
        if not app:
            status = "failed"
            reply = "I could not find the selected candidate to schedule."
            result_payload = {"reason": "candidate_not_found", "action": action}
        else:
            result = schedule_candidate_meeting(app, action)
            status = "completed" if result.get("ok") else "failed"
            contact = candidate_contact(app)
            if result.get("ok"):
                reply = f"Calendar invite sent to {contact.get('name') or 'the candidate'} with a Google Meet link."
            elif result.get("error") == "missing_candidate_email":
                reply = f"I found {contact.get('name') or 'the candidate'}, but I do not have their email."
            elif result.get("error") == "missing_meeting_time":
                reply = f"I found {contact.get('name') or 'the candidate'}, but I need the meeting date and time."
            else:
                reply = f"I could not schedule the meeting for {contact.get('name') or 'the candidate'}."
            result_payload = {**result, "selected_application": candidate_lookup_match_payload(app), "action": action}
    elif action_type == "hire_candidate":
        app = resolve_application_for_action(action, allow_latest=False)
        if not app:
            reply = "I could not find the candidate to hire."
            status = "failed"
            result_payload = {"reason": "candidate_not_found", "action": action}
        else:
            update_result = update_application_status(app, "hired")
            posthire_result = transition_hire(app)
            ok = bool(update_result.get("ok") and posthire_result.get("ok"))
            status = "completed" if ok else "failed"
            name = app.get("candidate_name") or action.get("subject_name") or "the candidate"
            reply = f"{name} is hired and employee setup is done." if ok else f"I could not complete hiring for {name}."
            result_payload = {"application": json_safe(app), "update": update_result, "posthire": posthire_result}
    elif action_type == "shortlist_candidate":
        app = resolve_application_for_action(action, allow_latest=False)
        if not app:
            reply = "I could not find the candidate to shortlist."
            status = "failed"
            result_payload = {"reason": "candidate_not_found", "action": action}
        else:
            update_result = update_application_status(app, "shortlisted")
            update_ok = workspace_tool_operation_ok(update_result)
            sheet_ok = workspace_tool_sheet_sync_ok(update_result)
            status = "completed" if update_ok and sheet_ok else "partial" if update_ok else "failed"
            name = app.get("candidate_name") or action.get("subject_name") or "the candidate"
            if update_ok and sheet_ok:
                reply = f"{name} is shortlisted and the sheet is synced."
            elif update_ok:
                reply = f"{name} is shortlisted in the backend, but Google Sheets sync failed."
            else:
                reply = f"I could not shortlist {name}."
            result_payload = {"application": json_safe(app), "update": update_result}
    elif action_type == "reject_candidate":
        app = resolve_application_for_action(action, allow_latest=False)
        if not app:
            reply = "I could not find the candidate to reject."
            status = "failed"
            result_payload = {"reason": "candidate_not_found", "action": action}
        else:
            update_result = update_application_status(app, "rejected")
            update_ok = workspace_tool_operation_ok(update_result)
            sheet_ok = workspace_tool_sheet_sync_ok(update_result)
            status = "completed" if update_ok and sheet_ok else "partial" if update_ok else "failed"
            name = app.get("candidate_name") or action.get("subject_name") or "the candidate"
            if update_ok and sheet_ok:
                reply = f"{name} is rejected and the sheet is synced."
            elif update_ok:
                reply = f"{name} is rejected in the backend, but Google Sheets sync failed."
            else:
                reply = f"I could not reject {name}."
            result_payload = {"application": json_safe(app), "update": update_result}
    elif action_type == "rank_candidates":
        result = rank_candidates(action, company_code=company_code)
        status = "completed" if result.get("ok") else "failed"
        reply = format_rank_candidates_reply(result) if result.get("ok") else "I could not rank candidates right now."
        result_payload = result
    elif action_type == "candidate_cv_evaluation":
        result = candidate_cv_evaluation(action, company_code=company_code)
        status = "completed" if result.get("ok") else "failed"
        reply = format_candidate_cv_evaluation_reply(result) if result.get("ok") else "I could not evaluate candidates from stored CV/application data right now."
        result_payload = result
    elif action_type == "compare_candidates":
        result = compare_candidates(action, company_code=company_code)
        status = "completed" if result.get("ok") else "failed"
        reply = format_compare_candidates_reply(result) if result.get("ok") else "Candidate comparison is not available for those records yet."
        result_payload = result
    elif action_type == "workforce_analytics":
        result = workforce_analytics(action, company_code=company_code)
        status = "completed" if result.get("ok") else "failed"
        reply = format_workforce_analytics_reply(result)
        result_payload = result
    elif action_type == "create_shift_assignment":
        result = create_shift_assignment(action, company_code=company_code, created_by_phone=state["request"].sender_phone)
        if result.get("ok"):
            result["employee_notification"] = notify_employee_shift_created(
                result=result,
                account_id=state["request"].account_id,
                created_by_phone=state["request"].sender_phone,
            )
        status = "completed" if result.get("ok") else "failed"
        reply = format_create_shift_reply(result)
        result_payload = result
    elif action_type == "replace_conflicting_shift_assignment":
        result = replace_conflicting_shift_assignment(
            action,
            company_code=company_code,
            created_by_phone=state["request"].sender_phone,
            account_id=state["request"].account_id,
        )
        status = "completed" if result.get("ok") else "failed"
        reply = format_replace_shift_reply(result)
        result_payload = result
    elif action_type == "list_shifts":
        result = list_shifts(action, company_code=company_code)
        status = "completed" if result.get("ok") else "failed"
        reply = format_list_shifts_reply(result)
        result_payload = result
    elif action_type == "cancel_shift_assignment":
        result = cancel_shift_assignment(action, company_code=company_code, created_by_phone=state["request"].sender_phone)
        if result.get("ok"):
            result["employee_notification"] = notify_employee_shift_cancelled(
                result=result,
                account_id=state["request"].account_id,
                created_by_phone=state["request"].sender_phone,
            )
        status = "completed" if result.get("ok") else "failed"
        reply = format_cancel_shift_reply(result)
        result_payload = result
    elif action_type == "request_availability":
        result = request_availability(action, company_code=company_code, created_by_phone=state["request"].sender_phone, account_id=state["request"].account_id)
        status = "completed" if result.get("ok") else "failed"
        reply = format_request_availability_reply(result)
        result_payload = result
    elif action_type == "list_availability":
        result = list_availability(action, company_code=company_code)
        status = "completed" if result.get("ok") else "failed"
        reply = format_list_availability_reply(result)
        result_payload = result
    elif action_type == "request_shift_swap":
        result = request_shift_swap(action, company_code=company_code, created_by_phone=state["request"].sender_phone, account_id=state["request"].account_id)
        status = "completed" if result.get("ok") else "failed"
        reply = format_request_shift_swap_reply(result)
        result_payload = result
    elif action_type == "approve_shift_swap":
        result = approve_shift_swap(action, company_code=company_code, created_by_phone=state["request"].sender_phone, account_id=state["request"].account_id)
        status = "completed" if result.get("ok") else "failed"
        reply = format_shift_swap_decision_reply(result, "approved")
        result_payload = result
    elif action_type == "reject_shift_swap":
        result = reject_shift_swap(action, company_code=company_code, created_by_phone=state["request"].sender_phone, account_id=state["request"].account_id)
        status = "completed" if result.get("ok") else "failed"
        reply = format_shift_swap_decision_reply(result, "rejected")
        result_payload = result
    elif action_type == "list_shift_swaps":
        result = list_shift_swaps(action, company_code=company_code)
        status = "completed" if result.get("ok") else "failed"
        reply = format_list_shift_swaps_reply(result)
        result_payload = result
    elif action_type == "check_in_employee":
        result = check_in_employee(action, company_code=company_code, created_by_phone=state["request"].sender_phone)
        status = "completed" if result.get("ok") else "needs_clarification" if result.get("needs_confirmation") else "failed"
        reply = format_attendance_mutation_reply(result, action_type)
        if result.get("ok") and int(((result.get("attendance") or {}).get("late_minutes") or 0)) > 0:
            result["hr_notification"] = notify_attendance_exception(result, account_id=state["request"].account_id, event_type="late_check_in")
        result_payload = result
    elif action_type == "check_out_employee":
        result = check_out_employee(action, company_code=company_code, created_by_phone=state["request"].sender_phone)
        status = "completed" if result.get("ok") else "failed"
        reply = format_attendance_mutation_reply(result, action_type)
        result_payload = result
    elif action_type == "mark_attendance_absent":
        result = mark_attendance_absent(action, company_code=company_code, created_by_phone=state["request"].sender_phone)
        status = "completed" if result.get("ok") else "needs_clarification" if result.get("needs_confirmation") else "failed"
        reply = format_attendance_mutation_reply(result, action_type)
        if result.get("ok"):
            result["hr_notification"] = notify_attendance_exception(result, account_id=state["request"].account_id, event_type="marked_absent")
        result_payload = result
    elif action_type == "correct_attendance_record":
        result = correct_attendance_record(action, company_code=company_code, created_by_phone=state["request"].sender_phone)
        status = "completed" if result.get("ok") else "needs_clarification" if result.get("needs_confirmation") else "failed"
        reply = format_attendance_mutation_reply(result, action_type)
        result_payload = result
    elif action_type == "list_attendance":
        result = list_attendance(action, company_code=company_code)
        status = "completed" if result.get("ok") else "failed"
        reply = format_list_attendance_reply(result)
        result_payload = result
    elif action_type == "request_leave":
        result = request_leave(action, company_code=company_code, created_by_phone=state["request"].sender_phone)
        status = "completed" if result.get("ok") else "failed"
        reply = format_leave_mutation_reply(result, action_type)
        result_payload = result
    elif action_type == "approve_leave_request":
        result = approve_leave_request(action, company_code=company_code, created_by_phone=state["request"].sender_phone, account_id=state["request"].account_id)
        status = "completed" if result.get("ok") else "needs_clarification" if result.get("needs_confirmation") else "failed"
        reply = format_leave_mutation_reply(result, action_type)
        result_payload = result
    elif action_type == "reject_leave_request":
        result = reject_leave_request(action, company_code=company_code, created_by_phone=state["request"].sender_phone, account_id=state["request"].account_id)
        status = "completed" if result.get("ok") else "failed"
        reply = format_leave_mutation_reply(result, action_type)
        result_payload = result
    elif action_type == "cancel_leave_request":
        result = cancel_leave_request(action, company_code=company_code, created_by_phone=state["request"].sender_phone, account_id=state["request"].account_id)
        status = "completed" if result.get("ok") else "failed"
        reply = format_leave_mutation_reply(result, action_type)
        result_payload = result
    elif action_type == "list_leave_requests":
        result = list_leave_requests(action, company_code=company_code)
        status = "completed" if result.get("ok") else "failed"
        reply = format_list_leave_requests_reply(result)
        result_payload = result
    elif action_type == "list_payroll_hours":
        result = list_payroll_hours(action, company_code=company_code)
        status = "completed" if result.get("ok") else "failed"
        reply = format_payroll_hours_reply(result)
        result_payload = result
    elif action_type == "create_timesheet_review":
        result = create_timesheet_review(action, company_code=company_code, created_by_phone=state["request"].sender_phone)
        status = "completed" if result.get("ok") else "failed"
        reply = format_create_timesheet_review_reply(result)
        result_payload = result
    elif action_type == "approve_timesheet":
        result = approve_timesheet(action, company_code=company_code, created_by_phone=state["request"].sender_phone)
        status = "completed" if result.get("ok") else "needs_clarification" if result.get("needs_clarification") else "failed"
        reply = format_timesheet_decision_reply(result, "approved")
        result_payload = result
    elif action_type == "reject_timesheet":
        result = reject_timesheet(action, company_code=company_code, created_by_phone=state["request"].sender_phone)
        status = "completed" if result.get("ok") else "needs_clarification" if result.get("needs_clarification") else "failed"
        reply = format_timesheet_decision_reply(result, "rejected")
        result_payload = result
    elif action_type == "list_timesheets":
        result = list_timesheets(action, company_code=company_code)
        status = "completed" if result.get("ok") else "failed"
        reply = format_list_timesheets_reply(result)
        result_payload = result
    elif action_type == "show_payroll_policy":
        result = show_payroll_policy(action, company_code=company_code)
        status = "completed" if result.get("ok") else "failed"
        reply = format_show_payroll_policy_reply(result)
        result_payload = result
    elif action_type == "set_payroll_policy":
        result = set_payroll_policy(action, company_code=company_code, created_by_phone=state["request"].sender_phone)
        status = "completed" if result.get("ok") else "needs_clarification" if result.get("needs_clarification") else "failed"
        reply = format_set_payroll_policy_reply(result)
        result_payload = result
    elif action_type == "preview_payroll":
        result = preview_payroll(action, company_code=company_code)
        status = "completed" if result.get("ok") else "failed"
        reply = format_preview_payroll_reply(result)
        result_payload = result
    elif action_type == "export_payroll":
        result = export_payroll(action, company_code=company_code, created_by_phone=state["request"].sender_phone)
        status = "completed" if result.get("ok") else "needs_clarification" if result.get("needs_clarification") else "failed"
        reply = format_export_payroll_reply(result)
        result_payload = result
    elif action_type == "list_payroll_exports":
        result = list_payroll_exports(action, company_code=company_code)
        status = "completed" if result.get("ok") else "failed"
        reply = format_list_payroll_exports_reply(result)
        result_payload = result
    elif action_type == "send_onboarding_reminder":
        employee = resolve_employee_for_direct_action(action, allow_latest=False)
        if not employee:
            status = "failed"
            reply = "I could not find the employee to remind."
            result_payload = {"reason": "employee_not_found", "action": action}
        else:
            result = send_onboarding_reminder(employee, state["request"].account_id)
            status = "completed" if result.get("ok") else "failed"
            name = employee.get("name") or action.get("subject_name") or "the employee"
            send_error = (result.get("send") or {}).get("error") if isinstance(result.get("send"), dict) else None
            if result.get("ok"):
                result["reminder_update"] = mark_onboarding_reminder_sent(str(employee.get("employee_key")))
                reply = f"Reminder sent to {name}."
            elif send_error in ("conversation_closed", "conversation_inactive"):
                reply = f"I found {name}, but WhatsApp conversation is not active. {name} needs to message us again before we can send the reminder."
            else:
                reply = f"I could not send the reminder to {name}."
            result_payload = result
    elif action_type == "send_custom_employee_message":
        employee = resolve_employee_for_direct_action(action, allow_latest=False)
        if not employee:
            status = "failed"
            reply = "I need the employee name or phone before I send that message."
            result_payload = {"reason": "employee_not_found", "action": action}
        else:
            result = send_custom_employee_message(employee, state["request"].account_id, action.get("message_text") or "")
            status = "completed" if result.get("ok") else "failed"
            name = employee.get("name") or action.get("subject_name") or "the employee"
            send_error = (result.get("send") or {}).get("error") if isinstance(result.get("send"), dict) else None
            if result.get("ok"):
                reply = f"Message sent to {name}."
            elif result.get("error") == "unsafe_placeholder":
                reply = "I will not send that yet because the message still contains a placeholder."
            elif send_error in ("conversation_closed", "conversation_inactive"):
                reply = f"I found {name}, but WhatsApp conversation is not active."
            else:
                reply = f"I could not send the message to {name}."
            result_payload = result
    elif action_type == "send_email":
        app = resolve_application_for_action(action, allow_latest=False)
        if not app:
            status = "failed"
            reply = "I could not find the candidate to email."
            result_payload = {"reason": "candidate_not_found", "action": action}
        else:
            result = send_email(app, action)
            status = "completed" if result.get("ok") else "failed"
            name = app.get("candidate_name") or action.get("subject_name") or "the candidate"
            reply = f"Email sent to {name}." if result.get("ok") else f"I could not send the email to {name}."
            result_payload = result
    elif action_type == "notify_candidate":
        subject_name = action.get("subject_name")
        app = resolve_application_for_action(action, allow_latest=False)
        if not app:
            status = "failed"
            reply = "I could not find the candidate to notify."
            result_payload = {"reason": "candidate_not_found", "action": action}
        else:
            result = notify_candidate(app, state["request"].account_id)
            status = "completed" if result.get("ok") else "failed"
            name = app.get("candidate_name") or action.get("subject_name") or "the candidate"
            send_error = (result.get("send") or {}).get("error") if isinstance(result.get("send"), dict) else None
            if result.get("ok"):
                reply = f"{name} was notified."
            elif send_error == "conversation_closed":
                reply = f"I found {name}, but WhatsApp conversation is not active. The candidate needs to message again before I can send a WhatsApp reply."
            else:
                reply = f"I could not notify {name}."
            result_payload = result
    else:
        status = "needs_backend_tool"
        reply = f"{action_type} needs a dedicated backend sender before I can execute it safely."
        result_payload = {"reason": "missing_backend_sender", "action": action}

    action_for_context = {**dict(action), "turn_id": state.get("turn_id")}
    result_payload = normalized_result_payload(
        action_type=action_type,
        status=status,
        action=action_for_context,
        result_payload=result_payload,
        template_reply=reply,
    )
    reply, wording = render_grounded_reply(
        action_type=action_type,
        status=status,
        result_payload=result_payload,
        template_reply=str(result_payload.get("safe_user_message") or reply),
        user_text=state["request"].raw_text,
        turn_id=state.get("turn_id"),
    )
    reply = enforce_operational_reply_invariants(reply, result_payload)
    result_payload = {**result_payload, "operational_wording": json_safe(wording)}
    final_reply_source = "direct_action_result"
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                UPDATE hr_turns
                SET intent=%s, turn_focus=%s, final_reply_source=%s
                WHERE turn_id=%s
                """,
                (action_type, "action_execution", final_reply_source, state["turn_id"]),
            )
            cur.execute(
                """
                INSERT INTO action_results
                (turn_id, action_id, action_type, status, result, final_reply,
                 company_code, actor_user_id, actor_email, actor_phone, actor_role)
                VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)
                """,
                (
                    state["turn_id"],
                    None,
                    action_type,
                    status,
                    Json(json_safe(result_payload)),
                    reply,
                    actor.get("company_code"),
                    actor.get("actor_user_id"),
                    actor.get("actor_email"),
                    actor.get("actor_phone"),
                    actor.get("actor_role"),
                ),
            )
            record_pending_operation_from_result(
                cur,
                state=state,
                action_type=action_type,
                status=status,
                action=action,
                result_payload=result_payload,
                reply=reply,
            )
        conn.commit()
    persistent_context = operational_context_from_action_result(
        state.get("persistent_context"),
        action_type=action_type,
        status=status,
        action=action_for_context,
        result_payload=result_payload,
    )
    return {
        **state,
        "persistent_context": persistent_context,
        "turn_scratch": {
            **(state.get("turn_scratch") or {}),
            "tool_result": {"ok": status == "completed", "result": json_safe(result_payload), "error": None if status == "completed" else status},
            "reply_text": reply,
        },
        "authoritative": True,
        "reply_text": reply,
        "final_reply_source": final_reply_source,
    }


def reject_pending_action(state: GraphState) -> GraphState:
    action = state.get("pending_action")
    if action:
        reply = "Okay, I will not start it now."
        action_type = str(action.get("action_type") or "pending_action")
        company_code = request_company_code(state["request"])
        actor = actor_context_for_hr_user(
            {"phone": digits(state["request"].sender_phone), "role": state["request"].sender_role or "hr_admin", "company_code": company_code},
            company_code=company_code or "",
            hr_phone=state["request"].sender_phone,
        )
        result_payload = normalized_result_payload(
            action_type=action_type,
            status="rejected",
            action={**dict(action), "turn_id": state.get("turn_id")},
            result_payload={"reason": "admin_rejected", "action": json_safe(action)},
            template_reply=reply,
        )
        with db_connect() as conn:
            with conn.cursor() as cur:
                cur.execute("UPDATE pending_actions SET status='rejected', resolved_at=now() WHERE action_id=%s", (action["action_id"],))
                cur.execute(
                    """
                    INSERT INTO action_results
                    (turn_id, action_id, action_type, status, result, final_reply,
                     company_code, actor_user_id, actor_email, actor_phone, actor_role)
                    VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)
                    """,
                    (
                        state["turn_id"],
                        action["action_id"],
                        action_type,
                        "rejected",
                        Json(json_safe(result_payload)),
                        reply,
                        actor.get("company_code"),
                        actor.get("actor_user_id"),
                        actor.get("actor_email"),
                        actor.get("actor_phone"),
                        actor.get("actor_role"),
                    ),
                )
            conn.commit()
    return {**state, "authoritative": True, "reply_text": "Okay, I will not start it now.", "final_reply_source": "pending_action_rejected"}


def answer_onboarding_status(state: GraphState) -> GraphState:
    company_code = request_company_code(state["request"])
    if not company_has_module(company_code, "onboarding"):
        reply = module_disabled_reply(company_code, "onboarding")
        return {**state, "authoritative": True, "reply_text": reply, "turn_focus": "module_disabled", "final_reply_source": "module_gate"}
    raw_text = state["request"].raw_text
    normalized = normalize_text(raw_text)
    if re.search(r"\b(who|list|all)\b", normalized) and re.search(r"\b(onboarding|pending|missing|still)\b", normalized):
        reply, payload = onboarding_queue_reply()
    else:
        employee = employee_mentioned_in_text(raw_text) or find_employee_by_name(extract_subject_name(raw_text))
        if not employee:
            reply = "Which employee do you mean? Please send the employee name or phone."
            payload = {}
        else:
            reply, payload = onboarding_status_reply(employee)
    reply, wording = compose_operational_reply(
        action_type="answer_onboarding_status",
        status="completed",
        result_payload=payload if isinstance(payload, dict) else {"payload": payload},
        template_reply=reply,
        user_text=state["request"].raw_text,
        turn_id=state.get("turn_id"),
    )
    payload = {**payload, "operational_wording": json_safe(wording)} if isinstance(payload, dict) else {"payload": payload, "operational_wording": json_safe(wording)}
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                "INSERT INTO memory_snapshots (turn_id, scope, payload) VALUES (%s,%s,%s)",
                (state["turn_id"], "onboarding_status", Json(payload)),
            )
        conn.commit()
    return {**state, "authoritative": True, "reply_text": reply, "turn_focus": "onboarding_status", "final_reply_source": "focused_backend_status"}


def latest_action_result(action_type: str | None, text: str) -> dict[str, Any] | None:
    employee = employee_mentioned_in_text(text)
    app = application_mentioned_in_text(text)
    filters: list[str] = []
    if employee:
        filters.extend(
            str(value)
            for value in [employee.get("employee_key"), employee.get("phone"), employee.get("name")]
            if value
        )
    if app:
        filters.extend(
            str(value)
            for value in [app.get("app_key"), app.get("phone"), app.get("candidate_name")]
            if value
        )
    with db_connect() as conn:
        with conn.cursor() as cur:
            if action_type:
                cur.execute(
                    """
                    SELECT action_type, status, result, final_reply, created_at
                    FROM action_results
                    WHERE action_type=%s
                    ORDER BY created_at DESC
                    LIMIT 20
                    """,
                    (action_type,),
                )
            else:
                cur.execute(
                    """
                    SELECT action_type, status, result, final_reply, created_at
                    FROM action_results
                    ORDER BY created_at DESC
                    LIMIT 20
                    """
                )
            rows = [dict(row) for row in cur.fetchall()]
    if not rows:
        return None
    if filters:
        lowered_filters = [item.lower() for item in filters]
        for row in rows:
            haystack = json.dumps(json_safe(row), ensure_ascii=False).lower()
            if any(item in haystack for item in lowered_filters):
                return row
    return rows[0]


ACTION_HISTORY_TYPES = (
    "send_email",
    "notify_candidate",
    "send_assessment",
    "send_custom_employee_message",
    "send_onboarding_reminder",
    "retry_last_failed_action",
    "retry_last_employee_message",
    "approve_leave_request",
    "reject_leave_request",
    "approve_shift_swap",
    "reject_shift_swap",
    "approve_timesheet",
    "reject_timesheet",
    "hire_candidate",
    "shortlist_candidate",
)


def scoped_action_history_results(
    request: WhatsAppTurnRequest,
    *,
    action_types: tuple[str, ...] = ACTION_HISTORY_TYPES,
    minutes: int = 240,
    limit: int = 20,
) -> list[dict[str, Any]]:
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT ar.action_type, ar.status, ar.result, ar.final_reply, ar.created_at, ht.raw_text
                FROM action_results ar
                JOIN hr_turns ht ON ht.turn_id=ar.turn_id
                WHERE ht.sender_phone=%s
                  AND (%s IS NULL OR ht.account_id=%s)
                  AND (%s IS NULL OR ht.conversation_id=%s)
                  AND ar.created_at > now() - (%s || ' minutes')::interval
                  AND ar.action_type = ANY(%s)
                ORDER BY ar.created_at DESC
                LIMIT %s
                """,
                (
                    digits(request.sender_phone),
                    request.account_id,
                    request.account_id,
                    request.conversation_id,
                    request.conversation_id,
                    max(1, minutes),
                    list(action_types),
                    max(1, min(limit, 50)),
                ),
            )
            return [dict(row) for row in cur.fetchall()]


def action_history_followup_context(request: WhatsAppTurnRequest, context: dict[str, Any] | None) -> dict[str, Any] | None:
    text = request.raw_text
    if not is_sent_message_history_question(text):
        return None
    rows = scoped_action_history_results(request)
    normalized_rows = [{**json_safe(row), "normalized_action_result": normalized_action_result_from_row(row)} for row in rows]
    latest_success = next((row for row in normalized_rows if (row.get("normalized_action_result") or {}).get("ok")), None)
    latest_any = normalized_rows[0] if normalized_rows else None
    return {
        "question": text,
        "kind": "sent_message_history",
        "latest_successful_action": latest_success,
        "latest_action": latest_any,
        "persistent_last_successful_action": (persistent_context_pruned(context).get("last_successful_action") if context else None),
    }


def scoped_recent_action_context(request: WhatsAppTurnRequest, *, minutes: int = 240, limit: int = 8) -> list[dict[str, Any]]:
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT ht.turn_id, ht.raw_text, ht.intent, ht.turn_focus, ht.final_reply_source, ht.created_at,
                       ar.action_type, ar.status AS action_status, ar.result AS action_result, ar.final_reply AS action_reply,
                       ms.scope AS memory_scope, ms.payload AS memory_payload
                FROM hr_turns ht
                LEFT JOIN action_results ar ON ar.turn_id=ht.turn_id
                LEFT JOIN memory_snapshots ms ON ms.turn_id=ht.turn_id AND ms.scope IN ('capability_decision','action_failure','action_history_followup','post_action_repair')
                WHERE ht.sender_phone=%s
                  AND (%s='' OR ht.turn_id::text<>%s)
                  AND (%s IS NULL OR ht.account_id=%s)
                  AND (%s IS NULL OR ht.conversation_id=%s)
                  AND ht.created_at > now() - (%s || ' minutes')::interval
                ORDER BY ht.created_at DESC, ar.created_at DESC NULLS LAST, ms.created_at DESC NULLS LAST
                LIMIT %s
                """,
                (
                    digits(request.sender_phone),
                    str(getattr(request, "turn_id", "") or ""),
                    str(getattr(request, "turn_id", "") or ""),
                    request.account_id,
                    request.account_id,
                    request.conversation_id,
                    request.conversation_id,
                    max(1, minutes),
                    max(1, min(limit, 25)),
                ),
            )
            return [dict(row) for row in cur.fetchall()]


def latest_repairable_context(request: WhatsAppTurnRequest) -> dict[str, Any] | None:
    rows = scoped_recent_action_context(request)
    for row in rows:
        memory = row.get("memory_payload") if isinstance(row.get("memory_payload"), dict) else {}
        if row.get("memory_scope") == "capability_decision" and memory.get("status") in {"unsupported", "needs_clarification"}:
            return {"source": "memory_snapshot", "kind": "capability_decision", "row": json_safe(row), "payload": json_safe(memory)}
        if row.get("action_type") and str(row.get("action_status") or "") in {"failed", "partial", "needs_clarification", "needs_details", "module_disabled", "needs_backend_tool"}:
            normalized = normalized_action_result_from_row({"action_type": row.get("action_type"), "status": row.get("action_status"), "result": row.get("action_result"), "final_reply": row.get("action_reply")})
            return {"source": "action_result", "kind": "failed_or_blocked_action", "row": json_safe(row), "payload": {"normalized_action_result": json_safe(normalized), "result": json_safe(row.get("action_result")), "final_reply": row.get("action_reply")}}
        if row.get("memory_scope") == "post_action_repair":
            return {"source": "memory_snapshot", "kind": "post_action_repair", "row": json_safe(row), "payload": json_safe(memory)}
    return None


def candidate_for_repair_status(request: WhatsAppTurnRequest, context: dict[str, Any] | None) -> dict[str, Any] | None:
    focus = candidate_focus_for_context(context)
    if isinstance(focus, dict):
        app_key = focus.get("app_key") or focus.get("key")
        app = find_application_by_key(str(app_key), company_code=request_company_code(request)) if app_key else None
        if app:
            return app
    resolution = resolve_candidate_reference_from_text(request.raw_text, company_code=request_company_code(request))
    if resolution.get("status") == "resolved" and isinstance(resolution.get("application"), dict):
        return resolution["application"]
    return None


def status_objection_signal(text: str) -> bool:
    normalized = normalize_text(text)
    return bool(
        re.search(r"\b(already|context|do you not have context|dont you have context|don't you have context)\b", normalized)
        and re.search(r"\b(hired|shortlisted|rejected|sent|emailed|email)\b", normalized)
    )


def post_action_repair_context(request: WhatsAppTurnRequest, context: dict[str, Any] | None) -> dict[str, Any] | None:
    text = request.raw_text
    if not is_post_action_repair_text(text):
        return None
    recent = latest_repairable_context(request)
    current = persistent_context_pruned(context)
    app = candidate_for_repair_status(request, current) if status_objection_signal(text) else None
    if app:
        contact = candidate_contact(app)
        return {
            "kind": "status_objection",
            "question": text,
            "candidate": candidate_lookup_match_payload(app),
            "reply": f"Yes — the live Postgres record shows {contact.get('name') or 'the candidate'} is currently {app.get('status') or app.get('current_step') or 'status missing'}. I’m treating that stored record, not a fresh hire command, as the source of truth.",
            "source": json_safe(recent),
        }
    if not recent:
        return None
    if recent.get("kind") == "post_action_repair":
        prior_source = (recent.get("payload") or {}).get("source") if isinstance(recent.get("payload"), dict) else None
        if isinstance(prior_source, dict):
            recent = prior_source
    payload = recent.get("payload") if isinstance(recent.get("payload"), dict) else {}
    proposal = payload.get("proposal") if isinstance(payload.get("proposal"), dict) else {}
    validation = payload.get("validation") if isinstance(payload.get("validation"), dict) else {}
    reason = str(validation.get("reason") or "")
    capability = str(payload.get("capability") or proposal.get("capability") or "")
    field = str(validation.get("field") or proposal.get("field") or "")
    if reason == "candidate_notes_not_whatsapp_editable_yet" or (capability == "update_record" and field == "notes"):
        target = validation.get("target") if isinstance(validation.get("target"), dict) else {}
        name = target.get("display_name") or target.get("name") or "that candidate"
        if re.search(r"\b(google sheets?|sheets?|sheet|its in|it's in)\b", normalize_text(text)):
            reply = (
                f"You’re right that {name} can have notes visible in Google Sheets. "
                "The reason I blocked the WhatsApp edit is that Sheets is a dashboard/export mirror here; Postgres and backend ActionResult are the operational truth. "
                "Before I edit notes from WhatsApp, we need a backend-owned candidate-notes action that writes Postgres first and then syncs Sheets."
            )
        else:
            reply = (
                "I said that because the previous turn was validated as a candidate notes update, but the backend marked notes as not editable from WhatsApp yet. "
                "That was a support boundary, not a claim that the candidate or the sheet does not exist."
            )
        return {"kind": "blocked_action_objection", "question": text, "reply": reply, "source": json_safe(recent)}
    normalized = payload.get("normalized_action_result") if isinstance(payload.get("normalized_action_result"), dict) else {}
    safe = normalized.get("safe_user_message") or payload.get("reply") or recent.get("row", {}).get("action_reply")
    reply = (
        "The previous operational turn did not complete as a normal supported action. "
        f"The grounded reason I have is: {safe or reason or 'no detailed backend reason was stored'}."
    )
    return {"kind": "post_action_repair", "question": text, "reply": reply, "source": json_safe(recent)}


def is_sent_message_content_question(question: str) -> bool:
    normalized = normalize_text(question)
    return bool(
        re.search(r"\b(content|body|subject|said what|say what|what did (?:(?:you|u) )?(?:send|email)|what (?:did|does).{0,40}(?:email|message).{0,20}(?:say|said)|u emailed.*what|you emailed.*what)\b", normalized)
        or (re.search(r"\b(what)\b", normalized) and re.search(r"\b(send|sent|email|emailed|message)\b", normalized))
    )


def format_action_history_followup_reply(followup: dict[str, Any]) -> str:
    latest_success = followup.get("latest_successful_action") if isinstance(followup.get("latest_successful_action"), dict) else None
    latest_any = followup.get("latest_action") if isinstance(followup.get("latest_action"), dict) else None
    question = normalize_text(str(followup.get("question") or ""))
    if not is_sent_message_content_question(question) and re.search(r"\b(did|was|were)\b", question) and re.search(r"\b(email|send|sent|emailed)\b", question):
        row = latest_any or latest_success
        if not row:
            return "I don’t see a recent email or message action in this conversation."
        normalized = row.get("normalized_action_result") if isinstance(row.get("normalized_action_result"), dict) else {}
        action_type = str(normalized.get("action_type") or row.get("action_type") or "action")
        target = normalized.get("target_name") or "the target"
        if normalized.get("ok"):
            if action_type == "send_email":
                recipient = (normalized.get("payload") or {}).get("recipient_email") if isinstance(normalized.get("payload"), dict) else None
                return f"Yes, I sent the email to {target}" + (f" at {recipient}." if recipient else ".")
            return f"Yes, the latest {action_type.replace('_', ' ')} completed for {target}."
        safe = normalized.get("safe_user_message") or "It did not complete."
        return f"No, the latest {action_type.replace('_', ' ')} did not complete: {safe}"

    if not latest_success:
        return "I don’t see a successful sent message in this conversation."
    normalized = latest_success.get("normalized_action_result") if isinstance(latest_success.get("normalized_action_result"), dict) else {}
    payload = normalized.get("payload") if isinstance(normalized.get("payload"), dict) else {}
    action_type = str(normalized.get("action_type") or latest_success.get("action_type") or "action")
    target = normalized.get("target_name") or "the target"
    if action_type == "send_email":
        candidate_payload = payload.get("candidate") if isinstance(payload.get("candidate"), dict) else {}
        recipient = payload.get("recipient_email") or candidate_payload.get("email")
        subject = payload.get("subject") or "No subject stored"
        body = payload.get("body") or "No body stored"
        return (
            f"I sent the email to {target}" + (f" at {recipient}." if recipient else ".") + "\n\n"
            f"Subject: {subject}\n\n"
            f"Body:\n{body}"
        )
    if action_type in {"notify_candidate", "send_assessment", "send_custom_employee_message", "send_onboarding_reminder"}:
        message = payload.get("message_text") or payload.get("text") or payload.get("body") or latest_success.get("final_reply")
        return f"I found the latest {action_type.replace('_', ' ')} to {target}. Stored message: {message}"
    return f"I found the latest successful action: {action_type.replace('_', ' ')} for {target}."


def answer_action_failure(state: GraphState) -> GraphState:
    text = state["request"].raw_text
    action_type = infer_action_type_from_text(text)
    context = persistent_context_pruned(state.get("persistent_context"))
    failed_context = context.get("last_failed_action") if isinstance(context.get("last_failed_action"), dict) and not focus_is_stale(context.get("last_failed_action")) else None
    result = None if failed_context and is_why_followup_question(text) else latest_action_result(action_type, text)
    if failed_context and (is_why_followup_question(text) or not result):
        normalized = normalized_action_result_from_failed_context(failed_context)
        payload = normalized
        result = {
            "action_type": normalized.get("action_type"),
            "status": "failed" if not normalized.get("ok") else "completed",
            "result": normalized,
            "final_reply": normalized.get("safe_user_message"),
        }
    elif result:
        payload = result.get("result") or {}
        normalized = normalized_action_result_from_row(result)
    else:
        return {**state, "authoritative": False, "final_reply_source": "llm_fallback"}

    reply = action_failure_explanation_from_normalized(normalized)
    result = {**result, "normalized_action_result": json_safe(normalized)}
    final_reply_source = "backend_action_failure_status"
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                UPDATE hr_turns
                SET intent=%s, turn_focus=%s, final_reply_source=%s
                WHERE turn_id=%s
                """,
                ("answer_action_failure", "action_failure", final_reply_source, state["turn_id"]),
            )
            cur.execute(
                "INSERT INTO memory_snapshots (turn_id, scope, payload) VALUES (%s,%s,%s)",
                (state["turn_id"], "action_failure", Json(json_safe(result))),
            )
        conn.commit()
    turn_scratch = {
        **(state.get("turn_scratch") or {}),
        "tool_result": {"ok": bool(normalized.get("ok")), "result": json_safe(normalized), "error": normalized.get("error_code")},
        "reply_text": reply,
    }
    return {
        **state,
        "turn_scratch": turn_scratch,
        "authoritative": True,
        "reply_text": reply,
        "turn_focus": "action_failure",
        "final_reply_source": final_reply_source,
    }


