def format_candidate_focus_reply(focus_context: dict[str, Any]) -> str:
    if focus_context.get("status") == "ambiguous":
        return str(focus_context.get("reply") or candidate_clarification_reply([]))
    if focus_context.get("status") == "needs_clarification":
        return str(focus_context.get("reply") or candidate_mutation_clarification(focus_context.get("action_type")))
    app = focus_context.get("application") if isinstance(focus_context.get("application"), dict) else {}
    name = app.get("candidate_name") or app.get("name") or (focus_context.get("focus") or {}).get("display_name") or "the candidate"
    job = app.get("position_title") or app.get("position_code") or (focus_context.get("focus") or {}).get("position_title") or "job missing"
    stage = app.get("status") or (focus_context.get("focus") or {}).get("status") or "status missing"
    return f"I found {name} — {job}, stage: {stage}. I’ll use this candidate as the current focus."


