def public_assessment_html() -> str:
    return """
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>Application Assessment</title>
  <style>
    :root { color-scheme: light; --ink:#171d29; --bg:#f6f1e8; --panel:#fffdf8; --line:#e7dece; --muted:#746b5f; }
    * { box-sizing: border-box; }
    body { margin:0; font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; background: radial-gradient(circle at top left,#fffaf0 0,#f7f3eb 40%,#f1eadf 100%); color:var(--ink); }
    main { min-height:100vh; display:grid; place-items:center; padding:24px; }
    .shell { width:min(760px,100%); border:1px solid var(--line); background:rgba(255,253,248,.94); border-radius:32px; box-shadow:0 24px 70px rgba(23,29,41,.12); overflow:hidden; }
    header { padding:28px 28px 20px; border-bottom:1px solid var(--line); }
    .brand { font-size:12px; letter-spacing:.2em; text-transform:uppercase; color:#a39a8d; font-weight:700; }
    h1 { margin:12px 0 8px; font-size:clamp(28px,6vw,44px); letter-spacing:-.05em; }
    .subtle { color:var(--muted); line-height:1.6; }
    .content { padding:28px; }
    .progress { height:8px; background:#eee6d8; border-radius:999px; overflow:hidden; margin-top:18px; }
    .bar { height:100%; width:0%; background:var(--ink); transition:width .25s ease; }
    .question { font-size:22px; line-height:1.45; font-weight:650; margin:0 0 22px; letter-spacing:-.02em; }
    .choices { display:grid; gap:12px; }
    button.choice { width:100%; text-align:left; border:1px solid var(--line); background:#fffaf2; color:var(--ink); border-radius:20px; padding:16px 18px; font-size:16px; line-height:1.45; cursor:pointer; transition:.15s ease; }
    button.choice:hover:not(:disabled) { transform:translateY(-1px); border-color:#1b2230; background:white; }
    button.choice:disabled { opacity:.6; cursor:not-allowed; }
    .key { display:inline-grid; place-items:center; width:28px; height:28px; margin-right:10px; border-radius:999px; background:var(--ink); color:white; font-size:13px; font-weight:700; }
    .done { text-align:center; padding:34px 10px; }
    .done-icon { width:54px; height:54px; border-radius:50%; display:grid; place-items:center; margin:0 auto 18px; background:var(--ink); color:white; }
    .error { border:1px solid #f0b9b9; background:#fff1f1; color:#8f1d1d; border-radius:18px; padding:14px 16px; }
  </style>
</head>
<body>
  <main>
    <section class="shell">
      <header>
        <div class="brand">Application Assessment</div>
        <h1 id="title">Opening your assessment...</h1>
        <div class="subtle" id="meta"></div>
        <div class="progress"><div class="bar" id="bar"></div></div>
      </header>
      <div class="content" id="content"><div class="subtle">Opening your assessment...</div></div>
    </section>
  </main>
  <script>
    const attemptId = location.pathname.split('/').pop();
    const token = new URLSearchParams(location.search).get('token') || '';
    const content = document.getElementById('content');
    const title = document.getElementById('title');
    const meta = document.getElementById('meta');
    const bar = document.getElementById('bar');
    function candidateSafeAssessmentError(code) {
      const normalized = String(code || '').toLowerCase();
      if (normalized.includes('invalid_assessment_answer')) {
        return 'Please choose one of the available answers.';
      }
      if (normalized.includes('invalid') || normalized.includes('expired') || normalized.includes('not_found')) {
        return 'This link is no longer available. Please contact the hiring team if you need a new link.';
      }
      if (normalized.includes('disabled') || normalized.includes('unavailable')) {
        return 'This assessment is not available right now. Please contact the hiring team.';
      }
      return 'Something went wrong. Please check your connection and try again.';
    }
    function renderUnavailable(message) {
      title.textContent = 'Application Assessment';
      meta.textContent = '';
      bar.style.width = '0%';
      content.innerHTML = `<div class="error">${escapeHtml(message || 'This link is no longer available. Please contact the hiring team if you need a new link.')}</div>`;
    }
    async function request(path, init) {
      const res = await fetch(path + '?token=' + encodeURIComponent(token), init);
      const json = await res.json().catch(() => ({}));
      if (!res.ok) {
        const err = new Error(candidateSafeAssessmentError(json.detail?.error || json.error || res.status));
        err.code = json.detail?.error || json.error || res.status;
        throw err;
      }
      return json;
    }
    function render(state) {
      const attempt = state.attempt || {};
      title.textContent = attempt.position_title ? `Assessment for ${attempt.position_title}` : 'Application Assessment';
      const answered = attempt.current_item_index || 0;
      const total = attempt.total_items || 0;
      const nextQuestion = Math.min(answered + 1, total || 1);
      meta.textContent = [attempt.candidate_name, total ? `Question ${nextQuestion} of ${total}` : ''].filter(Boolean).join(' · ');
      bar.style.width = `${attempt.percent_complete || 0}%`;
      if (state.completed) {
        content.innerHTML = '<div class="done"><div class="done-icon">✓</div><h2>Your assessment has been submitted</h2><p class="subtle">Thank you. The hiring team will review it with the rest of your application. You can close this page.</p></div>';
        bar.style.width = '100%';
        return;
      }
      const item = state.item;
      if (!item) {
        content.innerHTML = '<div class="error">Something went wrong loading your questions. Please contact the hiring team.</div>';
        return;
      }
      content.innerHTML = `<p class="question">${escapeHtml(item.prompt_text)}</p><div class="choices">${(item.choices || []).map(choice => `<button class="choice" data-key="${escapeHtml(choice.key)}"><span class="key">${escapeHtml(choice.key)}</span>${escapeHtml(choice.text)}</button>`).join('')}</div>`;
      content.querySelectorAll('button.choice').forEach(button => {
        button.addEventListener('click', async () => {
          content.querySelectorAll('button.choice').forEach(b => b.disabled = true);
          try {
            const next = await request(`/assessment/${attemptId}/answer`, { method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({ selected_key: button.dataset.key, response_text: button.innerText }) });
            render(next);
          } catch (err) {
            content.innerHTML = `<div class="error">${escapeHtml(err.message || 'We could not save your answer. Please try again.')}</div>`;
          }
        });
      });
    }
    function escapeHtml(value) {
      return String(value ?? '').replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
    }
    request(`/assessment/${attemptId}/state`, { method:'POST' }).then(render).catch(err => renderUnavailable(err.message));
  </script>
</body>
</html>
""".strip()


def public_video_interview_html() -> str:
    return """
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>Wathefni Video Interview</title>
  <style>
    :root {
      color-scheme: light;
      --ink:#161616;
      --muted:#71695f;
      --soft:#f6efe4;
      --panel:#fffdf8;
      --line:#e8ddce;
      --accent:#17130f;
      --danger:#8f1d1d;
      --danger-bg:#fff1f1;
    }
    * { box-sizing: border-box; }
    html { min-height: 100%; }
    body {
      min-height:100%;
      margin:0;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at top left, rgba(255,255,255,.9), rgba(255,255,255,0) 34rem),
        linear-gradient(135deg, #fbf6ec 0%, #f3ebdf 58%, #efe5d5 100%);
      color:var(--ink);
    }
    main { min-height:100svh; display:grid; place-items:center; padding:18px; }
    .shell {
      width:min(720px,100%);
      border:1px solid rgba(232,221,206,.92);
      background:rgba(255,253,248,.96);
      border-radius:30px;
      box-shadow:0 24px 70px rgba(23,19,15,.12);
      overflow:hidden;
    }
    header { padding:24px 22px 18px; border-bottom:1px solid var(--line); }
    .brand { font-size:11px; letter-spacing:.2em; text-transform:uppercase; color:#a59b8e; font-weight:750; }
    h1 { margin:12px 0 8px; font-size:clamp(32px,8vw,50px); line-height:.96; letter-spacing:-.065em; }
    h2 { margin:0 0 12px; font-size:clamp(24px,6vw,36px); letter-spacing:-.04em; }
    p { margin:0 0 16px; color:var(--muted); line-height:1.65; font-size:16px; }
    .content { padding:24px 22px 26px; }
    .meta { display:flex; align-items:center; justify-content:space-between; gap:12px; color:var(--muted); font-size:13px; }
    .progress { height:8px; background:#eee4d5; border-radius:999px; overflow:hidden; margin-top:16px; }
    .bar { height:100%; width:0%; background:var(--accent); transition:width .2s ease; }
    .card { border:1px solid var(--line); background:#fffaf1; border-radius:22px; padding:16px; margin:18px 0; }
    .question { color:var(--ink); font-size:clamp(24px,6vw,38px); line-height:1.12; letter-spacing:-.045em; font-weight:760; margin:0 0 20px; }
    .question-list { display:grid; gap:12px; margin:18px 0; padding:0; list-style:none; }
    .question-list li { border:1px solid var(--line); background:#fffaf1; border-radius:18px; padding:14px 14px 14px 52px; position:relative; line-height:1.5; }
    .question-list span { position:absolute; left:14px; top:14px; display:grid; place-items:center; width:26px; height:26px; border-radius:999px; background:var(--accent); color:white; font-size:13px; font-weight:800; }
    .actions { display:grid; gap:12px; margin-top:22px; }
    .button {
      appearance:none;
      border:0;
      width:100%;
      border-radius:999px;
      padding:15px 18px;
      background:var(--accent);
      color:white;
      font-weight:760;
      font-size:16px;
      cursor:pointer;
      box-shadow:0 14px 30px rgba(23,19,15,.16);
    }
    .button.secondary { background:#fffaf2; color:var(--ink); border:1px solid var(--line); box-shadow:none; }
    .button:disabled { opacity:.55; cursor:not-allowed; }
    .filebox {
      border:1px dashed #c9bba8;
      background:#fffaf2;
      border-radius:24px;
      padding:18px;
      display:grid;
      gap:12px;
    }
    input[type=file] { width:100%; font-size:15px; }
    video { width:100%; max-height:340px; background:#15110d; border-radius:20px; display:block; }
    .preview-meta { color:var(--muted); font-size:13px; line-height:1.5; overflow-wrap:anywhere; }
    .error { border:1px solid #f0b9b9; background:var(--danger-bg); color:var(--danger); border-radius:18px; padding:14px 16px; line-height:1.55; }
    .success-mark { width:56px; height:56px; display:grid; place-items:center; border-radius:999px; background:var(--accent); color:#fff; font-weight:800; margin-bottom:18px; }
    .hidden { display:none !important; }
    @media (min-width: 680px) {
      main { padding:32px; }
      header { padding:32px 34px 22px; }
      .content { padding:30px 34px 36px; }
      .actions { grid-template-columns: max-content max-content; align-items:center; }
      .button { width:auto; min-width:180px; }
    }
  </style>
</head>
<body>
  <main>
    <section class="shell" aria-live="polite">
      <header>
      <div class="brand">Wathefni Video Interview</div>
        <h1 id="title">Opening your interview...</h1>
        <div class="meta">
          <span id="subtitle"></span>
          <span id="progressText"></span>
        </div>
        <div class="progress"><div class="bar" id="bar"></div></div>
      </header>
      <div class="content">
      <div id="content"><p>Loading your interview link.</p></div>
      </div>
    </section>
  </main>
  <script>
    const interviewId = location.pathname.split('/').pop();
    const token = new URLSearchParams(location.search).get('token') || '';
    const title = document.getElementById('title');
    const subtitle = document.getElementById('subtitle');
    const progressText = document.getElementById('progressText');
    const bar = document.getElementById('bar');
    const content = document.getElementById('content');
    const maxUploadBytes = 75 * 1024 * 1024;
    const stateUrl = `/video-interview/${encodeURIComponent(interviewId)}/state?token=${encodeURIComponent(token)}`;
    const consentUrl = `/video-interview/${encodeURIComponent(interviewId)}/consent?token=${encodeURIComponent(token)}`;
    const responsesUrl = `/video-interview/${encodeURIComponent(interviewId)}/responses?token=${encodeURIComponent(token)}`;
    const completeUrl = `/video-interview/${encodeURIComponent(interviewId)}/complete?token=${encodeURIComponent(token)}`;
    const appState = {
      data: null,
      introSeen: false,
      selectedFile: null,
      selectedFileUrl: '',
      recorder: null,
      recordingStream: null,
      recordingChunks: [],
      recording: false,
      submitting: false,
      error: '',
    };

    function escapeHtml(value) {
      return String(value ?? '').replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
    }

    function setHeader(nextTitle, meta, progress, percent) {
      title.textContent = nextTitle || '';
      subtitle.textContent = meta || '';
      progressText.textContent = progress || '';
      bar.style.width = `${Math.max(0, Math.min(100, percent || 0))}%`;
    }

    function candidateSafeVideoError(detail) {
      const code = typeof detail === 'string' ? detail : detail && detail.error;
      const normalized = String(code || '').toLowerCase();
      if (normalized.includes('already_completed')) return 'Your interview has already been submitted.';
      if (normalized.includes('cancelled')) return 'This video interview is no longer available. Please contact the hiring team if you need help.';
      if (normalized.includes('expired') || normalized.includes('invalid') || normalized.includes('not_found')) {
        return 'This link is no longer available. Please contact the hiring team if you need a new link.';
      }
      return 'This link is no longer available. Please contact the hiring team if you need a new link.';
    }

    async function fetchJson(url, init) {
      const res = await fetch(url, { ...init, cache: 'no-store' });
      const data = await res.json().catch(() => ({}));
      if (!res.ok) {
        const err = new Error('request_failed');
        err.status = res.status;
        err.detail = data && data.detail;
        throw err;
      }
      return data;
    }

    async function loadState() {
      appState.data = await fetchJson(stateUrl, { method: 'GET' });
      return appState.data;
    }

    function answeredQuestionIds(data) {
      return new Set((data?.responses || []).map(item => String(item.question_id || '')).filter(Boolean));
    }

    function nextQuestion(data) {
      const answered = answeredQuestionIds(data);
      return (data?.questions || []).find(question => !answered.has(String(question.question_id || ''))) || null;
    }

    function responseMode(data) {
      return data?.interview?.response_mode === 'per_question_video' ? 'per_question_video' : 'single_video';
    }

    function singleVideoSubmitted(data) {
      return responseMode(data) === 'single_video' && (data?.responses || []).length > 0;
    }

    function anchorQuestion(data) {
      return (data?.questions || [])[0] || null;
    }

    function questionsListHtml(data) {
      return `<ol class="question-list">${(data?.questions || []).map((question, index) => `
        <li><span>${index + 1}</span>${escapeHtml(question.prompt_text || 'Video interview question')}</li>
      `).join('')}</ol>`;
    }

    function questionNumber(data, question) {
      const questions = data?.questions || [];
      const index = questions.findIndex(item => String(item.question_id) === String(question?.question_id));
      return index >= 0 ? index + 1 : 1;
    }

    function progressPercent(data, question) {
      const total = (data?.questions || []).length || 1;
      if (data?.completed) return 100;
      if (!question) return 0;
      return ((questionNumber(data, question) - 1) / total) * 100;
    }

    function cleanupPreview() {
      if (appState.selectedFileUrl) URL.revokeObjectURL(appState.selectedFileUrl);
      appState.selectedFileUrl = '';
    }

    function setSelectedFile(file) {
      cleanupPreview();
      appState.selectedFile = file || null;
      if (file) appState.selectedFileUrl = URL.createObjectURL(file);
    }

    function renderError(message, retry) {
      content.innerHTML = `
        <div class="error">${escapeHtml(message)}</div>
        ${retry ? '<div class="actions"><button class="button secondary" id="retryBtn" type="button">Try again</button></div>' : ''}
      `;
      const retryBtn = document.getElementById('retryBtn');
      if (retryBtn) retryBtn.addEventListener('click', retry);
    }

    function renderInvalid(message) {
      setHeader('Video Interview', '', '', 0);
      content.innerHTML = `
        <h2>Video Interview</h2>
        <p>${escapeHtml(message || 'This link is no longer available. Please contact the hiring team if you need a new link.')}</p>
      `;
    }

    function renderLoading() {
      setHeader('Opening your interview...', '', '', 0);
      content.innerHTML = '<p>Opening your interview...</p>';
    }

    function renderIntro() {
      setHeader('Video Interview', '', '', 0);
      content.innerHTML = `
        <p>Answer a few short questions for your application. Please make sure you are in a quiet place with good lighting before you begin.</p>
        <div class="card">
          <p>This is not a live interview. You will see all questions first, then answer them in one video when you are ready.</p>
        </div>
        <div class="actions"><button class="button" id="continueBtn" type="button">Continue</button></div>
      `;
      document.getElementById('continueBtn').addEventListener('click', () => {
        appState.introSeen = true;
        render();
      });
    }

    function renderConsent() {
      setHeader('Before you begin', '', '', 0);
      content.innerHTML = `
        <p>This interview will record your video answer and share it with the hiring team for review. Your response will only be used as part of the recruitment process.</p>
        <div class="card">
          <p>Please choose a quiet place, check your lighting, and make sure the video you submit is clear.</p>
        </div>
        ${appState.error ? `<div class="error">${escapeHtml(appState.error)}</div>` : ''}
        <div class="actions"><button class="button" id="consentBtn" type="button">I agree and want to continue</button></div>
      `;
      document.getElementById('consentBtn').addEventListener('click', async () => {
        if (appState.submitting) return;
        appState.submitting = true;
        appState.error = '';
        renderConsent();
        try {
          appState.data = await fetchJson(consentUrl, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ consent: true, privacy_notice_version: 'v1', device_info: { user_agent: navigator.userAgent } }),
          });
        } catch (err) {
          appState.error = 'We could not save your consent. Please check your connection and try again.';
        } finally {
          appState.submitting = false;
        }
        render();
      });
    }

    function renderCompleted() {
      cleanupPreview();
      setHeader('Your interview has been submitted', '', '', 100);
      content.innerHTML = `
        <div class="success-mark">✓</div>
        <h2>Your interview has been submitted</h2>
        <p>Thank you. The hiring team will review your answers and message you if anything else is needed.</p>
      `;
    }

    function renderAnswerScreen(question) {
      if (responseMode(appState.data) === 'single_video') {
        renderSingleVideo();
      } else {
        renderQuestion(question);
      }
    }

    function renderSingleVideo() {
      const data = appState.data;
      const question = anchorQuestion(data);
      if (!question) {
        renderError('No questions are available right now. Please contact the hiring team.', () => loadState().then(render).catch((err) => renderInvalid(candidateSafeVideoError(err.detail))));
        return;
      }
      setHeader('Video Interview', '', 'One video', singleVideoSubmitted(data) ? 90 : 40);
      const file = appState.selectedFile;
      const fileTooLarge = file && file.size > maxUploadBytes;
      content.innerHTML = `
        <p><strong>Please answer these questions in one video.</strong></p>
        ${questionsListHtml(data)}
        <div class="filebox">
          <label for="videoFile"><strong>Upload or record your video</strong></label>
          <input id="videoFile" type="file" accept="video/*" capture="user" />
          <p class="preview-meta">Choose one video from your phone or computer. You can also record below if your browser supports it.</p>
          <div id="recordControls"></div>
        </div>
        <div id="preview"></div>
        ${fileTooLarge ? '<div class="error">This video file is too large. Please upload a shorter video or reduce the file size.</div>' : ''}
        ${appState.error ? `<div class="error">${escapeHtml(appState.error)}</div>` : ''}
        <div class="actions">
          <button class="button" id="submitBtn" type="button" ${!file || fileTooLarge || appState.submitting ? 'disabled' : ''}>${appState.submitting ? 'Uploading...' : 'Submit interview'}</button>
          ${file ? '<button class="button secondary" id="clearBtn" type="button" ' + (appState.submitting ? 'disabled' : '') + '>Choose another video</button>' : ''}
        </div>
      `;
      const fileInput = document.getElementById('videoFile');
      const preview = document.getElementById('preview');
      if (file && appState.selectedFileUrl) {
        preview.innerHTML = `
          <div class="card">
            <video src="${appState.selectedFileUrl}" controls playsinline></video>
            <p class="preview-meta">${escapeHtml(file.name || 'Video interview')} · ${Math.round(file.size / 1024 / 1024 * 10) / 10} MB</p>
          </div>
        `;
      }
      fileInput.addEventListener('change', () => {
        appState.error = '';
        setSelectedFile(fileInput.files && fileInput.files[0] ? fileInput.files[0] : null);
        renderSingleVideo();
      });
      const clearBtn = document.getElementById('clearBtn');
      if (clearBtn) clearBtn.addEventListener('click', () => {
        appState.error = '';
        setSelectedFile(null);
        renderSingleVideo();
      });
      const submitBtn = document.getElementById('submitBtn');
      if (submitBtn) submitBtn.addEventListener('click', () => submitSingleVideo(question));
      renderRecorder(question);
    }

    function renderQuestion(question) {
      const data = appState.data;
      const total = (data.questions || []).length || 1;
      const number = questionNumber(data, question);
      setHeader('Video Interview', '', `Question ${number} of ${total}`, progressPercent(data, question));
      const file = appState.selectedFile;
      const fileTooLarge = file && file.size > maxUploadBytes;
      content.innerHTML = `
        <div class="meta"><strong>Question ${number} of ${total}</strong></div>
        <p class="question">${escapeHtml(question.prompt_text)}</p>
        <div class="filebox">
          <label for="videoFile"><strong>Upload your video answer</strong></label>
          <input id="videoFile" type="file" accept="video/*" capture="user" />
          <p class="preview-meta">Choose a short video from your phone or computer. You can also record below if your browser supports it.</p>
          <div id="recordControls"></div>
        </div>
        <div id="preview"></div>
        ${fileTooLarge ? '<div class="error">This video file is too large. Please upload a shorter video or reduce the file size.</div>' : ''}
        ${appState.error ? `<div class="error">${escapeHtml(appState.error)}</div>` : ''}
        <div class="actions">
          <button class="button" id="submitBtn" type="button" ${!file || fileTooLarge || appState.submitting ? 'disabled' : ''}>${appState.submitting ? 'Uploading...' : 'Submit answer'}</button>
          ${file ? '<button class="button secondary" id="clearBtn" type="button" ' + (appState.submitting ? 'disabled' : '') + '>Choose another video</button>' : ''}
        </div>
      `;
      const fileInput = document.getElementById('videoFile');
      const preview = document.getElementById('preview');
      if (file && appState.selectedFileUrl) {
        preview.innerHTML = `
          <div class="card">
            <video src="${appState.selectedFileUrl}" controls playsinline></video>
            <p class="preview-meta">${escapeHtml(file.name || 'Video answer')} · ${Math.round(file.size / 1024 / 1024 * 10) / 10} MB</p>
          </div>
        `;
      }
      fileInput.addEventListener('change', () => {
        appState.error = '';
        setSelectedFile(fileInput.files && fileInput.files[0] ? fileInput.files[0] : null);
        renderQuestion(question);
      });
      const clearBtn = document.getElementById('clearBtn');
      if (clearBtn) clearBtn.addEventListener('click', () => {
        appState.error = '';
        setSelectedFile(null);
        renderQuestion(question);
      });
      const submitBtn = document.getElementById('submitBtn');
      if (submitBtn) submitBtn.addEventListener('click', () => submitAnswer(question));
      renderRecorder(question);
    }

    function renderRecorder(question) {
      const host = document.getElementById('recordControls');
      if (!host || !navigator.mediaDevices || !window.MediaRecorder) {
        if (host) host.innerHTML = '<p class="preview-meta">Recording is not available in this browser. Please upload a recorded video file.</p>';
        return;
      }
      host.innerHTML = `
        <button class="button secondary" id="recordBtn" type="button">${appState.recording ? 'Stop recording' : 'Record in browser'}</button>
        <video id="livePreview" class="${appState.recording ? '' : 'hidden'}" autoplay muted playsinline></video>
      `;
      document.getElementById('recordBtn').addEventListener('click', async () => {
        if (appState.recording) {
          stopRecording();
          return;
        }
        try {
          appState.error = '';
          const stream = await navigator.mediaDevices.getUserMedia({ video: true, audio: true });
          appState.recordingStream = stream;
          appState.recordingChunks = [];
          const recorder = new MediaRecorder(stream);
          appState.recorder = recorder;
          recorder.ondataavailable = event => {
            if (event.data && event.data.size) appState.recordingChunks.push(event.data);
          };
          recorder.onstop = () => {
            const blob = new Blob(appState.recordingChunks, { type: recorder.mimeType || 'video/webm' });
            const recordedFile = new File([blob], responseMode(appState.data) === 'single_video' ? 'recorded-interview.webm' : 'recorded-answer.webm', { type: blob.type || 'video/webm' });
            setSelectedFile(recordedFile);
            appState.recording = false;
            stopTracks();
            renderAnswerScreen(question);
          };
          recorder.start();
          appState.recording = true;
          renderAnswerScreen(question);
          const livePreview = document.getElementById('livePreview');
          if (livePreview) livePreview.srcObject = stream;
        } catch (err) {
          appState.error = 'We could not access your camera or microphone. You can allow permission in your browser settings, or upload a recorded video file instead.';
          appState.recording = false;
          stopTracks();
          renderAnswerScreen(question);
        }
      });
      const livePreview = document.getElementById('livePreview');
      if (livePreview && appState.recordingStream) livePreview.srcObject = appState.recordingStream;
    }

    function stopTracks() {
      if (appState.recordingStream) {
        appState.recordingStream.getTracks().forEach(track => track.stop());
      }
      appState.recordingStream = null;
    }

    function stopRecording() {
      if (appState.recorder && appState.recorder.state !== 'inactive') {
        appState.recorder.stop();
      } else {
        appState.recording = false;
        stopTracks();
        render();
      }
    }

    async function submitAnswer(question) {
      if (appState.submitting || !appState.selectedFile) return;
      if (appState.selectedFile.size > maxUploadBytes) {
        appState.error = 'This video file is too large. Please upload a shorter video or reduce the file size.';
        renderQuestion(question);
        return;
      }
      appState.submitting = true;
      appState.error = '';
      renderQuestion(question);
      const form = new FormData();
      form.append('question_id', question.question_id);
      form.append('video', appState.selectedFile, appState.selectedFile.name || 'video-answer.webm');
      form.append('video_filename', appState.selectedFile.name || 'video-answer.webm');
      form.append('mime_type', appState.selectedFile.type || 'video/webm');
      form.append('metadata', JSON.stringify({ source: 'candidate_video_page_v1' }));
      try {
        await fetchJson(responsesUrl, { method: 'POST', body: form });
        setSelectedFile(null);
        appState.data = await loadState();
        await maybeCompleteOrRender();
      } catch (err) {
        try {
          const refreshed = await loadState();
          if (answeredQuestionIds(refreshed).has(String(question.question_id))) {
            setSelectedFile(null);
            await maybeCompleteOrRender();
            return;
          }
        } catch (_) {}
        appState.error = err && err.status === 413
          ? 'This video file is too large. Please upload a shorter video or reduce the file size.'
          : 'We could not upload this video. Please check your connection and try again.';
        renderQuestion(question);
      } finally {
        appState.submitting = false;
      }
    }

    async function submitSingleVideo(question) {
      if (appState.submitting || !appState.selectedFile || !question) return;
      if (appState.selectedFile.size > maxUploadBytes) {
        appState.error = 'This video file is too large. Please upload a shorter video or reduce the file size.';
        renderSingleVideo();
        return;
      }
      appState.submitting = true;
      appState.error = '';
      renderSingleVideo();
      const form = new FormData();
      form.append('question_id', question.question_id);
      form.append('response_mode', 'single_video');
      form.append('video', appState.selectedFile, appState.selectedFile.name || 'video-interview.webm');
      form.append('video_filename', appState.selectedFile.name || 'video-interview.webm');
      form.append('mime_type', appState.selectedFile.type || 'video/webm');
      form.append('metadata', JSON.stringify({ source: 'candidate_video_page_v1', response_mode: 'single_video' }));
      try {
        await fetchJson(responsesUrl, { method: 'POST', body: form });
        setSelectedFile(null);
        appState.data = await loadState();
        await maybeCompleteOrRender();
      } catch (err) {
        try {
          const refreshed = await loadState();
          if (singleVideoSubmitted(refreshed)) {
            setSelectedFile(null);
            await maybeCompleteOrRender();
            return;
          }
        } catch (_) {}
        appState.error = err && err.status === 413
          ? 'This video file is too large. Please upload a shorter video or reduce the file size.'
          : 'We could not upload this video. Please check your connection and try again.';
        renderSingleVideo();
      } finally {
        appState.submitting = false;
      }
    }

    async function maybeCompleteOrRender() {
      if (responseMode(appState.data) === 'single_video') {
        if (singleVideoSubmitted(appState.data)) {
          try {
            appState.data = await fetchJson(completeUrl, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{}' });
          } catch (err) {
            appState.error = 'We could not finish submitting your interview. Please check your connection and try again.';
            renderError(appState.error, () => maybeCompleteOrRender());
            return;
          }
        }
        render();
        return;
      }
      const question = nextQuestion(appState.data);
      const missingRequired = appState.data?.missing_required_question_ids || [];
      if (!question || missingRequired.length === 0 && answeredQuestionIds(appState.data).size >= (appState.data?.questions || []).length) {
        try {
          appState.data = await fetchJson(completeUrl, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{}' });
        } catch (err) {
          appState.error = 'We could not finish submitting your interview. Please check your connection and try again.';
          renderError(appState.error, () => maybeCompleteOrRender());
          return;
        }
      }
      render();
    }

    function render() {
      const data = appState.data;
      if (!data) {
        renderLoading();
        return;
      }
      if (data.completed) {
        renderCompleted();
        return;
      }
      if (!appState.introSeen && data.interview && data.interview.consent_required) {
        renderIntro();
        return;
      }
      if (data.interview && data.interview.consent_required) {
        renderConsent();
        return;
      }
      if (responseMode(data) === 'single_video') {
        if (singleVideoSubmitted(data)) {
          maybeCompleteOrRender();
          return;
        }
        renderSingleVideo();
        return;
      }
      const question = nextQuestion(data);
      if (!question) {
        maybeCompleteOrRender();
        return;
      }
      renderQuestion(question);
    }

    renderLoading();
    loadState().then(() => render()).catch((err) => renderInvalid(candidateSafeVideoError(err.detail)));
  </script>
</body>
</html>
""".strip()


@app.get("/assessment/{attempt_id}", response_class=HTMLResponse)
def public_assessment_page(attempt_id: str, token: str | None = Query(default=None)):
    return HTMLResponse(public_assessment_html())


@app.post("/assessment/{attempt_id}/state")
def public_assessment_state_endpoint(attempt_id: str, token: str | None = Query(default=None)):
    return public_assessment_state(attempt_id, token, start=True)


@app.post("/assessment/{attempt_id}/answer")
def public_assessment_answer_endpoint(attempt_id: str, answer: PublicAssessmentAnswer, token: str | None = Query(default=None)):
    state = public_assessment_state(attempt_id, token, start=True)
    if state.get("completed"):
        return state
    attempt = assessment_attempt_by_id(attempt_id)
    item = assessment_next_item(attempt or {})
    if not attempt or not item:
        return public_assessment_state(attempt_id, token, start=False)
    selected = parse_assessment_answer(answer.selected_key, item)
    if not selected:
        raise HTTPException(status_code=422, detail={"error": "invalid_assessment_answer"})
    recorded = record_assessment_response(attempt, item, answer.response_text or selected, selected)
    updated_attempt = recorded.get("attempt") or attempt
    if assessment_next_item(updated_attempt):
        return public_assessment_state(attempt_id, token, start=False)
    complete_assessment_attempt(updated_attempt)
    return public_assessment_state(attempt_id, token, start=False)


@app.get("/video-interview/{interview_id}", response_class=HTMLResponse)
def public_video_interview_page(interview_id: str, token: str | None = Query(default=None)):
    return HTMLResponse(public_video_interview_html())


@app.get("/video-interview/{interview_id}/state")
def public_video_interview_state_endpoint(interview_id: str, token: str | None = Query(default=None)):
    interview = fetch_public_async_video_interview(interview_id, token, start=True)
    return async_video_interview_public_state(interview)


@app.post("/video-interview/{interview_id}/consent")
def public_video_interview_consent_endpoint(interview_id: str, consent: PublicVideoInterviewConsent, token: str | None = Query(default=None)):
    interview = fetch_public_async_video_interview(interview_id, token, start=True)
    if not consent.consent:
        raise HTTPException(status_code=422, detail={"error": "recording_consent_required"})
    company = str(interview.get("company_code") or "").upper()
    payload = {
        "candidate_name": consent.candidate_name,
        "privacy_notice_version": consent.privacy_notice_version or "v1",
        "device_info": consent.device_info or {},
        "accepted_at": now_iso(),
    }
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                UPDATE candidate_interviews
                SET consent_accepted_at=COALESCE(consent_accepted_at, now()),
                    consent_payload=%s,
                    async_status=CASE WHEN async_status='completed' THEN async_status ELSE 'consented' END,
                    candidate_name=COALESCE(NULLIF(candidate_name, ''), NULLIF(%s, '')),
                    updated_at=now()
                WHERE interview_id=%s
                RETURNING *
                """,
                (Json(json_safe(payload)), str(consent.candidate_name or "").strip(), interview_id),
            )
            interview = dict(cur.fetchone() or interview)
        conn.commit()
    record_interview_event(
        interview_id,
        company,
        str(interview.get("app_key") or ""),
        "video_consent_accepted",
        payload,
        created_by_phone=digits(interview.get("phone")),
        actor_context=candidate_video_actor_context(interview),
        action="video_interview_consent",
        target_type="interview",
        target=interview_id,
    )
    return async_video_interview_public_state(interview)


@app.post("/video-interview/{interview_id}/responses")
async def public_video_interview_response_endpoint(interview_id: str, request: Request, token: str | None = Query(default=None)):
    response, video_bytes = await parse_public_video_interview_response_request(request)
    interview = fetch_public_async_video_interview(interview_id, token, start=True)
    if not interview.get("consent_accepted_at"):
        raise HTTPException(status_code=403, detail={"error": "recording_consent_required"})
    if interview.get("async_status") == "completed":
        raise HTTPException(status_code=409, detail={"error": "video_interview_already_completed"})
    questions = async_video_interview_questions(interview_id)
    response_mode = video_interview_response_mode(interview)
    question_id = str(response.question_id or "").strip()
    if response_mode == "single_video" and not question_id and questions:
        question_id = str(questions[0].get("question_id") or "")
    question = next((item for item in questions if str(item.get("question_id")) == question_id), None)
    if not question:
        raise HTTPException(status_code=404, detail={"error": "video_interview_question_not_found"})
    text = str(response.response_text or "").strip()
    transcript_text = str(response.transcript_text or "").strip()
    if not text and not transcript_text and not video_bytes:
        raise HTTPException(status_code=422, detail={"error": "video_answer_required"})
    with db_connect() as conn:
        with conn.cursor() as cur:
            if response_mode == "single_video":
                cur.execute(
                    """
                    SELECT *
                    FROM candidate_video_interview_responses
                    WHERE interview_id=%s
                    ORDER BY submitted_at DESC
                    LIMIT 1
                    """,
                    (interview_id,),
                )
            else:
                cur.execute(
                    """
                    SELECT *
                    FROM candidate_video_interview_responses
                    WHERE interview_id=%s AND question_id=%s
                    LIMIT 1
                    """,
                    (interview_id, question_id),
                )
            existing = dict(cur.fetchone() or {})
    config = interview.get("async_video_config") if isinstance(interview.get("async_video_config"), dict) else {}
    retake_policy = config.get("retake_policy") if isinstance(config.get("retake_policy"), dict) else {}
    if existing:
        if not retake_policy.get("enabled", True):
            raise HTTPException(status_code=409, detail={"error": "retake_not_allowed"})
        if int(existing.get("retake_count") or 0) >= int(retake_policy.get("max_retakes") or 0):
            raise HTTPException(status_code=409, detail={"error": "retake_limit_reached"})
    file_meta: dict[str, Any] = {}
    if video_bytes:
        file_meta = store_video_interview_file(
            interview=interview,
            question=question,
            video_bytes=video_bytes,
            filename=response.video_filename,
            mime_type=response.mime_type,
        )
    next_retake_count = int(existing.get("retake_count") or 0) + (1 if existing else 0)
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                INSERT INTO candidate_video_interview_responses (
                  interview_id, question_id, company_code, company_id, app_key, question_order,
                  response_text, transcript_text, video_file_id, local_path, storage_provider, storage_object_key,
                  original_filename, mime_type, size_bytes, content_sha256, duration_seconds,
                  transcript_status, transcript_error, transcript_model, transcript_language, transcript_metadata, transcribed_at,
                  retake_count, raw_json
                )
                VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,
                        CASE WHEN %s THEN 'pending' ELSE 'completed' END,
                        NULL,NULL,NULL,%s,CASE WHEN %s THEN NULL ELSE now() END,
                        %s,%s)
                ON CONFLICT (interview_id, question_id) DO UPDATE SET
                  response_text=EXCLUDED.response_text,
                  transcript_text=EXCLUDED.transcript_text,
                  video_file_id=COALESCE(EXCLUDED.video_file_id, candidate_video_interview_responses.video_file_id),
                  local_path=COALESCE(EXCLUDED.local_path, candidate_video_interview_responses.local_path),
                  storage_provider=COALESCE(EXCLUDED.storage_provider, candidate_video_interview_responses.storage_provider),
                  storage_object_key=COALESCE(EXCLUDED.storage_object_key, candidate_video_interview_responses.storage_object_key),
                  original_filename=COALESCE(EXCLUDED.original_filename, candidate_video_interview_responses.original_filename),
                  mime_type=COALESCE(EXCLUDED.mime_type, candidate_video_interview_responses.mime_type),
                  size_bytes=COALESCE(EXCLUDED.size_bytes, candidate_video_interview_responses.size_bytes),
                  content_sha256=COALESCE(EXCLUDED.content_sha256, candidate_video_interview_responses.content_sha256),
                  duration_seconds=COALESCE(EXCLUDED.duration_seconds, candidate_video_interview_responses.duration_seconds),
                  transcript_status=EXCLUDED.transcript_status,
                  transcript_error=NULL,
                  transcript_model=EXCLUDED.transcript_model,
                  transcript_language=EXCLUDED.transcript_language,
                  transcript_metadata=EXCLUDED.transcript_metadata,
                  transcribed_at=EXCLUDED.transcribed_at,
                  retake_count=EXCLUDED.retake_count,
                  raw_json=EXCLUDED.raw_json,
                  submitted_at=now(),
                  updated_at=now()
                RETURNING *
                """,
                (
                    interview_id,
                    question_id,
                    interview.get("company_code"),
                    interview.get("company_code"),
                    interview.get("app_key"),
                    int(question.get("question_order") or 0),
                    text or None,
                    transcript_text or None,
                    file_meta.get("file_id") or None,
                    file_meta.get("local_path"),
                    file_meta.get("storage_provider") or "local",
                    file_meta.get("storage_object_key"),
                    file_meta.get("original_filename"),
                    file_meta.get("mime_type") or response.mime_type,
                    file_meta.get("size_bytes"),
                    file_meta.get("content_sha256"),
                    response.duration_seconds,
                    bool(video_bytes),
                    Json({}),
                    bool(video_bytes),
                    next_retake_count,
                    Json(
                        json_safe(
                            {
                                "metadata": response.metadata or {},
                                "question": public_video_question_payload(question),
                                "questions": [public_video_question_payload(item) for item in questions],
                                "response_mode": response_mode,
                            }
                        )
                    ),
                ),
            )
            saved = dict(cur.fetchone() or {})
            cur.execute(
                """
                UPDATE candidate_interviews
                SET async_status='in_progress',
                    updated_at=now()
                WHERE interview_id=%s AND async_status <> 'completed'
                RETURNING *
                """,
                (interview_id,),
            )
            interview = dict(cur.fetchone() or interview)
        conn.commit()
    record_interview_event(
        interview_id,
        str(interview.get("company_code") or ""),
        str(interview.get("app_key") or ""),
        "video_response_submitted",
        {"question_id": question_id, "response_id": str(saved.get("response_id") or ""), "has_video": bool(file_meta), "retake_count": next_retake_count, "response_mode": response_mode},
        created_by_phone=digits(interview.get("phone")),
        actor_context=candidate_video_actor_context(interview),
        action="video_interview_response_submitted",
        target_type="interview" if response_mode == "single_video" else "question",
        target=interview_id if response_mode == "single_video" else question_id,
    )
    return async_video_interview_public_state(interview)


@app.post("/video-interview/{interview_id}/complete")
def public_video_interview_complete_endpoint(interview_id: str, token: str | None = Query(default=None)):
    interview = fetch_public_async_video_interview(interview_id, token, start=True)
