# ---------------------------------------------------------------------------
# HR Tasks & delivery follow-up (outbound layer, Phase B).
#
# Visible "what should HR do next?" surface for the shared outbound delivery
# layer: tasks raised when a critical employee message could not be delivered,
# plus the messages still needing follow-up. Company-scoped + manager-scope
# aware (a scoped manager only sees their own people; company-wide tasks stay
# with HR). Reads always work — they simply return empty until flows are wired.
# ---------------------------------------------------------------------------

_POSTHIRE_MODULES = ("onboarding", "attendance", "shifts", "payroll", "leave", "compliance")


def _hr_tasks_context(context: dict[str, Any], *, manage: bool = False) -> str:
    """Gate the HR-tasks surface: the company must have a post-hire module and the
    user must hold a matching read (or, for resolve, a manage) permission."""
    company = context["company_code"]
    readable = [m for m in _POSTHIRE_MODULES if company_has_module(company, m) and dashboard_context_has_permission(context, f"{m}.read")]
    if not readable:
        raise HTTPException(status_code=403, detail={"error": "module_disabled", "message": "This module is not enabled for your company."})
    if manage:
        can_manage = dashboard_context_has_permission(context, "users.manage") or any(
            dashboard_context_has_permission(context, f"{m}.manage") for m in _POSTHIRE_MODULES
        )
        if not can_manage:
            raise HTTPException(status_code=403, detail={"error": "permission_denied", "message": "You do not have access to do that."})
    return company


@app.get("/dashboard/hr-tasks")
def dashboard_hr_tasks(status: str = "open", context: dict[str, Any] = Depends(dashboard_context)):
    company = _hr_tasks_context(context)
    statuses = ["open"] if status == "open" else [s.strip() for s in status.split(",") if s.strip()]
    scope = context.get("scope")
    tasks = _outbound_delivery.list_hr_tasks(company_code=company, scope=scope, statuses=statuses, limit=200)
    return json_safe({"ok": True, "company_code": company, "open_count": _outbound_delivery.hr_task_open_count(company_code=company, scope=scope), "tasks": tasks})


@app.post("/dashboard/hr-tasks/{task_id}/resolve")
def dashboard_hr_task_resolve(task_id: str, request: HrTaskResolveRequest, context: dict[str, Any] = Depends(dashboard_context)):
    company = _hr_tasks_context(context, manage=True)
    result = _outbound_delivery.resolve_hr_task(company_code=company, task_id=task_id, status=request.status, resolver_phone=context.get("hr_phone"))
    if not result.get("ok"):
        raise HTTPException(status_code=404, detail={"error": result.get("error") or "task_not_found", "message": "This task was not found."})
    record_admin_audit(context, "hr_task_resolved", summary=f"Marked HR task {request.status}.", target_type="hr_task", target=task_id, details={"status": request.status, "source": result.get("task", {}).get("source")})
    return json_safe(result)


@app.get("/dashboard/outbound/needs-follow-up")
def dashboard_outbound_needs_follow_up(context: dict[str, Any] = Depends(dashboard_context)):
    company = _hr_tasks_context(context)
    scope = context.get("scope")
    messages = _outbound_delivery.list_needs_follow_up(company_code=company, scope=scope, limit=200)
    return json_safe({"ok": True, "company_code": company, "count": len(messages), "messages": messages})


# ---------------------------------------------------------------------------
# Setup Console (B) — client-facing workspace readiness checklist.
#
# Company-scoped, read-only guidance for the company Owner: "what should I do
# next to get my Wathefni workspace ready, and why?". It composes the company's
# own data (jobs, employees, compliance docs, team, WhatsApp) through the normal
# session auth — no platform-admin access, no cross-company reads, no mutations.
# Steps are module-aware (only shown for enabled modules); the frontend hides the
# card once every required step is done.
# ---------------------------------------------------------------------------

SETUP_READINESS_POSTHIRE_MODULES = {"onboarding", "attendance", "leave", "shifts", "payroll", "analytics", "compliance"}


@app.get("/dashboard/setup/readiness")
def dashboard_setup_readiness(context: dict[str, Any] = Depends(dashboard_context)):
    company = context["company_code"]
    modules = configured_company_modules(company)
    counts: dict[str, int] = {}
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute("SELECT count(*) AS n FROM dashboard_users WHERE company_code=%s AND status <> 'disabled'", (company,))
            counts["users"] = int((cur.fetchone() or {}).get("n") or 0)
            cur.execute("SELECT count(*) AS n FROM dashboard_whatsapp_identities WHERE company_code=%s AND status='active'", (company,))
            counts["whatsapp"] = int((cur.fetchone() or {}).get("n") or 0)
            if "pre_hiring" in modules:
                cur.execute("SELECT count(*) AS n FROM positions WHERE company_code=%s", (company,))
                counts["positions"] = int((cur.fetchone() or {}).get("n") or 0)
            if modules & SETUP_READINESS_POSTHIRE_MODULES:
                cur.execute("SELECT count(*) AS n FROM employees WHERE company_code=%s", (company,))
                counts["employees"] = int((cur.fetchone() or {}).get("n") or 0)
            if "compliance" in modules:
                cur.execute("SELECT count(*) AS n FROM compliance_documents WHERE company_code=%s", (company,))
                counts["compliance_documents"] = int((cur.fetchone() or {}).get("n") or 0)

    steps: list[dict[str, Any]] = []

    def add(key: str, title: str, done: bool, why: str, action_label: str, action_page: str, *, optional: bool = False) -> None:
        steps.append({
            "key": key,
            "title": title,
            "done": bool(done),
            "optional": optional,
            "why": why,
            "action_label": action_label,
            "action_page": action_page,
        })

    if "pre_hiring" in modules:
        add("first_job", "Post your first job", counts.get("positions", 0) > 0,
            "Create a job and share its application link or QR code so candidates can start applying.",
            "Create a job", "jobs")
    if modules & SETUP_READINESS_POSTHIRE_MODULES:
        add("first_employee", "Add your first employee", counts.get("employees", 0) > 0,
            "Hire a candidate or import employees to unlock onboarding, attendance, leave, and payroll.",
            "View employees", "employees")
    if "compliance" in modules:
        add("compliance_docs", "Track employee documents", counts.get("compliance_documents", 0) > 0,
            "Add documents like Civil ID and residency so Wathefni can flag what is missing or expiring.",
            "Open Compliance", "compliance")
    add("team", "Invite your HR team", counts.get("users", 0) >= 2,
        "Give your colleagues access so your whole HR team can manage hiring and employees.",
        "Invite a teammate", "settings", optional=True)
    add("whatsapp", "Connect WhatsApp", counts.get("whatsapp", 0) >= 1,
        "Act on candidates and employees from WhatsApp, and receive reminders where you already work.",
        "Link WhatsApp", "settings", optional=True)

    required = [step for step in steps if not step["optional"]]
    ready = all(step["done"] for step in required) if required else True
    return {
        "company_code": company,
        "ready": ready,
        "completed": sum(1 for step in steps if step["done"]),
        "total": len(steps),
        "steps": steps,
    }


# ---------------------------------------------------------------------------
# Setup Console V1 (A) — super-admin provisioning console (Wathefni operators).
#
# Lets a platform operator onboard a new client company without hand-editing DB
# rows or workspace config: create/select a company, enable modules, seed the
# first Owner, set timezone/basic settings, optionally link the Owner's WhatsApp,
# and see readiness. It is a thin, fully audited orchestration over EXISTING
# tables (companies, company_modules, company_settings, dashboard_users +
# dashboard_user_invites, dashboard_whatsapp_identities) — no new source of truth.
#
# Strictly gated, fail-closed:
#   * behind WATHEFNI_SETUP_CONSOLE_ENABLED (default off -> 404, feature hidden)
#   * only an operator presenting the configured dashboard token AND an
#     allowlisted platform-admin phone (WATHEFNI_PLATFORM_ADMINS) may use it
#   * company-owner session tokens are NOT platform admins
# Every mutation writes record_admin_audit scoped to the TARGET company.
# ---------------------------------------------------------------------------

SETUP_CONSOLE_MODULES = (
    "pre_hiring", "assessments", "video_interviews", "onboarding", "compliance",
    "shifts", "attendance", "leave", "payroll", "analytics",
)
SETUP_COMPANY_CODE_RE = re.compile(r"^[A-Z][A-Z0-9_]{1,31}$")


def setup_console_enabled() -> bool:
    return os.environ.get("WATHEFNI_SETUP_CONSOLE_ENABLED", "").strip().lower() in {"1", "true", "yes", "on"}


def platform_admin_phones() -> set[str]:
    raw = os.environ.get("WATHEFNI_PLATFORM_ADMINS", "") or ""
    return {digits(part) for part in re.split(r"[,\s]+", raw) if digits(part)}


def superadmin_context(
    authorization: str | None = Header(default=None),
    x_dashboard_token: str | None = Header(default=None, alias="X-Dashboard-Token"),
    x_hr_phone: str | None = Header(default=None, alias="X-HR-Phone"),
) -> dict[str, Any]:
    """Platform-admin gate for the Setup Console. Fail-closed at every step."""
    ensure_schema()
    if not setup_console_enabled():
        raise HTTPException(status_code=404, detail={"error": "not_found", "message": "Not found."})
    provided = bearer_token(authorization) or str(x_dashboard_token or "").strip()
    configured = dashboard_configured_token()
    if not configured or not provided or provided != configured:
        raise HTTPException(status_code=401, detail={"error": "dashboard_auth_failed", "message": "Platform admin access was rejected."})
    phone = digits(x_hr_phone)
    allow = platform_admin_phones()
    if not phone or not allow or phone not in allow:
        raise HTTPException(status_code=403, detail={"error": "not_platform_admin", "message": "This account is not a Wathefni platform administrator."})
    return {
        "is_platform_admin": True,
        "actor_phone": phone,
        "hr_phone": phone,
        "actor_user_id": f"platform_admin:{phone}",
        "actor_email": "",
        "actor_role": "platform_admin",
        "hr_user": {"phone": phone, "role": "platform_admin", "name": "Wathefni Platform Admin", "status": "active"},
    }


def _setup_audit_context(superadmin: dict[str, Any], company_code: str) -> dict[str, Any]:
    """Audit as the platform admin, scoped to the TARGET company so each change is
    traceable on the company's own audit surface."""
    return {**superadmin, "company_code": company_code}


def _setup_company_exists(company_code: str) -> bool:
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute("SELECT 1 FROM companies WHERE company_code=%s LIMIT 1", (company_code,))
            return bool(cur.fetchone())


def _setup_normalize_company_code(raw: str | None) -> str:
    company = str(raw or "").strip().upper()
    if not SETUP_COMPANY_CODE_RE.match(company):
        raise HTTPException(status_code=422, detail={"error": "invalid_company_code", "message": "Company code must start with a letter and use only A–Z, 0–9, or underscore (max 32 characters)."})
    return company


def setup_console_company_readiness(company_code: str) -> dict[str, Any]:
    """Read-only readiness snapshot: what's done and what's left to make a company
    ready. Composes the existing tables; never mutates."""
    company = str(company_code or "").strip().upper()
    name: str | None = None
    modules: list[str] = []
    owners = 0
    whatsapp_links = 0
    exists = False
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute("SELECT company_code, name FROM companies WHERE company_code=%s LIMIT 1", (company,))
            crow = cur.fetchone()
            exists = bool(crow)
            name = (dict(crow).get("name") if crow else None)
            cur.execute("SELECT module_key FROM company_modules WHERE company_code=%s AND enabled IS TRUE ORDER BY module_key", (company,))
            modules = [str(r["module_key"]) for r in cur.fetchall()]
            cur.execute("SELECT count(*) AS n FROM dashboard_users WHERE company_code=%s AND role='owner' AND status <> 'disabled'", (company,))
            owners = int((cur.fetchone() or {}).get("n") or 0)
            cur.execute("SELECT count(*) AS n FROM dashboard_whatsapp_identities WHERE company_code=%s AND status='active'", (company,))
            whatsapp_links = int((cur.fetchone() or {}).get("n") or 0)
    settings = get_company_settings(company)
    timezone_value = str(settings.get("timezone") or "").strip()
    steps = [
        {"key": "company", "label": "Company created", "done": exists},
        {"key": "modules", "label": "At least one module enabled", "done": bool(modules)},
        {"key": "owner", "label": "Owner account seeded", "done": owners > 0},
        {"key": "timezone", "label": "Timezone set", "done": bool(timezone_value)},
        {"key": "whatsapp", "label": "Owner WhatsApp linked", "done": whatsapp_links > 0, "optional": True},
    ]
    required_done = all(step["done"] for step in steps if not step.get("optional"))
    return {
        "company_code": company,
        "name": name,
        "exists": exists,
        "modules": modules,
        "module_display": {key: MODULE_DISPLAY_NAMES.get(key, key) for key in modules},
        "owners": owners,
        "whatsapp_links": whatsapp_links,
        "timezone": timezone_value or None,
        "steps": steps,
        "ready": bool(exists and required_done),
    }


class SetupCompanyCreateRequest(BaseModel):
    company_code: str
    name: str | None = None


class SetupModulesRequest(BaseModel):
    modules: list[str] = Field(default_factory=list)


class SetupSettingsRequest(BaseModel):
    timezone: str | None = None


class SetupOwnerRequest(BaseModel):
    email: str
    name: str | None = None
    phone: str | None = None


class SetupWhatsAppLinkRequest(BaseModel):
    phone: str
    email: str | None = None


@app.get("/dashboard/superadmin/setup/companies")
def setup_console_list_companies(superadmin: dict[str, Any] = Depends(superadmin_context)):
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute("SELECT company_code FROM companies ORDER BY company_code")
            codes = [str(r["company_code"]) for r in cur.fetchall()]
    return {"companies": [setup_console_company_readiness(code) for code in codes]}


@app.get("/dashboard/superadmin/setup/companies/{company_code}")
def setup_console_company_detail(company_code: str, superadmin: dict[str, Any] = Depends(superadmin_context)):
    company = str(company_code or "").strip().upper()
    if not _setup_company_exists(company):
        raise HTTPException(status_code=404, detail={"error": "company_not_found", "message": "That company does not exist yet."})
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT user_id, company_code, email, name, phone, role, status, last_active_at, invited_at, accepted_at, created_at, metadata
                FROM dashboard_users WHERE company_code=%s
                ORDER BY CASE status WHEN 'active' THEN 0 WHEN 'invited' THEN 1 ELSE 2 END, lower(name), email
                LIMIT 500
                """,
                (company,),
            )
            users = [dashboard_user_public(dict(row)) for row in cur.fetchall()]
    return {
        "readiness": setup_console_company_readiness(company),
        "available_modules": [{"key": key, "label": MODULE_DISPLAY_NAMES.get(key, key)} for key in SETUP_CONSOLE_MODULES],
        "users": users,
    }


@app.post("/dashboard/superadmin/setup/companies")
def setup_console_create_company(request: SetupCompanyCreateRequest, superadmin: dict[str, Any] = Depends(superadmin_context)):
    company = _setup_normalize_company_code(request.company_code)
    provided_name = str(request.name or "").strip()
    insert_name = provided_name or company.title()
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                INSERT INTO companies (company_code, name, metadata, raw_json, created_at, updated_at)
                VALUES (%s,%s,%s,%s,now(),now())
                ON CONFLICT (company_code)
                DO UPDATE SET name = COALESCE(NULLIF(%s,''), companies.name), updated_at = now()
                RETURNING (xmax = 0) AS created
                """,
                (company, insert_name, Json({}), Json({}), provided_name),
            )
            created = bool((cur.fetchone() or {}).get("created"))
        conn.commit()
    record_admin_audit(
        _setup_audit_context(superadmin, company),
        "setup_company_created" if created else "setup_company_selected",
        summary=(f"Created company {company}." if created else f"Selected existing company {company}.") + (f" Name: {provided_name}." if provided_name else ""),
        target_type="company",
        target=company,
        details={"company_code": company, "name": provided_name or insert_name, "created": created},
    )
    return {"ok": True, "created": created, "readiness": setup_console_company_readiness(company)}


@app.patch("/dashboard/superadmin/setup/companies/{company_code}/modules")
def setup_console_set_modules(company_code: str, request: SetupModulesRequest, superadmin: dict[str, Any] = Depends(superadmin_context)):
    company = str(company_code or "").strip().upper()
    if not _setup_company_exists(company):
        raise HTTPException(status_code=404, detail={"error": "company_not_found", "message": "That company does not exist yet."})
    requested: list[str] = []
    invalid: list[str] = []
    for module in request.modules or []:
        key = normalize_module_key(module)
        if key in SETUP_CONSOLE_MODULES:
            requested.append(key)
        else:
            invalid.append(str(module))
    if invalid:
        raise HTTPException(status_code=422, detail={"error": "unknown_module", "message": f"Unknown module(s): {', '.join(invalid)}."})
    requested = sorted(set(requested))
    existing_tz = (get_company_settings(company).get("timezone") or "Asia/Kuwait")
    with db_connect() as conn:
        with conn.cursor() as cur:
            for key in requested:
                settings = {"timezone": existing_tz, "reminder_hours_before": 2} if key == "shifts" else {}
                cur.execute(
                    """
                    INSERT INTO company_modules (company_code, module_key, enabled, source, settings, updated_at)
                    VALUES (%s,%s,true,'setup_console',%s,now())
                    ON CONFLICT (company_code, module_key)
                    DO UPDATE SET enabled=true, source='setup_console', updated_at=now()
                    """,
                    (company, key, Json(settings)),
                )
            cur.execute(
                "UPDATE company_modules SET enabled=false, source='setup_console', updated_at=now() "
                "WHERE company_code=%s AND enabled IS TRUE AND module_key <> ALL(%s)",
                (company, requested),
            )
        conn.commit()
    record_admin_audit(
        _setup_audit_context(superadmin, company),
        "setup_modules_updated",
        summary=f"Enabled modules for {company}: {', '.join(requested) or 'none'}.",
        target_type="company",
        target=company,
        details={"company_code": company, "modules": requested},
    )
    return {"ok": True, "modules": requested, "readiness": setup_console_company_readiness(company)}


@app.patch("/dashboard/superadmin/setup/companies/{company_code}/settings")
def setup_console_set_settings(company_code: str, request: SetupSettingsRequest, superadmin: dict[str, Any] = Depends(superadmin_context)):
    company = str(company_code or "").strip().upper()
    if not _setup_company_exists(company):
        raise HTTPException(status_code=404, detail={"error": "company_not_found", "message": "That company does not exist yet."})
    changes: list[str] = []
    if request.timezone is not None:
        timezone_value = str(request.timezone).strip()
        if not timezone_value:
            raise HTTPException(status_code=422, detail={"error": "invalid_timezone", "message": "Enter a timezone, e.g. Asia/Kuwait."})
        set_company_setting(company, "timezone", timezone_value)
        changes.append(f"timezone → {timezone_value}")
    if not changes:
        raise HTTPException(status_code=422, detail={"error": "no_update", "message": "No setting was provided."})
    record_admin_audit(
        _setup_audit_context(superadmin, company),
        "setup_settings_updated",
        summary=f"Updated {company} settings: {', '.join(changes)}.",
        target_type="company",
        target=company,
        details={"company_code": company, "changes": changes},
    )
    return {"ok": True, "readiness": setup_console_company_readiness(company)}


@app.post("/dashboard/superadmin/setup/companies/{company_code}/owner")
def setup_console_seed_owner(company_code: str, request: SetupOwnerRequest, superadmin: dict[str, Any] = Depends(superadmin_context)):
    company = str(company_code or "").strip().upper()
    if not _setup_company_exists(company):
        raise HTTPException(status_code=404, detail={"error": "company_not_found", "message": "That company does not exist yet."})
    email = normalize_email(request.email)
    if not email or "@" not in email:
        raise HTTPException(status_code=422, detail={"error": "invalid_email", "message": "Enter a valid email address."})
    invite_token = secrets.token_urlsafe(32)
    expires_at = now_utc() + timedelta(days=14)
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                INSERT INTO dashboard_users (company_code, email, name, phone, role, status, invited_by_user_id, invited_at, updated_at)
                VALUES (%s,%s,%s,%s,'owner','invited',NULL,now(),now())
                ON CONFLICT (company_code, email)
                DO UPDATE SET role='owner',
                              name=CASE WHEN dashboard_users.name='' THEN EXCLUDED.name ELSE dashboard_users.name END,
                              phone=COALESCE(EXCLUDED.phone, dashboard_users.phone),
                              status=CASE WHEN dashboard_users.status='disabled' THEN dashboard_users.status ELSE dashboard_users.status END,
                              invited_at=COALESCE(dashboard_users.invited_at, now()),
                              updated_at=now()
                RETURNING *
                """,
                (company, email, str(request.name or "").strip(), digits(request.phone) or None),
            )
            user = dict(cur.fetchone() or {})
            cur.execute(
                "UPDATE dashboard_user_invites SET status='superseded' WHERE company_code=%s AND email=%s AND status='pending'",
                (company, email),
            )
            cur.execute(
                """
                INSERT INTO dashboard_user_invites (company_code, email, role, token_hash, invited_by_user_id, expires_at, metadata)
                VALUES (%s,%s,'owner',%s,NULL,%s,%s)
                RETURNING invite_id, company_code, email, role, status, expires_at, created_at
                """,
                (company, email, dashboard_token_hash(invite_token), expires_at, Json({"invite_token_preview": invite_token, "seeded_via": "setup_console"})),
            )
            invite = dict(cur.fetchone() or {})
        conn.commit()
    record_admin_audit(
        _setup_audit_context(superadmin, company),
        "setup_owner_seeded",
        summary=f"Seeded Owner {email} for {company}.",
        target_type="team_member",
        target=email,
        details={"company_code": company, "email": email, "role": "owner"},
    )
    return {"ok": True, "user": dashboard_user_public(user), "invite": json_safe(invite), "invite_token": invite_token, "readiness": setup_console_company_readiness(company)}


@app.post("/dashboard/superadmin/setup/companies/{company_code}/whatsapp-link")
def setup_console_link_whatsapp(company_code: str, request: SetupWhatsAppLinkRequest, superadmin: dict[str, Any] = Depends(superadmin_context)):
    company = str(company_code or "").strip().upper()
    if not _setup_company_exists(company):
        raise HTTPException(status_code=404, detail={"error": "company_not_found", "message": "That company does not exist yet."})
    phone = digits(request.phone)
    if not phone:
        raise HTTPException(status_code=422, detail={"error": "phone_required", "message": "Enter a valid WhatsApp phone."})
    target_email = normalize_email(request.email) if request.email else ""
    with db_connect() as conn:
        with conn.cursor() as cur:
            if target_email:
                cur.execute(
                    "SELECT user_id FROM dashboard_users WHERE company_code=%s AND email=%s AND status <> 'disabled' LIMIT 1",
                    (company, target_email),
                )
            else:
                cur.execute(
                    "SELECT user_id FROM dashboard_users WHERE company_code=%s AND role='owner' AND status <> 'disabled' "
                    "ORDER BY CASE status WHEN 'active' THEN 0 ELSE 1 END, created_at ASC LIMIT 1",
                    (company,),
                )
            owner = cur.fetchone()
            if not owner:
                raise HTTPException(status_code=422, detail={"error": "owner_required", "message": "Seed an Owner for this company before linking a WhatsApp number."})
            user_id = owner["user_id"]
            cur.execute(
                """
                INSERT INTO dashboard_whatsapp_identities (company_code, user_id, phone, status, updated_at)
                VALUES (%s,%s,%s,'active',now())
                ON CONFLICT (company_code, phone)
                DO UPDATE SET user_id=EXCLUDED.user_id, status='active', updated_at=now()
                """,
                (company, user_id, phone),
            )
            cur.execute("UPDATE dashboard_users SET phone=%s, updated_at=now() WHERE user_id=%s AND company_code=%s", (phone, user_id, company))
        conn.commit()
    record_admin_audit(
        _setup_audit_context(superadmin, company),
        "setup_owner_whatsapp_linked",
        summary=f"Linked WhatsApp {phone} to the Owner of {company}.",
        target_type="whatsapp_identity",
        target=phone,
        details={"company_code": company, "phone": phone, "user_id": str(user_id)},
    )
    return {"ok": True, "phone": phone, "user_id": str(user_id), "readiness": setup_console_company_readiness(company)}


def bounded_limit(value: int, *, default: int = 50, maximum: int = 200) -> int:
    try:
        parsed = int(value)
    except Exception:
        parsed = default
    return max(1, min(parsed, maximum))


def dashboard_candidate_name(row: dict[str, Any]) -> str | None:
    name = candidate_name_from_row(row)
    return None if name == "Unknown" else name


def prehire_application_summary(row: dict[str, Any], *, include_raw: bool = False, include_assessment: bool = True) -> dict[str, Any]:
    raw_json = row.get("raw_json") if isinstance(row.get("raw_json"), dict) else {}
    candidate_raw = row.get("candidate_raw_json") if isinstance(row.get("candidate_raw_json"), dict) else {}
    screening = raw_json.get("screening") if isinstance(raw_json.get("screening"), dict) else {}
    profile = row.get("candidate_profile") if isinstance(row.get("candidate_profile"), dict) else {}
    cv = raw_json.get("cv") if isinstance(raw_json.get("cv"), dict) else {}
    cv_storage = cv.get("storage") if isinstance(cv.get("storage"), dict) else {}
    assessment = row.get("assessment_json") if isinstance(row.get("assessment_json"), dict) else (raw_json.get("assessment") if isinstance(raw_json.get("assessment"), dict) else {})
    latest_interview = row.get("interview_json") if isinstance(row.get("interview_json"), dict) else None
    interview = candidate_interview_summary(latest_interview) if latest_interview else (raw_json.get("interview") if isinstance(raw_json.get("interview"), dict) else {})
    payload = {
        "app_key": row.get("app_key"),
        "company_code": row.get("company_code"),
        "phone": row.get("phone"),
        "candidate": {
            "name": dashboard_candidate_name(row),
            "email": row.get("candidate_email") or candidate_raw.get("email"),
            "profile": json_safe(profile) if include_raw else None,
        },
        "position": {
            "code": row.get("position_code"),
            "title": row.get("position_title") or row.get("position_code"),
        },
        "status": row.get("status"),
        "current_step": row.get("current_step"),
        "screening_status": row.get("screening_status") or screening.get("status"),
        "data_source": row.get("data_source") or raw_json.get("data_source") or PRODUCTION_DATA_SOURCE,
        "lead_quality": application_lead_quality(row),
        "cv": {
            "received": bool(row.get("cv_received") is True or cv),
            "storage_status": ((cv.get("storage") or {}).get("status") if isinstance(cv.get("storage"), dict) else None),
            "filename": cv.get("filename"),
            "mime_type": cv_storage.get("mime_type"),
            "size_bytes": cv_storage.get("size_bytes"),
            "preview_available": bool(cv_storage.get("url") or cv.get("path")),
        },
        "ingested_at": json_safe(row.get("ingested_at")),
        "updated_at": json_safe(row.get("updated_at")),
    }
    if include_assessment:
        payload["assessment"] = json_safe(assessment) if assessment else None
    payload["interview"] = json_safe(interview) if interview else None
    rank_evaluation = row.get("rank_evaluation_json") if isinstance(row.get("rank_evaluation_json"), dict) else None
    if rank_evaluation:
        payload["ranking"] = rank_evaluation
    if include_raw:
        payload["raw_json"] = json_safe(raw_json)
        payload["candidate_raw_json"] = json_safe(candidate_raw)
    else:
        payload["candidate"] = {key: value for key, value in payload["candidate"].items() if value is not None}
    return payload


def dashboard_delivery_status(row: dict[str, Any]) -> str:
    status = str(row.get("status") or "").strip().lower()
    error = str(row.get("last_error") or "").strip().lower()
    if status == "sent":
        return "sent"
    if error == "conversation_closed":
        return "blocked_closed_conversation"
    if error == "conversation_inactive":
        return "stale_conversation"
    if error in {"missing_candidate_conversation_id", "no_usable_conversation_id"}:
        return "no_usable_conversation"
    if status == "failed":
        return "failed"
    return status or "unknown"


def dashboard_apply_whatsapp_number() -> str:
    return digits(os.environ.get("WATHEFNI_APPLY_WHATSAPP_NUMBER") or os.environ.get("WATHEFNI_WHATSAPP_NUMBER") or "96599338566")


def dashboard_apply_link(apply_code: str | None) -> str | None:
    code = str(apply_code or "").strip()
    number = dashboard_apply_whatsapp_number()
    if not code or not number:
        return None
    return f"https://wa.me/{number}?text={urllib.parse.quote(code)}"


def dashboard_position_summary(row: dict[str, Any]) -> dict[str, Any]:
    company = str(row.get("company_code") or "WATHEFNI").upper()
    position_code = str(row.get("position_code") or "").strip()
    apply_code = str(row.get("apply_code") or "").strip() or (f"APPLY-{company}-{position_code}" if position_code else None)
    status = str(row.get("status") or "").strip().lower() or ("open" if int(row.get("active_count") or 0) > 0 else "closed")
    latest_name = row.get("latest_candidate_name") or row.get("latest_phone")
    return {
        "company_code": company,
        "position_code": position_code,
        "position_title": row.get("position_title") or row.get("title") or position_code,
        "job_key": row.get("job_key") or position_code,
        "application_key": row.get("application_key") or apply_code,
        "apply_code": apply_code,
        "application_link": dashboard_apply_link(apply_code),
        "qr_value": dashboard_apply_link(apply_code),
        "status": status,
        "description": row.get("description"),
        "requirements": json_safe(row.get("requirements") or []),
        "application_count": int(row.get("application_count") or 0),
        "active_count": int(row.get("active_count") or 0),
        "latest_application_at": json_safe(row.get("latest_application_at")),
        "latest_applicant": latest_name,
        "latest_applicant_app_key": row.get("latest_applicant_app_key"),
        "created_at": json_safe(row.get("created_at")),
        "updated_at": json_safe(row.get("updated_at")),
        "stage_counts": json_safe(row.get("stage_counts") or []),
        "recent_applicants": json_safe(row.get("recent_applicants") or []),
        "notifications": json_safe(row.get("notifications") or []),
    }


def dashboard_prehire_positions_payload(company: str, *, limit: int = 200) -> list[dict[str, Any]]:
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                WITH app_stats AS (
                  SELECT
                    company_code,
                    position_code,
                    COALESCE(MAX(position_title), position_code) AS position_title,
                    COUNT(*) AS application_count,
                    COUNT(*) FILTER (WHERE status NOT IN ('hired','rejected')) AS active_count,
                    MAX(updated_at) AS latest_application_at
                  FROM applications
                  WHERE company_code=%s
                    AND COALESCE(data_source, raw_json->>'data_source', 'production')='production'
                    AND (cv_received IS TRUE OR jsonb_typeof(raw_json->'cv') = 'object')
                  GROUP BY company_code, position_code
                ),
                latest AS (
                  SELECT DISTINCT ON (a.company_code, a.position_code)
                    a.company_code,
                    a.position_code,
                    a.app_key AS latest_applicant_app_key,
                    a.phone AS latest_phone,
                    COALESCE(NULLIF(c.name, ''), a.raw_json->>'candidate_name', a.raw_json->>'name') AS latest_candidate_name
                  FROM applications a
                  LEFT JOIN candidates c ON c.phone=a.phone
                  WHERE a.company_code=%s
                    AND COALESCE(a.data_source, a.raw_json->>'data_source', 'production')='production'
                    AND (a.cv_received IS TRUE OR jsonb_typeof(a.raw_json->'cv') = 'object')
                  ORDER BY a.company_code, a.position_code, a.ingested_at DESC NULLS LAST, a.updated_at DESC NULLS LAST
                )
                SELECT
                  COALESCE(p.company_code, s.company_code) AS company_code,
                  COALESCE(p.position_code, s.position_code) AS position_code,
                  COALESCE(p.title, s.position_title, p.position_code, s.position_code) AS position_title,
                  p.status,
                  p.apply_code,
                  p.requirements,
                  p.metadata,
                  p.raw_json,
                  p.created_at,
                  p.updated_at,
                  COALESCE(s.application_count, 0) AS application_count,
                  COALESCE(s.active_count, 0) AS active_count,
                  s.latest_application_at,
                  l.latest_applicant_app_key,
                  l.latest_phone,
                  l.latest_candidate_name
                FROM positions p
                FULL OUTER JOIN app_stats s ON s.company_code=p.company_code AND s.position_code=p.position_code
                LEFT JOIN latest l ON l.company_code=COALESCE(p.company_code, s.company_code) AND l.position_code=COALESCE(p.position_code, s.position_code)
                WHERE COALESCE(p.company_code, s.company_code)=%s
                ORDER BY COALESCE(s.active_count, 0) DESC, COALESCE(s.application_count, 0) DESC, COALESCE(p.updated_at, s.latest_application_at) DESC NULLS LAST
                LIMIT %s
                """,
                (company, company, company, limit),
            )
            rows = [dict(row) for row in cur.fetchall()]
            cur.execute(
                """
                SELECT position_code, status, COUNT(*) AS count
                FROM applications
                WHERE company_code=%s
                  AND COALESCE(data_source, raw_json->>'data_source', 'production')='production'
                  AND (cv_received IS TRUE OR jsonb_typeof(raw_json->'cv') = 'object')
                GROUP BY position_code, status
                """,
                (company,),
            )
            stage_counts: dict[str, list[dict[str, Any]]] = {}
            for row in cur.fetchall():
                stage_counts.setdefault(str(row.get("position_code") or ""), []).append({"status": row.get("status"), "count": int(row.get("count") or 0)})
            cur.execute(
                """
                SELECT *
                FROM (
                  SELECT
                    a.position_code,
                    a.app_key,
                    a.phone,
                    COALESCE(NULLIF(c.name, ''), a.raw_json->>'candidate_name', a.raw_json->>'name') AS candidate_name,
                    c.email AS candidate_email,
                    a.status,
                    a.ingested_at,
                    a.updated_at,
                    ROW_NUMBER() OVER (PARTITION BY a.position_code ORDER BY a.ingested_at DESC NULLS LAST, a.updated_at DESC NULLS LAST) AS rn
                  FROM applications a
                  LEFT JOIN candidates c ON c.phone=a.phone
                  WHERE a.company_code=%s
                    AND COALESCE(a.data_source, a.raw_json->>'data_source', 'production')='production'
                    AND (a.cv_received IS TRUE OR jsonb_typeof(a.raw_json->'cv') = 'object')
                ) recent
                WHERE rn <= 5
                ORDER BY position_code, rn
                """,
                (company,),
            )
            recent: dict[str, list[dict[str, Any]]] = {}
            for row in cur.fetchall():
                item = json_safe(dict(row))
                recent.setdefault(str(row.get("position_code") or ""), []).append(item)
            cur.execute(
                """
                SELECT *
                FROM (
                  SELECT
                    a.position_code,
                    ode.delivery_id,
                    ode.target_phone,
                    ode.status,
                    ode.last_error,
                    ode.created_at,
                    ROW_NUMBER() OVER (PARTITION BY a.position_code ORDER BY ode.created_at DESC) AS rn
                  FROM outbound_delivery_events ode
                  JOIN applications a ON a.app_key=ode.subject_key
                  WHERE a.company_code=%s AND a.position_code IS NOT NULL
                    AND COALESCE(a.data_source, a.raw_json->>'data_source', 'production')='production'
                    AND (a.cv_received IS TRUE OR jsonb_typeof(a.raw_json->'cv') = 'object')
                ) events
                WHERE rn <= 5
                ORDER BY position_code, rn
                """,
                (company,),
            )
            notifications: dict[str, list[dict[str, Any]]] = {}
            for row in cur.fetchall():
                item = json_safe(dict(row))
                notifications.setdefault(str(row.get("position_code") or ""), []).append(item)
    enriched = []
    for row in rows:
        code = str(row.get("position_code") or "")
        metadata = row.get("metadata") if isinstance(row.get("metadata"), dict) else {}
        raw_json = row.get("raw_json") if isinstance(row.get("raw_json"), dict) else {}
        row["description"] = metadata.get("description") or raw_json.get("description")
        row["requirements"] = row.get("requirements") or metadata.get("requirements") or raw_json.get("requirements")
        row["stage_counts"] = stage_counts.get(code, [])
        row["recent_applicants"] = recent.get(code, [])
        row["notifications"] = notifications.get(code, [])
        enriched.append(dashboard_position_summary(row))
    return enriched


def dashboard_record_action_result(action_type: str, status: str, result_payload: dict[str, Any], final_reply: str) -> dict[str, Any]:
    raw_payload = json_safe(result_payload)
    action = raw_payload.get("action") if isinstance(raw_payload.get("action"), dict) else {}
    actor = actor_context_from_payload(raw_payload)
    payload = normalized_result_payload(
        action_type=action_type,
        status=status,
        action=action,
        result_payload=raw_payload,
        template_reply=final_reply,
    )
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                INSERT INTO action_results
                (turn_id, action_id, action_type, status, result, final_reply,
                 company_code, actor_user_id, actor_email, actor_phone, actor_role)
                VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)
                RETURNING result_id, created_at
                """,
                (
                    None,
                    None,
                    action_type,
                    status,
                    Json(payload),
                    final_reply,
                    actor.get("company_code"),
                    actor.get("actor_user_id"),
                    actor.get("actor_email"),
                    actor.get("actor_phone"),
                    actor.get("actor_role"),
                ),
            )
            row = dict(cur.fetchone() or {})
        conn.commit()
    return json_safe(row)


def record_admin_audit(
    context: dict[str, Any],
    action_type: str,
    *,
    summary: str,
    target_type: str = "config",
    target: str | None = None,
    details: dict[str, Any] | None = None,
    status: str = "completed",
) -> None:
    """Best-effort audit row for admin/config mutations (team, WhatsApp identity,
    integrations, import).

    Records into the same `action_results` store the dashboard and AI action paths
    already use, so every config change is traceable to an actor + company with one
    consistent query surface. This is called AFTER the change has committed and must
    never raise — a failed audit write must not break a config change that already
    succeeded.
    """
    company = context.get("company_code")
    payload = {
        "action": {"type": action_type, "target_type": target_type, "target": target},
        "summary": summary,
        "details": json_safe(details or {}),
        "source": "dashboard",
        "company_code": company,
        "company_id": company,
        "actor_user_id": context.get("actor_user_id"),
        "actor_email": context.get("actor_email"),
        "actor_phone": digits(context.get("actor_phone") or context.get("hr_phone")) or None,
        "actor_role": context.get("actor_role"),
        "requested_by": context.get("hr_user"),
    }
    try:
        dashboard_record_action_result(action_type, status, payload, summary)
    except Exception:
        logger.warning("admin audit failed for %s", action_type, exc_info=True)


# ---------------------------------------------------------------------------
# Company Activity & Audit (read-only).
#
# A safe, company-scoped view over the EXISTING action_results audit substrate
# so client HR can see "who did what". There is NO mutation or delete path —
# audit rows are immutable. Operator/platform/provider actions are never
# exposed to clients, and only a whitelist of safe, humanized fields is
# returned (never raw result payloads, details blobs, final replies, tokens,
# provider config, or stack traces).
# ---------------------------------------------------------------------------

