@app.patch("/dashboard/prehire/interviews/{interview_id}")
def dashboard_prehire_interview_update(
    interview_id: str,
    request: DashboardInterviewStateRequest,
    context: dict[str, Any] = Depends(prehire_dashboard_context),
):
    require_entitlement(context, "pre_hiring", "interview.manage")
    company = context["company_code"]
    interview = fetch_candidate_interview(interview_id, company)
    if not interview:
        raise HTTPException(status_code=404, detail={"error": "interview_not_found"})
    status = normalize_interview_status(request.status, default="")
    if not status:
        raise HTTPException(status_code=422, detail={"error": "invalid_interview_status", "allowed": sorted(INTERVIEW_STATUSES)})
    hr_phone = digits(context.get("hr_phone")) or digits((context.get("hr_user") or {}).get("phone"))
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                UPDATE candidate_interviews
                SET status=%s,
                    feedback_status=CASE
                      WHEN %s='completed' AND COALESCE(notes, '')='' THEN 'notes_pending'
                      ELSE feedback_status
                    END,
                    updated_by_phone=%s,
                    updated_at=now()
                WHERE interview_id=%s AND company_code=%s
                RETURNING *
                """,
                (status, status, hr_phone, interview_id, company),
            )
            row = dict(cur.fetchone() or {})
        conn.commit()
    if row:
        record_interview_event(str(row["interview_id"]), company, str(row.get("app_key") or ""), f"status_{status}", {"status": status}, hr_phone)
        update_application_interview_snapshot(str(row.get("app_key") or ""), row)
    reply = f"Interview marked {status.replace('_', ' ')}."
    dashboard_record_action_result(
        "interview_status_update",
        "completed",
        {
            "interview": candidate_interview_summary(row),
            "action": {"type": "interview_status_update", "target": interview_id, "status": status},
            "company_code": company,
            "requested_by": context.get("hr_user"),
            "source": "dashboard",
        },
        reply,
    )
    return {"company_code": company, "ok": True, "interview": candidate_interview_summary(row)}


@app.post("/dashboard/prehire/interviews/{interview_id}/notes")
def dashboard_prehire_interview_notes(
    interview_id: str,
    request: DashboardInterviewNotesRequest,
    context: dict[str, Any] = Depends(prehire_dashboard_context),
):
    require_entitlement(context, "pre_hiring", "interview.manage")
    company = context["company_code"]
    interview = fetch_candidate_interview(interview_id, company)
    if not interview:
        raise HTTPException(status_code=404, detail={"error": "interview_not_found"})
    notes = str(request.notes or "").strip()
    transcript = str(request.transcript or "").strip()
    if not notes and not transcript:
        raise HTTPException(status_code=422, detail={"error": "interview_notes_required"})
    application = dashboard_application_or_404(str(interview.get("app_key") or ""), company)
    status = normalize_interview_status(request.status, default=str(interview.get("status") or "completed"))
    if status == "scheduled":
        status = "completed"
    summary = generate_interview_ai_summary(notes, transcript, application, interview) if request.generate_summary else deterministic_interview_summary(notes, transcript)
    hr_phone = digits(context.get("hr_phone")) or digits((context.get("hr_user") or {}).get("phone"))
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                UPDATE candidate_interviews
                SET status=%s,
                    feedback_status='feedback_complete',
                    notes=%s,
                    transcript=NULLIF(%s, ''),
                    ai_summary=%s,
                    updated_by_phone=%s,
                    updated_at=now()
                WHERE interview_id=%s AND company_code=%s
                RETURNING *
                """,
                (status, notes or transcript, transcript, Json(json_safe(summary)), hr_phone, interview_id, company),
            )
            row = dict(cur.fetchone() or {})
        conn.commit()
    if row:
        record_interview_event(
            str(row["interview_id"]),
            company,
            str(row.get("app_key") or ""),
            "feedback_complete",
            {"status": status, "summary": json_safe(summary)},
            hr_phone,
        )
        update_application_interview_snapshot(str(row.get("app_key") or ""), row)
    reply = "Interview notes saved and summarized. HR remains the final decision-maker."
    result_payload = {
        "interview": candidate_interview_summary(row),
        "application": json_safe(application),
        "action": {"type": "interview_feedback", "target": interview_id, "status": status},
        "company_code": company,
        "requested_by": context.get("hr_user"),
        "source": "dashboard",
    }
    dashboard_record_action_result("interview_feedback", "completed", result_payload, reply)
    return {"company_code": company, "ok": True, "reply": reply, "interview": candidate_interview_summary(row)}


@app.get("/dashboard/prehire/interviews/{interview_id}/responses/{response_id}/video")
def dashboard_prehire_video_interview_response_video(
    interview_id: str,
    response_id: str,
    context: dict[str, Any] = Depends(prehire_dashboard_context),
):
    require_entitlement(context, "video_interviews", "prehire.read")
    company = context["company_code"]
    interview = fetch_candidate_interview(interview_id, company)
    if not interview:
        raise HTTPException(status_code=404, detail={"error": "interview_not_found"})
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT *
                FROM candidate_video_interview_responses
                WHERE response_id=%s AND interview_id=%s AND company_code=%s
                LIMIT 1
                """,
                (response_id, interview_id, company),
            )
            response = dict(cur.fetchone() or {})
    path = Path(str(response.get("local_path") or ""))
    if not response or not path.exists() or not path.is_file():
        raise HTTPException(status_code=404, detail={"error": "video_file_not_found"})
    media_type = response.get("mime_type") or mimetypes.guess_type(path.name)[0] or "video/webm"
    return FileResponse(path, media_type=media_type, filename=str(response.get("original_filename") or path.name))


@app.post("/dashboard/prehire/interviews/{interview_id}/transcripts/retry")
def dashboard_prehire_video_interview_transcript_retry(
    interview_id: str,
    context: dict[str, Any] = Depends(prehire_dashboard_context),
):
    require_entitlement(context, "video_interviews", "interview.manage")
    company = context["company_code"]
    interview = fetch_candidate_interview(interview_id, company)
    if not interview:
        raise HTTPException(status_code=404, detail={"error": "interview_not_found"})
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                UPDATE candidate_video_interview_responses
                SET transcript_status='pending',
                    transcript_error=NULL,
                    updated_at=now()
                WHERE interview_id=%s
                  AND company_code=%s
                  AND video_file_id IS NOT NULL
                  AND COALESCE(transcript_status, 'pending') IN ('failed', 'pending')
                RETURNING response_id
                """,
                (interview_id, company),
            )
            queued = [str(row.get("response_id")) for row in cur.fetchall()]
        conn.commit()
    hr_phone = digits(context.get("hr_phone")) or digits((context.get("hr_user") or {}).get("phone"))
    record_interview_event(
        interview_id,
        company,
        str(interview.get("app_key") or ""),
        "video_transcript_retry_queued",
        {"queued_response_ids": queued},
        hr_phone,
        actor_context={
            "company_code": company,
            "actor_user_id": str((context.get("hr_user") or {}).get("phone") or hr_phone or ""),
            "actor_phone": hr_phone,
            "actor_role": str(context.get("actor_role") or ((context.get("access") or {}).get("role") if isinstance(context.get("access"), dict) else "")),
        },
        action="video_interview_transcription_retry_queued",
        target_type="interview",
        target=interview_id,
    )
    refreshed = fetch_candidate_interview(interview_id, company) or interview
    return {
        "company_code": company,
        "ok": True,
        "queued_response_ids": queued,
        "reply": "Video interview transcription has been queued for retry.",
        "interview": candidate_interview_summary(refreshed),
    }


def require_internal_worker_access(request: Request, token: str | None) -> None:
    configured = os.environ.get("WATHEFNI_INTERNAL_WORKER_TOKEN") or os.environ.get("WATHEFNI_INTERNAL_TOKEN")
    if configured:
        if not token or not hmac.compare_digest(token, configured):
            raise HTTPException(status_code=403, detail={"error": "internal_worker_forbidden"})
        return
    client_host = (request.client.host if request.client else "") or ""
    if client_host not in {"127.0.0.1", "::1", "localhost"}:
        raise HTTPException(status_code=403, detail={"error": "internal_worker_forbidden"})


