def dashboard_notification_item(
    *,
    kind: str,
    title: str,
    count: int,
    severity: str,
    action: str,
    page: str,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any] | None:
    if count <= 0:
        return None
    return {
        "kind": kind,
        "title": title,
        "count": count,
        "severity": severity,
        "action": action,
        "page": page,
        "metadata": json_safe(metadata or {}),
    }


def csv_cell(value: Any) -> str:
    if isinstance(value, (dict, list)):
        text = json.dumps(json_safe(value), ensure_ascii=False, default=str)
    else:
        text = "" if value is None else str(json_safe(value))
    return '"' + text.replace('"', '""') + '"'


def csv_line(values: list[Any]) -> str:
    return ",".join(csv_cell(value) for value in values) + "\n"


REPORT_STATUS_LABELS = {
    "": "",
    "unknown": "",
    "cv_received": "CV received",
    "screening": "Screening in progress",
    "screening_complete": "Screening complete",
    "review_pending": "Ready for review",
    "shortlisted": "Shortlisted",
    "interview": "Interview stage",
    "offered": "Offer stage",
    "hired": "Hired",
    "rejected": "Not selected",
    "pending": "Pending",
    "sent": "Sent",
    "started": "Started",
    "in_progress": "In progress",
    "completed": "Completed",
    "expired": "Expired",
    "cancelled": "Cancelled",
    "scheduled": "Scheduled",
    "rescheduled": "Rescheduled",
    "no_show": "No-show",
    "passed": "Passed",
    "failed": "Needs follow-up",
    "recovered": "",
    "not_added": "Not added",
}


def prehire_report_status_label(value: Any) -> str:
    key = str(value or "").strip().lower()
    if key in REPORT_STATUS_LABELS:
        return REPORT_STATUS_LABELS[key]
    return key.replace("_", " ").replace("-", " ").strip().title()


def prehire_report_export_value(report_type: str, key: str, value: Any) -> Any:
    if key in {"status", "screening", "assessment", "interview", "feedback_status"}:
        return prehire_report_status_label(value)
    return value


def csv_stream_response(filename: str, headers: list[str], rows: Any) -> StreamingResponse:
    def generate():
        yield csv_line(headers)
        for row in rows:
            yield csv_line(list(row))

    return StreamingResponse(
        generate(),
        media_type="text/csv; charset=utf-8",
        headers={"Content-Disposition": f'attachment; filename="{filename}"'},
    )


def prehire_report_summary_payload(company: str) -> dict[str, Any]:
    reviewable = reviewable_application_predicate("a")
    production = production_application_predicate("a")
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                f"""
                SELECT COALESCE(NULLIF(a.status, ''), 'unknown') AS label, COUNT(*) AS count
                FROM applications a
                WHERE a.company_code=%s AND {reviewable}
                GROUP BY COALESCE(NULLIF(a.status, ''), 'unknown')
                ORDER BY count DESC, label
                """,
                (company,),
            )
            stage_counts = [{"label": row["label"], "count": int(row["count"] or 0)} for row in cur.fetchall()]

            cur.execute(
                f"""
                SELECT
                  COUNT(*) FILTER (WHERE a.cv_received IS TRUE OR jsonb_typeof(a.raw_json->'cv') = 'object') AS received,
                  COUNT(*) FILTER (WHERE NOT (a.cv_received IS TRUE OR jsonb_typeof(a.raw_json->'cv') = 'object')) AS missing
                FROM applications a
                WHERE a.company_code=%s AND {production}
                """,
                (company,),
            )
            cv = cur.fetchone() or {}

            cur.execute(
                f"""
                SELECT
                  COUNT(*) FILTER (
                    WHERE a.screening_status='complete'
                       OR a.raw_json->'screening'->>'status'='complete'
                       OR a.status IN ('screening_complete','review_pending','shortlisted','interview','hired')
                  ) AS screening_complete,
                  COUNT(*) FILTER (WHERE a.status IN ('screening_complete','review_pending')) AS ready_for_review
                FROM applications a
                WHERE a.company_code=%s AND {reviewable}
                """,
                (company,),
            )
            progress = cur.fetchone() or {}

            cur.execute(
                f"""
                SELECT COALESCE(NULLIF(a.position_title, ''), NULLIF(a.position_code, ''), 'Unassigned role') AS label,
                       COUNT(*) AS count
                FROM applications a
                WHERE a.company_code=%s AND {reviewable}
                GROUP BY COALESCE(NULLIF(a.position_title, ''), NULLIF(a.position_code, ''), 'Unassigned role')
                ORDER BY count DESC, label
                LIMIT 25
                """,
                (company,),
            )
            role_counts = [{"label": row["label"], "count": int(row["count"] or 0)} for row in cur.fetchall()]

            cur.execute(
                f"""
                WITH report_roles AS (
                  SELECT p.position_code
                  FROM positions p
                  WHERE p.company_code=%s
                  UNION
                  SELECT a.position_code
                  FROM applications a
                  WHERE a.company_code=%s AND {reviewable}
                  GROUP BY a.position_code
                )
                SELECT COUNT(*) AS count
                FROM report_roles
                """,
                (company, company),
            )
            role_total = int((cur.fetchone() or {}).get("count") or 0)

            assessment_counts: list[dict[str, Any]] = []
            if company_has_module(company, "assessments"):
                cur.execute(
                    f"""
                    SELECT COALESCE(NULLIF(aa.status, ''), 'unknown') AS label, COUNT(*) AS count
                    FROM assessment_attempts aa
                    JOIN applications a ON a.company_code=aa.company_code AND a.app_key=aa.app_key
                    WHERE aa.company_code=%s AND {reviewable}
                    GROUP BY COALESCE(NULLIF(aa.status, ''), 'unknown')
                    ORDER BY count DESC, label
                    """,
                    (company,),
                )
                assessment_counts = [{"label": row["label"], "count": int(row["count"] or 0)} for row in cur.fetchall()]

            cur.execute(
                f"""
                SELECT COALESCE(NULLIF(ci.status, ''), 'unknown') AS label, COUNT(*) AS count
                FROM candidate_interviews ci
                JOIN applications a ON a.company_code=ci.company_code AND a.app_key=ci.app_key
                WHERE ci.company_code=%s AND {reviewable}
                GROUP BY COALESCE(NULLIF(ci.status, ''), 'unknown')
                ORDER BY count DESC, label
                """,
                (company,),
            )
            interview_counts = [{"label": row["label"], "count": int(row["count"] or 0)} for row in cur.fetchall()]

            cur.execute(
                f"""
                SELECT
                  CASE
                    WHEN ode.last_error='conversation_closed' THEN 'Contact candidate'
                    WHEN ode.last_error='conversation_inactive' THEN 'Follow up with candidate'
                    WHEN ode.last_error IN ('missing_candidate_conversation_id','no_usable_conversation_id') THEN 'Needs contact review'
                    WHEN ode.status='failed' THEN 'Needs follow-up'
                    ELSE COALESCE(NULLIF(ode.status, ''), 'Needs HR attention')
                  END AS label,
                  COUNT(*) AS count
                FROM outbound_delivery_events ode
                JOIN applications a ON a.app_key=ode.subject_key
                WHERE a.company_code=%s
                  AND {reviewable}
                  AND COALESCE(ode.status, '') NOT IN ('sent','recovered')
                  AND ode.recovered_at IS NULL
                  AND (ode.status='failed' OR ode.last_error IS NOT NULL)
                GROUP BY label
                ORDER BY count DESC, label
                """,
                (company,),
            )
            followup_counts = [{"label": row["label"], "count": int(row["count"] or 0)} for row in cur.fetchall()]

    assessment_pending = sum(item["count"] for item in assessment_counts if item["label"] not in {"completed", "expired", "cancelled"})
    assessment_completed = sum(item["count"] for item in assessment_counts if item["label"] == "completed")
    scheduled_interviews = sum(item["count"] for item in interview_counts if item["label"] in {"scheduled", "rescheduled"})
    completed_interviews = sum(item["count"] for item in interview_counts if item["label"] == "completed")
    no_show_interviews = sum(item["count"] for item in interview_counts if item["label"] == "no_show")
    return {
        "company_code": company,
        "ok": True,
        "exports": {
            "candidate_rows": int(cv.get("received") or 0),
            "role_rows": role_total,
            "assessment_rows": sum(item["count"] for item in assessment_counts),
            "interview_rows": sum(item["count"] for item in interview_counts),
            "followup_rows": sum(item["count"] for item in followup_counts),
        },
        "summary": {
            "cv_received": int(cv.get("received") or 0),
            "cv_missing": int(cv.get("missing") or 0),
            "screening_complete": int(progress.get("screening_complete") or 0),
            "ready_for_review": int(progress.get("ready_for_review") or 0),
            "assessment_pending": assessment_pending,
            "assessment_completed": assessment_completed,
            "interview_scheduled": scheduled_interviews,
            "interview_completed": completed_interviews,
            "interview_no_show": no_show_interviews,
            "followups": sum(item["count"] for item in followup_counts),
        },
        "breakdowns": {
            "applications_by_stage": stage_counts,
            "candidates_by_role": role_counts,
            "assessment_status": assessment_counts,
            "interview_status": interview_counts,
            "followups_by_type": followup_counts,
        },
    }


def prehire_report_export_rows(company: str, report_type: str):
    reviewable = reviewable_application_predicate("a")
    conn = db_connect()
    cur = conn.cursor(name=f"prehire_report_{uuid.uuid4().hex}")

    def close():
        try:
            cur.close()
        finally:
            conn.close()

    if report_type == "candidates":
        cur.execute(
            f"""
            SELECT
              COALESCE(NULLIF(c.name, ''), a.raw_json->>'candidate_name', a.raw_json->>'name', a.phone) AS candidate,
              a.phone,
              c.email,
              COALESCE(NULLIF(a.position_title, ''), a.position_code) AS job,
              a.status,
              COALESCE(a.screening_status, a.raw_json->'screening'->>'status') AS screening,
              latest_assessment.status AS assessment,
              latest_interview.status AS interview,
              CASE WHEN a.cv_received IS TRUE OR jsonb_typeof(a.raw_json->'cv') = 'object' THEN 'Yes' ELSE 'No' END AS cv_received,
              a.updated_at
            FROM applications a
            LEFT JOIN candidates c ON c.phone=a.phone
            LEFT JOIN LATERAL (
              SELECT aa.status
              FROM assessment_attempts aa
              WHERE aa.company_code=a.company_code AND aa.app_key=a.app_key
              ORDER BY aa.updated_at DESC, aa.created_at DESC
              LIMIT 1
            ) latest_assessment ON TRUE
            LEFT JOIN LATERAL (
              SELECT ci.status
              FROM candidate_interviews ci
              WHERE ci.company_code=a.company_code AND ci.app_key=a.app_key
              ORDER BY ci.scheduled_start DESC NULLS LAST, ci.updated_at DESC
              LIMIT 1
            ) latest_interview ON TRUE
            WHERE a.company_code=%s AND {reviewable}
            ORDER BY a.updated_at DESC NULLS LAST, a.ingested_at DESC NULLS LAST
            """,
            (company,),
        )
    elif report_type == "roles":
        cur.execute(
            f"""
            WITH app_stats AS (
              SELECT
                a.company_code,
                a.position_code,
                COALESCE(MAX(a.position_title), a.position_code) AS position_title,
                COUNT(*) AS application_count,
                COUNT(*) FILTER (WHERE a.status NOT IN ('hired','rejected')) AS active_count,
                COUNT(*) FILTER (WHERE a.status IN ('screening_complete','review_pending')) AS ready_for_review,
                MAX(a.updated_at) AS latest_application_at
              FROM applications a
              WHERE a.company_code=%s AND {reviewable}
              GROUP BY a.company_code, a.position_code
            )
            SELECT
              COALESCE(p.title, s.position_title, p.position_code, s.position_code) AS job,
              COALESCE(p.position_code, s.position_code) AS position_code,
              p.apply_code,
              COALESCE(p.status, CASE WHEN COALESCE(s.active_count, 0) > 0 THEN 'open' ELSE 'closed' END) AS status,
              COALESCE(s.application_count, 0) AS applications,
              COALESCE(s.active_count, 0) AS active_applications,
              COALESCE(s.ready_for_review, 0) AS ready_for_review,
              s.latest_application_at
            FROM positions p
            FULL OUTER JOIN app_stats s ON s.company_code=p.company_code AND s.position_code=p.position_code
            WHERE COALESCE(p.company_code, s.company_code)=%s
            ORDER BY active_applications DESC, applications DESC, job
            """,
            (company, company),
        )
    elif report_type == "assessments":
        if not company_has_module(company, "assessments"):
            close()
            raise HTTPException(status_code=403, detail={"error": "module_disabled", "required_module": "assessments"})
        cur.execute(
            f"""
            SELECT
              COALESCE(aa.candidate_name, NULLIF(c.name, ''), a.raw_json->>'candidate_name', aa.phone) AS candidate,
              aa.phone,
              COALESCE(NULLIF(aa.position_title, ''), aa.position_code, a.position_title, a.position_code) AS job,
              aa.status,
              s.percent,
              s.band,
              aa.completed_at,
              aa.updated_at
            FROM assessment_attempts aa
            JOIN applications a ON a.company_code=aa.company_code AND a.app_key=aa.app_key
            LEFT JOIN candidates c ON c.phone=aa.phone
            LEFT JOIN assessment_scores s ON s.attempt_id=aa.attempt_id
            WHERE aa.company_code=%s AND {reviewable}
            ORDER BY aa.updated_at DESC, aa.created_at DESC
            """,
            (company,),
        )
    elif report_type == "interviews":
        cur.execute(
            f"""
            SELECT
              COALESCE(ci.candidate_name, NULLIF(c.name, ''), a.raw_json->>'candidate_name', ci.phone) AS candidate,
              ci.phone,
              ci.candidate_email,
              COALESCE(NULLIF(ci.position_title, ''), ci.position_code, a.position_title, a.position_code) AS job,
              ci.status,
              ci.feedback_status,
              ci.scheduled_start,
              ci.scheduled_end,
              CASE WHEN ci.candidate_notified OR ci.candidate_invited OR ci.calendar_invite_sent THEN 'Yes' ELSE 'No' END AS invite_sent,
              ci.updated_at
            FROM candidate_interviews ci
            JOIN applications a ON a.company_code=ci.company_code AND a.app_key=ci.app_key
            LEFT JOIN candidates c ON c.phone=ci.phone
            WHERE ci.company_code=%s AND {reviewable}
            ORDER BY ci.scheduled_start DESC NULLS LAST, ci.updated_at DESC
            """,
            (company,),
        )
    elif report_type == "followups":
        cur.execute(
            f"""
            SELECT
              COALESCE(NULLIF(c.name, ''), a.raw_json->>'candidate_name', a.raw_json->>'name', a.phone) AS candidate,
              ode.target_phone,
              COALESCE(NULLIF(a.position_title, ''), a.position_code) AS job,
              CASE
                WHEN ode.last_error='conversation_closed' THEN 'Contact candidate'
                WHEN ode.last_error='conversation_inactive' THEN 'Follow up with candidate'
                WHEN ode.last_error IN ('missing_candidate_conversation_id','no_usable_conversation_id') THEN 'Needs contact review'
                WHEN ode.status='failed' THEN 'Needs follow-up'
                ELSE COALESCE(NULLIF(ode.status, ''), 'Needs HR attention')
              END AS followup_type,
              CASE
                WHEN ode.last_error='conversation_closed' THEN 'Contact the candidate or choose the best contact method.'
                WHEN ode.last_error='conversation_inactive' THEN 'Follow up with the candidate.'
                WHEN ode.last_error IN ('missing_candidate_conversation_id','no_usable_conversation_id') THEN 'Review the candidate phone or email before contacting them.'
                WHEN ode.status='failed' THEN 'Try another contact method.'
                ELSE 'Needs HR attention.'
              END AS recommended_action,
              ode.created_at
            FROM outbound_delivery_events ode
            JOIN applications a ON a.app_key=ode.subject_key
            LEFT JOIN candidates c ON c.phone=a.phone
            WHERE a.company_code=%s
              AND {reviewable}
              AND COALESCE(ode.status, '') NOT IN ('sent','recovered')
              AND ode.recovered_at IS NULL
              AND (ode.status='failed' OR ode.last_error IS NOT NULL)
            ORDER BY ode.created_at DESC
            """,
            (company,),
        )
    else:
        close()
        raise HTTPException(status_code=400, detail={"error": "unknown_report_type"})

    try:
        while True:
            batch = cur.fetchmany(1000)
            if not batch:
                break
            for row in batch:
                yield [prehire_report_export_value(report_type, key, row.get(key)) for key in row.keys()]
    finally:
        close()


def prehire_report_export_headers(report_type: str) -> list[str]:
    return {
        "candidates": ["Candidate", "Phone", "Email", "Job", "Stage", "Screening", "Assessment", "Interview", "CV received", "Updated"],
        "roles": ["Job", "Job code", "Apply code", "Status", "Applications", "Active applications", "Ready for review", "Latest application"],
        "assessments": ["Candidate", "Phone", "Job", "Status", "Score percent", "Band", "Completed at", "Updated"],
        "interviews": ["Candidate", "Phone", "Email", "Job", "Status", "Feedback", "Scheduled start", "Scheduled end", "Invite sent", "Updated"],
        "followups": ["Candidate", "Phone", "Job", "Follow-up type", "Recommended action", "Created"],
    }.get(report_type, [])


def dashboard_notification_action_items(company: str) -> list[dict[str, Any]]:
    items: list[dict[str, Any]] = []
    enabled_modules = notification_enabled_modules(company)
    pre_hiring_enabled = "pre_hiring" in enabled_modules
    onboarding_enabled = False
    compliance_alerts_enabled = "compliance" in enabled_modules
    reviewable = reviewable_application_predicate("a")
    company_hr_phones = [user["phone"] for user in hr_admin_users(company)]
    with db_connect() as conn:
        with conn.cursor() as cur:
            if onboarding_enabled:
                cur.execute(
                    """
                    SELECT COALESCE(NULLIF(document_type, ''), item_id) AS doc_key,
                           COALESCE(NULLIF(label, ''), NULLIF(document_type, ''), item_id) AS label,
                           COUNT(DISTINCT employee_key) AS employee_count
                    FROM onboarding_items
                    WHERE required IS TRUE
                      AND status IN ('missing','pending','requested')
                      AND employee_key IN (SELECT employee_key FROM employees WHERE company_code=%s)
                    GROUP BY COALESCE(NULLIF(document_type, ''), item_id),
                             COALESCE(NULLIF(label, ''), NULLIF(document_type, ''), item_id)
                    ORDER BY employee_count DESC
                    LIMIT 5
                    """,
                    (company,),
                )
                for row in cur.fetchall():
                    count = int(row.get("employee_count") or 0)
                    label = item_display_label({"document_type": row.get("doc_key"), "label": row.get("label")})
                    item = dashboard_notification_item(
                        kind="missing_onboarding_item",
                        title="Missing document",
                        count=count,
                        severity="medium",
                        action="Follow up with employee",
                        page="onboarding",
                        metadata={"document_type": row.get("doc_key"), "label": label, "module_group": "onboarding"},
                    )
                    if item:
                        items.append(item)
            if pre_hiring_enabled:
                cur.execute(
                    f"""
                    SELECT
                      COUNT(*) FILTER (
                        WHERE lower(COALESCE(ode.message_kind, ode.subject_type, '')) LIKE '%%assessment%%'
                           OR lower(COALESCE(ode.subject_type, '')) LIKE '%%assessment%%'
                      ) AS assessment_failed_count,
                      COUNT(*) FILTER (
                        WHERE lower(COALESCE(ode.message_kind, ode.subject_type, '')) LIKE '%%interview%%'
                           OR lower(COALESCE(ode.subject_type, '')) LIKE '%%interview%%'
                      ) AS interview_failed_count
                    FROM outbound_delivery_events ode
                    JOIN applications a ON a.app_key=ode.subject_key
                    WHERE ode.status='failed'
                      AND ode.created_at >= now() - interval '7 days'
                      AND a.company_code=%s
                      AND {reviewable}
                    """,
                    (company,),
                )
                delivery_counts = cur.fetchone() or {}
                assessment_failed = int(delivery_counts.get("assessment_failed_count") or 0) if company_has_module(company, "assessments") else 0
                interview_failed = int(delivery_counts.get("interview_failed_count") or 0)
                item = dashboard_notification_item(
                    kind="assessment_delivery_failed",
                    title="Assessment delivery failed",
                    count=assessment_failed,
                    severity="high",
                    action="Contact candidate or send the assessment another way",
                    page="assessments",
                    metadata={"window": "7_days", "module_group": "delivery_issues"},
                )
                if item:
                    items.append(item)
                item = dashboard_notification_item(
                    kind="interview_invite_failed",
                    title="Interview invite failed",
                    count=interview_failed,
                    severity="high",
                    action="Contact candidate or resend the interview invite",
                    page="interviews",
                    metadata={"window": "7_days", "module_group": "delivery_issues"},
                )
                if item:
                    items.append(item)
                if company_hr_phones:
                    cur.execute(
                        """
                        SELECT COUNT(*) AS pending_count
                        FROM pending_actions
                        WHERE status='pending'
                          AND expires_at > now()
                          AND admin_phone = ANY(%s)
                          AND action_type = ANY(%s)
                        """,
                        (company_hr_phones, PREHIRE_DASHBOARD_ACTION_TYPES),
                    )
                    pending_count = int((cur.fetchone() or {}).get("pending_count") or 0)
                    item = dashboard_notification_item(
                        kind="ai_action_needs_approval",
                        title="AI action needs approval",
                        count=pending_count,
                        severity="high",
                        action="Review and approve or cancel the pending action",
                        page="ai",
                        metadata={"module_group": "pre_hiring"},
                    )
                    if item:
                        items.append(item)
            if pre_hiring_enabled:
                cur.execute(
                    """
                    SELECT COUNT(*) AS completed_count
                    FROM applications
                    WHERE company_code=%s
                      AND (cv_received IS TRUE OR jsonb_typeof(raw_json->'cv') = 'object')
                      AND (
                        screening_status='complete'
                        OR raw_json->'screening'->>'status'='complete'
                        OR raw_json->'assessment'->>'status'='completed'
                      )
                      AND updated_at >= CURRENT_DATE
                    """,
                    (company,),
                )
                completed_screening = int((cur.fetchone() or {}).get("completed_count") or 0)
                item = dashboard_notification_item(
                    kind="screening_completed_today",
                    title="Review completed screening",
                    count=completed_screening,
                    severity="low",
                    action="Review completed candidates",
                    page="candidates",
                    metadata={"window": "today", "module_group": "completions"},
                )
                if item:
                    items.append(item)
            if compliance_alerts_enabled:
                cur.execute(
                    """
                    SELECT
                      COUNT(*) FILTER (WHERE c.expiry_date < CURRENT_DATE) AS expired_count,
                      COUNT(*) FILTER (
                        WHERE c.expiry_date >= CURRENT_DATE
                          AND c.expiry_date <= CURRENT_DATE + (COALESCE(c.warning_days, 30) || ' days')::interval
                      ) AS expiring_count,
                      COUNT(*) FILTER (
                        WHERE c.expiry_date IS NULL AND c.status='received'
                      ) AS needs_review_count
                    FROM compliance_documents c
                    JOIN employees e ON e.employee_key=c.employee_key
                    WHERE e.company_code=%s
                    """,
                    (company,),
                )
                compliance = cur.fetchone() or {}
                expired = int(compliance.get("expired_count") or 0)
                expiring = int(compliance.get("expiring_count") or 0)
                needs_review = int(compliance.get("needs_review_count") or 0)
                item = dashboard_notification_item(
                    kind="compliance_document_expired",
                    title="Expired documents",
                    count=expired,
                    severity="high",
                    action="Start renewal and remind the employee",
                    page="compliance",
                    metadata={"status": "expired", "module_group": "compliance"},
                )
                if item:
                    items.append(item)
                item = dashboard_notification_item(
                    kind="compliance_document_expiring",
                    title="Documents expiring soon",
                    count=expiring,
                    severity="medium",
                    action="Remind the employee to renew",
                    page="compliance",
                    metadata={"status": "expiring_soon", "module_group": "compliance"},
                )
                if item:
                    items.append(item)
                item = dashboard_notification_item(
                    kind="compliance_needs_review",
                    title="Documents need review",
                    count=needs_review,
                    severity="medium",
                    action="Review the document and mark it reviewed",
                    page="compliance",
                    metadata={"status": "needs_review", "module_group": "compliance"},
                )
                if item:
                    items.append(item)
    severity_order = {"high": 0, "medium": 1, "low": 2}
    return sorted(items, key=lambda item: (severity_order.get(str(item.get("severity")), 9), -int(item.get("count") or 0)))[:12]


@app.get("/dashboard/prehire/rank")
def dashboard_prehire_rank(
    q: str | None = None,
    position: str | None = None,
    status: str | None = None,
    top_n: int = Query(default=10, ge=1, le=50),
    context: dict[str, Any] = Depends(prehire_dashboard_context),
):
    company = context["company_code"]
    result = rank_candidates(
        {
            "query": (q or "").strip(),
            "position": (position or "").strip(),
            "status": (status or "").strip(),
            "top_n": top_n,
        },
        company_code=company,
    )
    return {"company_code": company, **json_safe(result)}


@app.get("/dashboard/prehire/notifications")
def dashboard_prehire_notifications(
    status: str | None = None,
    limit: int = Query(default=50, ge=1, le=200),
    context: dict[str, Any] = Depends(prehire_dashboard_context),
):
    company = context["company_code"]
    enabled_modules = notification_enabled_modules(company)
    where = ["a.company_code=%s", reviewable_application_predicate("a")]
    params: list[Any] = [company]
    if "pre_hiring" not in enabled_modules:
        where.append("FALSE")
    if status:
        where.append("ode.status=%s")
        params.append(status)
    else:
        where.append("(ode.status <> 'sent' OR ode.last_error IS NOT NULL)")
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                f"""
                SELECT ode.delivery_id, ode.account_id, ode.target_phone, ode.target_conversation_id,
                       ode.subject_type, ode.subject_key, ode.status, ode.last_error,
                       ode.message_kind, ode.sent_at, ode.failed_at, ode.created_at, ode.updated_at,
                       a.app_key, a.position_code, a.position_title, c.name AS candidate_name,
                       c.email AS candidate_email
                FROM outbound_delivery_events ode
                JOIN applications a ON a.app_key=ode.subject_key
                LEFT JOIN candidates c ON c.phone=a.phone
                WHERE {' AND '.join(where)}
                ORDER BY ode.created_at DESC
                LIMIT %s
                """,
                [*params, bounded_limit(limit)],
            )
            rows = []
            for row in cur.fetchall():
                payload = json_safe(dict(row))
                payload["dashboard_status"] = dashboard_delivery_status(dict(row))
                rows.append(payload)
    return {
        "company_code": company,
        "enabled_modules": sorted(enabled_modules),
        "notification_policy": {
            "principle": "Notifications interrupt HR only for urgent or important alerts; normal work stays in module queues.",
            "module_scope": "pre_hiring_dashboard_only",
            "disabled_module_alerts": "hidden",
            "routine_activity": "activity_audit_only",
            "hr_notify": [
                "assessment_delivery_failed",
                "interview_invite_failed",
                "ai_action_needs_approval",
                "review_completed_screening",
            ],
        },
        "action_items": dashboard_notification_action_items(company),
        "notifications": rows,
    }


