@app.get("/dashboard/prehire/audit")
def dashboard_prehire_audit(
    limit: int = Query(default=50, ge=1, le=200),
    context: dict[str, Any] = Depends(prehire_dashboard_context),
):
    company = context["company_code"]
    company_hr_phones = [user["phone"] for user in hr_admin_users(company)]
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT ar.result_id, ar.turn_id, ar.action_id, ar.action_type, ar.status,
                       ar.result, ar.final_reply, ar.created_at,
                       ht.sender_phone, ht.raw_text, ht.final_reply_source
                FROM action_results ar
                LEFT JOIN hr_turns ht ON ht.turn_id=ar.turn_id
                WHERE ar.action_type = ANY(%s)
                  AND (
                    ar.result->'filters'->>'company_code' = %s
                    OR ar.result->'application'->>'company_code' = %s
                    OR ar.result->'selected_application'->>'company_code' = %s
                    OR ht.sender_phone = ANY(%s)
                  )
                ORDER BY ar.created_at DESC
                LIMIT %s
                """,
                (PREHIRE_DASHBOARD_ACTION_TYPES, company, company, company, company_hr_phones, bounded_limit(limit)),
            )
            rows = [json_safe(dict(row)) for row in cur.fetchall()]
    return {"company_code": company, "action_results": rows}


# --- Bulk CV import: dashboard layer ----------------------------------------
IMPORT_CV_EXTENSIONS = {".pdf", ".docx", ".doc", ".rtf", ".txt", ".md", ".png", ".jpg", ".jpeg", ".webp"}
IMPORT_METADATA_EXTENSIONS = {".csv", ".xlsx"}
IMPORT_MAX_FILES = 300
IMPORT_MAX_TOTAL_BYTES = 250 * 1024 * 1024
# Where a batch came from. Generic CSV/Excel + CV files are the universal bridge;
# these are provenance labels only — we do not build direct ATS integrations here.
IMPORT_SOURCES = {
    "bulk_upload",
    "linkedin_export",
    "oracle_taleo_export",
    "workday_export",
    "sap_successfactors_export",
    "email",
    "email_inbound",
    "other_ats_export",
}
# A confident match (>= this) auto-assigns a role; below it we only *suggest* a
# role and the candidate waits in Needs role / Import review.
IMPORT_ROLE_ASSIGN_THRESHOLD = 0.9


def _import_norm_key(value: str | None) -> str:
    return re.sub(r"\s+", " ", str(value or "").strip().lower())


def _import_role_label(value: str | None) -> str:
    return _import_norm_key(str(value or "").replace("_", " ").replace("-", " "))


def resolve_import_role(
    positions: list[dict[str, Any]],
    *,
    position_code: str | None = None,
    applied_role: str | None = None,
    folder_hint: str | None = None,
) -> dict[str, Any]:
    """Resolve an imported candidate's role against the company's real positions.

    Pure function over a preloaded position list (no DB calls) so it is safe to
    reuse from a future chunked enterprise migration job. Returns a dict with an
    `assigned` code/title only when we are confident; otherwise a non-binding
    `suggested` code/title plus a `source`/`confidence` for the reviewer. Folder
    paths only ever suggest — never auto-assign — so we don't over-trust them.
    """
    by_code: dict[str, dict[str, str]] = {}
    by_title: dict[str, dict[str, str]] = {}
    for pos in positions:
        code = str(pos.get("position_code") or "").strip()
        title = str(pos.get("title") or pos.get("position_title") or "").strip()
        entry = {"position_code": code, "position_title": title or code}
        if code:
            by_code[code.upper()] = entry
        if title:
            by_title[_import_role_label(title)] = entry

    def _best_label_match(text: str) -> tuple[float, dict[str, str] | None]:
        label = _import_role_label(text)
        if not label:
            return 0.0, None
        if label in by_title:
            return 1.0, by_title[label]
        # Code given as free text (e.g. applied_role="WELDER").
        if label.upper().replace(" ", "_") in by_code or text.strip().upper() in by_code:
            return 1.0, by_code.get(label.upper().replace(" ", "_")) or by_code.get(text.strip().upper())
        best: tuple[float, dict[str, str] | None] = (0.0, None)
        for title_label, entry in by_title.items():
            if not title_label:
                continue
            if title_label in label or label in title_label:
                score = 0.9
            else:
                tokens = [t for t in title_label.split() if len(t) > 2]
                overlap = sum(1 for t in tokens if re.search(rf"\b{re.escape(t)}\b", label))
                score = 0.6 if tokens and overlap == len(tokens) else (0.6 if overlap >= 1 and len(tokens) == 1 else 0.0)
            if score > best[0]:
                best = (score, entry)
        return best

    result: dict[str, Any] = {
        "assigned_code": None,
        "assigned_title": None,
        "suggested_code": None,
        "suggested_title": None,
        "confidence": 0.0,
        "source": None,
    }

    # 1) Explicit position_code that matches a real company position -> assign.
    code = str(position_code or "").strip()
    if code:
        match = by_code.get(code.upper())
        if match:
            result.update({
                "assigned_code": match["position_code"], "assigned_title": match["position_title"],
                "confidence": 1.0, "source": "metadata_position_code",
            })
            return result
        # Given but unknown to this company -> suggest for review, never assign.
        result.update({"suggested_code": code, "suggested_title": None, "confidence": 0.3, "source": "metadata_unmatched_code"})

    # 2) applied_role text -> assign on a strong match, else suggest.
    if applied_role:
        score, match = _best_label_match(applied_role)
        if match and score >= IMPORT_ROLE_ASSIGN_THRESHOLD:
            result.update({
                "assigned_code": match["position_code"], "assigned_title": match["position_title"],
                "confidence": score, "source": "metadata_applied_role",
            })
            return result
        if match and score > result["confidence"]:
            result.update({"suggested_code": match["position_code"], "suggested_title": match["position_title"], "confidence": score, "source": "metadata_applied_role"})

    # 3) ZIP folder path -> suggest only (do not over-trust folder structure).
    if folder_hint and not result["assigned_code"]:
        score, match = _best_label_match(folder_hint)
        if match and score >= 0.6:
            suggested_conf = min(score, 0.6)
            if suggested_conf > result["confidence"]:
                result.update({"suggested_code": match["position_code"], "suggested_title": match["position_title"], "confidence": suggested_conf, "source": "zip_folder_path"})

    return result


def parse_import_metadata_file(filename: str, data: bytes) -> dict[str, dict[str, str]]:
    """Parse an optional CSV/Excel sheet mapping filename -> candidate metadata.

    Recognised columns (case-insensitive): filename, name, email, phone,
    position_code (or position), position_title. Rows without a filename are ignored.
    """
    suffix = Path(filename or "").suffix.lower()
    rows: list[dict[str, str]] = []
    if suffix == ".csv":
        text = data.decode("utf-8-sig", errors="replace")
        reader = csv.DictReader(io.StringIO(text))
        for raw in reader:
            rows.append({str(k or "").strip().lower(): str(v or "").strip() for k, v in raw.items()})
    elif suffix == ".xlsx":
        import openpyxl  # available in the deployment venv

        with tempfile.NamedTemporaryFile(prefix="wathefni-import-meta-", suffix=".xlsx", delete=False) as tmp:
            tmp.write(data)
            tmp_path = tmp.name
        try:
            wb = openpyxl.load_workbook(tmp_path, read_only=True, data_only=True)
            ws = wb.active
            header: list[str] = []
            for idx, excel_row in enumerate(ws.iter_rows(values_only=True)):
                values = ["" if c is None else str(c).strip() for c in excel_row]
                if idx == 0:
                    header = [v.lower() for v in values]
                    continue
                rows.append({header[i]: values[i] for i in range(min(len(header), len(values)))})
            wb.close()
        finally:
            try:
                os.unlink(tmp_path)
            except Exception:
                pass
    else:
        return {}
    mapping: dict[str, dict[str, str]] = {}
    for row in rows:
        fname = row.get("filename") or row.get("file") or row.get("cv") or ""
        key = _import_norm_key(Path(fname).name)
        if not key:
            continue
        mapping[key] = {
            "name": row.get("name") or row.get("candidate_name") or "",
            "email": row.get("email") or row.get("candidate_email") or "",
            "phone": row.get("phone") or row.get("mobile") or "",
            "position_code": row.get("position_code") or row.get("position") or "",
            "position_title": row.get("position_title") or row.get("title") or "",
            # Free-text role the candidate applied for; resolved against real positions.
            "applied_role": row.get("applied_role") or row.get("role") or row.get("job") or row.get("job_title") or "",
        }
    return mapping


def _import_expand_files(uploaded: list[tuple[str, bytes]]) -> list[tuple[str, bytes, str | None]]:
    """Expand ZIP archives into individual CV files; pass non-archives through.

    Returns (filename, data, folder_hint). folder_hint is the immediate parent
    folder inside a ZIP (e.g. cvs/engineering/cv.pdf -> "engineering"), used only
    as a non-binding role suggestion. Non-archive uploads have no folder hint.
    """
    expanded: list[tuple[str, bytes, str | None]] = []
    for filename, data in uploaded:
        suffix = Path(filename or "").suffix.lower()
        if suffix == ".zip":
            try:
                with zipfile.ZipFile(io.BytesIO(data)) as archive:
                    for info in archive.infolist():
                        if info.is_dir():
                            continue
                        inner_name = Path(info.filename).name
                        if not inner_name or inner_name.startswith(".") or "__MACOSX" in info.filename:
                            continue
                        if Path(inner_name).suffix.lower() not in IMPORT_CV_EXTENSIONS:
                            continue
                        parents = [p for p in Path(info.filename).parent.parts if p and p not in (".", "/")]
                        folder_hint = parents[-1] if parents else None
                        expanded.append((inner_name, archive.read(info), folder_hint))
            except Exception:
                expanded.append((filename, data, None))  # surfaced later as failed/unsupported
        else:
            expanded.append((filename, data, None))
    return expanded


def _import_load_company_positions(cur: Any, company: str) -> list[dict[str, Any]]:
    cur.execute(
        "SELECT position_code, title FROM positions WHERE company_code=%s AND (status='open' OR status IS NULL) ORDER BY updated_at DESC NULLS LAST LIMIT 500",
        (company,),
    )
    return [dict(r) for r in cur.fetchall()]


def _import_process_one_file(
    cur: Any,
    *,
    company: str,
    batch_id: str,
    source: str,
    company_positions: list[dict[str, Any]],
    filename: str,
    data: bytes,
    seen_checksums: dict[str, str],
    folder_hint: str | None = None,
    meta: dict[str, str] | None = None,
    default_position_code: str | None = None,
    default_position_title: str | None = None,
    auto_admit_enabled: bool = True,
) -> dict[str, Any]:
    """Shared per-file import step used by BOTH bulk upload and mailbox sync.

    Performs dedupe (in-run + company-scoped existing-CV), role resolution, and
    registration through the single shared core (register_imported_cv). Returns an
    item_record; it does NOT insert the import_items row (see _import_insert_item).
    """
    meta = meta or {}
    suffix = Path(filename or "").suffix.lower()
    checksum = hashlib.sha256(data).hexdigest()
    item_record: dict[str, Any] = {
        "original_filename": Path(filename).name,
        "content_sha256": checksum,
        "mime_type": mimetypes.guess_type(filename)[0],
        "size_bytes": len(data),
    }
    candidate_name = meta.get("name") or _parse_candidate_name_from_filename(filename)
    candidate_email = meta.get("email") or None
    candidate_phone = meta.get("phone") or None

    role = resolve_import_role(
        company_positions,
        position_code=(meta.get("position_code") or default_position_code or "").strip() or None,
        applied_role=(meta.get("applied_role") or "").strip() or None,
        folder_hint=folder_hint,
    )
    position_code = (role.get("assigned_code") or "").strip()
    position_title = (role.get("assigned_title") or meta.get("position_title") or (default_position_title if position_code else "") or "").strip()
    # Explicit role signal == a strong, declared match (position_code that maps to an
    # open position, or an exact applied_role match). Those auto-admit when the company
    # setting allows. Folder hints / fuzzy / unmatched codes are suggestions only.
    explicit_role = bool(role.get("assigned_code"))
    auto_admit = bool(explicit_role and auto_admit_enabled)
    admit_reason = role.get("source") if auto_admit else None
    role_suggestion = {
        "suggested_code": role.get("suggested_code"),
        "suggested_title": role.get("suggested_title"),
        "confidence": role.get("confidence"),
        "source": role.get("source"),
        "folder_hint": folder_hint,
    } if (role.get("assigned_code") or role.get("suggested_code") or role.get("source")) else None

    if suffix not in IMPORT_CV_EXTENSIONS:
        item_record.update({"status": "failed", "error": f"unsupported_file_type:{suffix or 'unknown'}"})
        return item_record
    if checksum in seen_checksums:
        item_record.update({"status": "duplicate", "duplicate_of_app_key": seen_checksums[checksum], "error": "duplicate_in_batch"})
        return item_record
    cur.execute(
        """
        SELECT subject_key FROM file_registry
        WHERE company_code=%s AND file_kind='candidate_cv' AND content_sha256=%s
        ORDER BY updated_at DESC LIMIT 1
        """,
        (company, checksum),
    )
    existing = cur.fetchone()
    if existing:
        item_record.update({"status": "duplicate", "duplicate_of_app_key": existing.get("subject_key"), "error": "duplicate_existing_cv"})
        return item_record

    tmp_path = None
    try:
        with tempfile.NamedTemporaryFile(prefix="wathefni-import-", suffix=(suffix or ".bin"), delete=False) as tmp:
            tmp.write(data)
            tmp_path = tmp.name
        result = register_imported_cv(
            cur,
            company_code=company,
            batch_id=batch_id,
            source_path=Path(tmp_path),
            original_filename=Path(filename).name,
            mime_type=item_record["mime_type"],
            checksum=checksum,
            size_bytes=len(data),
            candidate_name=candidate_name,
            candidate_email=candidate_email,
            candidate_phone=candidate_phone,
            position_code=position_code or None,
            position_title=position_title or None,
            source=source,
            role_suggestion=role_suggestion,
            source_ref=f"{source}:{Path(filename).name}",
            auto_admit=auto_admit,
            admit_reason=admit_reason,
        )
    except Exception as exc:  # one bad file must not abort the batch
        result = {"ok": False, "error": f"import_failed:{exc}"}
    finally:
        if tmp_path:
            try:
                os.unlink(tmp_path)
            except Exception:
                pass

    if result.get("ok"):
        seen_checksums[checksum] = result.get("app_key")
        item_record.update({
            "status": "imported",
            "held_status": result.get("status"),
            "auto_admitted": bool(result.get("auto_admitted")),
            "admit_reason": result.get("admit_reason"),
            "app_key": result.get("app_key"),
            "surrogate_phone": result.get("surrogate_phone"),
            "candidate_name": candidate_name,
            "candidate_email": candidate_email,
            "candidate_phone": candidate_phone,
            "position_code": position_code or None,
            "position_title": position_title or None,
            "file_id": result.get("file_id"),
            "document_id": result.get("document_id"),
        })
    else:
        item_record.update({"status": "failed", "error": result.get("error") or "import_failed"})
    return item_record


def _import_bump_counts(counts: dict[str, int], item_record: dict[str, Any]) -> None:
    def bump(key: str) -> None:
        counts[key] = counts.get(key, 0) + 1

    status = item_record.get("status")
    if status == "imported":
        bump("imported")
        if item_record.get("auto_admitted"):
            bump("auto_admitted")
        elif item_record.get("held_status") == "needs_role":
            bump("needs_role")
        else:
            bump("review")
    elif status == "duplicate":
        bump("duplicate")
    elif status == "failed":
        bump("failed")


def _import_insert_item(
    cur: Any,
    *,
    batch_id: str,
    company: str,
    item_record: dict[str, Any],
    provenance: dict[str, Any] | None = None,
) -> str:
    provenance = provenance or {}
    cur.execute(
        """
        INSERT INTO import_items
            (batch_id, company_code, original_filename, content_sha256, mime_type, size_bytes,
             status, app_key, surrogate_phone, candidate_name, candidate_email, candidate_phone,
             position_code, position_title, duplicate_of_app_key, file_id, document_id, error,
             source_message_id, source_sender, source_received_at, source_subject, source_label)
        VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)
        RETURNING item_id::text
        """,
        (
            batch_id, company, item_record.get("original_filename"), item_record.get("content_sha256"),
            item_record.get("mime_type"), item_record.get("size_bytes"), item_record.get("status"),
            item_record.get("app_key"), item_record.get("surrogate_phone"), item_record.get("candidate_name"),
            item_record.get("candidate_email"), item_record.get("candidate_phone"), item_record.get("position_code"),
            item_record.get("position_title"), item_record.get("duplicate_of_app_key"),
            item_record.get("file_id"), item_record.get("document_id"), item_record.get("error"),
            provenance.get("source_message_id"), provenance.get("source_sender"), provenance.get("source_received_at"),
            provenance.get("source_subject"), provenance.get("source_label"),
        ),
    )
    return cur.fetchone()["item_id"]


def process_bulk_cv_import(
    *,
    company_code: str,
    created_by_user_id: str | None,
    created_by_email: str | None,
    uploaded_files: list[tuple[str, bytes]],
    metadata_rows: dict[str, dict[str, str]],
    default_position_code: str | None,
    default_position_title: str | None,
    source: str | None = "bulk_upload",
) -> dict[str, Any]:
    company = str(company_code or "").strip().upper()
    source = source if source in IMPORT_SOURCES else "bulk_upload"
    files = _import_expand_files(uploaded_files)
    items: list[dict[str, Any]] = []
    seen_checksums: dict[str, str] = {}
    counts = {"imported": 0, "duplicate": 0, "failed": 0, "needs_role": 0, "review": 0, "auto_admitted": 0}
    auto_admit_enabled = company_auto_admit_imports(company)

    with db_connect() as conn:
        with conn.cursor() as cur:
            # Preload the company's positions once so per-file role resolution makes
            # no extra DB calls (keeps the core reusable by chunked enterprise jobs).
            company_positions = _import_load_company_positions(cur, company)

            cur.execute(
                """
                INSERT INTO import_batches
                    (company_code, source, status, created_by_user_id, created_by_email, total_files, default_position_code, options)
                VALUES (%s,%s,'processing',%s,%s,%s,%s,%s)
                RETURNING batch_id::text
                """,
                (
                    company,
                    source,
                    created_by_user_id,
                    created_by_email,
                    len(files),
                    (default_position_code or None),
                    Json(json_safe({"default_position_title": default_position_title, "metadata_rows": len(metadata_rows), "source": source})),
                ),
            )
            batch_id = cur.fetchone()["batch_id"]

            for filename, data, folder_hint in files:
                item_record = _import_process_one_file(
                    cur,
                    company=company,
                    batch_id=batch_id,
                    source=source,
                    company_positions=company_positions,
                    filename=filename,
                    data=data,
                    folder_hint=folder_hint,
                    meta=metadata_rows.get(_import_norm_key(Path(filename).name), {}),
                    default_position_code=default_position_code,
                    default_position_title=default_position_title,
                    auto_admit_enabled=auto_admit_enabled,
                    seen_checksums=seen_checksums,
                )
                _import_bump_counts(counts, item_record)
                item_record["item_id"] = _import_insert_item(cur, batch_id=batch_id, company=company, item_record=item_record)
                items.append(item_record)

            cur.execute(
                """
                UPDATE import_batches
                SET status='completed', imported_count=%s, duplicate_count=%s, failed_count=%s,
                    needs_role_count=%s, updated_at=now()
                WHERE batch_id=%s
                """,
                (counts["imported"], counts["duplicate"], counts["failed"], counts["needs_role"], batch_id),
            )
        conn.commit()

    return {
        "batch_id": batch_id,
        "company_code": company,
        "total_files": len(files),
        "counts": counts,
        "items": json_safe(items),
    }


# --- Mailbox ingestion: sync core (provider-agnostic) -----------------------
# Email CVs feed the SAME shared import core as bulk upload (no separate pipeline):
#   provider.fetch_new_messages -> _import_process_one_file -> register_imported_cv
#   -> Import review / Needs role. Sync never messages candidates and never enters
#   Ranking. A provider adapter (Gmail in Step 3) is injected; tests inject a fake.
_EMAIL_ADDR_RE = re.compile(r"[\w.+-]+@[\w-]+\.[\w.-]+")


def _parse_email_address(sender: str | None) -> str | None:
    match = _EMAIL_ADDR_RE.search(str(sender or ""))
    return match.group(0).lower() if match else None


# --- Gmail read-only transport via the `gog` CLI ----------------------------
# `gog` is used ONLY to move bytes: it never stores credentials (token is passed
# via $GOG_ACCESS_TOKEN env, not argv) and never touches Wathefni's DB. All import
# logic stays in run_mailbox_sync / the shared import core.
GOG_GMAIL_ENABLED_COMMANDS = "gmail"


def _run_gog_gmail(args: list[str], *, account: str, access_token: str, timeout: int = 60) -> Any:
    """Invoke a read-only gmail subcommand. The access token is injected through the
    environment so it never appears in argv, process lists, or our logs. On failure
    we raise a generic reason — raw Google/gog errors are never surfaced."""
    env_vars = os.environ.copy()
    env_vars.update(openclaw_env())
    env_vars["GOG_ACCESS_TOKEN"] = access_token
    full = ["gog", "gmail", *args, "--account", account, "--enable-commands", GOG_GMAIL_ENABLED_COMMANDS, "--json", "--no-input"]
    proc = subprocess.run(full, text=True, capture_output=True, timeout=timeout, env=env_vars)
    if proc.returncode != 0:
        raise RuntimeError(f"gog_gmail_failed:{proc.returncode}")
    out = (proc.stdout or "").strip()
    if not out:
        return None
    try:
        return json.loads(out)
    except Exception:
        return None


def _gmail_extract_message_ids(search: Any) -> list[str]:
    raw: list[str] = []
    candidates: list[Any] = []
    if isinstance(search, list):
        candidates = search
    elif isinstance(search, dict):
        for key in ("messages", "threads", "results", "result", "items"):
            value = search.get(key)
            if isinstance(value, list) and value:
                candidates = value
                break
    for item in candidates:
        if isinstance(item, dict) and item.get("id"):
            raw.append(str(item["id"]))
        elif isinstance(item, str):
            raw.append(item)
    seen: set[str] = set()
    ordered: list[str] = []
    for mid in raw:
        if mid not in seen:
            seen.add(mid)
            ordered.append(mid)
    return ordered


def _gmail_header(headers: list[dict[str, Any]] | None, name: str) -> str | None:
    for header in headers or []:
        if str(header.get("name") or "").lower() == name.lower():
            return header.get("value")
    return None


def _gmail_walk_parts(part: dict[str, Any], out: list[dict[str, Any]]) -> None:
    if not isinstance(part, dict):
        return
    body = part.get("body") or {}
    filename = part.get("filename") or ""
    attachment_id = body.get("attachmentId")
    if filename and attachment_id:
        out.append({"filename": filename, "attachment_id": attachment_id, "mime_type": part.get("mimeType")})
    for child in part.get("parts") or []:
        _gmail_walk_parts(child, out)


def _gmail_normalize_message(full: Any, message_id: str) -> dict[str, Any]:
    """Map a Gmail message resource into the provider-neutral shape consumed by
    run_mailbox_sync. Isolated here so the exact gog/Gmail envelope is the only
    thing that ever needs adjusting."""
    msg = full if isinstance(full, dict) else {}
    # gog may wrap the resource (e.g. {"message": {...}} or {"result": {...}}).
    for key in ("message", "result", "data"):
        if isinstance(msg.get(key), dict) and (msg[key].get("payload") or msg[key].get("id")):
            msg = msg[key]
            break
    payload = msg.get("payload") if isinstance(msg.get("payload"), dict) else {}
    headers = payload.get("headers") if isinstance(payload.get("headers"), list) else []
    attachment_refs: list[dict[str, Any]] = []
    if payload:
        _gmail_walk_parts(payload, attachment_refs)
    internal_ms = 0
    try:
        internal_ms = int(msg.get("internalDate") or 0)
    except (TypeError, ValueError):
        internal_ms = 0
    return {
        "message_id": str(msg.get("id") or message_id),
        "sender": _gmail_header(headers, "From"),
        "subject": _gmail_header(headers, "Subject"),
        "received_at": _gmail_header(headers, "Date"),
        "_internal_epoch": int(internal_ms / 1000) if internal_ms else 0,
        "_attachment_refs": attachment_refs,
    }


class GmailProvider:
    """Read-only Gmail adapter. Wraps `gog` as a stateless transport; Wathefni mints
    the access token from its own encrypted refresh token per call."""

    def _account(self, connection: dict[str, Any]) -> str:
        account = str(connection.get("email_address") or "").strip()
        if not account:
            raise RuntimeError("gmail_account_missing")
        return account

    def _access_token(self, connection: dict[str, Any]) -> str:
        refresh = get_mailbox_credential(connection.get("company_code"), connection.get("mailbox_id"), "oauth_refresh_token")
        if not refresh:
            raise RuntimeError("gmail_no_credentials")
        return mint_google_access_token(refresh)

    def list_labels(self, connection: dict[str, Any]) -> list[dict[str, Any]]:
        account = self._account(connection)
        token = self._access_token(connection)
        data = _run_gog_gmail(["labels", "list"], account=account, access_token=token)
        items: list[Any] = []
        if isinstance(data, list):
            items = data
        elif isinstance(data, dict):
            for key in ("labels", "result", "items"):
                if isinstance(data.get(key), list):
                    items = data[key]
                    break
        labels: list[dict[str, Any]] = []
        for item in items:
            if not isinstance(item, dict):
                continue
            name = item.get("name")
            if not name:
                continue
            labels.append({"id": item.get("id"), "name": name, "type": item.get("type") or "user"})
        return labels

    def _download_attachment(self, account: str, token: str, message_id: str, attachment_id: str) -> bytes | None:
        with tempfile.TemporaryDirectory(prefix="wathefni-gmail-") as tmp_dir:
            out_path = str(Path(tmp_dir) / "attachment.bin")
            _run_gog_gmail(["attachment", message_id, attachment_id, "--out", out_path], account=account, access_token=token)
            try:
                return Path(out_path).read_bytes()
            except Exception:
                return None

    def fetch_new_messages(self, *, connection: dict[str, Any], cursor: dict[str, Any] | None):
        account = self._account(connection)
        token = self._access_token(connection)
        label = str(connection.get("label_filter") or "").strip()
        after_epoch = 0
        try:
            after_epoch = int((cursor or {}).get("after_epoch") or 0)
        except (TypeError, ValueError):
            after_epoch = 0

        query_parts = ["has:attachment"]
        if label:
            query_parts.append(f'label:"{label}"')
        if after_epoch:
            query_parts.append(f"after:{after_epoch}")
        query = " ".join(query_parts)

        search = _run_gog_gmail(["search", query, "--max", "50"], account=account, access_token=token)
        message_ids = _gmail_extract_message_ids(search)

        messages: list[dict[str, Any]] = []
        max_epoch = after_epoch
        for message_id in message_ids:
            full = _run_gog_gmail(["get", message_id, "--format", "full"], account=account, access_token=token)
            msg = _gmail_normalize_message(full, message_id)
            attachments: list[dict[str, Any]] = []
            for ref in msg.pop("_attachment_refs", []):
                if Path(str(ref.get("filename") or "")).suffix.lower() not in IMPORT_CV_EXTENSIONS:
                    continue
                data = self._download_attachment(account, token, msg["message_id"], ref["attachment_id"])
                if data:
                    attachments.append({"filename": ref["filename"], "data": data, "mime_type": ref.get("mime_type")})
            msg["label"] = label or None
            msg["attachments"] = attachments
            max_epoch = max(max_epoch, int(msg.pop("_internal_epoch", 0) or 0))
            messages.append(msg)

        # Re-query the boundary second next time; message-id + checksum dedupe makes
        # reprocessing the boundary message safe.
        next_cursor = {"after_epoch": max_epoch or after_epoch}
        return messages, next_cursor


def build_mailbox_provider(connection: dict[str, Any]) -> Any:
    """Resolve a read-only provider adapter for a connection. Tests may inject a
    provider explicitly; production resolves the real adapter here."""
    provider = str(connection.get("provider") or "").strip().lower()
    if provider == "gmail":
        return GmailProvider()
    raise NotImplementedError(f"mailbox_provider_unavailable:{provider}")


def _mailbox_record_sync_outcome(
    company: str, mailbox_id: str, *, status: str, last_sync_status: str,
    last_error: str | None = None, cursor: dict[str, Any] | None = None,
) -> None:
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                UPDATE mailbox_connections
                SET status=%s, last_sync_status=%s, last_error=%s, last_synced_at=now(),
                    cursor=COALESCE(%s, cursor), updated_at=now()
                WHERE company_code=%s AND mailbox_id=%s
                """,
                (status, last_sync_status, last_error, (Json(json_safe(cursor)) if cursor is not None else None), company, mailbox_id),
            )
        conn.commit()


def run_mailbox_sync(
    company_code: str,
    mailbox_id: str,
    mode: str = "manual",
    *,
    provider: Any = None,
    limit: int = 200,
) -> dict[str, Any]:
    """Reusable sync entrypoint for BOTH manual ('Check now') and scheduled runs.

    Read-only: fetches new messages since the stored cursor, imports CV attachments
    through the shared import core (held in Needs role / Import review), advances the
    cursor only on a committed live run, and never sends anything to candidates.
    """
    company = str(company_code or "").strip().upper()
    if not mailbox_ingestion_enabled():
        return {"ok": False, "skipped": "mailbox_sync_disabled"}
    connection = get_mailbox_connection(company, mailbox_id)
    if not connection:
        return {"ok": False, "error": "mailbox_not_found"}
    if str(connection.get("status") or "") == "disabled" or not connection.get("sync_enabled", False) and mode == "scheduled":
        return {"ok": False, "skipped": "mailbox_sync_off"}

    prov = provider or build_mailbox_provider(connection)
    cursor = connection.get("cursor") if isinstance(connection.get("cursor"), dict) else {}
    live = str(connection.get("sync_mode") or "dry_run").strip().lower() == "live"

    try:
        messages, next_cursor = prov.fetch_new_messages(connection=connection, cursor=cursor)
    except Exception as exc:
        # Any provider/auth/network failure becomes a calm "needs reconnecting"
        # state; the raw reason is kept internally and never surfaced to HR.
        _mailbox_record_sync_outcome(company, mailbox_id, status="needs_reconnect", last_sync_status="error", last_error=str(exc)[:500])
        return {"ok": False, "error": "mailbox_fetch_failed"}

    messages = list(messages or [])[: max(1, int(limit))]

    def _attachments(message: dict[str, Any]) -> list[dict[str, Any]]:
        return [a for a in (message.get("attachments") or []) if a.get("data") is not None and a.get("filename")]

    if not live:
        # Dry run: report what WOULD import, write nothing, do not advance the cursor.
        would = sum(len(_attachments(m)) for m in messages)
        _mailbox_record_sync_outcome(company, mailbox_id, status="connected", last_sync_status="dry_run")
        return {"ok": True, "dry_run": True, "mode": mode, "messages": len(messages), "would_import": would, "mailbox_id": mailbox_id}

    items: list[dict[str, Any]] = []
    seen_checksums: dict[str, str] = {}
    counts = {"imported": 0, "duplicate": 0, "failed": 0, "needs_role": 0, "review": 0, "auto_admitted": 0}
    total_attachments = sum(len(_attachments(m)) for m in messages)
    auto_admit_enabled = company_auto_admit_imports(company)

    with db_connect() as conn:
        with conn.cursor() as cur:
            company_positions = _import_load_company_positions(cur, company)
            cur.execute(
                """
                INSERT INTO import_batches
                    (company_code, source, status, total_files, mailbox_id, options)
                VALUES (%s,'email','processing',%s,%s,%s)
                RETURNING batch_id::text
                """,
                (company, total_attachments, mailbox_id, Json(json_safe({"mode": mode, "messages": len(messages)}))),
            )
            batch_id = cur.fetchone()["batch_id"]

            for message in messages:
                sender = message.get("sender")
                provenance = {
                    "source_message_id": message.get("message_id"),
                    "source_sender": sender,
                    "source_received_at": message.get("received_at"),
                    "source_subject": message.get("subject"),
                    "source_label": message.get("label") or connection.get("label_filter"),
                }
                for attachment in _attachments(message):
                    item_record = _import_process_one_file(
                        cur,
                        company=company,
                        batch_id=batch_id,
                        source="email",
                        company_positions=company_positions,
                        filename=attachment.get("filename"),
                        data=attachment.get("data"),
                        folder_hint=None,  # email folders/labels are not roles
                        meta={"email": _parse_email_address(sender)},
                        auto_admit_enabled=auto_admit_enabled,
                        seen_checksums=seen_checksums,
                    )
                    _import_bump_counts(counts, item_record)
                    item_record["item_id"] = _import_insert_item(cur, batch_id=batch_id, company=company, item_record=item_record, provenance=provenance)
                    items.append(item_record)

            cur.execute(
                """
                UPDATE import_batches
                SET status='completed', imported_count=%s, duplicate_count=%s, failed_count=%s,
                    needs_role_count=%s, updated_at=now()
                WHERE batch_id=%s
                """,
                (counts["imported"], counts["duplicate"], counts["failed"], counts["needs_role"], batch_id),
            )
            # Advance the cursor in the SAME transaction: if the import rolls back,
            # the cursor does not move, so the next run safely retries the messages.
            cur.execute(
                """
                UPDATE mailbox_connections
                SET cursor=%s, status='connected', last_sync_status='ok', last_error=NULL,
                    last_synced_at=now(), updated_at=now()
                WHERE company_code=%s AND mailbox_id=%s
                """,
                (Json(json_safe(next_cursor or cursor)), company, mailbox_id),
            )
        conn.commit()

    return {
        "ok": True,
        "mode": mode,
        "batch_id": batch_id,
        "company_code": company,
        "messages": len(messages),
        "total_files": total_attachments,
        "counts": counts,
        "items": json_safe(items),
    }


# --- Mailbox ingestion: management helpers + Settings -> Integrations API ----
def mailbox_feature_status() -> dict[str, Any]:
    """Whether the Integrations surface should be shown at all. Fail-closed: the
    feature is hidden unless the master flag is on, encryption is configured, and
    the Gmail OAuth app is configured."""
    return {
        "enabled": mailbox_ingestion_enabled(),
        "encryption_ready": mailbox_encryption_available(),
        "gmail_oauth_ready": gmail_oauth_available(),
        "providers": [{"key": "gmail", "label": MAILBOX_PROVIDER_LABELS["gmail"]}],
    }


def mailbox_status_label(row: dict[str, Any]) -> str:
    """Calm, HR-facing status copy. No technical states leak to the UI."""
    status = str(row.get("status") or "disconnected")
    if status == "connected":
        return "Connected"
    if status == "needs_reconnect" or status == "error":
        return "Needs reconnecting"
    if status == "disabled":
        return "Disabled"
    return "Not connected"


def mailbox_connection_ui(row: dict[str, Any] | None) -> dict[str, Any] | None:
    public = mailbox_connection_public(row)
    if not public:
        return None
    public["status_label"] = mailbox_status_label(row or {})
    public["auto_import"] = bool((row or {}).get("sync_enabled"))
    return public


def gmail_list_labels_safe(company: str, mailbox_id: str) -> dict[str, Any]:
    """List labels for the label picker. Any provider/auth failure becomes a calm
    needs_reconnect state; raw Gmail/OAuth errors are never surfaced."""
    connection = get_mailbox_connection(company, mailbox_id)
    if not connection:
        return {"ok": False, "error": "mailbox_not_found"}
    try:
        provider = build_mailbox_provider(connection)
        labels = provider.list_labels(connection)
    except Exception:
        _mailbox_record_sync_outcome(company, mailbox_id, status="needs_reconnect", last_sync_status="error", last_error="label_list_failed")
        return {"ok": False, "error": "mailbox_needs_reconnect"}
    # Only show selectable mail labels; hide Gmail system categories that are not folders.
    hidden = {"CHAT", "SENT", "DRAFT", "TRASH", "SPAM"}
    names = [lab["name"] for lab in labels if str(lab.get("id") or "").upper() not in hidden]
    return {"ok": True, "labels": sorted(names, key=lambda s: s.lower())}


def run_due_mailbox_syncs(limit_per_mailbox: int = 200) -> dict[str, Any]:
    """Scheduled entrypoint (for a timer/worker): syncs every connected mailbox that
    has auto-import on. Safe to call when the flag is off (no-op)."""
    if not mailbox_ingestion_enabled():
        return {"ok": False, "skipped": "mailbox_sync_disabled"}
    processed: list[dict[str, Any]] = []
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT company_code, mailbox_id::text AS mailbox_id
                FROM mailbox_connections
                WHERE sync_enabled=true AND status='connected'
                ORDER BY last_synced_at ASC NULLS FIRST
                """,
            )
            due = [dict(r) for r in cur.fetchall()]
    for row in due:
        try:
            result = run_mailbox_sync(row["company_code"], row["mailbox_id"], "scheduled", limit=limit_per_mailbox)
        except Exception:
            result = {"ok": False, "error": "sync_failed"}
        processed.append({"company_code": row["company_code"], "mailbox_id": row["mailbox_id"], "ok": bool(result.get("ok"))})
    return {"ok": True, "synced": len(processed), "results": processed}


def _mailbox_require_feature(context: dict[str, Any]) -> str:
    """Gate every Integrations endpoint behind settings.manage + the master flag.
    Returns the company code."""
    require_entitlement(context, "pre_hiring", "settings.manage")
    if not mailbox_ingestion_enabled():
        raise HTTPException(status_code=404, detail={"error": "mailbox_feature_unavailable", "message": "Email inbox import is not available."})
    return context["company_code"]


@app.get("/dashboard/prehire/integrations/mailbox")
def dashboard_mailbox_list(context: dict[str, Any] = Depends(prehire_dashboard_context)):
    require_entitlement(context, "pre_hiring", "settings.manage")
    company = context["company_code"]
    status = mailbox_feature_status()
    connections = [mailbox_connection_ui(row) for row in list_mailbox_connections(company)] if status["enabled"] else []
    return {"company_code": company, "feature": status, "connections": connections}


@app.post("/dashboard/prehire/integrations/mailbox/connect")
def dashboard_mailbox_connect(
    request: dict[str, Any] | None = None,
    context: dict[str, Any] = Depends(prehire_dashboard_context),
):
    company = _mailbox_require_feature(context)
    if not gmail_oauth_available():
        raise HTTPException(status_code=503, detail={"error": "gmail_not_configured", "message": "Email connection is not configured on the server yet."})
    body = request or {}
    label_filter = str(body.get("label_filter") or "").strip() or None
    connection = create_mailbox_connection(
        company_code=company,
        provider="gmail",
        label_filter=label_filter,
        scopes=list(GMAIL_OAUTH_SCOPES),
        created_by_user_id=context.get("actor_user_id"),
        created_by_email=context.get("actor_email"),
    )
    state = sign_mailbox_oauth_state({
        "company_code": company,
        "mailbox_id": connection["mailbox_id"],
        "nonce": secrets.token_urlsafe(8),
        "exp": int(time_module.time()) + 900,
    })
    record_admin_audit(
        context,
        "mailbox_connection_started",
        summary="Started connecting an email inbox (Gmail).",
        target_type="mailbox",
        target=str(connection.get("mailbox_id") or ""),
        details={"provider": "gmail", "label_filter": label_filter},
    )
    return {"ok": True, "mailbox_id": connection["mailbox_id"], "authorize_url": gmail_authorize_url(state)}


@app.get("/dashboard/prehire/integrations/mailbox/callback")
def dashboard_mailbox_callback(
    code: str | None = Query(default=None),
    state: str | None = Query(default=None),
    error: str | None = Query(default=None),
):
    # Hit by Google in the user's browser (no dashboard headers). We rely on the
    # HMAC-signed state for company/mailbox binding + CSRF protection.
    redirect_base = "/dashboard/?page=settings&mailbox="
    if not mailbox_ingestion_enabled() or not gmail_oauth_available():
        return RedirectResponse(url=redirect_base + "unavailable", status_code=302)
    payload = verify_mailbox_oauth_state(state or "")
    if error or not code or not payload:
        return RedirectResponse(url=redirect_base + "failed", status_code=302)
    company = str(payload.get("company_code") or "")
    mailbox_id = str(payload.get("mailbox_id") or "")
    connection = get_mailbox_connection(company, mailbox_id)
    if not connection:
        return RedirectResponse(url=redirect_base + "failed", status_code=302)
    try:
        tokens = exchange_gmail_auth_code(code)
        set_mailbox_credential(
            company_code=company,
            mailbox_id=mailbox_id,
            secret_value=tokens["refresh_token"],
            secret_type="oauth_refresh_token",
            token_meta={"scope": " ".join(GMAIL_OAUTH_SCOPES)},
        )
        with db_connect() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """
                    UPDATE mailbox_connections
                    SET status='connected', sync_mode='live', email_address=COALESCE(%s, email_address),
                        last_error=NULL, updated_at=now()
                    WHERE company_code=%s AND mailbox_id=%s
                    """,
                    (tokens.get("email_address"), company, mailbox_id),
                )
            conn.commit()
    except Exception:
        # Never surface the raw OAuth/Google error.
        _mailbox_record_sync_outcome(company, mailbox_id, status="needs_reconnect", last_sync_status="error", last_error="oauth_exchange_failed")
        return RedirectResponse(url=redirect_base + "failed", status_code=302)
    return RedirectResponse(url=redirect_base + "connected", status_code=302)


@app.get("/dashboard/prehire/integrations/mailbox/{mailbox_id}/labels")
def dashboard_mailbox_labels(mailbox_id: str, context: dict[str, Any] = Depends(prehire_dashboard_context)):
    company = _mailbox_require_feature(context)
    result = gmail_list_labels_safe(company, mailbox_id)
    if not result.get("ok"):
        if result.get("error") == "mailbox_not_found":
            raise HTTPException(status_code=404, detail={"error": "mailbox_not_found"})
        # Calm reconnect signal; the UI shows "Needs reconnecting".
        raise HTTPException(status_code=409, detail={"error": "mailbox_needs_reconnect", "message": "Reconnect the inbox to continue."})
    return {"company_code": company, "labels": result["labels"]}


@app.patch("/dashboard/prehire/integrations/mailbox/{mailbox_id}")
def dashboard_mailbox_update(
    mailbox_id: str,
    request: dict[str, Any] | None = None,
    context: dict[str, Any] = Depends(prehire_dashboard_context),
):
    company = _mailbox_require_feature(context)
    connection = get_mailbox_connection(company, mailbox_id)
    if not connection:
        raise HTTPException(status_code=404, detail={"error": "mailbox_not_found"})
    body = request or {}
    sets: list[str] = []
    params: list[Any] = []
    if "label_filter" in body:
        sets.append("label_filter=%s")
        params.append(str(body.get("label_filter") or "").strip() or None)
    if "auto_import" in body:
        sets.append("sync_enabled=%s")
        params.append(bool(body.get("auto_import")))
    if not sets:
        raise HTTPException(status_code=400, detail={"error": "nothing_to_update"})
    params.extend([company, mailbox_id])
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                f"UPDATE mailbox_connections SET {', '.join(sets)}, updated_at=now() WHERE company_code=%s AND mailbox_id=%s",
                tuple(params),
            )
        conn.commit()
    record_admin_audit(
        context,
        "mailbox_settings_updated",
        summary="Updated email inbox settings.",
        target_type="mailbox",
        target=mailbox_id,
        details={key: body.get(key) for key in ("label_filter", "auto_import") if key in body},
    )
    return {"ok": True, "connection": mailbox_connection_ui(get_mailbox_connection(company, mailbox_id))}


@app.post("/dashboard/prehire/integrations/mailbox/{mailbox_id}/check-now")
def dashboard_mailbox_check_now(mailbox_id: str, context: dict[str, Any] = Depends(prehire_dashboard_context)):
    company = _mailbox_require_feature(context)
    connection = get_mailbox_connection(company, mailbox_id)
    if not connection:
        raise HTTPException(status_code=404, detail={"error": "mailbox_not_found"})
    if not connection.get("has_credentials"):
        raise HTTPException(status_code=409, detail={"error": "mailbox_needs_reconnect", "message": "Connect the inbox first."})
    result = run_mailbox_sync(company, mailbox_id, "manual")
    if not result.get("ok"):
        if result.get("error") == "mailbox_fetch_failed":
            raise HTTPException(status_code=409, detail={"error": "mailbox_needs_reconnect", "message": "Reconnect the inbox to continue."})
        raise HTTPException(status_code=409, detail={"error": "mailbox_unavailable", "message": "Could not check the inbox right now."})
    counts = result.get("counts") or {}
    imported = int(counts.get("imported") or 0)
    # HR-facing summary only; no technical fields.
    return {
        "ok": True,
        "imported": imported,
        "duplicates": int(counts.get("duplicate") or 0),
        "skipped": int(counts.get("failed") or 0),
        "needs_role": int(counts.get("needs_role") or 0),
        "message": (f"Imported {imported} new CV{'s' if imported != 1 else ''} to Import Review." if imported else "No new CVs found."),
    }


@app.delete("/dashboard/prehire/integrations/mailbox/{mailbox_id}")
def dashboard_mailbox_disconnect(mailbox_id: str, context: dict[str, Any] = Depends(prehire_dashboard_context)):
    company = _mailbox_require_feature(context)
    if not delete_mailbox_connection(company, mailbox_id):
        raise HTTPException(status_code=404, detail={"error": "mailbox_not_found"})
    record_admin_audit(
        context,
        "mailbox_disconnected",
        summary="Disconnected an email inbox.",
        target_type="mailbox",
        target=mailbox_id,
    )
    return {"ok": True}


# --- Inbound email intake: routing + processing + Postmark webhook ----------
def _split_email_address(addr: str | None) -> tuple[str, str]:
    parsed = _parse_email_address(addr) or str(addr or "").strip().lower()
    if "@" in parsed:
        local, _, domain = parsed.partition("@")
        return local, domain
    return parsed, ""


def _parse_email_date(value: str | None):
    if not value:
        return None
    try:
        from email.utils import parsedate_to_datetime

        return parsedate_to_datetime(value)
    except Exception:
        return None


def _postmark_spam_score(payload: dict[str, Any]) -> tuple[float | None, bool]:
    score: float | None = None
    flagged = False
    for header in payload.get("Headers") or []:
        name = str(header.get("Name") or "").lower()
        value = str(header.get("Value") or "")
        if name == "x-spam-score":
            try:
                score = float(value.strip())
            except ValueError:
                pass
        elif name == "x-spam-status" and value.strip().lower().startswith("yes"):
            flagged = True
    return score, flagged


def resolve_intake_address(cur: Any, recipient: str | None, mailbox_hash: str | None) -> dict[str, Any] | None:
    """Map an inbound recipient (envelope address) to a company intake row.
    Tries exact local+domain, then base local (domain-agnostic), then the
    Postmark mailbox hash as a slug. company_code comes only from this table."""
    local, domain = _split_email_address(recipient)
    base = local.split("+", 1)[0]
    attempts: list[tuple[str, str]] = [(base, domain), (base, "")]
    if mailbox_hash:
        attempts += [(mailbox_hash.lower(), domain), (mailbox_hash.lower(), "")]
    for cand_local, cand_domain in attempts:
        if not cand_local:
            continue
        cur.execute(
            "SELECT *, intake_id::text AS intake_id FROM intake_addresses "
            "WHERE status='active' AND lower(local_part)=%s AND lower(coalesce(domain,''))=%s LIMIT 1",
            (cand_local, cand_domain),
        )
        row = cur.fetchone()
        if row:
            return dict(row)
    return None


def process_postmark_inbound(payload: dict[str, Any]) -> dict[str, Any]:
    """Process one Postmark inbound message through the shared import core.

    Idempotent on (provider, provider_message_id). Resolves recipient -> company,
    quarantines spam, extracts CV attachments, and lands them in Import review /
    Needs role. Never messages candidates and never enters Ranking.
    """
    provider = "postmark"
    provider_message_id = str(payload.get("MessageID") or "").strip()
    recipient = str(payload.get("OriginalRecipient") or "").strip()
    if not recipient:
        to_full = payload.get("ToFull") or []
        if isinstance(to_full, list) and to_full:
            recipient = str((to_full[0] or {}).get("Email") or "")
    if not recipient:
        recipient = str(payload.get("To") or "")
    mailbox_hash = str(payload.get("MailboxHash") or "").strip()
    from_full = payload.get("FromFull") or {}
    from_address = (from_full.get("Email") if isinstance(from_full, dict) else None) or _parse_email_address(payload.get("From"))
    subject = str(payload.get("Subject") or "").strip() or None
    received_at = _parse_email_date(payload.get("Date"))
    spam_score, spam_flagged = _postmark_spam_score(payload)
    if not provider_message_id:
        provider_message_id = "synth-" + hashlib.sha256(f"{recipient}|{from_address}|{subject}|{payload.get('Date')}".encode("utf-8")).hexdigest()[:24]

    attachments = [a for a in (payload.get("Attachments") or []) if isinstance(a, dict) and a.get("Name") and a.get("Content")]

    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                INSERT INTO inbound_messages
                    (provider, provider_message_id, from_address, envelope_recipient, subject,
                     received_at, spam_score, attachment_count, status)
                VALUES (%s,%s,%s,%s,%s,%s,%s,%s,'received')
                ON CONFLICT (provider, provider_message_id) DO NOTHING
                RETURNING inbound_id::text
                """,
                (provider, provider_message_id, from_address, recipient, subject, received_at, spam_score, len(attachments)),
            )
            inserted = cur.fetchone()
            if not inserted:
                conn.commit()
                return {"duplicate": True}
            inbound_id = inserted["inbound_id"]

            intake = resolve_intake_address(cur, recipient, mailbox_hash)
            if not intake:
                cur.execute("UPDATE inbound_messages SET status='rejected', error='unknown_recipient', updated_at=now() WHERE inbound_id=%s", (inbound_id,))
                conn.commit()
                return {"ignored": "unknown_recipient"}
            company = str(intake.get("company_code") or "").strip().upper()
            cur.execute("UPDATE inbound_messages SET company_code=%s, intake_id=%s, updated_at=now() WHERE inbound_id=%s", (company, intake["intake_id"], inbound_id))

            if spam_flagged or (spam_score is not None and spam_score >= INBOUND_SPAM_QUARANTINE_THRESHOLD):
                cur.execute("UPDATE inbound_messages SET status='quarantined', updated_at=now() WHERE inbound_id=%s", (inbound_id,))
                conn.commit()
                return {"company_code": company, "quarantined": True}

            if not attachments:
                cur.execute("UPDATE inbound_messages SET status='processed', error='no_attachments', updated_at=now() WHERE inbound_id=%s", (inbound_id,))
                conn.commit()
                return {"company_code": company, "imported": 0, "note": "no_attachments"}

            company_positions = _import_load_company_positions(cur, company)
            cur.execute(
                """
                INSERT INTO import_batches (company_code, source, status, total_files, intake_id, options)
                VALUES (%s,'email_inbound','processing',%s,%s,%s)
                RETURNING batch_id::text
                """,
                (company, len(attachments), intake["intake_id"], Json(json_safe({"provider": provider, "from": from_address}))),
            )
            batch_id = cur.fetchone()["batch_id"]

            provenance = {
                "source_message_id": provider_message_id,
                "source_sender": payload.get("From") or from_address,
                "source_received_at": received_at,
                "source_subject": subject,
                "source_label": recipient,
            }
            counts = {"imported": 0, "duplicate": 0, "failed": 0, "needs_role": 0, "review": 0, "auto_admitted": 0}
            auto_admit_enabled = company_auto_admit_imports(company)
            seen_checksums: dict[str, str] = {}
            items: list[dict[str, Any]] = []
            for attachment in attachments:
                try:
                    data = base64.b64decode(attachment.get("Content") or "")
                except Exception:
                    continue
                item_record = _import_process_one_file(
                    cur,
                    company=company,
                    batch_id=batch_id,
                    source="email_inbound",
                    company_positions=company_positions,
                    filename=attachment.get("Name"),
                    data=data,
                    folder_hint=None,
                    meta={"email": from_address},
                    seen_checksums=seen_checksums,
                    default_position_code=(intake.get("position_code") or None),
                    default_position_title=(intake.get("position_title") or None),
                    auto_admit_enabled=auto_admit_enabled,
                )
                _import_bump_counts(counts, item_record)
                item_record["item_id"] = _import_insert_item(cur, batch_id=batch_id, company=company, item_record=item_record, provenance=provenance)
                items.append(item_record)

            cur.execute(
                """
                UPDATE import_batches
                SET status='completed', imported_count=%s, duplicate_count=%s, failed_count=%s,
                    needs_role_count=%s, updated_at=now()
                WHERE batch_id=%s
                """,
                (counts["imported"], counts["duplicate"], counts["failed"], counts["needs_role"], batch_id),
            )
            cur.execute("UPDATE inbound_messages SET status='processed', batch_id=%s, updated_at=now() WHERE inbound_id=%s", (batch_id, inbound_id))
        conn.commit()

    return {"company_code": company, "batch_id": batch_id, "counts": counts, "items": json_safe(items)}


def _verify_postmark_token(authorization: str | None, token: str | None, secret: str) -> bool:
    if not secret:
        return False
    provided = (token or "").strip()
    if not provided and authorization and authorization.lower().startswith("basic "):
        try:
            decoded = base64.b64decode(authorization.split(" ", 1)[1]).decode("utf-8")
            provided = decoded.split(":", 1)[1] if ":" in decoded else decoded
        except Exception:
            provided = ""
    return bool(provided) and hmac.compare_digest(provided, secret)


def _verify_postmark_secret(authorization: str | None, token: str | None) -> bool:
    return _verify_postmark_token(authorization, token, inbound_postmark_secret())


@app.post("/webhook/postmark/inbound")
async def webhook_postmark_inbound(
    request: Request,
    authorization: str | None = Header(default=None),
    token: str | None = Query(default=None),
):
    ensure_schema()
    # Fail closed: require the shared secret (Basic Auth password or ?token=).
    if not inbound_postmark_secret():
        raise HTTPException(status_code=503, detail={"error": "inbound_not_configured"})
    if not _verify_postmark_secret(authorization, token):
        raise HTTPException(status_code=401, detail={"error": "unauthorized"})
    if not inbound_email_enabled():
        return {"ok": True, "ignored": "inbound_disabled"}
    try:
        payload = await request.json()
    except Exception:
        raise HTTPException(status_code=400, detail={"error": "invalid_json"})
    if not isinstance(payload, dict):
        raise HTTPException(status_code=400, detail={"error": "invalid_payload"})
    try:
        result = process_postmark_inbound(payload)
    except Exception:
        # Never 500 to Postmark (it would retry); ack and rely on the audit row.
        return {"ok": False, "error": "inbound_processing_failed"}
    return {"ok": True, **result}


def process_postmark_outbound_status(payload: dict[str, Any]) -> dict[str, Any]:
    """Record a Postmark delivery/bounce/complaint webhook as a delivery event.

    Best-effort links back to the original send (via the stored message_id) so the
    audit row is company/subject scoped. Opens and other record types are ignored.
    """
    record_type = str(payload.get("RecordType") or "").strip().lower()
    message_id = str(payload.get("MessageID") or "").strip()
    recipient = str(payload.get("Recipient") or payload.get("Email") or "").strip().lower() or None
    status_map = {"delivery": "delivered", "bounce": "bounced", "spamcomplaint": "complaint"}
    status = status_map.get(record_type)
    if not status:
        return {"ignored": record_type or "unknown"}
    last_error = None
    if status == "bounced":
        last_error = str(payload.get("Description") or payload.get("Details") or payload.get("Type") or "bounced")[:500]
    elif status == "complaint":
        last_error = "spam_complaint"
    company = subject_type = subject_key = None
    if message_id:
        try:
            with db_connect() as conn:
                with conn.cursor() as cur:
                    cur.execute(
                        "SELECT company_code, subject_type, subject_key FROM outbound_delivery_events "
                        "WHERE channel='email' AND payload->>'message_id'=%s ORDER BY created_at ASC LIMIT 1",
                        (message_id,),
                    )
                    row = cur.fetchone()
            if row:
                company = row.get("company_code")
                subject_type = row.get("subject_type")
                subject_key = row.get("subject_key")
        except Exception:
            pass
    record_outbound_delivery_event(
        account_id=None,
        target_phone=None,
        target_conversation_id=None,
        status=status,
        message_text="",
        last_error=last_error,
        payload={"postmark_status": json_safe(payload), "message_id": message_id, "recipient_email": recipient, "provider": "postmark"},
        subject_type=subject_type or "candidate",
        subject_key=subject_key,
        channel="email",
        message_kind="email_status",
        company_code=company,
    )
    return {"status": status, "message_id": message_id}


@app.post("/webhook/postmark/outbound")
async def webhook_postmark_outbound(
    request: Request,
    authorization: str | None = Header(default=None),
    token: str | None = Query(default=None),
):
    ensure_schema()
    secret = outbound_postmark_secret()
    if not secret:
        raise HTTPException(status_code=503, detail={"error": "outbound_webhook_not_configured"})
    if not _verify_postmark_token(authorization, token, secret):
        raise HTTPException(status_code=401, detail={"error": "unauthorized"})
    try:
        payload = await request.json()
    except Exception:
        raise HTTPException(status_code=400, detail={"error": "invalid_json"})
    if not isinstance(payload, dict):
        raise HTTPException(status_code=400, detail={"error": "invalid_payload"})
    try:
        result = process_postmark_outbound_status(payload)
    except Exception:
        return {"ok": False, "error": "outbound_status_processing_failed"}
    return {"ok": True, **result}


