@app.post("/dashboard/prehire/import/upload")
async def dashboard_prehire_import_upload(
    files: list[UploadFile] = File(default=[]),
    metadata_file: UploadFile | None = File(default=None),
    position_code: str | None = Form(default=None),
    position_title: str | None = Form(default=None),
    source: str | None = Form(default="bulk_upload"),
    context: dict[str, Any] = Depends(prehire_dashboard_context),
):
    require_entitlement(context, "pre_hiring", "candidate.import")
    company = context["company_code"]
    source = (source or "bulk_upload").strip().lower()
    if source not in IMPORT_SOURCES:
        source = "bulk_upload"
    if not files:
        raise HTTPException(status_code=400, detail={"error": "no_files", "message": "Attach at least one CV file or a ZIP archive."})
    if len(files) > IMPORT_MAX_FILES:
        raise HTTPException(status_code=400, detail={"error": "too_many_files", "message": f"Import up to {IMPORT_MAX_FILES} files at a time."})

    uploaded: list[tuple[str, bytes]] = []
    total = 0
    for upload in files:
        data = await upload.read()
        total += len(data)
        if total > IMPORT_MAX_TOTAL_BYTES:
            raise HTTPException(status_code=400, detail={"error": "upload_too_large", "message": "Total upload exceeds the size limit."})
        uploaded.append((upload.filename or "file", data))

    metadata_rows: dict[str, dict[str, str]] = {}
    if metadata_file is not None and metadata_file.filename:
        meta_suffix = Path(metadata_file.filename).suffix.lower()
        if meta_suffix not in IMPORT_METADATA_EXTENSIONS:
            raise HTTPException(status_code=400, detail={"error": "unsupported_metadata", "message": "Metadata must be a .csv or .xlsx file."})
        try:
            metadata_rows = parse_import_metadata_file(metadata_file.filename, await metadata_file.read())
        except Exception as exc:
            raise HTTPException(status_code=400, detail={"error": "metadata_parse_failed", "message": f"Could not read the metadata file: {exc}"})

    result = process_bulk_cv_import(
        company_code=company,
        created_by_user_id=context.get("actor_user_id"),
        created_by_email=context.get("actor_email"),
        uploaded_files=uploaded,
        metadata_rows=metadata_rows,
        default_position_code=(position_code or "").strip() or None,
        default_position_title=(position_title or "").strip() or None,
        source=source,
    )
    return {"ok": True, **result}


