@app.post("/dashboard/prehire/import/items/assign")
def dashboard_prehire_import_assign(
    request: dict[str, Any],
    context: dict[str, Any] = Depends(prehire_dashboard_context),
):
    require_entitlement(context, "pre_hiring", "candidate.import")
    company = context["company_code"]
    app_key = str((request or {}).get("app_key") or "").strip()
    position_code = str((request or {}).get("position_code") or "").strip()
    position_title = str((request or {}).get("position_title") or "").strip()
    promote = bool((request or {}).get("promote", True))
    if not app_key:
        raise HTTPException(status_code=400, detail={"error": "app_key_required"})

    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT app_key, status, position_code, position_title, phone FROM applications WHERE app_key=%s AND company_code=%s LIMIT 1",
                (app_key, company),
            )
            row = cur.fetchone()
            if not row:
                raise HTTPException(status_code=404, detail={"error": "application_not_found"})
            if str(row.get("status") or "") not in HELD_IMPORT_STATUSES:
                raise HTTPException(status_code=409, detail={"error": "not_in_import_review", "message": "This candidate is already in the pipeline."})
            effective_position = position_code or str(row.get("position_code") or "").strip()
            effective_title = position_title or str(row.get("position_title") or "").strip()
            if promote and not effective_position:
                raise HTTPException(status_code=400, detail={"error": "role_required", "message": "Assign a role before adding this candidate to the pipeline."})
            new_status = "review_pending" if promote else ("import_review" if effective_position else "needs_role")
            cur.execute(
                """
                UPDATE applications
                SET position_code=%s, position_title=%s, status=%s,
                    current_step=CASE WHEN %s='review_pending' THEN 'review' ELSE current_step END,
                    raw_json=COALESCE(raw_json,'{}'::jsonb) || jsonb_build_object(
                        'import', COALESCE(raw_json->'import','{}'::jsonb) || jsonb_build_object(
                            'needs_role', %s, 'promoted', %s, 'promoted_at', %s, 'role_assigned_by', %s
                        )
                    ),
                    updated_at=CURRENT_DATE
                WHERE app_key=%s
                """,
                (
                    effective_position or "", effective_title or None, new_status, new_status,
                    new_status == "needs_role", new_status == "review_pending",
                    now_iso() if new_status == "review_pending" else None,
                    context.get("actor_email"), app_key,
                ),
            )
            if effective_position:
                cur.execute(
                    "UPDATE candidates SET active_position_code=%s, updated_at=now() WHERE phone=%s",
                    (effective_position, row.get("phone")),
                )
            cur.execute(
                "UPDATE import_items SET position_code=%s, position_title=%s, updated_at=now() WHERE app_key=%s AND company_code=%s",
                (effective_position or None, effective_title or None, app_key, company),
            )
        conn.commit()
    record_admin_audit(
        context,
        "import_candidate_assigned",
        summary=f"Assigned {app_key} to {effective_position or 'no role'} ({new_status}).",
        target_type="application",
        target=app_key,
        details={"position_code": effective_position or None, "status": new_status, "promote": promote},
    )
    return {"ok": True, "app_key": app_key, "status": new_status, "position_code": effective_position or None}


def _intake_confidence_label(value: Any) -> str:
    try:
        c = float(value)
    except (TypeError, ValueError):
        return "none"
    if c >= 0.9:
        return "high"
    if c >= 0.6:
        return "medium"
    if c > 0:
        return "low"
    return "none"


