@app.get("/orchestrator/audit/turns")
def audit_turns(limit: int = 20):
    limit = max(1, min(limit, 100))
    with db_connect() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT turn_id, account_id, conversation_id, sender_phone, sender_role, raw_text,
                       intent, turn_focus, final_reply_source, created_at
                FROM hr_turns
                ORDER BY created_at DESC
                LIMIT %s
                """,
                (limit,),
            )
            rows = [json_safe(dict(row)) for row in cur.fetchall()]
    return {"turns": rows}


