@app.get("/dashboard/{asset_path:path}")
def dashboard_spa_or_asset(asset_path: str):
    # The dashboard SPA routes via query params + React state, so there are no
    # deep static paths (e.g. /dashboard/candidates). Only serve real built
    # files here (hashed assets, favicon, index). Any other /dashboard/* path is
    # an unmatched API route or routing mistake and must fail clearly as a JSON
    # 404 rather than masking it by returning the index shell as HTML 200.
    dist = DASHBOARD_DIST_PATH.resolve()
    if dist.exists() and asset_path:
        candidate = (dist / asset_path.lstrip("/")).resolve()
        try:
            candidate.relative_to(dist)
        except ValueError:
            candidate = None
        if candidate is not None and candidate.is_file():
            response = FileResponse(candidate)
            if candidate.name == "index.html":
                response.headers["Cache-Control"] = "no-store, max-age=0"
            elif "/assets/" in str(candidate).replace("\\", "/"):
                response.headers["Cache-Control"] = "public, max-age=31536000, immutable"
            return response
    raise HTTPException(status_code=404, detail="Not found")
